class RawCond:
    """
    Minimal wrapper for composite/corrected boolean conditions.

    Current PALemitter._cond() can render constants through _const().
    By presenting the expression string as const_value, we avoid requiring
    an immediate emitter patch.
    """
    is_constant = True

    def __init__(self, expr, source=None, inverted=False, reason=None):
        self.const_value = expr
        self.value = expr
        self.offset = expr
        self.name = expr
        self.ssa_id = None
        self.source = source
        self.inverted = inverted
        self.reason = reason

    def __str__(self):
        return self.const_value


# ============================================================================
# EXECUTION NODES
# ============================================================================

class ExecNode:
    def __init__(self, kind):
        self.kind = kind
        self.children = []
        self.parent = None

    def add(self, node):
        node.parent = self
        self.children.append(node)
        return node


class ExecBlock(ExecNode):
    def __init__(self, cfg_node):
        super().__init__("block")
        self.cfg_node = cfg_node


class ExecBreak(ExecNode):
    def __init__(self, target_loop=None, reason=None):
        super().__init__("break")
        self.target_loop = target_loop
        self.reason = reason


class ExecContinue(ExecNode):
    def __init__(self, target_loop=None, reason=None):
        super().__init__("continue")
        self.target_loop = target_loop
        self.reason = reason


class ExecIf(ExecNode):
    def __init__(self, cfg_node, cond_var):
        super().__init__("if")
        self.cfg_node = cfg_node
        self.cond_var = cond_var

        self.then_branch = ExecNode("then")
        self.else_branch = ExecNode("else")

        self.add(self.then_branch)
        self.add(self.else_branch)

        # v70 / bohdi emperor: every branch arm has a stable structural
        # surface before any direct-to-join classification occurs.  An empty
        # arm is still an executable container; downstream PHI lowering may
        # attach edge-owned transitions without inventing an ExecBlock.
        for arm in (self.then_branch, self.else_branch):
            arm.edge_identity = None
            arm.pred_addr = None
            arm.join_addr = None
            arm.direct_join = False
            arm.direct_join_contract = None
            arm.direct_join_edge_fact = None
            arm.direct_join_owner_schema = None
            arm.sgl_emits_phi_assignments = False

            # v71 / cook emperor: typed structural ownership is separate from
            # the v70 empty-arm attachment surface.  Only genuine empty arms
            # receive the direct_join fields above; predicate, continuation,
            # and loop owners are recorded on their actual structural nodes.
            arm.cook_emperor_owner_kind_v71 = None
            arm.cook_emperor_owner_record_v71 = None
            arm.target_addr_v71 = None
            arm.join_addr_hint_v71 = None


class ExecCase(ExecNode):
    """
    One semantically owned arm of an indirect/multiway dispatch.

    ``kind`` is ``case`` for label-bearing arms and ``default`` for the
    separately proven default edge.  The body is path-local: shared CFG blocks
    may legitimately appear beneath more than one case when semantic custody
    proves that each path executes them.
    """

    def __init__(
        self,
        dispatcher_node,
        target_node,
        values=None,
        role="dispatch_case",
        contract=None,
    ):
        kind = "default" if role == "dispatch_default" else "case"
        super().__init__(kind)

        self.dispatcher = dispatcher_node
        self.cfg_node = target_node
        self.target = target_node
        self.values = list(values or [])
        self.role = role
        self.contract = dict(contract or {})

        self.dispatcher_addr = getattr(dispatcher_node, "addr", None)
        self.target_addr = getattr(target_node, "addr", None)
        self.edge_identity = (self.dispatcher_addr, self.target_addr)

        self.join_predecessors = list(
            self.contract.get("join_predecessors", []) or []
        )
        self.phi_inputs = list(self.contract.get("phi_inputs", []) or [])
        self.falls_through_to_arms = list(
            (self.contract.get("region") or {}).get(
                "falls_through_to_arms", []
            ) or []
        )

        self.body = ExecNode("case_body")
        self.add(self.body)


class ExecDispatch(ExecNode):
    """
    Explicit SGL representation of BRANCHIND / multiway control.

    FunctionCFG owns case labels and destinations. SemanticGraph owns selector,
    arm-region and PHI-predecessor custody. SGL owns path-local execution shape.
    """

    def __init__(
        self,
        cfg_node,
        selector_expr=None,
        computed_target_expr=None,
        join_node=None,
        contract=None,
    ):
        super().__init__("dispatch")

        self.cfg_node = cfg_node
        self.dispatcher = cfg_node
        self.selector_expr = selector_expr
        self.selector = RawCond(
            selector_expr,
            source=cfg_node,
            reason="semantic_multiway_selector_v57",
        ) if selector_expr is not None else None
        self.computed_target_expr = computed_target_expr
        self.join_node = join_node
        self.join = join_node
        self.contract = dict(contract or {})

        self.cases = []
        self.default_case = None

    def add_case(self, case_node):
        self.add(case_node)
        if getattr(case_node, "role", None) == "dispatch_default":
            self.default_case = case_node
        else:
            self.cases.append(case_node)
        return case_node


class ExecConditionTransaction(ExecNode):
    """
    Repeatable executable work that must run before every loop predicate test.

    This is neither ordinary loop-body payload nor one-time condition setup.
    It owns the complete pre-CBRANCH execution of a conditional loop header.
    """

    def __init__(self, header_node):
        super().__init__("loop_condition_transaction")
        self.header = header_node
        self.cfg_node = header_node
        self.header_addr = getattr(header_node, "addr", None)
        self.execution_order = "before_every_predicate_evaluation"


class ExecLoop(ExecNode):
    def __init__(self, header_node, cond_var, condition_role=None):
        super().__init__("loop")
        self.header = header_node
        self.cfg_node = header_node
        self.cond_var = cond_var

        # v20 loop condition contract:
        #   "true" -> emitter prints while True
        #   "body" -> emitter prints while cond
        #   "exit" -> emitter prints while not(cond)
        #
        # SGL owns this semantic decision.  The emitter should consume this
        # directly and avoid expression-shape polarity guesses.
        self.condition_role = condition_role or ("true" if cond_var is None else "body")
        self.emit_condition_mode = self.condition_role

        self.header_is_body = False
        self.guard_node = None
        self.condition_transaction = None
        self.condition_evaluation_order = "predicate_only"

        # v73 / ingenious emperor: an exact canonical loop predicate is not
        # merely condition text.  It is a transaction with one topology-owned
        # continuation edge, one exit edge, and one selected EdgeTruth
        # projection.  These fields are populated only after the complete
        # contract has been proven; legacy loops remain explicitly unbound.
        self.condition_semantics = (
            "unconditional"
            if self.condition_role == "true"
            else (
                "continue_when_true"
                if self.condition_role == "body"
                else "exit_when_true"
            )
        )
        self.continue_edge_key = None
        self.exit_edge_key = None
        self.selected_condition_edge_key = None
        self.selected_edge_invert = None
        self.edge_role_authority = None
        self.loop_edge_role_contract_v73 = None

        # v68: exact snapshot captures that are structurally equivalent to one
        # assignment immediately after this loop. The emitter consumes these
        # bindings; SGL remains the sole placement authority.
        self.loop_exit_snapshot_bindings_v68 = []

        self.body = ExecNode("loop_body")
        self.add(self.body)


