        self.mars_occurrence_authority_version_v75 = (
            "v75_mars_exec_occurrence_authority_v1"
        )
        # v76 is a transport normalization over the v75 occurrence protocol.
        # It does not alter ExecTree topology or the v75 placement classifier.
        self.mars_occurrence_transport_version_v76 = (
            "v76_mars_occurrence_token_handoff_normalization_v1"
        )
        # v77 projects the adjacent PALPHIfolder consumer key without
