    def _commit_canonical_handoff_generation_v80o(self):
        """Commit state-flow and occurrence aliases as one final generation.

        Older publication passes copied the state-flow dictionary while the
        occurrence payload remained identity-shared.  That is safe only while
        no later pass mutates either transfer.  v80o performs one final commit,
        recomputes the occurrence digest, and proves that every canonical alias
        read by PHIfolder resolves to the same object generation.
        """
        version = getattr(
            self,
            "mars_phi_demand_unlock_generation_version_v80o",
            "v80o_mars_phi_demand_unlock_generation_commit_v1",
        )
        state_payload = self.state_flow_handoff_v1
        occurrence_payload = self.occurrence_authority_handoff_v1
        failures = []
        if not isinstance(state_payload, dict):
            state_payload = {}
            failures.append({
                "kind": "canonical_state_flow_payload_missing_v80o"
            })
        if not isinstance(occurrence_payload, dict):
            occurrence_payload = {}
            failures.append({
                "kind": "canonical_occurrence_payload_missing_v80o"
            })

        accepted_demands = sorted({
            tuple(item.get("consumer_transition_id"))
            for collection in (
                list(getattr(self, "phi_transition_demand_unlock_receipts_v80o", []) or []),
                list(getattr(self, "specialized_phi_root_pathway_receipts_v80p", []) or []),
            )
            for item in collection
            if isinstance(item, dict)
            and item.get("status") == "accepted"
            and isinstance(item.get("consumer_transition_id"), (tuple, list))
            and len(item.get("consumer_transition_id")) == 5
        }, key=str)
        material = {
            "version": version,
            "state_edge_epochs": len(
                list(state_payload.get("edge_epoch_receipts") or [])
            ),
            "transition_receipts": len(
                list(occurrence_payload.get("transition_placement_receipts") or [])
            ),
            "accepted_demands": [list(item) for item in accepted_demands],
        }
        generation = hashlib.sha256(json.dumps(
            material, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")).hexdigest()
        generation_record = {
            "kind": "canonical_handoff_generation_v80o",
            "schema": "canonical_handoff_generation_v1",
            "version": version,
            "generation": generation,
            "accepted_demands": len(accepted_demands),
            "specialized_phi_root_pathway_version_v80p": getattr(
                self, "mars_specialized_phi_root_pathway_version_v80p",
                "v80p_mars_specialized_phi_root_pathway_rewrite_v1",
            ),
            "input_order_used": False,
            "successor_order_used": False,
            "authority": "PALSGL_v80o_single_generation_commit",
        }
        state_payload["canonical_handoff_generation_v80o"] = generation_record
        occurrence_payload["canonical_handoff_generation_v80o"] = generation_record
        state_payload["phi_transition_demand_unlock_audit_v80o"] = dict(
            self.phi_transition_demand_unlock_audit_v80o
        )
        occurrence_payload["phi_demand_finalization_audit_v80o"] = dict(
            self.phi_demand_finalization_audit_v80o
        )

        encoded = json.dumps(
            occurrence_payload, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")
        payload_ref = dict(getattr(self, "occurrence_authority_ref_v75", {}) or {})
        payload_ref.update({
            "kind": "exec_occurrence_authority_ref_v1",
            "schema": "exec_occurrence_authority_ref_v1",
            "version": self.mars_occurrence_authority_version_v75,
            "transport_version": self.mars_occurrence_transport_version_v76,
            "consumer_key_version": self.mars_occurrence_consumer_key_version_v77,
            "phi_demand_unlock_generation_version_v80o": version,
            "canonical_generation_v80o": generation,
            "attribute": "sgl_occurrence_authority_v75",
            "legacy_full_payload_attribute": "exec_occurrence_authority_handoff_v1",
            "sha256": hashlib.sha256(encoded).hexdigest(),
        })
        state_payload["exec_occurrence_authority_ref_v1"] = payload_ref
        self.state_flow_handoff_v1 = state_payload
        self.occurrence_authority_handoff_v1 = occurrence_payload
        self.occurrence_authority_ref_v75 = payload_ref

        # Canonical aliases consumed by PHIfolder.  Each alias group is one
        # object, not a late copy of a prior generation.
        self.func.state_flow_handoff_v1 = state_payload
        self.func.sgl_state_flow_handoff_v1 = state_payload
        self.func.sgl_state_flow_handoff = state_payload
        self.func.exec_occurrence_authority_handoff_v1 = occurrence_payload
        self.func.sgl_occurrence_authority_v75 = occurrence_payload
        self.func.sgl_exec_occurrence_authority_ref_v75 = payload_ref
        handoff = getattr(self.func, "sgl_metadata_handoff", None)
        if not isinstance(handoff, dict):
            handoff = {}
            self.func.sgl_metadata_handoff = handoff
        handoff["state_flow_handoff_v1"] = state_payload
        handoff["exec_occurrence_authority_handoff_v1"] = occurrence_payload
        handoff["sgl_occurrence_authority_v75"] = occurrence_payload
        handoff["exec_occurrence_authority_ref_v1"] = payload_ref
        handoff["canonical_handoff_generation_v80o"] = generation_record

        alias_gates = {
            "state_aliases_same_object": (
                self.func.state_flow_handoff_v1 is state_payload
                and self.func.sgl_state_flow_handoff_v1 is state_payload
                and self.func.sgl_state_flow_handoff is state_payload
                and handoff.get("state_flow_handoff_v1") is state_payload
            ),
            "occurrence_aliases_same_object": (
                self.func.exec_occurrence_authority_handoff_v1 is occurrence_payload
                and self.func.sgl_occurrence_authority_v75 is occurrence_payload
                and handoff.get("exec_occurrence_authority_handoff_v1") is occurrence_payload
                and handoff.get("sgl_occurrence_authority_v75") is occurrence_payload
            ),
            "generation_shared": (
                state_payload.get("canonical_handoff_generation_v80o")
                is occurrence_payload.get("canonical_handoff_generation_v80o")
            ),
            "occurrence_digest_current": (
                payload_ref.get("sha256") == hashlib.sha256(encoded).hexdigest()
            ),
        }
        if not all(alias_gates.values()):
            failures.append({
                "kind": "canonical_handoff_alias_generation_failure_v80o",
                "failed_gates": [
                    name for name, passed in alias_gates.items() if not passed
                ],
            })

        placement_records = list(
            occurrence_payload.get("transition_placement_receipts") or []
        )
        edge_epochs = list(state_payload.get("edge_epoch_receipts") or [])
        for transition_id in accepted_demands:
            accepted_edges = [
                item for item in edge_epochs
                if isinstance(item, dict)
                and tuple(item.get("transition_id") or ()) == transition_id
                and item.get("status") == "accepted"
            ]
            accepted_placements = [
                item for item in placement_records
                if isinstance(item, dict)
                and tuple(item.get("transition_id") or ()) == transition_id
                and item.get("status") == "accepted"
                and list(item.get("authorized_placements") or [])
            ]
            if len(accepted_edges) != 1 or len(accepted_placements) != 1:
                failures.append({
                    "kind": "canonical_handoff_exact_ticket_lookup_failure_v80o",
                    "transition_id": transition_id,
                    "accepted_edge_epochs": len(accepted_edges),
                    "accepted_placement_receipts": len(accepted_placements),
                })

        audit = {
            "kind": (
                "canonical_handoff_generation_verified_v80o"
                if not failures else "canonical_handoff_generation_failed_v80o"
            ),
            "schema": "canonical_handoff_generation_audit_v1",
            "version": version,
            "generation": generation,
            "accepted_demands": len(accepted_demands),
            "alias_gates": alias_gates,
            "failures": list(failures),
            "rule": (
                "one_final_object_generation_for_state_flow_occurrence_and_"
                "metadata_aliases_before_PHIfolder_construction"
            ),
        }
        self.canonical_handoff_generation_audit_v80o = dict(audit)
        self.func.sgl_canonical_handoff_generation_audit_v80o = dict(audit)
        handoff["canonical_handoff_generation_audit_v80o"] = dict(audit)
        if failures:
            raise RuntimeError(
                "PALSGL v80o canonical handoff generation lock failure: %s"
                % failures
            )
        return audit

    def _collect_loop_condition_roles_v19b(self):
        out = {}

        def walk(node):
            if node is None:
                return

            if getattr(node, "kind", None) == "loop":
                h = getattr(getattr(node, "header", None), "addr", None)
                c = getattr(node, "cond_var", None)
                out[h] = {
                    "role": getattr(node, "condition_role", None),
                    "mode": getattr(node, "emit_condition_mode", None),
                    "cond": str(getattr(c, "name", c)),
                    "condition_transaction": getattr(
                        getattr(node, "condition_transaction", None),
                        "header_addr",
                        None,
                    ),
                    "condition_evaluation_order": getattr(
                        node, "condition_evaluation_order", None
                    ),
                    "condition_semantics": getattr(
                        node, "condition_semantics", None
                    ),
                    "continue_edge_key": getattr(
                        node, "continue_edge_key", None
                    ),
                    "exit_edge_key": getattr(node, "exit_edge_key", None),
                    "selected_condition_edge_key": getattr(
                        node, "selected_condition_edge_key", None
                    ),
                    "selected_edge_invert": getattr(
                        node, "selected_edge_invert", None
                    ),
                    "edge_role_authority": getattr(
                        node, "edge_role_authority", None
                    ),
                    "loop_edge_role_contract_v73": dict(
                        getattr(node, "loop_edge_role_contract_v73", None)
                        or {}
                    ),
                }

            for child in list(getattr(node, "children", []) or []):
                walk(child)

        walk(self.root)
        return out

    # =========================================================================
    # LOOP DISCOVERY
    # =========================================================================

    def _identify_loops(self):
        """
        Prefer FunctionCFG loop metadata when available.

        v11 rule:
            FunctionCFG owns topology and loop/backedge metadata.
            SGL consumes that metadata and only falls back to local inference
            when running against an older PALlibrary.
        """

        cfg_loop_headers = getattr(self.cfg, "loop_headers", None)
        cfg_loop_latches = getattr(self.cfg, "loop_latches", None)
        cfg_loop_nodes = getattr(self.cfg, "loop_nodes", None)
        cfg_loop_exits = getattr(self.cfg, "loop_exits", None)

        if cfg_loop_headers is not None and cfg_loop_latches is not None:
            self.loop_headers = set(cfg_loop_headers or set())
            self.loop_latches = {
                h: list(cfg_loop_latches.get(h, []) or [])
                for h in self.loop_headers
            }

            for header in list(self.loop_headers):
                if isinstance(cfg_loop_nodes, dict) and header in cfg_loop_nodes:
                    self.loop_nodes[header] = set(cfg_loop_nodes.get(header, set()) or set())
                else:
                    self.loop_nodes[header] = self._natural_loop_nodes(
                        header,
                        self.loop_latches.get(header, []),
                    )

                if isinstance(cfg_loop_exits, dict) and header in cfg_loop_exits:
                    self.loop_exits[header] = set(cfg_loop_exits.get(header, set()) or set())
                else:
                    self.loop_exits[header] = self._natural_loop_exits(
                        header,
                        self.loop_nodes.get(header, set()),
                    )
        else:
            # Backward-compatible fallback for older PALlibrary builds.
            for node in self._real_nodes():

                for e in getattr(node, "out_edges", []):

                    dst = getattr(e, "dst", None)

                    if dst is None:
                        continue

                    if dst in getattr(node, "dominators", set()):
                        self.loop_headers.add(dst)
                        self.loop_latches.setdefault(dst, []).append(node)

            for header in list(self.loop_headers):
                nodes = self._natural_loop_nodes(header, self.loop_latches.get(header, []))
                self.loop_nodes[header] = nodes
                self.loop_exits[header] = self._natural_loop_exits(header, nodes)

        # Derived SGL metadata.
        for header in list(self.loop_headers):

            if self._loop_header_has_executable_ops(header):
                if self._loop_header_is_condition_transaction_v59(header):
                    self.loop_condition_transaction_headers.add(header)
                    event = {
                        "kind": (
                            "loop_header_condition_transaction_"
                            "classified_v59"
                        ),
                        "header": getattr(header, "addr", None),
                        "condition_role": "pretest_header",
                        "execution_order": (
                            "before_every_predicate_evaluation"
                        ),
                        "opcodes": self._node_payload_opcodes_v55(header),
                    }
                    self.loop_condition_transaction_events.append(event)
                    self.loop_contract_events.append(dict(event))
                else:
                    self.loop_body_headers.add(header)

            for latch in self.loop_latches.get(header, []):
                if self._get_condition(latch) is not None:
                    self.loop_tail_test_nodes.add(latch)

            guard = self._detect_loop_guard_chain_node(header)
            if guard is not None:
                self.loop_guard_nodes[header] = guard

            self.loop_normal_exits[header] = self._natural_loop_normal_exits(header)

            if self._is_single_exit_test_loop(header):
                self.loop_single_exit_tests.add(header)

            tail = self._detect_latch_tail_chain(header)
            if tail:
                self.loop_tail_chains[header] = tail

    def _natural_loop_nodes(self, header, latches):
        loop_nodes = {header}
        work = list(latches or [])

        for latch in work:
            loop_nodes.add(latch)

        while work:
            n = work.pop()

            for pred in self._predecessors(n):
                if pred not in loop_nodes:
                    loop_nodes.add(pred)
                    work.append(pred)

        return loop_nodes

    def _natural_loop_exits(self, header, nodes):
        exits = set()

        for n in nodes:
            for succ in self._successors(n):
                if succ not in nodes:
                    exits.add(succ)

        return exits

    def _natural_loop_normal_exits(self, header):
        """
        Normal loop exits are the exits reached by loop guard/header tests,
        not arbitrary break-action blocks inside the loop.

        For alpha_four inner loop:
            0x10126f / 0x101275 guard exits -> 0x10127f normal continuation
            0x10125c false -> 0x101262 break action, not normal exit

        The break-action node must stay in the branch that reaches it; it must
        not be emitted unconditionally after the loop.
        """

        nodes = self.loop_nodes.get(header, set())
        exits = self.loop_exits.get(header, set())
        normals = set()

        # Header direct exits.
        for succ in self._successors(header):
            if succ not in nodes and succ in exits:
                normals.add(succ)

        # Guard-chain exits.
        guard = self.loop_guard_nodes.get(header)
        if guard is not None:
            for succ in self._successors(guard):
                if succ not in nodes and succ in exits:
                    normals.add(succ)

        # Body-header latch-tested loops may exit through latch/test nodes.
        # Keep this conservative: only exits from latch condition blocks count
        # as normal. Action exits from arbitrary body branches do not.
        for latch in self.loop_latches.get(header, []):
            if self._get_condition(latch) is None:
                continue
            for succ in self._successors(latch):
                if succ not in nodes and succ in exits:
                    normals.add(succ)

        if normals:
            return normals

        # Fallback: if there is a single exit, it is probably normal.
        if len(exits) == 1:
            return set(exits)

        return set()


    def _is_single_exit_test_loop(self, header):
        """
        Detect loops whose header condition is an exit test.

        Pattern:
            header has condition
            one successor is loop body
            the other successor is loop exit/join

        For alpha_four's small gamma loop, the header condition is:
            gamma < 1
        which is an exit test for source while(gamma > 0). The emitter already
        inverts loop conditions for this CFG shape, so we pass the exit test.
        """

        if self._get_condition(header) is None:
            return False

        nodes = self.loop_nodes.get(header, set())
        exits = self.loop_exits.get(header, set())

        if not nodes or not exits:
            return False

        succs = self._successors(header)

        if len(succs) != 2:
            return False

        inside = [s for s in succs if s in nodes and s is not header]
        outside = [s for s in succs if s not in nodes or s in exits]

        return bool(inside and outside)

    def _detect_latch_tail_chain(self, header):
        """
        Detect simple latch/tail condition chains for body-header loops.

        alpha_four outer do/while tail:
            0x10129b: counter update; if 4 < counter backedge else 0x1012a9
            0x1012a9: if 99 < alpha backedge else return

        We do not emit break/continue here yet. We preserve metadata so the
        emitter or a later SGL lowering can render an executable tail check.
        """

        if header not in self.loop_body_headers:
            return []

        latches = list(self.loop_latches.get(header, []) or [])

        chain = []

        for latch in latches:
            if self._get_condition(latch) is None:
                continue

            chain.append(latch)

            for succ in self._successors(latch):
                if succ is header:
                    continue
                if succ in self.loop_nodes.get(header, set()):
                    continue
                # Follow one external condition node that can backedge to the
                # same header; this catches OR-style tail chains.
                if self._get_condition(succ) is not None:
                    for ss in self._successors(succ):
                        if ss is header:
                            chain.append(succ)
                            break

        # Stable order by address.
        return self._ordered_nodes(set(chain))

    def _loop_header_has_executable_ops(self, header):
        """
        True when a loop header contains executable work beyond PHI and branch
        condition construction.
        """

        block = getattr(header, "block", None)

        if block is None:
            return False

        term = getattr(block, "terminator", None)
        term_cond = getattr(term, "condition", None)
        cond_sid = getattr(term_cond, "ssa_id", None)

        for op in list(getattr(block, "ops", []) or []):
            opcode = getattr(op, "opcode", None)

            if opcode == "MULTIEQUAL":
                continue

            out = getattr(op, "output", None)
            out_sid = getattr(out, "ssa_id", None)

            if cond_sid is not None and out_sid == cond_sid:
                continue

            if opcode in ("INT_EQUAL", "INT_NOTEQUAL", "INT_LESS", "INT_SLESS",
                          "INT_LESSEQUAL", "INT_SLESSEQUAL", "BOOL_NEGATE"):
                if term is not None and getattr(term, "opcode", None) == "CBRANCH":
                    continue

            return True

        return False

    def _loop_header_is_condition_transaction_v59(self, header):
        """
        Classify a conditional pre-test header whose executable operations
        must run before every predicate evaluation.

        Required topology:
          * the header owns a real condition and executable pre-branch work;
          * exactly one successor remains in the natural loop body;
          * exactly one successor exits the natural loop;
          * the header is not merely an unconditional body header.

        This is address-, opcode-, and sample-independent.  It does not infer
        source-level comma expressions or hoist individual operations.
        """
        if header is None or self._get_condition(header) is None:
            return False
        if not self._loop_header_has_executable_ops(header):
            return False

        nodes = set(self.loop_nodes.get(header, set()) or set())
        exits = set(self.loop_exits.get(header, set()) or set())
        successors = list(self._successors(header) or [])
        if len(successors) != 2 or not nodes:
            return False

        inside = [
            node for node in successors
            if node in nodes and node is not header
        ]
        outside = [
            node for node in successors
            if node not in nodes or node in exits
        ]
        return len(inside) == 1 and len(outside) == 1

    def _predecessors(self, node):
        try:
            return list(node.predecessors())
        except Exception:
            out = []
            for e in list(getattr(node, "in_edges", []) or []):
                src = getattr(e, "src", None)
                if src is not None:
                    out.append(src)
            return out

    def _detect_loop_guard_chain_node(self, header):
        """
        Detect a two-stage loop guard:

            header condition exits loop or continues to guard
            guard condition exits loop or continues to body

        alpha_four inner loop:
            0x10126f: i > 9 exit else 0x101275
            0x101275: beta < 1 exit else body

        We return the guard node so traversal can skip emitting it as a nested
        if. The composed condition is handled by _loop_guard_chain_condition().
        """

        nodes = self.loop_nodes.get(header, set())
        exits = self.loop_exits.get(header, set())

        if not nodes or not exits:
            return None

        succs = self._successors(header)

        if len(succs) != 2:
            return None

        inside = [s for s in succs if s in nodes and s is not header]
        outside = [s for s in succs if s not in nodes]

        if len(inside) != 1 or len(outside) != 1:
            return None

        cand = inside[0]

        if self._get_condition(cand) is None:
            return None

        # v55: a second-stage loop guard may be folded into the loop predicate
        # only when it is condition-only.  A candidate that performs calls,
        # stores, loads/state updates, or produces a downstream-used value is
        # an executable loop-body entry with an early exit, not a guard shim.
        # Folding it would drop both the payload and its definitions before
        # downstream use (Station main 0x402538 / v_510 class).
        if self._conditional_payload_required_v55(cand):
            rec = {
                "kind": "loop_guard_chain_candidate_rejected_payload_v55",
                "loop": getattr(header, "addr", None),
                "candidate": getattr(cand, "addr", None),
                "reason": "candidate_owns_executable_prebranch_payload",
                "opcodes": self._node_payload_opcodes_v55(cand),
            }
            self.payload_custody_events.append(rec)
            self.loop_contract_events.append(dict(rec))
            self._record_metadata_event_v43(dict(rec))
            return None

        cand_succs = self._successors(cand)

        if len(cand_succs) != 2:
            return None

        cand_inside = [s for s in cand_succs if s in nodes and s is not header and s is not cand]
        cand_outside = [s for s in cand_succs if s not in nodes or s in exits]

        if not cand_inside or not cand_outside:
            return None

        return cand

    def _loop_guard_chain_body(self, header):
        guard = self.loop_guard_nodes.get(header)

        if guard is None:
            return None

        nodes = self.loop_nodes.get(header, set())

        for succ in self._successors(guard):
            if succ in nodes and succ is not header and succ is not guard:
                return succ

        return None

    def _loop_guard_chain_condition(self, header):
        """
        Conservative executable lowering for chained loop guards.

        We treat both header and guard conditions as exit tests and continue
        while neither is true:
            while not(header_exit_cond) and not(guard_exit_cond):
        """

        guard = self.loop_guard_nodes.get(header)

        if guard is None:
            return None

        h = self._cond_expr_raw(header)
        g = self._cond_expr_raw(guard)

        if not h or not g:
            return None

        # Return the exit-test disjunction, not the continue condition.
        # The current emitter's loop-condition forcing inverts header
        # conditions for this CFG shape, so passing exit1 OR exit2 yields:
        #     while not (exit1 or exit2):
        # which is the desired executable guard.
        return RawCond("(%s) or (%s)" % (h, g))



    def _as_list(self, maybe_iterable):
        if maybe_iterable is None:
            return []
        try:
            if callable(maybe_iterable):
                maybe_iterable = maybe_iterable()
        except Exception:
            return []
        try:
            return list(maybe_iterable or [])
        except TypeError:
            return [maybe_iterable]
        except Exception:
            return []

    # =========================================================================
    # v26 SEMANTIC-GRAPH METADATA SANDWICH CONSUMERS
    # =========================================================================

    def _addr_v26(self, node_or_addr):
        """Return an integer address for a CFG node or integer-like address."""
        if node_or_addr is None:
            return None
        if isinstance(node_or_addr, int):
            return node_or_addr
        try:
            addr = getattr(node_or_addr, "addr", None)
            if isinstance(addr, int):
                return addr
        except Exception:
            pass
        return None

    def _hex_v26(self, x):
        try:
            return hex(x) if isinstance(x, int) else str(x)
        except Exception:
            return str(x)

    def _edge_key_candidates_v26(self, src, dst):
        saddr = self._addr_v26(src)
        daddr = self._addr_v26(dst)
        keys = []
        if saddr is not None and daddr is not None:
            keys.extend([
                (saddr, daddr),
                (self._hex_v26(saddr), self._hex_v26(daddr)),
                "%s->%s" % (self._hex_v26(saddr), self._hex_v26(daddr)),
                "%s->%s" % (saddr, daddr),
            ])
        return keys

    def _edge_truth_record_v40(self, src, dst):
        """Return canonical PALSemanticGraphBuilder v25 EdgeTruth for src->dst."""
        table = getattr(self, "edge_truth", {}) or {}
        if not table or src is None or dst is None:
            return None

        for key in self._edge_key_candidates_v26(src, dst):
            try:
                if key in table:
                    rec = table.get(key)
                    if isinstance(rec, dict):
                        return rec
            except Exception:
                pass

        saddr = self._addr_v26(src)
        daddr = self._addr_v26(dst)
        for rec in list(table.values()):
            if not isinstance(rec, dict):
                continue
            if rec.get("src") == saddr and rec.get("dst") == daddr:
                return rec
            if rec.get("src_hex") == self._hex_v26(saddr) and rec.get("dst_hex") == self._hex_v26(daddr):
                return rec
        return None

    def _edge_truth_record_v26(self, src, dst):
        """
        Compatibility lookup used by older SGL code paths.

        v40 prefers canonical EdgeTruth records produced by
        PALSemanticGraphBuilder v25.  If absent, fall back to the older v24
        edge_condition_truth table so old binaries/stacks remain runnable.
        """
        rec = self._edge_truth_record_v40(src, dst)
        if rec is not None:
            return rec

        table = getattr(self, "edge_condition_truth", {}) or {}
        if not table or src is None or dst is None:
            return None

        for key in self._edge_key_candidates_v26(src, dst):
            try:
                if key in table:
                    return table.get(key)
            except Exception:
                pass

        saddr = self._addr_v26(src)
        daddr = self._addr_v26(dst)
        for rec in list(table.values()):
            if not isinstance(rec, dict):
                continue
            if rec.get("src") == saddr and rec.get("dst") == daddr:
                return rec
            if rec.get("src_hex") == self._hex_v26(saddr) and rec.get("dst_hex") == self._hex_v26(daddr):
                return rec
        return None

    def _metadata_record_is_canonical_edge_truth_v40(self, rec):
        if not isinstance(rec, dict):
            return False
        version = str(rec.get("version") or "").lower()
        if "edgetruth" in version:
            return True
        if "predicate_authoritative" in rec:
            return True
        if "predicate_holds_means_take_edge" in rec:
            return True
        return False

    def _clothed_emperor_record_event_v72(self, kind, **kw):
        event = {"kind": kind}
        event.update(kw)
        key = (
            kind,
            event.get("src"),
            event.get("dst"),
            event.get("peer_dst"),
            event.get("consumer"),
            event.get("reason"),
        )
        keys = getattr(self, "_clothed_emperor_event_keys_v72", None)
        if keys is None:
            keys = set()
            self._clothed_emperor_event_keys_v72 = keys
        if key in keys:
            return event
        keys.add(key)
        events = getattr(self, "clothed_emperor_events_v72", None)
        if events is None:
            events = []
            self.clothed_emperor_events_v72 = events
        events.append(event)
        return event

    def _publish_clothed_emperor_handoff_v72(self):
        events = list(getattr(self, "clothed_emperor_events_v72", []) or [])
        failures = list(
            getattr(self, "clothed_emperor_failures_v72", []) or []
        )
        audit = {
            "kind": (
                "sgl_clothed_emperor_edgetruth_failed_v72"
                if failures
                else "sgl_clothed_emperor_edgetruth_verified_v72"
            ),
            "version": getattr(
                self,
                "clothed_emperor_version_v72",
                "v72_clothed_emperor_edgetruth_fail_closed",
            ),
            "status": "failed" if failures else "verified",
            "authoritative_edge_consumptions": sum(
                1
                for rec in events
                if rec.get("kind")
                == "clothed_emperor_authoritative_edge_consumed_v72"
            ),
            "binary_pair_checks": sum(
                1
                for rec in events
                if rec.get("kind")
                == "clothed_emperor_binary_pair_verified_v72"
            ),
            "failures": failures,
        }
        self.clothed_emperor_audit_v72 = audit
        func = getattr(self, "func", None)
        if func is not None:
            func.sgl_clothed_emperor_version_v72 = audit["version"]
            func.sgl_clothed_emperor_events_v72 = events
            func.sgl_clothed_emperor_failures_v72 = failures
            func.sgl_clothed_emperor_audit_v72 = dict(audit)
        return audit

    def _canonical_edge_truth_authority_v72(self, rec):
        """Return (is_authoritative, reason) for one canonical edge record."""
        if not isinstance(rec, dict):
            return False, "canonical_record_missing"
        if rec.get("predicate_authoritative") is not True:
            return False, "predicate_authoritative_not_true"
        if rec.get("predicate_holds_means_take_edge") is not True:
            return False, "predicate_holds_means_take_edge_not_true"
        if not isinstance(rec.get("invert_for_edge"), bool):
            return False, "invert_for_edge_not_boolean"
        confidence = str(
            rec.get("confidence") or rec.get("trust") or ""
        ).lower()
        if confidence not in ("authoritative", "high"):
            return False, "confidence_not_authoritative_or_high"
        expr = rec.get("predicate") or rec.get("edge_expr")
        if expr is None or not str(expr).strip():
            return False, "edge_predicate_missing"
        return True, "authoritative_edge_truth_v72"

    def _clothed_emperor_fail_v72(
        self,
        src,
        dst,
        consumer,
        reason,
        rec=None,
        peer_dst=None,
        peer_rec=None,
    ):
        failure = {
            "kind": "unresolved_binary_edge_truth_reached_execution_v72",
            "version": getattr(
                self,
                "clothed_emperor_version_v72",
                "v72_clothed_emperor_edgetruth_fail_closed",
            ),
            "src": self._addr_v26(src),
            "dst": self._addr_v26(dst),
            "peer_dst": self._addr_v26(peer_dst),
            "consumer": consumer,
            "reason": reason,
            "edge": {
                "predicate_authoritative": (
                    rec.get("predicate_authoritative")
                    if isinstance(rec, dict) else None
                ),
                "predicate_holds_means_take_edge": (
                    rec.get("predicate_holds_means_take_edge")
                    if isinstance(rec, dict) else None
                ),
                "invert_for_edge": (
                    rec.get("invert_for_edge")
                    if isinstance(rec, dict) else None
                ),
                "confidence": (
                    rec.get("confidence") or rec.get("trust")
                    if isinstance(rec, dict) else None
                ),
                "selection_source": (
                    rec.get("selection_source")
                    if isinstance(rec, dict) else None
                ),
                "selection_reason": (
                    rec.get("selection_reason")
                    if isinstance(rec, dict) else None
                ),
                "predicate_status": (
                    rec.get("predicate_status")
                    if isinstance(rec, dict) else None
                ),
            },
            "peer_edge": {
                "predicate_authoritative": (
                    peer_rec.get("predicate_authoritative")
                    if isinstance(peer_rec, dict) else None
                ),
                "predicate_holds_means_take_edge": (
                    peer_rec.get("predicate_holds_means_take_edge")
                    if isinstance(peer_rec, dict) else None
                ),
                "invert_for_edge": (
                    peer_rec.get("invert_for_edge")
                    if isinstance(peer_rec, dict) else None
                ),
                "confidence": (
                    peer_rec.get("confidence") or peer_rec.get("trust")
                    if isinstance(peer_rec, dict) else None
                ),
            },
            "action": (
                "repair FunctionCFG/EdgeTruth evidence; do not synthesize "
                "branch orientation in SGL"
            ),
        }
        failures = getattr(self, "clothed_emperor_failures_v72", None)
        if failures is None:
            failures = []
            self.clothed_emperor_failures_v72 = failures
        failures.append(failure)
        self._clothed_emperor_record_event_v72(
            failure["kind"],
            src=failure["src"],
            dst=failure["dst"],
            peer_dst=failure["peer_dst"],
            consumer=consumer,
            reason=reason,
        )
        self._publish_clothed_emperor_handoff_v72()
        raise RuntimeError(
            "PALSGL v72 unresolved binary EdgeTruth reached execution: %s"
            % failure
        )

    def _require_binary_edge_truth_pair_v72(self, src, consumer):
        """Require a resolved complementary pair when canonical truth exists."""
        if src is None:
            return None
        true_node = self._true_edge(src)
        false_node = self._false_edge(src)
        if (
            true_node is None
            or false_node is None
            or true_node is false_node
        ):
            return None

        true_rec = self._edge_truth_record_v40(src, true_node)
        false_rec = self._edge_truth_record_v40(src, false_node)
        if true_rec is None and false_rec is None:
            return None
        if true_rec is None or false_rec is None:
            missing = true_node if true_rec is None else false_node
            present = false_rec if true_rec is None else true_rec
            present_dst = false_node if true_rec is None else true_node
            self._clothed_emperor_fail_v72(
                src,
                missing,
                consumer,
                "canonical_binary_peer_record_missing",
                rec=None,
                peer_dst=present_dst,
                peer_rec=present,
            )

        true_ok, true_reason = self._canonical_edge_truth_authority_v72(
            true_rec
        )
        false_ok, false_reason = self._canonical_edge_truth_authority_v72(
            false_rec
        )
        if not true_ok:
            self._clothed_emperor_fail_v72(
                src,
                true_node,
                consumer,
                true_reason,
                rec=true_rec,
                peer_dst=false_node,
                peer_rec=false_rec,
            )
        if not false_ok:
            self._clothed_emperor_fail_v72(
                src,
                false_node,
                consumer,
                false_reason,
                rec=false_rec,
                peer_dst=true_node,
                peer_rec=true_rec,
            )

        true_invert = true_rec.get("invert_for_edge")
        false_invert = false_rec.get("invert_for_edge")
        if {true_invert, false_invert} != {False, True}:
            self._clothed_emperor_fail_v72(
                src,
                true_node,
                consumer,
                "binary_edge_inversions_not_complementary",
                rec=true_rec,
                peer_dst=false_node,
                peer_rec=false_rec,
            )

        true_sid = true_rec.get("condition_sid")
        false_sid = false_rec.get("condition_sid")
        if (
            true_sid is not None
            and false_sid is not None
            and str(true_sid) != str(false_sid)
        ):
            self._clothed_emperor_fail_v72(
                src,
                true_node,
                consumer,
                "binary_edge_condition_sid_mismatch",
                rec=true_rec,
                peer_dst=false_node,
                peer_rec=false_rec,
            )

        true_opcode = true_rec.get("condition_opcode")
        false_opcode = false_rec.get("condition_opcode")
        if (
            true_opcode is not None
            and false_opcode is not None
            and str(true_opcode) != str(false_opcode)
        ):
            self._clothed_emperor_fail_v72(
                src,
                true_node,
                consumer,
                "binary_edge_condition_opcode_mismatch",
                rec=true_rec,
                peer_dst=false_node,
                peer_rec=false_rec,
            )

        self._clothed_emperor_record_event_v72(
            "clothed_emperor_binary_pair_verified_v72",
            src=self._addr_v26(src),
            dst=self._addr_v26(true_node),
            peer_dst=self._addr_v26(false_node),
            consumer=consumer,
            reason="authoritative_complementary_binary_edge_truth",
            true_invert=true_invert,
            false_invert=false_invert,
        )
        return True

    def _authoritative_edgetruth_condition_v72(
        self, src, dst, cond=None, consumer="edge_condition"
    ):
        rec = self._edge_truth_record_v40(src, dst)
        if not isinstance(rec, dict):
            return None

        authoritative, reason = self._canonical_edge_truth_authority_v72(rec)
        if not authoritative:
            self._clothed_emperor_fail_v72(
                src,
                dst,
                consumer,
                reason,
                rec=rec,
            )

        expr = rec.get("predicate") or rec.get("edge_expr")
        expr = self._refresh_edge_projection_expr_v64(src, rec, expr)
        self._clothed_emperor_record_event_v72(
            "clothed_emperor_authoritative_edge_consumed_v72",
            src=self._addr_v26(src),
            dst=self._addr_v26(dst),
            consumer=consumer,
            reason=rec.get("selection_reason")
            or rec.get("selection_source")
            or "authoritative_edge_truth_v72",
            invert_for_edge=rec.get("invert_for_edge"),
            confidence=rec.get("confidence") or rec.get("trust"),
        )
        self._metadata_record_event_v26(
            "edge_truth_v72_authoritative_consumed",
            src=self._addr_v26(src),
            dst=self._addr_v26(dst),
            expr=expr,
            confidence=rec.get("confidence"),
            selection_source=rec.get("selection_source"),
            selection_reason=rec.get("selection_reason"),
            invert_for_edge=rec.get("invert_for_edge"),
            is_taken_edge=rec.get("is_taken_edge"),
            is_fallthrough_edge=rec.get("is_fallthrough_edge"),
        )
        return RawCond(
            expr,
            source=cond,
            inverted=str(expr).strip().startswith("not "),
            reason=rec.get("selection_reason")
            or rec.get("selection_source")
            or "edge_truth_v72_authoritative",
        )

    def _edgetruth_condition_for_edge_v40(self, src, dst, cond=None):
        """
        Return RawCond only from authoritative canonical EdgeTruth.  This is used by
        places such as loop-condition normalization where we want to know
        whether the new edge-bound contract actually exists, not merely fall
        back to legacy block-condition heuristics.
        """
        return self._authoritative_edgetruth_condition_v72(
            src,
            dst,
            cond=cond,
            consumer="edgetruth_condition_for_edge_v40",
        )

    def _block_branch_custody_record_v26(self, node):
        addr = self._addr_v26(node)
        table = getattr(self, "block_branch_custody", {}) or {}
        if addr is None or not table:
            return None
        for key in (addr, self._hex_v26(addr), str(addr)):
            try:
                if key in table:
                    return table.get(key)
            except Exception:
                pass
        for rec in list(table.values()):
            if isinstance(rec, dict) and rec.get("block_addr") == addr:
                return rec
        return None

    def _block_ownership_record_v26(self, node):
        addr = self._addr_v26(node)
        table = getattr(self, "block_ownership_facts", {}) or {}
        if addr is None or not table:
            return None
        for key in (addr, self._hex_v26(addr), str(addr)):
            try:
                if key in table:
                    return table.get(key)
            except Exception:
                pass
        for rec in list(table.values()):
            if isinstance(rec, dict) and rec.get("addr") == addr:
                return rec
        return None

    def _latch_facts_for_loop_v26(self, loop_header):
        haddr = self._addr_v26(loop_header)
        table = getattr(self, "latch_update_facts", {}) or {}
        if haddr is None or not table:
            return None
        for key in (haddr, self._hex_v26(haddr), str(haddr)):
            try:
                if key in table:
                    return table.get(key)
            except Exception:
                pass
        for rec in list(table.values()):
            if isinstance(rec, dict) and rec.get("loop_header") == haddr:
                return rec
        return None

    def _metadata_record_event_v26(self, kind, **kw):
        try:
            rec = {"kind": kind}
            rec.update(kw)
            self.metadata_consumed_events.append(rec)
        except Exception:
            pass

    def _metadata_condition_for_edge_v26(self, src, dst, cond=None):
        """Return RawCond true for src->dst from GraphBuilder edge metadata.

        v72 consumes canonical EdgeTruth only through its explicit authority
        contract.  A canonical unresolved record fails closed here and vetoes
        the v24 compatibility path.  The older edge_condition_truth table is
        considered only when canonical EdgeTruth is entirely absent.
        """
        canonical = self._edge_truth_record_v40(src, dst)
        if isinstance(canonical, dict):
            return self._authoritative_edgetruth_condition_v72(
                src,
                dst,
                cond=cond,
                consumer="metadata_condition_for_edge_v26",
            )

        # Compatibility is absence-only.  Do not call this fallback after a
        # canonical unresolved verdict.
        rec = self._edge_truth_record_v26(src, dst)
        if not rec:
            return None

        expr = rec.get("predicate") or rec.get("edge_expr") or rec.get("hf_expr")
        if not expr:
            return None

        original_expr = str(expr).strip()
        mirror = self._metadata_branch_mirror_requires_not_v30(src, dst, rec)
        if mirror:
            expr = self._metadata_not_expr_v30(original_expr)
            if expr != original_expr:
                self._metadata_record_event_v26(
                    "protected_metadata_branch_mirror_not_applied_v31",
                    src=self._addr_v26(src),
                    dst=self._addr_v26(dst),
                    original_expr=original_expr,
                    expr=expr,
                    mnemonic=mirror.get("mnemonic"),
                    opcode=mirror.get("opcode"),
                    reason=mirror.get("reason"),
                )

        self._metadata_record_event_v26(
            "legacy_edge_condition_truth_consumed_v72",
            src=self._addr_v26(src),
            dst=self._addr_v26(dst),
            expr=expr,
            trust=rec.get("trust") or rec.get("confidence"),
            reason=rec.get("invert_source")
            or rec.get("selection_reason")
            or rec.get("selection_source"),
        )
        return RawCond(
            expr,
            source=cond,
            inverted=str(expr).strip().startswith("not "),
            reason=(
                "protected_metadata_branch_mirror_not_v31"
                if mirror
                else (
                    rec.get("invert_source")
                    or rec.get("trust")
                    or rec.get("confidence")
                    or "legacy_metadata_edge_condition_truth_v72"
                )
            ),
        )

    def _metadata_not_expr_v30(self, expr):
        """Wrap an already-oriented predicate in NOT without double-negating."""
        s = str(expr or "").strip()
        if not s:
            return s
        if s.startswith("not "):
            return s
        return "not (%s)" % s

    def _metadata_branch_mirror_requires_not_v30(self, src, dst, rec=None):
        """Return protected branch-mirror metadata, or None.

        v31 tight rule:
          A raw-mnemonic/HF-opcode complement pair is not enough by itself.
          Ordinary switch/range/parity branches frequently need edge-oriented
          not(...) predicates, but they are not protected branch mirrors.

          Protected mirror NOT is allowed only when PAL metadata proves all of:
            1. the edge predicate is complement-shaped or explicitly inverted;
            2. the edge participates in loop-control custody;
            3. the edge/block has suspicious raw/HF successor custody.

          This remains address-agnostic and constant-agnostic.  It does not know
          alpha_four, 0x101235, local_18, or 0xf.
        """
        if rec is None:
            rec = self._edge_truth_record_v26(src, dst)

        mnemonic, opcode = self._metadata_mnemonic_opcode_pair_v29(src, dst)
        mnemonic = str(mnemonic or "").upper()
        opcode = str(opcode or "").upper()

        complement_reason = None

        if self._metadata_pair_is_complement_v29(mnemonic, opcode):
            complement_reason = "raw_mnemonic_hf_opcode_complement"

        if isinstance(rec, dict):
            try:
                if rec.get("invert_for_edge") is True:
                    complement_reason = complement_reason or "edge_invert_for_edge_metadata"
            except Exception:
                pass

            blob = " ".join(
                str(rec.get(k) or "")
                for k in (
                    "invert_source", "reason", "trust", "edge_reason",
                    "condition_reason", "condition_polarity_reason",
                    "condition_polarity", "role", "raw_type", "status",
                )
            ).lower()

            # Only explicit complement/mirror declarations count here.  The word
            # "invert" may appear in ordinary edge-polarity records and is too
            # broad for the protected branch-mirror class.
            if "complement" in blob or "mirror" in blob:
                complement_reason = complement_reason or "metadata_text_declares_complement"

        if not complement_reason:
            return None

        loop_custody = self._metadata_edge_has_loop_control_custody_v31(src, dst)
        suspicious = self._metadata_edge_has_suspicious_custody_v31(src, dst, rec)

        if not (loop_custody and suspicious):
            self._metadata_record_event_v26(
                "metadata_branch_mirror_rejected_v31",
                src=self._addr_v26(src),
                dst=self._addr_v26(dst),
                mnemonic=mnemonic,
                opcode=opcode,
                complement_reason=complement_reason,
                loop_custody=bool(loop_custody),
                suspicious_custody=bool(suspicious),
            )
            return None

        return {
            "mnemonic": mnemonic,
            "opcode": opcode,
            "reason": "protected_branch_mirror_v31:%s" % complement_reason,
            "loop_custody": True,
            "suspicious_custody": True,
        }

    def _metadata_edge_has_loop_control_custody_v31(self, src, dst):
        """True when src->dst is a loop-control edge, not an ordinary branch arm."""
        if src is None or dst is None:
            return False

        owner = self._innermost_loop_for_node(src)
        if owner is None:
            return False

        if dst is owner:
            return True

        try:
            if self._edge_continues_loop(src, dst) is owner:
                return True
        except Exception:
            pass

        try:
            if self._edge_exits_loop(src, dst) is owner:
                return True
        except Exception:
            pass

        try:
            if self._target_is_loop_latch_node(owner, dst):
                return True
        except Exception:
            pass

        try:
            if self._metadata_target_is_continuation_gateway_v26(dst, owner_loop=owner, from_node=src):
                return True
        except Exception:
            pass

        # Metadata sandwich fallback: some graph records already classify edge
        # custody textually even when CFG loop helpers are incomplete.
        text = self._role_text_for_edge_v28(src, dst)
        if any(tok in text for tok in (
            "latch", "backedge", "loop_exit", "loop-exit",
            "continue", "continuation_gateway", "normal_exit",
        )):
            return True

        return False

    def _metadata_edge_has_suspicious_custody_v31(self, src, dst, rec=None):
        """True for raw/HF successor-custody anomalies supplied by PAL metadata."""
        if rec is None:
            rec = self._edge_truth_record_v26(src, dst)

        blobs = []

        def add_obj(obj):
            if not isinstance(obj, dict):
                return
            for k in (
                "status", "palraw_status", "raw_status", "successor_status",
                "role", "raw_type", "trust", "invert_source", "reason",
                "edge_reason", "condition_reason", "condition_polarity_reason",
                "condition_source", "custody", "role_hint",
            ):
                v = obj.get(k)
                if v:
                    blobs.append(str(v))
            for k in (
                "successors_differ", "successor_mismatch", "mismatch",
                "hf_extra_successors", "raw_missing_successors",
                "raw_terminal_successors", "norm_successors",
            ):
                v = obj.get(k)
                if v not in (None, False, [], (), set(), ""):
                    blobs.append("%s=%r" % (k, v))

        add_obj(rec)
        add_obj(self._block_branch_custody_record_v26(src))
        add_obj(self._block_ownership_record_v26(src))
        add_obj(self._block_ownership_record_v26(dst))

        try:
            e = self._cfg_edge(src, dst)
            if e is not None:
                for attr in (
                    "status", "palraw_status", "raw_status", "successor_status",
                    "role", "raw_type", "type", "condition_polarity_reason",
                    "condition_polarity_source", "condition_source",
                ):
                    v = getattr(e, attr, None)
                    if v:
                        blobs.append(str(v))
                for attr in (
                    "successors_differ", "successor_mismatch",
                    "hf_extra_successors", "raw_missing_successors",
                ):
                    v = getattr(e, attr, None)
                    if v not in (None, False, [], (), set(), ""):
                        blobs.append("%s=%r" % (attr, v))
        except Exception:
            pass

        # Global suspicious-successor table from GraphBuilder.
        saddr = self._addr_v26(src)
        daddr = self._addr_v26(dst)
        for item in list(getattr(self, "suspicious_successor_custody", []) or []):
            if not isinstance(item, dict):
                continue
            is_src = item.get("src") == saddr or item.get("src_addr") == saddr or item.get("block") == saddr or item.get("block_addr") == saddr
            is_dst = item.get("dst") == daddr or item.get("dst_addr") == daddr or item.get("target") == daddr or item.get("target_addr") == daddr
            if is_src and (is_dst or daddr is None or item.get("dst") is None and item.get("dst_addr") is None):
                blobs.append(str(item))

        text = " ".join(blobs).lower()
        suspicious_tokens = (
            "successors_differ", "successor_mismatch", "mismatch",
            "order_fallback", "raw_true_order_fallback",
            "hf_extra", "raw_missing", "not seen in raw",
            "normalized_extra", "suspicious",
        )
        if any(tok in text for tok in suspicious_tokens):
            return True

        # A continuation gateway on a loop-control edge is also suspicious enough
        # for protected mirror use: it means the edge's destination is a
        # structuring substitute/join rather than the raw terminal target.
        try:
            owner = self._innermost_loop_for_node(src)
            if owner is not None and self._metadata_target_is_continuation_gateway_v26(dst, owner_loop=owner, from_node=src):
                return True
        except Exception:
            pass

        return False

    def _metadata_edge_invert_v26(self, src, dst):
        rec = self._edge_truth_record_v26(src, dst)
        if isinstance(rec, dict) and "invert_for_edge" in rec:
            value = rec.get("invert_for_edge")
            return value if isinstance(value, bool) else None
        return None

    def _metadata_edge_reason_v26(self, src, dst):
        rec = self._edge_truth_record_v26(src, dst)
        if not isinstance(rec, dict):
            return None
        return (
            rec.get("selection_reason")
            or rec.get("selection_source")
            or rec.get("invert_source")
            or rec.get("trust")
            or rec.get("confidence")
            or rec.get("role")
            or rec.get("raw_type")
        )

    def _metadata_edge_mnemonic_v26(self, src, dst=None):
        rec = self._edge_truth_record_v26(src, dst) if dst is not None else None
        if isinstance(rec, dict) and rec.get("mnemonic"):
            return str(rec.get("mnemonic")).upper()
        brec = self._block_branch_custody_record_v26(src)
        if isinstance(brec, dict) and brec.get("terminal_mnemonic"):
            return str(brec.get("terminal_mnemonic")).upper()
        return ""

    def _metadata_mnemonic_opcode_pair_v29(self, src, dst=None):
        """
        Extract raw branch mnemonic and HF/formula condition opcode from any
        available metadata/debug string.

        Some GraphBuilder iterations expose these as explicit fields; others
        only leave strings such as:
            mnemonic=JZ hf_cond_opcode=INT_NOTEQUAL
        in the reason/invert_source field.  SGL uses this only for generic
        branch/opcode complement pairs, never for address-specific repairs.
        """
        mnemonic = None
        opcode = None

        rec = self._edge_truth_record_v26(src, dst) if dst is not None else None
        if isinstance(rec, dict):
            for k in (
                "mnemonic", "branch_mnemonic", "terminal_mnemonic",
                "raw_mnemonic", "raw_terminal_mnemonic",
            ):
                v = rec.get(k)
                if v and not mnemonic:
                    mnemonic = str(v).upper()

            for k in (
                "hf_cond_opcode", "condition_opcode", "cond_opcode",
                "opcode", "hf_opcode",
            ):
                v = rec.get(k)
                if v and not opcode:
                    opcode = str(v).upper()

            blob = " ".join(
                str(rec.get(k) or "")
                for k in (
                    "invert_source", "reason", "trust", "edge_reason",
                    "condition_reason", "role", "raw_type", "status",
                )
            )
            if blob:
                if not mnemonic:
                    m = re.search(r"mnemonic\s*=\s*([A-Za-z][A-Za-z0-9_]*)", blob)
                    if m:
                        mnemonic = m.group(1).upper()
                if not opcode:
                    m = re.search(r"(?:hf_cond_opcode|condition_opcode|cond_opcode|opcode)\s*=\s*([A-Z_]+)", blob)
                    if m:
                        opcode = m.group(1).upper()

        if not mnemonic:
            mnemonic = self._metadata_edge_mnemonic_v26(src, dst) or self._edge_mnemonic_v23(src, dst)
            mnemonic = str(mnemonic or "").upper()

        if not opcode:
            opcode = self._condition_opcode_for_cfg_node_v19(src)
            opcode = str(opcode or "").upper()

        return mnemonic, opcode

    def _metadata_pair_is_complement_v29(self, mnemonic, opcode):
        """Generic raw-mnemonic/HF-opcode complement table."""
        m = str(mnemonic or "").upper()
        op = str(opcode or "").upper()

        if m in ("JZ", "JE") and op == "INT_NOTEQUAL":
            return True
        if m in ("JNZ", "JNE") and op == "INT_EQUAL":
            return True
        if m in ("JG", "JA", "JNLE", "JNBE") and op in (
            "INT_SLESS", "INT_LESS", "INT_SLESSEQUAL", "INT_LESSEQUAL"
        ):
            return True

        return False

    def _metadata_target_is_continuation_gateway_v26(self, target_node, owner_loop=None, from_node=None):
        """
        True when GraphBuilder/CFG structure marks target as a shared
        continuation/join/gateway that should not be inlined as branch-local
        action of owner_loop.

        v32 extends the original metadata-only rule with a conservative
        structural fallback: when an edge exits an inner loop to a conditional
        or postdominator join that belongs to an enclosing region and has other
        incoming paths, the target is a continuation gateway.  The inner loop
        arm should emit `break`; the enclosing region should emit the gateway.
        """
        rec = self._block_ownership_record_v26(target_node)
        if isinstance(rec, dict):
            role = str(rec.get("role_hint") or "").lower()

            gateway_role = bool(role) and any(x in role for x in (
                "gateway", "shared_join", "shared_condition", "shared_executable_join",
                "order_fallback", "enclosing_loop_condition",
            ))

            if gateway_role:
                owner_addr = self._addr_v26(owner_loop)
                not_owned = set(rec.get("not_owned_by_loops") or [])
                if owner_addr is not None and owner_addr in not_owned:
                    return True

                # For optimized CFGs, the successor may be a condition/join block
                # reached by an order-fallback or loop-exit edge.  Treat it as
                # shared continuation even when loop ownership maps are incomplete.
                if rec.get("condition_block") and (
                    rec.get("is_join")
                    or rec.get("incoming_order_fallback")
                    or rec.get("incoming_loop_exit")
                ):
                    return True

                if "order_fallback" in role or "enclosing_loop_condition" in role:
                    return True

        # v32 structural fallback.  This intentionally does not depend on a
        # particular address, constant, switch value, or test program.  It fires
        # only for nested-loop exits to shared enclosing-region joins/gateways.
        if self._structural_target_is_continuation_gateway_v32(
            target_node,
            owner_loop=owner_loop,
            from_node=from_node,
        ):
            return True

        return False

    def _structural_target_is_continuation_gateway_v32(self, target_node, owner_loop=None, from_node=None):
        """
        Conservative generic fallback for continuation-gateway ownership.

        A target is a structural continuation gateway for owner_loop when:
          * from_node is inside owner_loop;
          * target_node is outside owner_loop but still in an enclosing region;
          * target_node is a condition block, an ipdom/join, or has multiple
            predecessors; and
          * at least one incoming path comes from outside owner_loop, or an
            enclosing conditional region has target_node as ipdom and reaches
            from_node before that join.

        This prevents a nested loop's exit arm from swallowing the enclosing
        switch/if continuation condition as branch-local action.  Break the
        inner loop; emit the continuation at the enclosing region boundary.
        """
        if target_node is None or owner_loop is None or from_node is None:
            return False

        owner_nodes = set(self.loop_nodes.get(owner_loop, set()) or set())
        if not owner_nodes:
            return False

        if from_node not in owner_nodes:
            return False

        if target_node in owner_nodes:
            return False

        if target_node in self.loop_headers:
            return False

        if self._target_is_function_exit_block(target_node):
            return False

        if self._target_is_loop_tail_chain_node(target_node):
            return False

        # A plain single-predecessor cleanup/action block after a break is not
        # a shared continuation gateway.  Keep those as action+break.
        preds = list(self._predecessors(target_node) or [])
        pred_set = set(preds)
        outside_preds = [p for p in preds if p not in owner_nodes]
        inside_preds = [p for p in preds if p in owner_nodes]

        is_condition = self._get_condition(target_node) is not None
        is_shared_pred = len(pred_set) >= 2 and bool(outside_preds)

        # ipdom/enclosing-region evidence: some conditional/dispatch node
        # outside the inner loop uses target_node as its join, and that region
        # reaches the inner-loop latch/break source.  This captures switch/range
        # and if/else continuations without naming the construct.
        ipdom_join = False
        try:
            for n in self._real_nodes():
                if n is target_node or n in owner_nodes:
                    continue
                if getattr(n, "ipdom", None) is not target_node:
                    continue
                if self._reaches(n, from_node):
                    ipdom_join = True
                    break
        except Exception:
            ipdom_join = False

        if not (is_condition or is_shared_pred or ipdom_join):
            return False

        if not (outside_preds or ipdom_join):
            return False

        # If the target is executable but not conditional/shared, it may be a
        # cleanup block attached to a real break; do not steal it.  Conditional
        # executable joins are allowed, because they are region continuations.
        if self._node_has_executable_ops_cfg(target_node) and not is_condition and not ipdom_join:
            return False

        self._metadata_record_event_v26(
            "structural_continuation_gateway_v32",
            source="cfg_ipdom_predicate_fallback",
            from_addr=self._addr_v26(from_node),
            target=self._addr_v26(target_node),
            owner_loop=self._addr_v26(owner_loop),
            is_condition=is_condition,
            shared_pred=is_shared_pred,
            ipdom_join=ipdom_join,
            pred_count=len(pred_set),
            outside_pred_count=len(outside_preds),
            inside_pred_count=len(inside_preds),
        )
        return True

    def _node_by_addr_v27(self, addr):
        """Resolve integer block address back to a CFG node when possible."""
        if addr is None:
            return None
        try:
            nodes = getattr(self.cfg, "nodes", {}) or {}
            if addr in nodes:
                return nodes.get(addr)
            h = self._hex_v26(addr)
            if h in nodes:
                return nodes.get(h)
        except Exception:
            pass
        for n in self._real_nodes():
            if self._addr_v26(n) == addr:
                return n
        return None

    def _metadata_loop_continuation_gateway_nodes_v27(self, loop_header):
        """
        Return loop-exit continuation/gateway nodes supplied by GraphBuilder.
        These are normal post-loop continuation candidates, not branch-local
        action blocks.  SGL may emit them after the loop body, just as it emits
        normal guard exits.
        """
        facts = self._latch_facts_for_loop_v26(loop_header) or {}
        out = []
        for a in list(facts.get("continuation_gateways") or []):
            if not isinstance(a, int):
                continue
            n = self._node_by_addr_v27(a)
            if n is not None:
                out.append(n)
        return out

    def _metadata_edge_complement_requires_invert_v27(self, src, dst):
        """True only for the protected branch-mirror class.

        v31: raw mnemonic/HF opcode complement alone is ordinary edge
        orientation, not necessarily a protected mirror.  Require the same
        loop-control + suspicious-custody filter used by
        _metadata_branch_mirror_requires_not_v30().
        """
        rec = self._edge_truth_record_v26(src, dst)
        mirror = self._metadata_branch_mirror_requires_not_v30(src, dst, rec)
        if not mirror:
            return False

        self._metadata_record_event_v26(
            "protected_metadata_complement_pair_detected_v31",
            src=self._addr_v26(src),
            dst=self._addr_v26(dst),
            mnemonic=mirror.get("mnemonic"),
            opcode=mirror.get("opcode"),
            reason=mirror.get("reason"),
        )
        return True

    def _metadata_loop_update_blocks_v26(self, loop_header):
        facts = self._latch_facts_for_loop_v26(loop_header) or {}
        out = set()
        for k in ("update_blocks", "latch_blocks"):
            for a in list(facts.get(k) or []):
                if isinstance(a, int):
                    out.add(a)
        return out

    def _metadata_node_is_latch_update_for_loop_v26(self, loop_header, node):
        addr = self._addr_v26(node)
        if addr is None or loop_header is None:
            return False
        return addr in self._metadata_loop_update_blocks_v26(loop_header)

    def _metadata_action_reaches_latch_update_v26(self, loop_header, target_node, limit=4):
        """
        v27 conservative metadata-guided reachability to a known update/latch block.

        General rule: metadata may confirm a simple linear action-to-latch path,
        but it must not collapse structured branch arms.  If the candidate arm
        begins at, or crosses through, a conditional dispatch/gateway, SGL must
        emit the structure normally and let the latch appear through ordinary
        traversal or loop-exit handling.

        This prevents the O3 alpha_four class from degrading into:
            non-case-3 switch subtree -> default action + i++ + continue
        while still preserving simple forms such as:
            action block -> latch/update block -> loop header
        """
        if loop_header is None or target_node is None:
            return None, None

        update_addrs = self._metadata_loop_update_blocks_v26(loop_header)
        if not update_addrs:
            return None, None

        # Direct update/latch target is always safe.
        if self._addr_v26(target_node) in update_addrs:
            return [], target_node

        # Never summarize a branch arm whose root is itself conditional.  That
        # arm may be a switch/range ladder, short-circuit boolean, or early-exit
        # gateway.  Structuring it is more important than grabbing the latch.
        if self._get_condition(target_node) is not None:
            self._metadata_record_event_v26(
                "metadata_latch_path_rejected_structured_root_v27",
                loop=self._addr_v26(loop_header),
                target=self._addr_v26(target_node),
            )
            return None, None

        seen = set()
        cur = target_node
        prefix = []
        depth = 0

        while cur is not None and depth <= limit:
            if cur in seen:
                return None, None
            seen.add(cur)

            if cur in self.loop_headers and cur is not loop_header:
                return None, None
            if self._target_is_function_exit_block(cur):
                return None, None
            if self._is_loop_tail_chain_member(cur):
                return None, None
            if self._metadata_target_is_continuation_gateway_v26(cur, owner_loop=loop_header):
                return None, None
            if self._get_condition(cur) is not None:
                return None, None

            caddr = self._addr_v26(cur)
            if caddr in update_addrs:
                return prefix, cur

            if self._node_has_executable_ops_cfg(cur):
                prefix.append(cur)

            nxts = self._successors(cur)
            if len(nxts) != 1:
                return None, None

            nxt = nxts[0]
            # Do not cross into condition blocks or gateways just to reach a
            # latch.  That would erase the internal control structure.
            if nxt is not None:
                if self._get_condition(nxt) is not None:
                    return None, None
                if self._metadata_target_is_continuation_gateway_v26(nxt, owner_loop=loop_header):
                    return None, None

            cur = nxt
            depth += 1

        return None, None

    # ---------------------------------------------------------------------
    # v29: conditional latch truth + explicit loop-normal iterator epilogue support
    # ---------------------------------------------------------------------

    def _conditional_latch_edge_kind_v28(self, from_node, target_node, owner_loop):
        """
        Classify an edge inside a conditional latch-test relative to the loop it
        controls.  This deliberately separates edge semantics from CFG true/false
        labels so SGL can attach the condition to the edge that actually breaks
        or continues the loop.
        """
        if from_node is None or target_node is None or owner_loop is None:
            return None

        if target_node is owner_loop:
            return "continue"

        cont = self._edge_continues_loop(from_node, target_node)
        if cont is owner_loop:
            return "continue"

        br = self._edge_exits_loop(from_node, target_node)
        if br is owner_loop:
            return "exit"

        nodes = set(self.loop_nodes.get(owner_loop, set()) or set())
        if target_node in nodes:
            return "body"

        # If the source is inside the owner loop and the target is outside it,
        # treat it as an exit even when older CFG metadata did not tag the edge.
        if from_node in nodes and target_node not in nodes:
            return "exit"

        return None

    def _role_text_for_edge_v28(self, src, dst):
        parts = []
        rec = self._edge_truth_record_v26(src, dst)
        if isinstance(rec, dict):
            for k in ("role", "raw_type", "trust", "invert_source", "status"):
                v = rec.get(k)
                if v:
                    parts.append(str(v))
        try:
            parts.append(self._edge_role_text_v25(src, dst))
        except Exception:
            pass
        return " ".join(parts).lower()

    def _conditional_latch_edge_needs_invert_v28(self, src, dst, exit_kind=None, continue_peer=None):
        """
        Return True when the predicate printed for src->dst must be the
        complement of the raw/HF condition expression.  This handles generic
        raw/HF complement pairs first, then a conservative order-fallback
        pattern seen when a raw terminal target is normalized to a nearby
        continuation/gateway block.
        """
        if self._metadata_edge_complement_requires_invert_v27(src, dst):
            return True

        try:
            if self._edge_condition_invert_for_edge(src, dst):
                return True
        except Exception:
            pass

        mnemonic, opcode = self._metadata_mnemonic_opcode_pair_v29(src, dst)
        op = str(opcode or "").upper()

        # Conservative metadata-only fallback: a conditional latch-test whose
        # exit edge is an order-fallback/gateway while the peer continues to the
        # loop header is exactly the class where HF successor normalization can
        # attach the complement predicate to the wrong edge.  Limit this to
        # equality predicates and loop-control edges; ordinary if-statements do
        # not pass through this helper.
        role_text = self._role_text_for_edge_v28(src, dst)
        peer_text = self._role_text_for_edge_v28(src, continue_peer) if continue_peer is not None else ""
        if exit_kind == "exit" and ("order_fallback" in role_text or "gateway" in role_text):
            if ("latch" in peer_text or "backedge" in peer_text or continue_peer is not None):
                if op in ("INT_NOTEQUAL", "INT_EQUAL"):
                    return True

        return False

    def _condition_for_conditional_latch_edge_v28(self, src, dst, cond=None, exit_kind=None, continue_peer=None):
        """Return a RawCond true when the conditional-latch edge src->dst is taken."""
        base = self._raw_condition_expr_for_cfg_node(src) or self._cond_to_string_v19(cond)

        meta_cond = self._metadata_condition_for_edge_v26(src, dst, cond=cond)
        if meta_cond is not None:
            # v48: EdgeTruth/edge-condition metadata is edge-specific truth.
            #
            # alpha_four O0 exposed a legacy latch path that did this:
            #   1. EdgeTruth for src->dst supplied direct authoritative truth:
            #          (v_1743 != 0xf), invert_for_edge=False
            #   2. The older latch complement heuristic saw JZ + INT_NOTEQUAL
            #      and overrode that direct edge predicate with:
            #          not ((v_1743 != 0xf))
            #
            # That is backwards.  The complement/mirror heuristic is a fallback
            # for missing/ambiguous edge truth; it must not override a concrete
            # edge predicate that already states the expression for this exact
            # src->dst edge.
            ms = self._cond_to_string_v19(meta_cond)
            rec = self._edge_truth_record_v26(src, dst)
            if isinstance(rec, dict):
                explicit_inv = rec.get("invert_for_edge")
                conf = str(rec.get("confidence") or rec.get("trust") or "").lower()
                source = str(rec.get("selection_source") or rec.get("source") or "").lower()
                has_strong_edge_truth = conf in ("authoritative", "high") or "edge" in source
                if explicit_inv is False and has_strong_edge_truth:
                    try:
                        self._metadata_record_event_v26(
                            "conditional_latch_direct_edge_truth_preserved_v48",
                            src=self._addr_v26(src),
                            dst=self._addr_v26(dst),
                            expr=ms,
                            confidence=conf,
                            selection_source=source,
                            reason="direct_edge_truth_beats_legacy_notequal_complement",
                        )
                    except Exception:
                        pass
                    return meta_cond

            # If metadata already supplied an inverted edge expression, keep it.
            if ms and str(ms).strip().startswith("not "):
                return meta_cond

        if base and self._conditional_latch_edge_needs_invert_v28(
            src, dst, exit_kind=exit_kind, continue_peer=continue_peer
        ):
            s = str(base).strip()
            if s.startswith("not "):
                expr = s
            else:
                expr = "not (%s)" % s
            self._metadata_record_event_v26(
                "conditional_latch_edge_predicate_inverted_v28",
                src=self._addr_v26(src),
                dst=self._addr_v26(dst),
                expr=expr,
                opcode=self._condition_opcode_for_cfg_node_v19(src),
                role_text=self._role_text_for_edge_v28(src, dst),
            )
            return RawCond(
                expr,
                source=cond,
                inverted=True,
                reason="v28_conditional_latch_edge_complement",
            )

        if meta_cond is not None:
            return meta_cond

        return self._condition_for_edge(src, dst, cond=cond)

    def _metadata_loop_normal_epilogue_nodes_v28(self, loop_header):
        """
        Return simple executable latch/update nodes that should run after an
        ordinary fallthrough completion of a loop body.  These are not branch
        arms; they are the normal iterator epilogue of lowered for-like loops.
        """
        if loop_header is None:
            return []
        if loop_header in self.loop_body_headers:
            # Body-header do/while tail chains have their own epilogue lowering.
            return []

        facts = self._latch_facts_for_loop_v26(loop_header) or {}
        candidates = []
        for k in ("normal_epilogue_blocks", "update_blocks", "latch_blocks"):
            for a in list(facts.get(k) or []):
                if isinstance(a, int) and a not in candidates:
                    candidates.append(a)

        out = []
        for a in candidates:
            n = self._node_by_addr_v27(a)
            if n is None:
                continue
            if self._is_loop_tail_chain_member(n):
                continue
            if not self._node_has_executable_ops_cfg(n):
                continue
            # A normal epilogue latch must be a simple update block returning
            # directly to the loop header.  Reject conditional or multi-exit
            # blocks so we do not summarize structured control.
            if self._get_condition(n) is not None:
                continue
            succs = list(self._successors(n) or [])
            if not succs or any(s is not loop_header for s in succs):
                continue
            if n not in out:
                out.append(n)
        return out

    def _conditional_latch_target_is_loop_owned_epilogue_v52(
        self,
        owner_loop,
        from_node,
        target_node,
    ):
        """
        True when a conditional-latch arm points directly at the normal
        iterator/latch epilogue already owned by ``owner_loop``.

        This is a custody rule, not an address- or expression-specific repair.
        ``_emit_normal_latch_epilogue_for_loop_v28`` is the sole execution
        owner for metadata-proven normal epilogues.  Re-emitting the same block
        inside a surviving conditional arm duplicates the iterator update:

            if break_condition:
                break
            else:
                iterator += 1       # wrong arm-local copy
            iterator += 1           # loop-owned normal epilogue

        Required structural proof:
          * the source belongs to the owner loop;
          * the target is one of that loop's metadata-derived normal epilogue
            blocks;
          * the target is a plain executable block whose only successor is the
            owner loop header; and
          * the edge is not a loop exit.

        The normal-epilogue inventory already rejects conditional, multi-exit,
        tail-chain, and non-executable candidates.  The repeated checks here
        keep this consumer safe if an older metadata producer is incomplete.
        """
        if owner_loop is None or from_node is None or target_node is None:
            return False

        if target_node is owner_loop:
            return False
        if target_node in set(getattr(self, "loop_headers", set()) or set()):
            return False
        if self._target_is_loop_tail_chain_node(target_node):
            return False
        if self._target_is_function_exit_block(target_node):
            return False

        owner_nodes = set(self.loop_nodes.get(owner_loop, set()) or set())
        if from_node is not owner_loop and from_node not in owner_nodes:
            return False

        try:
            epilogue_nodes = set(
                self._metadata_loop_normal_epilogue_nodes_v28(owner_loop) or []
            )
        except Exception:
            epilogue_nodes = set()
        if target_node not in epilogue_nodes:
            return False

        if self._get_condition(target_node) is not None:
            return False
        if not self._node_has_executable_ops_cfg(target_node):
            return False

        successors = list(self._successors(target_node) or [])
        if not successors or any(s is not owner_loop for s in successors):
            return False

        try:
            if self._edge_exits_loop(from_node, target_node) is owner_loop:
                return False
        except Exception:
            pass

        return True

    def _exec_subtree_has_unconditional_loop_control_v28(self, node, loop_header):
        """
        True when the top-level body already ends in unconditional break/continue
        for this loop.  Used only as a coarse guard before appending a normal
        epilogue; branch-local controls remain branch-local and do not block the
        epilogue for other paths.
        """
        if node is None:
            return False
        k = getattr(node, "kind", None)
        if k in ("break", "continue"):
            target = getattr(node, "target_loop", None)
            return target is None or target is loop_header
        # Only a sequence whose last child is control should block epilogue.
        if k in ("sequence", "loop_body"):
            children = list(getattr(node, "children", []) or [])
            if not children:
                return False
            return self._exec_subtree_has_unconditional_loop_control_v28(children[-1], loop_header)
        return False

    def _exec_subtree_all_paths_terminate_for_loop_v41(self, node, loop_header):
        """
        Conservative all-path terminal test for loop bodies.

        This is narrower than general source cleanup.  It exists only to avoid
        appending the normal latch epilogue after a branch/switch ladder whose
        every visible arm already contains its own latch/update + continue (or
        other terminal control).

        It deliberately treats ordinary blocks and nested loops as fallthrough
        unless a later sequence element proves terminality.  For an if-node,
        both arms must terminate.  This catches the o3_alpha_two shape:

            if case_ladder:
                ... latch; continue
            else:
                ... latch; continue
            # normal latch epilogue here would be unreachable duplication
        """
        if node is None:
            return False

        kind = getattr(node, "kind", None)

        if kind in ("break", "continue", "return"):
            return True

        if kind == "if":
            then_branch = getattr(node, "then_branch", None)
            else_branch = getattr(node, "else_branch", None)
            return (
                self._exec_subtree_all_paths_terminate_for_loop_v41(then_branch, loop_header)
                and self._exec_subtree_all_paths_terminate_for_loop_v41(else_branch, loop_header)
            )

        if kind in ("sequence", "then", "else", "loop_body"):
            children = list(getattr(node, "children", []) or [])
            if not children:
                return False

            # Sequential execution: once a child terminates on every path, all
            # following children are unreachable for this path.  Earlier partial
            # terminals are okay because their fallthrough paths may be closed
            # by a later child.
            for child in children:
                if self._exec_subtree_all_paths_terminate_for_loop_v41(child, loop_header):
                    return True
            return False

        # Nested loops, blocks, and unknown nodes are conservative fallthrough.
        return False

    # ---------------------------------------------------------------------
    # v42 tail-position continue elision
    # ---------------------------------------------------------------------

    def _elide_tail_position_continues_v42(self):
        """
        Remove redundant continue leaves that occur in tail position of their
        own loop body after latch/update blocks have already been emitted.

        This is a source-shape cleanup, not a branch-truth decision.  It runs
        only after v41 normal-latch suppression, because the v41 proof needs
        explicit continue leaves to establish that every path has already
        closed through a latch/backedge.

        Safe class:
            while cond:
                if arm:
                    <action>
                    <latch update>
                    continue   # tail-position for this same while

        The explicit continue is equivalent to falling off the bottom of the
        while body, because there is no remaining code in that loop iteration.
        The latch/update block is preserved.
        """
        count = self._elide_tail_continues_walk_v42(getattr(self, "root", None))
        if count:
            self.branch_control_events.append({
                "kind": "tail_position_continue_elision_v42",
                "count": count,
                "reason": "continue_at_tail_of_own_loop_body",
            })
            self._metadata_record_event_v26(
                "tail_position_continue_elision_v42",
                count=count,
                reason="continue_at_tail_of_own_loop_body",
            )

    def _elide_tail_continues_walk_v42(self, node):
        if node is None:
            return 0

        count = 0
        kind = getattr(node, "kind", None)

        if kind == "loop":
            header = getattr(node, "header", None) or getattr(node, "cfg_node", None)
            count += self._elide_tail_continues_in_tail_context_v42(getattr(node, "body", None), header)

            # Recurse into nested structures that may not be in this loop body
            # shape for compatibility with older SGL trees.
            for child in list(getattr(node, "children", []) or []):
                if child is getattr(node, "body", None):
                    continue
                count += self._elide_tail_continues_walk_v42(child)
            return count

        for child in list(getattr(node, "children", []) or []):
            count += self._elide_tail_continues_walk_v42(child)

        for attr in ("body", "then_branch", "else_branch"):
            child = getattr(node, attr, None)
            if child is not None:
                count += self._elide_tail_continues_walk_v42(child)

        return count

    def _elide_tail_continues_in_tail_context_v42(self, node, loop_header):
        """
        Mutate only tail-position subtrees for loop_header.  Earlier siblings
        are traversed only to find nested loops; their continues are not tail
        continues for this loop because later code in the same iteration still
        exists.
        """
        if node is None:
            return 0

        kind = getattr(node, "kind", None)
        count = 0

        if kind in ("sequence", "then", "else", "loop_body"):
            children = list(getattr(node, "children", []) or [])
            if not children:
                return 0

            # Non-tail siblings may contain nested loops, but a continue there
            # is not redundant for this loop because following code exists.
            for child in children[:-1]:
                count += self._elide_tail_continues_walk_v42(child)

            last = children[-1]
            count += self._elide_tail_continues_in_tail_context_v42(last, loop_header)

            if self._continue_targets_loop_v42(last, loop_header):
                children.pop()
                setattr(node, "children", children)
                count += 1
            return count

        if kind == "if":
            count += self._elide_tail_continues_in_tail_context_v42(getattr(node, "then_branch", None), loop_header)
            count += self._elide_tail_continues_in_tail_context_v42(getattr(node, "else_branch", None), loop_header)
            return count

        if kind == "loop":
            # A nested loop has its own iteration boundary.  Clean it under its
            # own header, but do not treat its interior as tail-context for the
            # enclosing loop.
            count += self._elide_tail_continues_walk_v42(node)
            return count

        return count

    def _continue_targets_loop_v42(self, node, loop_header):
        if node is None or getattr(node, "kind", None) != "continue":
            return False

        target = getattr(node, "target_loop", None)
        if target is None:
            return True
        if target is loop_header:
            return True

        try:
            return getattr(target, "addr", None) == getattr(loop_header, "addr", None)
        except Exception:
            return False

    def _emit_normal_latch_epilogue_for_loop_v28(self, header, loop):
        """
        Append iterator/latch update blocks for ordinary fallthrough completion
        of the loop body.  Explicit continue arms still carry their own
        action+latch+continue sequence.  v41 adds a terminal-body guard: if the
        structured body already has no fallthrough path, the normal epilogue is
        unreachable CFG scaffolding and must not be appended.
        """
        if header is None or loop is None:
            return False
        nodes = self._metadata_loop_normal_epilogue_nodes_v28(header)
        if not nodes:
            return False
        if self._exec_subtree_has_unconditional_loop_control_v28(getattr(loop, "body", None), header):
            return False
        if self._exec_subtree_all_paths_terminate_for_loop_v41(getattr(loop, "body", None), header):
            self.branch_control_events.append({
                "kind": "normal_latch_epilogue_suppressed_v41",
                "loop": self._addr_v26(header),
                "candidate_blocks": [self._addr_v26(n) for n in nodes],
                "reason": "loop_body_all_paths_already_terminal",
            })
            self._metadata_record_event_v26(
                "normal_latch_epilogue_suppressed_v41",
                loop=self._addr_v26(header),
                blocks=[self._addr_v26(n) for n in nodes],
                reason="loop_body_all_paths_already_terminal",
            )
            return False

        emitted = []
        for n in nodes:
            b = ExecBlock(n)
            try:
                b.force_emit = True
                b.path_local_duplicate = True
                b.sgl_latch_epilogue = True
                b.latch_epilogue_header = header
                b.reason = "normal_latch_epilogue_v29"
            except Exception:
                pass
            loop.body.add(b)
            emitted.append(self._addr_v26(n))

        if emitted:
            # v29: make the epilogue edge explicit.  Some emitter/PHI paths
            # materialize iterator updates as branch-edge/drop-in transitions
            # rather than ordinary block assignments.  A naked epilogue block at
            # the end of the loop body can therefore be structurally present but
            # print-suppressed.  block + continue preserves the real backedge and
            # gives downstream layers the same edge context as explicit continue
            # arms, without summarizing away the structured body.
            cont = ExecContinue(header, "normal_latch_epilogue_continue_v29")
            try:
                cont.sgl_latch_epilogue_continue = True
                cont.latch_epilogue_blocks = list(emitted)
            except Exception:
                pass
            loop.body.add(cont)

            self.branch_control_events.append({
                "kind": "normal_latch_epilogue_v29",
                "loop": self._addr_v26(header),
                "blocks": emitted,
                "source": "semantic_graph_latch_update_facts_v29",
            })
            self._metadata_record_event_v26(
                "normal_latch_epilogue_emitted_v29",
                loop=self._addr_v26(header),
                blocks=emitted,
                explicit_continue=True,
            )
            return True
        return False

    def _edge_condition_invert_for_edge(self, src, dst):
        canonical = self._edge_truth_record_v40(src, dst)
        if isinstance(canonical, dict):
            authoritative, reason = (
                self._canonical_edge_truth_authority_v72(canonical)
            )
            if authoritative:
                return canonical.get("invert_for_edge")
            self._clothed_emperor_record_event_v72(
                "clothed_emperor_unresolved_invert_preserved_v72",
                src=self._addr_v26(src),
                dst=self._addr_v26(dst),
                consumer="edge_condition_invert_for_edge",
                reason=reason,
            )
            return None

        meta_inv = self._metadata_edge_invert_v26(src, dst)
        if meta_inv is not None:
            return meta_inv

        """
        v19/PALRAW: consume PALlibrary raw-condition polarity.

        CFG topology is owned by raw/HF edge metadata.  This helper says
        whether the HighFunction condition expression must be negated to
        describe THIS edge.
        """
        e = self._cfg_edge(src, dst)
        if e is None:
            return False

        for attr in ("condition_invert_for_edge", "invert_condition_for_edge", "condition_inverted_for_edge"):
            if hasattr(e, attr):
                try:
                    value = getattr(e, attr)
                    if isinstance(value, bool):
                        return value
                    if value is None:
                        return None
                except Exception:
                    pass

        # Fallback: if edge itself lacks flag but terminator says condition
        # is fallthrough-polarity, then explicit/true target edge needs not().
        pol = getattr(e, "condition_polarity", None)
        if pol == "fallthrough":
            raw_type = getattr(e, "raw_type", getattr(e, "type", None))
            role = getattr(e, "role", None)
            explicit = bool(
                getattr(e, "explicit_target", False) or
                getattr(e, "is_explicit_target", False) or
                role == "raw_true_explicit_target" or
                raw_type == "true"
            )
            return explicit

        return False

    def _edge_condition_reason(self, src, dst):
        meta_reason = self._metadata_edge_reason_v26(src, dst)
        if meta_reason:
            return meta_reason

        e = self._cfg_edge(src, dst)
        if e is None:
            return None
        return (
            getattr(e, "condition_polarity_reason", None)
            or getattr(e, "condition_polarity", None)
            or getattr(e, "role", None)
            or getattr(e, "raw_type", None)
        )

    def _edge_role_text_v25(self, src, dst):
        e = self._cfg_edge(src, dst)
        if e is None:
            return ""
        vals = []
        for attr in (
            "role", "raw_type", "type", "condition_polarity_reason",
            "condition_polarity_source", "condition_source",
        ):
            val = getattr(e, attr, None)
            if val:
                vals.append(str(val))
        return " ".join(vals).lower()

    def _edge_is_raw_true_explicit_target_v25(self, src, dst):
        e = self._cfg_edge(src, dst)
        if e is None:
            return False

        role = getattr(e, "role", None)
        raw_type = getattr(e, "raw_type", getattr(e, "type", None))

        if role == "raw_true_explicit_target" or raw_type == "true":
            return True

        return bool(
            getattr(e, "explicit_target", False)
            or getattr(e, "is_explicit_target", False)
        )

    def _edge_successors_match_or_unknown_v25(self, src, dst):
        """
        Trust only edge-local facts. PALRAW may attach status strings to an
        edge in newer PALlibrary builds, but older builds expose only topology.
        Absence of a status is not failure.
        """
        e = self._cfg_edge(src, dst)
        if e is None:
            return False

        for attr in ("status", "palraw_status", "raw_status", "successor_status"):
            val = getattr(e, attr, None)
            if val:
                s = str(val).lower()
                if "successors_differ" in s or "mismatch" in s:
                    return False
                if "successors_match" in s or "match" in s:
                    return True

        return True

    def _edge_is_latch_to_header_v25(self, src, dst):
        if src is None or dst is None:
            return False

        if self._edge_is_latch_edge(src, dst):
            return True

        role_text = self._edge_role_text_v25(src, dst)
        if "latch_to_header" in role_text:
            return True

        try:
            if dst in self.loop_headers and src in set(self.loop_latches.get(dst, []) or []):
                return True
        except Exception:
            pass

        return False

    def _edge_invert_is_protected_latch_v25(self, src, dst, base_expr=None):
        """
        Protect valid latch-to-header edges from being discarded as
        malformed/low-confidence merely because the HF predicate shape is
        source-unpleasant or contains a post-update expression.

        Narrow rule:
          - edge already requests inversion;
          - edge is a latch/backedge to a loop header;
          - edge is raw true explicit target;
          - successor topology is not known-bad;
          - mnemonic/HF-opcode form is one of the observed complementary
            compare/test classes.

        Alpha-Four tail:
            JLE header with HF INT_SLESS const < var
        becomes:
            if not (const < var): continue
        """

        if not self._edge_condition_invert_for_edge(src, dst):
            return False

        if not self._edge_is_latch_to_header_v25(src, dst):
            return False

        if not self._edge_is_raw_true_explicit_target_v25(src, dst):
            return False

        if not self._edge_successors_match_or_unknown_v25(src, dst):
            return False

        mnemonic = self._edge_mnemonic_v23(src, dst)
        opcode = self._condition_opcode_name_v23(src)
        expr = str(base_expr or self._raw_condition_expr_for_cfg_node(src) or "")

        compare_ops = ("INT_SLESS", "INT_LESS", "INT_SLESSEQUAL", "INT_LESSEQUAL")
        equality_ops = ("INT_EQUAL", "INT_NOTEQUAL")

        if mnemonic in ("JLE", "JBE", "JNG", "JNA"):
            if opcode in compare_ops or "<" in expr or "<=" in expr:
                return True

        if mnemonic in ("JG", "JA", "JNLE", "JNBE"):
            if opcode in compare_ops or "<" in expr or "<=" in expr:
                return True

        if mnemonic in ("JZ", "JE", "JNZ", "JNE"):
            if opcode in equality_ops or "==" in expr or "!=" in expr:
                return True

        return False

    def _raw_condition_expr_for_cfg_node(self, cfg_node):
        expr = self._cond_expr_raw(cfg_node)
        if expr is None:
            cond = self._get_condition(cfg_node)
            if cond is None:
                return None
            return getattr(cond, "name", None) or str(cond)
        return expr

    def _edge_has_high_confidence_raw_condition_v22(self, src, dst):
        """
        v23 compatibility name.  Return True only when raw/machine predicate
        text is explicitly attached to the edge, not merely when a topology
        edge exists.  Inversion trust is decided separately by
        _edge_invert_is_trustworthy_v23().
        """
        e = self._cfg_edge(src, dst)
        if e is None:
            return False

        for attr in (
            "raw_condition_expr", "raw_terminal_condition", "raw_branch_condition",
            "machine_condition", "terminal_condition_expr",
        ):
            val = getattr(e, attr, None)
            if val:
                return True

        reason = str(
            getattr(e, "condition_polarity_reason", "") or
            getattr(e, "condition_polarity_source", "") or
            getattr(e, "condition_source", "") or ""
        ).lower()
        return "raw_expr" in reason or "machine_expr" in reason or "palraw_expr" in reason

    def _condition_opcode_name_v23(self, src):
        try:
            n = self._condition_formula_node(src)
            if n is not None:
                op = getattr(n, "opcode", None)
                if op:
                    return str(op)
        except Exception:
            pass

        try:
            cond = self._get_condition(src)
            op = self._find_block_def_op(src, cond)
            if op is not None:
                opcode = getattr(op, "opcode", None)
                if opcode:
                    return str(opcode)
        except Exception:
            pass

        return ""

    def _edge_mnemonic_v23(self, src, dst=None):
        meta_m = self._metadata_edge_mnemonic_v26(src, dst)
        if meta_m:
            return meta_m

        e = self._cfg_edge(src, dst) if dst is not None else None

        candidates = []
        if e is not None:
            for attr in ("mnemonic", "branch_mnemonic", "terminal_mnemonic", "raw_mnemonic"):
                val = getattr(e, attr, None)
                if val:
                    candidates.append(str(val))

        if e is not None:
            reason = str(
                getattr(e, "condition_polarity_reason", "") or
                getattr(e, "condition_polarity_source", "") or
                getattr(e, "condition_source", "") or
                getattr(e, "role", "") or ""
            )
            candidates.append(reason)

        for c in candidates:
            m = re.search(r"mnemonic\s*=\s*([A-Za-z][A-Za-z0-9_]*)", c)
            if m:
                return m.group(1).upper()
            s = c.strip().upper()
            if re.match(r"^J[A-Z]+$", s):
                return s

        return ""

    def _edge_invert_is_trustworthy_v23(self, src, dst, base_expr=None):
        """
        Decide whether an edge inversion bit should be consumed.

        Raw topology always owns successor identity.  Predicate inversion is
        consumed only for mnemonic/HF-opcode pairs whose meaning is stable.
        This deliberately omits malformed abstractions instead of blindly
        applying either HF or RAW polarity.

        Examples from Sample X:
          JLE + INT_SLESS + (x < C+1)  => do NOT invert
          JG  + INT_SLESS + (x < C+1)  => invert
          JNZ + INT_EQUAL              => invert
          JZ  + INT_NOTEQUAL           => invert
        """
        if not self._edge_condition_invert_for_edge(src, dst):
            return False

        mnemonic = self._edge_mnemonic_v23(src, dst)
        opcode = self._condition_opcode_name_v23(src)
        expr = str(base_expr or self._raw_condition_expr_for_cfg_node(src) or "")

        # Equality/test pairs.
        if mnemonic in ("JNZ", "JNE"):
            if opcode == "INT_EQUAL" or "==" in expr:
                return True
            if opcode == "INT_NOTEQUAL" or "!=" in expr:
                return False

        if mnemonic in ("JZ", "JE"):
            if opcode == "INT_NOTEQUAL" or "!=" in expr:
                return True
            if opcode == "INT_EQUAL" or "==" in expr:
                return False

        # Signed/unsigned greater-than against an HF less-than predicate.
        # A JG/JNLE target is the complement of x < C(+1).
        if mnemonic in ("JG", "JA", "JNLE", "JNBE"):
            if opcode in ("INT_SLESS", "INT_LESS", "INT_SLESSEQUAL", "INT_LESSEQUAL") or "<" in expr:
                return True

        # JLE/JBE often appears as an already-adjusted HF less-than predicate
        # such as x < 0xc9 for source x <= 0xc8.  Do not invert that form.
        if mnemonic in ("JLE", "JBE", "JNG", "JNA"):
            if opcode in ("INT_SLESS", "INT_LESS", "INT_SLESSEQUAL", "INT_LESSEQUAL") or "<" in expr:
                return False

        # If PALlibrary later supplies explicit machine condition text, trust it.
        return self._edge_has_high_confidence_raw_condition_v22(src, dst)

    def _raw_edge_condition_expr_v22(self, src, dst):
        e = self._cfg_edge(src, dst)
        if e is not None:
            for attr in (
                "raw_condition_expr", "raw_terminal_condition", "raw_branch_condition",
                "machine_condition", "terminal_condition_expr",
            ):
                val = getattr(e, attr, None)
                if isinstance(val, str) and val.strip():
                    return val.strip()
                if val is not None and not isinstance(val, bool):
                    s = str(val).strip()
                    if s:
                        return s
        return self._raw_condition_expr_for_cfg_node(src)

    def _select_condition_expr_for_edge_v22(self, src, dst, cond=None):
        """
        v23 RAW/HF arbitration rule.

        Topology is raw-CFG owned. Predicate text usually comes from the best
        HF/formula expression.  Edge inversion is consumed only when the
        branch mnemonic and HF predicate opcode form a stable complementary
        pair; otherwise the abstraction is treated as malformed/low-confidence
        and omitted.
        """
        base_expr = self._raw_edge_condition_expr_v22(src, dst)
        if base_expr is None:
            return None, None

        invert = self._edge_condition_invert_for_edge(src, dst)
        reason = self._edge_condition_reason(src, dst)

        if invert:
            if self._edge_invert_is_trustworthy_v23(src, dst, base_expr):
                try:
                    self.condition_source_events.append({
                        "kind": "applied_trusted_edge_invert_v23",
                        "src": getattr(src, "addr", None),
                        "dst": getattr(dst, "addr", None),
                        "expr": base_expr,
                        "mnemonic": self._edge_mnemonic_v23(src, dst),
                        "opcode": self._condition_opcode_name_v23(src),
                        "reason": reason,
                    })
                except Exception:
                    pass
                return "not (%s)" % base_expr, reason or "trusted_edge_invert_v23"

            # v25: latch-to-header edges are not ordinary branch prettification.
            # If raw topology says this is the true explicit latch edge and the
            # mnemonic/HF-opcode pair is the known complementary form, preserve
            # the edge by applying inversion rather than dropping it as
            # low-confidence.
            if self._edge_invert_is_protected_latch_v25(src, dst, base_expr):
                try:
                    self.condition_source_events.append({
                        "kind": "applied_protected_latch_edge_invert_v25",
                        "src": getattr(src, "addr", None),
                        "dst": getattr(dst, "addr", None),
                        "expr": base_expr,
                        "mnemonic": self._edge_mnemonic_v23(src, dst),
                        "opcode": self._condition_opcode_name_v23(src),
                        "reason": reason,
                    })
                except Exception:
                    pass
                return "not (%s)" % base_expr, reason or "protected_latch_edge_invert_v25"

            try:
                self.condition_source_events.append({
                    "kind": "omitted_malformed_or_low_confidence_edge_invert_v23",
                    "src": getattr(src, "addr", None),
                    "dst": getattr(dst, "addr", None),
                    "expr": base_expr,
                    "mnemonic": self._edge_mnemonic_v23(src, dst),
                    "opcode": self._condition_opcode_name_v23(src),
                    "reason": reason,
                })
            except Exception:
                pass
            return base_expr, "hf_formula_invert_omitted_v23"

        return base_expr, reason or "edge_direct"

    def _condition_for_edge(self, src, dst, cond=None):
        """
        Return a condition object true when execution takes src -> dst.

        v26 first consumes GraphBuilder edge_condition_truth when present.
        v22 fallback keeps raw-CFG topology, but arbitrates predicate text
        between machine/raw and HF/formula sources. Low-confidence RAW/HF
        polarity is not allowed to silently invert ordinary branch conditions.
        """
        if src is None or dst is None:
            return cond if cond is not None else self._get_condition(src)

        # v72: if canonical truth exists for either binary successor, both
        # records must be authoritative and complementary before any one edge
        # can govern executable structure.
        self._require_binary_edge_truth_pair_v72(
            src,
            consumer="condition_for_edge",
        )

        meta_cond = self._metadata_condition_for_edge_v26(src, dst, cond=cond)
        if meta_cond is not None:
            return meta_cond

        expr, reason = self._select_condition_expr_for_edge_v22(src, dst, cond=cond)
        if expr is None:
            return cond if cond is not None else self._get_condition(src)

        return RawCond(expr, source=cond, inverted=str(expr).strip().startswith("not "), reason=reason)

    def _condition_for_branch_then(self, src, then_node, cond=None):
        return self._condition_for_edge(src, then_node, cond=cond)

    def _condition_for_loop_exit_edge(self, header):
        """
        For single-exit loop headers, return the predicate under which the
        loop exits.  The emitter already wraps these as while-not(exit_cond)
        for this SGL shape.
        """
        true_node = self._true_edge(header)
        false_node = self._false_edge(header)

        true_exits = self._edge_exits_loop(header, true_node) is header
        false_exits = self._edge_exits_loop(header, false_node) is header

        if true_exits and not false_exits:
            return self._condition_for_edge(header, true_node, cond=self._get_condition(header))

        if false_exits and not true_exits:
            return self._condition_for_edge(header, false_node, cond=self._get_condition(header))

        return None


    def _condition_for_loop_body_edge(self, header):
        """
        For single-exit header loops rendered by emitter as while <cond>,
        return the predicate under which the loop body executes.
        """
        true_node = self._true_edge(header)
        false_node = self._false_edge(header)

        true_exits = self._edge_exits_loop(header, true_node) is header
        false_exits = self._edge_exits_loop(header, false_node) is header

        if true_exits and not false_exits:
            return self._condition_for_edge(header, false_node, cond=self._get_condition(header))

        if false_exits and not true_exits:
            return self._condition_for_edge(header, true_node, cond=self._get_condition(header))

        return None


    def _cond_to_string_v19(self, cond):
        if cond is None:
            return None
        for attr in ("const_value", "value", "offset", "name"):
            v = getattr(cond, attr, None)
            if isinstance(v, str) and v:
                return v
        return str(cond)

    def _strip_redundant_outer_parens_v19(self, s):
        if s is None:
            return None
        s = str(s).strip()
        changed = True
        while changed and s.startswith("(") and s.endswith(")"):
            changed = False
            depth = 0
            ok = True
            for i, ch in enumerate(s):
                if ch == "(":
                    depth += 1
                elif ch == ")":
                    depth -= 1
                    if depth == 0 and i != len(s) - 1:
                        ok = False
                        break
            if ok:
                s = s[1:-1].strip()
                changed = True
        return s

    def _negated_less_inner_v19(self, expr):
        """
        Return (var, inner_expr) for strings like:
            not ((local_20 < 3))
            not (((local_1c < 2)))

        Used only as a guarded induction-loop repair, not as a general
        expression simplifier.
        """
        s = self._strip_redundant_outer_parens_v19(expr)
        if not s or not s.startswith("not "):
            return None, None

        inner = s[4:].strip()
        inner = self._strip_redundant_outer_parens_v19(inner)

        m = re.match(r"^([A-Za-z_][A-Za-z0-9_]*)\s*<\s*(0x[0-9a-fA-F]+|\d+)$", inner)
        if not m:
            return None, None

        return m.group(1), inner

    def _loop_has_positive_induction_update_v19(self, header, var_name):
        """
        Detect simple positive induction updates feeding a loop-header PHI.

        v20b broadens v19:
          - v19 only accepted direct output-to-local updates:
                INT_ADD local_20, 1 -> local_20
          - Ghidra/O0 commonly uses:
                INT_ADD local_20, 1 -> v_1678
                MULTIEQUAL [local_20, v_1678] -> local_20

        The second form is the alpha_two j/k/i loop shape.  This routine
        therefore accepts either direct local writes or temp writes that feed
        a header MULTIEQUAL whose output is var_name.
        """
        if header is None or not var_name:
            return False

        def const_int(v):
            if v is None:
                return None
            if getattr(v, "is_constant", False):
                for attr in ("const_value", "value", "offset"):
                    val = getattr(v, attr, None)
                    if isinstance(val, int):
                        return val
            # Some PAL varnodes do not expose is_constant reliably.
            for attr in ("const_value", "value", "offset"):
                val = getattr(v, attr, None)
                if isinstance(val, int):
                    return val
            return None

        def is_positive_one(opcode, c):
            if opcode == "INT_ADD" and c in (1,):
                return True
            if opcode == "INT_SUB" and c in (-1, 0xffffffff, 0xffffffffffffffff):
                return True
            return False

        # Header PHI source sids that close into var_name.
        phi_source_sids = set()
        hblock = getattr(header, "block", None)
        if hblock is not None:
            for op in list(getattr(hblock, "ops", []) or []):
                if getattr(op, "opcode", None) != "MULTIEQUAL":
                    continue
                out = getattr(op, "output", None)
                if self._var_expr(out) != var_name:
                    continue
                for inp in list(getattr(op, "inputs", []) or []):
                    sid = getattr(inp, "ssa_id", None)
                    if sid is not None:
                        phi_source_sids.add(sid)

        nodes = set(self.loop_nodes.get(header, set()) or set())
        nodes.add(header)

        # Include latches/tail nodes explicitly; some natural-loop maps exclude
        # executable latch blocks in O0 CFGs.
        for n in list(self.loop_latches.get(header, []) or []):
            if n is not None:
                nodes.add(n)

        tail_chain = self.loop_tail_chains.get(header, None)
        if tail_chain:
            try:
                for n in tail_chain:
                    if n is not None:
                        nodes.add(n)
            except TypeError:
                nodes.add(tail_chain)

        for n in nodes:
            block = getattr(n, "block", None)
            if block is None:
                continue

            for op in list(getattr(block, "ops", []) or []):
                opcode = getattr(op, "opcode", None)
                if opcode not in ("INT_ADD", "INT_SUB"):
                    continue

                inputs = list(getattr(op, "inputs", []) or [])
                if len(inputs) != 2:
                    continue

                non_const = None
                const_val = None

                for inp in inputs:
                    c = const_int(inp)
                    if c is not None:
                        const_val = c
                    else:
                        non_const = inp

                if non_const is None or const_val is None:
                    continue

                if self._var_expr(non_const) != var_name:
                    continue

                if not is_positive_one(opcode, const_val):
                    continue

                out = getattr(op, "output", None)
                out_name = self._var_expr(out)
                out_sid = getattr(out, "ssa_id", None)

                # Direct local update.
                if out_name == var_name:
                    return True

                # SSA temp update closing into header PHI target.
                if out_sid is not None and out_sid in phi_source_sids:
                    return True

        return False

    def _repair_induction_loop_condition_v19(self, header, cond):
        """
        v19/v19b: Single-exit loop predicate correction.

        v19 fixed alpha_four's mutated gamma loop by using the body edge
        predicate, but alpha_two exposed a regression for ordinary induction
        loops:
            j = 0
            while not (j < 3):   # wrong, never enters

        If the condition is exactly not(var < const) and the loop body has a
        positive induction update for var, strip the not and use var < const.
        """
        expr = self._cond_to_string_v19(cond)
        var_name, inner = self._negated_less_inner_v19(expr)
        if not var_name or not inner:
            return cond

        if self._loop_has_positive_induction_update_v19(header, var_name):
            return RawCond(
                inner,
                source=cond,
                inverted=False,
                reason="v19_induction_loop_body_predicate_repair",
            )

        return cond

    def _normalize_loop_condition_role_v20(self, header, cond, role):
        """
        v21c: normalize loop role/predicate from edge custody first.

        Emitter contract:
            role=body -> while cond
            role=exit -> while not(cond)
            role=true -> while True

        If raw/HF true edge enters the loop body, raw condition is body-admit.
        If raw/HF true edge exits and false edge enters, raw condition is exit.
        Textual/induction heuristics are fallback only.
        """

        original_cond, original_role = cond, role

        def record(new_cond, new_role, why):
            try:
                self.loop_condition_events.append({
                    "header": getattr(header, "addr", None),
                    "old_cond": getattr(original_cond, "name", original_cond),
                    "old_role": original_role,
                    "new_cond": getattr(new_cond, "name", new_cond),
                    "new_role": new_role,
                    "why": why,
                })
            except Exception:
                pass
            return new_cond, new_role

        if role in (None, "true") or cond is None:
            return cond, role

        true_node = self._true_edge(header)
        false_node = self._false_edge(header)

        true_body = self._edge_enters_loop_body_v21b(header, true_node)
        false_body = self._edge_enters_loop_body_v21b(header, false_node)

        # v40: if canonical EdgeTruth exists, bind loop condition to the exact
        # body edge predicate.  This prevents exit predicates such as j >= 3
        # from being printed as while-body predicates for forward induction
        # loops, while preserving body-header forms such as gamma >= 1 when
        # EdgeTruth says that exact edge admits the loop body.
        if true_body and not false_body:
            et_cond = self._edgetruth_condition_for_edge_v40(header, true_node, cond=cond)
            if et_cond is not None:
                return record(et_cond, "body", "v40_edge_truth_true_body_predicate")

        if false_body and not true_body:
            et_cond = self._edgetruth_condition_for_edge_v40(header, false_node, cond=cond)
            if et_cond is not None:
                return record(et_cond, "body", "v40_edge_truth_false_body_predicate")

        # Edge truth first: raw true condition points to body.
        if true_body and not false_body:
            # Strip a not(var<const) only when the raw/HF edge itself did NOT
            # require inversion.  This preserves Sample Y's meaningful
            # gamma-loop predicate while fixing Sample X's accidental j/k
            # loop inversion.
            stripped = self._strip_accidental_negated_body_predicate_v21c(header, cond, true_node)
            if stripped is not cond:
                return record(stripped, "body", "true_edge_body_strip_accidental_not_no_edge_invert")
            if role != "body":
                return record(cond, "body", "true_edge_enters_body")
            return cond, role

        # Edge truth: raw true condition points away from body; false enters.
        if false_body and not true_body:
            raw = self._strip_simple_not_rawcond_v21b(cond)
            if raw is not None:
                # cond was already negated into a body predicate.
                return record(raw, "body", "false_edge_body_negated_condition")
            if role != "exit":
                return record(cond, "exit", "true_edge_exits_false_edge_body")
            return cond, role

        # Fallback 1: role=body with not(var < const) and positive induction.
        if role == "body":
            repaired = self._repair_induction_loop_condition_v19(header, cond)
            if repaired is not cond:
                return record(repaired, "body", "strip_negated_induction_body_predicate")

        # Fallback 2: role=body with const < var under positive induction is exit.
        expr = self._cond_to_string_v19(cond)
        expr_clean = self._strip_redundant_outer_parens_v19(expr)

        if role == "body" and expr_clean:
            m = re.match(
                r"^(0x[0-9a-fA-F]+|\d+)\s*<\s*([A-Za-z_][A-Za-z0-9_]*)$",
                expr_clean,
            )
            if m:
                var_name = m.group(2)
                return record(RawCond(
                    expr_clean,
                    source=cond,
                    inverted=False,
                    reason="v21c_const_less_var_exit_predicate",
                ), "exit", "const_less_var_exit_predicate")

        # Fallback 3: formula-level const < var.
        if role == "body":
            formula = self._condition_formula_node(header)
            if formula is not None:
                opcode = getattr(formula, "opcode", None)
                inputs = list(getattr(formula, "inputs", []) or [])

                if opcode in ("INT_LESS", "INT_SLESS") and len(inputs) == 2:
                    left, right = inputs[0], inputs[1]
                    if getattr(left, "is_constant", False) and not getattr(right, "is_constant", False):
                        var_name = self._var_expr(right)
                        exit_expr = "%s < %s" % (self._const_expr(left), var_name)
                        return record(RawCond(
                            exit_expr,
                            source=cond,
                            inverted=False,
                            reason="v21c_formula_const_less_var_exit_predicate",
                        ), "exit", "formula_const_less_var_exit_predicate")

        return cond, role

    def _edge_enters_loop_body_v21b(self, header, node):
        if header is None or node is None:
            return False

        nodes = set(self.loop_nodes.get(header, set()) or set())
        if node in nodes and node is not header:
            return True

        # If natural-loop membership is incomplete, body successors normally
        # reach the header/latch again without crossing a known exit. Keep this
        # conservative and bounded.
        try:
            if node is not header and self._reaches(node, header):
                return True
        except Exception:
            pass

        return False

    def _strip_simple_not_rawcond_v21b(self, cond):
        s = self._cond_to_string_v19(cond)
        if not s:
            return None
        s = self._strip_redundant_outer_parens_v19(s)
        if not s.startswith("not "):
            return None
        inner = self._strip_redundant_outer_parens_v19(s[4:].strip())
        if not inner:
            return None
        return RawCond(
            inner,
            source=cond,
            inverted=False,
            reason="v21c_strip_simple_not_rawcond",
        )

    def _strip_accidental_negated_body_predicate_v21c(self, header, cond, body_node=None):
        """
        Strip not(var<const) only when edge metadata says the body edge did not
        require condition inversion.

        Sample X j/k:
            raw true edge enters body, HF cond is var<const, no edge invert,
            but SGL carried not(var<const). Strip.

        Sample Y gamma loop:
            body predicate is genuinely not(local_18<1) due to raw/HF polarity.
            Edge invert is present, so keep it.
        """
        if body_node is not None:
            try:
                if self._edge_condition_invert_for_edge(header, body_node):
                    return cond
            except Exception:
                pass

        s = self._cond_to_string_v19(cond)
        if not s:
            return cond

        var_name, inner = self._negated_less_inner_v19(s)
        if var_name and inner:
            return RawCond(
                inner,
                source=cond,
                inverted=False,
                reason="v21c_true_edge_body_strip_negated_less_no_edge_invert",
            )

        return cond


    def _condition_opcode_for_cfg_node_v19(self, cfg_node):
        node = self._condition_formula_node(cfg_node)
        if node is not None:
            return getattr(node, "opcode", None)

        cond = self._get_condition(cfg_node)
        op = self._find_block_def_op(cfg_node, cond)
        if op is not None:
            return getattr(op, "opcode", None)

        return None

    def _repair_conditional_latch_break_condition_v19(self, node, owner, true_node, false_node, cond):
        """
        v19/v19b narrow fallback for internal raw targets such as alpha_four
        0x101235 -> 0x101252, where raw normalization should map the JZ target
        to the loop-exit block but older PALlibrary metadata may not yet expose
        condition_invert_for_edge.

        Pattern:
            then arm exits/breaks loop
            else arm continues loop
            condition opcode is INT_NOTEQUAL
        Therefore break must be when NOT(condition).
        """
        if node is None or owner is None:
            return cond

        true_exit = self._edge_exits_loop(node, true_node) is owner
        false_exit = self._edge_exits_loop(node, false_node) is owner
        true_cont = self._edge_continues_loop(node, true_node) is owner or true_node is owner
        false_cont = self._edge_continues_loop(node, false_node) is owner or false_node is owner

        if not (true_exit and false_cont and not false_exit):
            return cond

        cond_text = self._cond_to_string_v19(cond)
        if cond_text and str(cond_text).strip().startswith("not "):
            return cond

        opcode = self._condition_opcode_for_cfg_node_v19(node)
        raw_expr = self._raw_condition_expr_for_cfg_node(node) or cond_text
        if not raw_expr:
            return cond

        # v27: if raw mnemonic/HF opcode or edge_condition_truth says the
        # break edge is taken on the complement of the HF condition, force the
        # condition attached to the then/break arm to be the edge predicate.
        # This is generic branch-predicate custody, not an alpha_four literal.
        if self._metadata_edge_complement_requires_invert_v27(node, true_node):
            return RawCond(
                "not (%s)" % raw_expr,
                source=cond,
                inverted=True,
                reason="v27_complementary_raw_edge_break_predicate",
            )

        if opcode != "INT_NOTEQUAL":
            return cond

        # v47: retire the old blind INT_NOTEQUAL internal-break inversion.
        #
        # The original v19 fallback assumed this shape meant the break predicate
        # must be the complement of the HF condition:
        #
        #     true arm exits/breaks loop
        #     false arm continues loop
        #     opcode == INT_NOTEQUAL
        #     no mnemonic/polarity metadata available
        #
        # alpha_four O0 disproves that assumption.  The block can contain a
        # direct ground-truth comparison such as:
        #
        #     INT_NOTEQUAL [call_result, 0xf]
        #     CBRANCH cond
        #
        # and the true edge is exactly the break edge.  Inverting here poisons
        # PHIfolder post_update_condition_aliases and later the emitter prints
        # `if x == 0xf: break`.
        #
        # We already handled the only safe complement case above via explicit
        # edge metadata (`_metadata_edge_complement_requires_invert_v27`).  If
        # that evidence is absent, preserve raw condition truth.
        try:
            self.branch_control_events.append({
                "kind": "retired_blind_notequal_break_invert_v47",
                "from": getattr(node, "addr", None),
                "owner": getattr(owner, "addr", None),
                "true": getattr(true_node, "addr", None),
                "false": getattr(false_node, "addr", None),
                "cond": cond_text,
                "raw_expr": raw_expr,
                "reason": "preserve_raw_INT_NOTEQUAL_break_condition_without_complement_metadata",
            })
        except Exception:
            pass
        return cond


    def _cfg_edge(self, src, dst):
        if hasattr(self.cfg, "edge_between"):
            try:
                return self.cfg.edge_between(src, dst)
            except Exception:
                pass

        if src is None or dst is None:
            return None

        for e in self._as_list(getattr(src, "out_edges", None)):
            if getattr(e, "dst", None) is dst:
                return e

        return None

    def _edge_raw_type(self, src, dst):
        e = self._cfg_edge(src, dst)

        if e is None:
            return None

        return getattr(e, "raw_type", getattr(e, "type", None))

    def _edge_is_loop_exit(self, src, dst):
        if hasattr(self.cfg, "is_loop_exit_edge"):
            try:
                return bool(self.cfg.is_loop_exit_edge(src, dst))
            except Exception:
                pass

        e = self._cfg_edge(src, dst)
        return bool(getattr(e, "is_loop_exit", False)) if e is not None else False

    def _edge_is_latch_edge(self, src, dst):
        if hasattr(self.cfg, "is_latch_edge"):
            try:
                return bool(self.cfg.is_latch_edge(src, dst))
            except Exception:
                pass

        e = self._cfg_edge(src, dst)
        return bool(getattr(e, "is_latch_edge", False)) if e is not None else False

    def _edge_is_function_exit(self, src, dst):
        if hasattr(self.cfg, "is_function_exit_edge"):
            try:
                return bool(self.cfg.is_function_exit_edge(src, dst))
            except Exception:
                pass

        e = self._cfg_edge(src, dst)

        if e is not None and getattr(e, "is_function_exit_edge", False):
            return True

        return dst in getattr(self.cfg, "exit_nodes", set()) or dst is getattr(self.cfg, "exit", None)

    def _target_is_loop_tail_chain_node(self, target_node):
        """
        True when target_node is one of the explicitly recognized body-header
        loop tail/latch condition blocks.

        Such nodes are not ordinary branch arms. They are emitted once in the
        loop epilogue/tail-chain position. This prevents cases like alpha_four:

            if parity:
                ...
            else:
                <outer increment/tail block>

        where the tail block must run after the optional action, not only in
        the else branch.
        """

        if target_node is None:
            return False

        for _header, chain in getattr(self, "loop_tail_chains", {}).items():
            if target_node in set(chain or []):
                return True

        return False

    def _loop_tail_header_for_node(self, target_node):
        if target_node is None:
            return None

        for header, chain in getattr(self, "loop_tail_chains", {}).items():
            if target_node in set(chain or []):
                return header

        return None


    def _is_loop_tail_chain_member(self, node):
        """
        True when node is part of a multi-node body-header tail chain.

        Tail-chain nodes are not simple latch/update epilogues. A node such as
        alpha_four 0x10129b has both:
            0x10129b -> loop header  (backedge)
            0x10129b -> 0x1012a9     (fallthrough tail test)
        Collapsing it to block+continue skips the fallthrough test and breaks
        state truth.
        """

        if node is None:
            return False

        return self._loop_tail_header_for_node(node) is not None


    def _target_is_loop_latch_node(self, loop_header, target_node):
        if loop_header is None or target_node is None:
            return False

        if self._metadata_node_is_latch_update_for_loop_v26(loop_header, target_node):
            return True

        if hasattr(self.cfg, "loop_latches_for"):
            try:
                return target_node in set(self.cfg.loop_latches_for(loop_header) or [])
            except Exception:
                pass

        return target_node in set(self.loop_latches.get(loop_header, []) or [])

    def _target_is_function_exit_block(self, target_node):
        if target_node is None:
            return False

        return target_node in getattr(self.cfg, "exit_nodes", set()) or target_node is getattr(self.cfg, "exit", None)

    def _record_metadata_event_v43(self, rec):
        try:
            if not hasattr(self, "metadata_consumed_events"):
                self.metadata_consumed_events = []
            self.metadata_consumed_events.append(rec)
        except Exception:
            pass

    def _conditional_header_has_prebranch_payload_v43(self, cfg_node):
        """Return True only for real pre-CBRANCH executable payload.

        v58 replaces the opcode whitelist with a terminal-condition dependency
        cone proof.  CAST/COPY/extension/arithmetic operations are not globally
        structural: they are control-owned only when their temporary outputs
        are pure, wholly inside the terminal-condition cone, and have no uses
        outside that cone.
        """
        if cfg_node is None or self._get_condition(cfg_node) is None:
            return False

        rec = self._classify_condition_block_v58(cfg_node)
        return not bool(rec.get("condition_only"))


    def _node_terminator_opcode_v57(self, cfg_node):
        if cfg_node is None:
            return ""
        block = getattr(cfg_node, "block", None)
        term = getattr(block, "terminator", None) if block is not None else None
        opcode = getattr(term, "opcode", None)
        value = str(opcode or "").strip().upper()
        if "." in value:
            value = value.rsplit(".", 1)[-1]
        return value

    def _cfg_node_for_addr_v57(self, addr):
        if addr is None:
            return None

        try:
            nodes = getattr(self.cfg, "nodes", {}) or {}
            if isinstance(nodes, dict):
                for key in (addr, str(addr), hex(addr) if isinstance(addr, int) else None):
                    if key is not None and key in nodes:
                        return nodes.get(key)
        except Exception:
            pass

        for node in self._real_nodes():
            if getattr(node, "addr", None) == addr:
                return node
        return None

    def _semantic_multiway_record_v57(self, node_or_addr):
        addr = self._addr_v26(node_or_addr)
        if addr is None:
            return None

        table = getattr(self, "semantic_multiway_dispatch_by_block", {}) or {}
        for key in (addr, str(addr), self._hex_v26(addr)):
            try:
                rec = table.get(key)
            except Exception:
                rec = None
            if isinstance(rec, dict):
                return rec

        for rec in list(
            getattr(self, "semantic_multiway_dispatch_facts", []) or []
        ):
            if not isinstance(rec, dict):
                continue
            if rec.get("dispatcher") == addr:
                return rec
            if rec.get("dispatcher_hex") == self._hex_v26(addr):
                return rec
        return None

    def _physical_multiway_dispatch_v57(self, cfg_node):
        if cfg_node is None:
            return False

        try:
            if hasattr(self.cfg, "is_multiway_dispatch"):
                if self.cfg.is_multiway_dispatch(cfg_node):
                    return True
        except Exception:
            pass

        if self._node_terminator_opcode_v57(cfg_node) == "BRANCHIND":
            return True

        successors = []
        for succ in list(self._successors(cfg_node) or []):
            if succ is not None and succ not in successors:
                successors.append(succ)
        return len(successors) > 2

    def _multiway_structuring_failure_v57(self, cfg_node, rec, reason):
        addr = self._addr_v26(cfg_node)
        event = {
            "kind": "multiway_dispatch_unresolved_v57",
            "dispatcher": addr,
            "dispatcher_hex": self._hex_v26(addr),
            "reason": reason,
            "semantic_record_present": isinstance(rec, dict),
            "structuring_status": (
                rec.get("structuring_status") if isinstance(rec, dict) else None
            ),
            "issues": list(rec.get("issues", []) or []) if isinstance(rec, dict) else [],
            "successor_order_used_for_case_values": False,
            "phi_input_order_used_for_predecessor_mapping": False,
        }
        self.multiway_dispatch_events.append(event)
        self._record_metadata_event_v43(dict(event))
        try:
            self.func.sgl_multiway_dispatch_events = list(
                self.multiway_dispatch_events
            )
        except Exception:
            pass

        label = self._hex_v26(addr)
        status = event.get("structuring_status") or "missing"
        issues = event.get("issues") or []
        raise RuntimeError(
            "PALSGL v57 unresolved multiway dispatch at %s; "
            "semantic_status=%s reason=%s issues=%s"
            % (label, status, reason, issues)
        )

    def _emit_multiway_payload_v57(self, cfg_node, parent):
        if cfg_node is None or parent is None:
            return False
        if cfg_node in self.payload_emitted:
            return False
        if not self._node_requires_payload_custody_v55(cfg_node):
            return False

        parent.add(ExecBlock(cfg_node))
        self.payload_emitted.add(cfg_node)

        rec = {
            "kind": "multiway_dispatch_payload_preserved_v57",
            "dispatcher": self._addr_v26(cfg_node),
            "reason": "executable_ops_before_BRANCHIND",
            "opcodes": self._node_payload_opcodes_v55(cfg_node),
        }
        self.multiway_dispatch_events.append(rec)
        self.payload_custody_events.append(dict(rec))
        self._record_metadata_event_v43(dict(rec))
        return True

    def _multiway_region_nodes_v57(self, arm):
        region = dict((arm or {}).get("region") or {})
        out = set()
        for addr in list(region.get("blocks", []) or []):
            node = self._cfg_node_for_addr_v57(addr)
            if node is not None:
                out.add(node)
        return out

    def _multiway_region_boundary_nodes_v57(
        self,
        region_nodes,
        join_node,
        arm_root_nodes,
    ):
        boundaries = set()
        for region_node in set(region_nodes or set()):
            for succ in list(self._successors(region_node) or []):
                if succ is None or succ in region_nodes:
                    continue
                boundaries.add(succ)

        if join_node is not None:
            boundaries.add(join_node)
        boundaries |= set(arm_root_nodes or set())
        return boundaries

    def _multiway_case_node_v57(self, dispatcher_node, arm):
        role = str((arm or {}).get("role") or "dispatch_case")
        target = self._cfg_node_for_addr_v57((arm or {}).get("target"))
        return ExecCase(
            dispatcher_node,
            target,
            values=list((arm or {}).get("values", []) or []),
            role=role,
            contract=arm,
        )

    def _emit_multiway_arm_v57(
        self,
        dispatcher_node,
        dispatch_exec,
        arm,
        join_node,
        all_arm_roots,
        outer_stop_nodes,
    ):
        arm = dict(arm or {})
        role = str(arm.get("role") or "dispatch_case")
        target_addr = arm.get("target")
        target_node = self._cfg_node_for_addr_v57(target_addr)
        region = dict(arm.get("region") or {})
        region_status = str(region.get("status") or "")

        accepted_statuses = {
            "resolved_to_join",
            "resolved_terminal",
            "resolved_fallthrough_to_arm",
        }
        if target_node is None:
            self._multiway_structuring_failure_v57(
                dispatcher_node,
                dispatch_exec.contract,
                "arm_target_missing:%s" % target_addr,
            )
        if region_status not in accepted_statuses:
            self._multiway_structuring_failure_v57(
                dispatcher_node,
                dispatch_exec.contract,
                "arm_region_%s:%s" % (target_addr, region_status or "missing"),
            )

        case_exec = self._multiway_case_node_v57(dispatcher_node, arm)
        dispatch_exec.add_case(case_exec)

        region_nodes = self._multiway_region_nodes_v57(arm)
        if target_node not in region_nodes:
            region_nodes.add(target_node)

        boundaries = self._multiway_region_boundary_nodes_v57(
            region_nodes,
            join_node,
            all_arm_roots - {target_node},
        )
        local_stops = set(outer_stop_nodes or set()) | boundaries

        # Dispatch arms are path-local.  Temporarily release global visited
        # custody for the proved region so one case cannot erase another case's
        # shared/fallthrough blocks.  After emission, only SemanticGraph-proven
        # path-local blocks become global owners; shared blocks remain eligible
        # for other cases.
        visited_before = set(self.visited)
        self.visited.difference_update(region_nodes)

        self._emit_node(
            target_node,
            case_exec.body,
            stop_nodes=local_stops,
        )

        visited_after = set(self.visited)
        outside_new = {
            node for node in (visited_after - visited_before)
            if node not in region_nodes
        }

        path_local_nodes = set()
        for addr in list(region.get("path_local_blocks", []) or []):
            node = self._cfg_node_for_addr_v57(addr)
            if node is not None:
                path_local_nodes.add(node)

        self.visited = visited_before | outside_new | path_local_nodes

        event = {
            "kind": (
                "multiway_dispatch_default_owned_v57"
                if role == "dispatch_default"
                else "multiway_dispatch_case_owned_v57"
            ),
            "dispatcher": self._addr_v26(dispatcher_node),
            "target": target_addr,
            "values": list(arm.get("values", []) or []),
            "region_status": region_status,
            "region_blocks": list(region.get("blocks", []) or []),
            "path_local_blocks": list(region.get("path_local_blocks", []) or []),
            "shared_blocks": list(region.get("shared_blocks", []) or []),
            "falls_through_to_arms": list(
                region.get("falls_through_to_arms", []) or []
            ),
            "join_predecessors": list(arm.get("join_predecessors", []) or []),
            "phi_inputs": len(list(arm.get("phi_inputs", []) or [])),
            "edge_identity": case_exec.edge_identity,
        }
        self.multiway_dispatch_events.append(event)
        self.branch_control_events.append(dict(event))
        self._record_metadata_event_v43(dict(event))
        return case_exec

    def _try_emit_multiway_dispatch_v57(self, cfg_node, parent, stop_nodes):
        if not self._physical_multiway_dispatch_v57(cfg_node):
            return False

        rec = self._semantic_multiway_record_v57(cfg_node)
        if not isinstance(rec, dict):
            self._multiway_structuring_failure_v57(
                cfg_node,
                rec,
                "semantic_multiway_handoff_missing",
            )

        if str(rec.get("structuring_status") or "") != "resolved":
            self._multiway_structuring_failure_v57(
                cfg_node,
                rec,
                "semantic_multiway_handoff_not_resolved",
            )

        if rec.get("successor_order_used_for_case_values") is not False:
            self._multiway_structuring_failure_v57(
                cfg_node,
                rec,
                "successor_order_case_authority_not_explicitly_false",
            )
        if rec.get("phi_input_order_used_for_predecessor_mapping") is not False:
            self._multiway_structuring_failure_v57(
                cfg_node,
                rec,
                "phi_input_order_predecessor_authority_not_explicitly_false",
            )

        selector = dict(rec.get("selector") or {})
        selector_expr = rec.get("selector_expr") or selector.get("selector_expr")
        selector_status = str(selector.get("status") or "")
        if not selector_expr or not selector_status.startswith("resolved"):
            self._multiway_structuring_failure_v57(
                cfg_node,
                rec,
                "selector_not_semantically_resolved",
            )

        join_addr = rec.get("join")
        join_node = self._cfg_node_for_addr_v57(join_addr)
        if join_addr is not None and join_node is None:
            self._multiway_structuring_failure_v57(
                cfg_node,
                rec,
                "join_cfg_node_missing:%s" % join_addr,
            )

        arms = [dict(arm) for arm in list(rec.get("arms", []) or [])]
        if not arms:
            # Compatibility with handoffs that expose cases/default separately.
            arms = [dict(arm) for arm in list(rec.get("cases", []) or [])]
            default_arm = rec.get("default")
            if isinstance(default_arm, dict):
                arms.append(dict(default_arm))

        if not arms:
            self._multiway_structuring_failure_v57(
                cfg_node,
                rec,
                "resolved_record_has_no_arms",
            )

        self._emit_multiway_payload_v57(cfg_node, parent)

        dispatch_exec = ExecDispatch(
            cfg_node,
            selector_expr=selector_expr,
            computed_target_expr=rec.get("computed_target_expr"),
            join_node=join_node,
            contract=rec,
        )
        parent.add(dispatch_exec)

        self.visited.add(cfg_node)
        self.control_emitted.add(cfg_node)

        arm_root_nodes = set()
        for arm in arms:
            target = self._cfg_node_for_addr_v57(arm.get("target"))
            if target is not None:
                arm_root_nodes.add(target)

        for arm in arms:
            self._emit_multiway_arm_v57(
                cfg_node,
                dispatch_exec,
                arm,
                join_node,
                arm_root_nodes,
                stop_nodes,
            )

        event = {
            "kind": "multiway_dispatch_detected_v57",
            "dispatcher": self._addr_v26(cfg_node),
            "selector_expr": selector_expr,
            "computed_target_expr": rec.get("computed_target_expr"),
            "case_count": len(dispatch_exec.cases),
            "has_default": dispatch_exec.default_case is not None,
            "join": join_addr,
            "semantic_version": rec.get("version"),
            "authority": rec.get("authority"),
            "successor_order_used_for_case_values": False,
            "phi_input_order_used_for_predecessor_mapping": False,
        }
        self.multiway_dispatch_events.append(event)
        self.branch_control_events.append(dict(event))
        self._record_metadata_event_v43(dict(event))

        # The common join has one ordinary post-dispatch owner.  When an outer
        # structure already owns it as a stop node, leave it untouched.
        if join_node is not None and join_node not in set(stop_nodes or set()):
            self._emit_node(join_node, parent, stop_nodes=set(stop_nodes or set()))
            join_event = {
                "kind": "multiway_dispatch_join_owned_v57",
                "dispatcher": self._addr_v26(cfg_node),
                "join": join_addr,
                "owner": "single_post_dispatch_exec_owner",
            }
            self.multiway_dispatch_events.append(join_event)
            self._record_metadata_event_v43(dict(join_event))

        return True

    def _exec_subtree_cfg_addresses_v57(self, root):
        addresses = set()

        def walk(node):
            if node is None:
                return
            kind = getattr(node, "kind", None)
            cfg_node = None
            if kind in ("block", "if", "dispatch", "case", "default"):
                cfg_node = getattr(node, "cfg_node", None)
            elif kind == "loop":
                cfg_node = getattr(node, "header", None)
            addr = getattr(cfg_node, "addr", None) if cfg_node is not None else None
            if addr is not None:
                addresses.add(addr)
            for child in list(getattr(node, "children", []) or []):
                walk(child)

        walk(root)
        return addresses

    def _audit_exec_tree_multiway_custody_v57(self):
        dispatch_nodes = {}

        def walk(node):
            if node is None:
                return
            if getattr(node, "kind", None) == "dispatch":
                addr = getattr(getattr(node, "cfg_node", None), "addr", None)
                dispatch_nodes.setdefault(addr, []).append(node)
            for child in list(getattr(node, "children", []) or []):
                walk(child)

        walk(self.root)

        missing = []
        details = []
        for rec in list(self.semantic_multiway_dispatch_facts or []):
            if not isinstance(rec, dict):
                continue
            if str(rec.get("structuring_status") or "") != "resolved":
                continue

            dispatcher = rec.get("dispatcher")
            owners = list(dispatch_nodes.get(dispatcher, []) or [])
            detail = {
                "dispatcher": dispatcher,
                "dispatch_owners": len(owners),
                "missing_cases": [],
                "missing_case_region_blocks": [],
                "default_missing": False,
                "join_owner_count": 0,
                "phi_custody_missing": [],
            }

            if len(owners) != 1:
                detail["missing_dispatch_owner"] = True
                missing.append({
                    "dispatcher": dispatcher,
                    "reason": "dispatch_owner_count_%d" % len(owners),
                })
                details.append(detail)
                continue

            owner = owners[0]
            expected_arms = [dict(a) for a in list(rec.get("arms", []) or [])]
            actual_arms = [
                child for child in list(getattr(owner, "children", []) or [])
                if getattr(child, "kind", None) in ("case", "default")
            ]

            for expected in expected_arms:
                role = str(expected.get("role") or "dispatch_case")
                target = expected.get("target")
                values = list(expected.get("values", []) or [])
                matches = [
                    arm for arm in actual_arms
                    if getattr(arm, "role", None) == role
                    and getattr(arm, "target_addr", None) == target
                    and list(getattr(arm, "values", []) or []) == values
                ]
                if len(matches) != 1:
                    detail["missing_cases"].append({
                        "role": role,
                        "target": target,
                        "values": values,
                        "owners": len(matches),
                    })
                    continue

                arm_node = matches[0]
                actual_region = self._exec_subtree_cfg_addresses_v57(
                    getattr(arm_node, "body", None)
                )
                expected_region = set(
                    (expected.get("region") or {}).get("blocks", []) or []
                )
                absent_region = sorted(expected_region - actual_region)
                if absent_region:
                    detail["missing_case_region_blocks"].append({
                        "role": role,
                        "target": target,
                        "values": values,
                        "missing": absent_region,
                    })

                expected_phi = list(expected.get("phi_inputs", []) or [])
                actual_phi = list(getattr(arm_node, "phi_inputs", []) or [])
                if expected_phi != actual_phi:
                    detail["phi_custody_missing"].append({
                        "role": role,
                        "target": target,
                        "expected_count": len(expected_phi),
                        "actual_count": len(actual_phi),
                    })

            join = rec.get("join")
            if join is not None:
                whole_tree_addresses = []

                def count_join(node):
                    if node is None:
                        return
                    if getattr(node, "kind", None) == "block":
                        cfg_node = getattr(node, "cfg_node", None)
                        if getattr(cfg_node, "addr", None) == join:
                            whole_tree_addresses.append(join)
                    for child in list(getattr(node, "children", []) or []):
                        count_join(child)

                count_join(self.root)
                detail["join_owner_count"] = len(whole_tree_addresses)
                if len(whole_tree_addresses) != 1:
                    missing.append({
                        "dispatcher": dispatcher,
                        "reason": "join_owner_count_%d" % len(whole_tree_addresses),
                        "join": join,
                    })

            if (
                detail["missing_cases"]
                or detail["missing_case_region_blocks"]
                or detail["phi_custody_missing"]
            ):
                missing.append({
                    "dispatcher": dispatcher,
                    "reason": "case_or_phi_custody_incomplete",
                })

            details.append(detail)

        audit = {
            "kind": (
                "exec_tree_multiway_custody_verified_v57"
                if not missing
                else "exec_tree_multiway_custody_missing_v57"
            ),
            "semantic_dispatchers": len(self.semantic_multiway_dispatch_facts),
            "dispatch_owners": sum(len(v) for v in dispatch_nodes.values()),
            "details": details,
            "missing": missing,
            "successor_order_used_for_case_values": False,
            "phi_input_order_used_for_predecessor_mapping": False,
        }
        self.multiway_dispatch_audit = audit
        self.multiway_dispatch_events.append(dict(audit))

        try:
            self.func.sgl_multiway_dispatch_audit = dict(audit)
            self.func.sgl_multiway_dispatch_events = list(
                self.multiway_dispatch_events
            )
        except Exception:
            pass

        if missing:
            labels = [
                self._hex_v26(rec.get("dispatcher"))
                for rec in missing
            ]
            raise RuntimeError(
                "PALSGL v57 multiway custody audit failed; dispatcher(s): %s"
                % ", ".join(labels)
            )
        return audit


    # ---------------------------------------------------------------------
    # v58: terminal-condition dependency-cone custody
    # ---------------------------------------------------------------------

    def _formula_nodes_v58(self):
        nodes = getattr(self.func, "formula_nodes", None)
        if isinstance(nodes, dict):
            return nodes

        raw = getattr(self.func, "var_nodes", None)
        if isinstance(raw, tuple):
            raw = raw[0] if raw else {}
        return raw if isinstance(raw, dict) else {}

    def _sid_variants_v58(self, sid):
        out = []
        if sid is None:
            return out
        for value in (sid, str(sid)):
            if value not in out:
                out.append(value)
        s = str(sid)
        if s.startswith("v_") and s[2:].isdigit():
            for value in (s[2:], int(s[2:])):
                if value not in out:
                    out.append(value)
        elif s.isdigit():
            value = "v_" + s
            if value not in out:
                out.append(value)
            try:
                value = int(s)
                if value not in out:
                    out.append(value)
            except Exception:
                pass
        return out

    def _formula_node_for_sid_v58(self, sid):
        nodes = self._formula_nodes_v58()
        for key in self._sid_variants_v58(sid):
            try:
                if key in nodes:
                    return nodes.get(key)
            except Exception:
                pass
        return None

    def _formula_node_sid_v58(self, node):
        if node is None:
            return None
        var = getattr(node, "var", None)
        if var is None:
            var = getattr(node, "output", None)
        sid = getattr(var, "ssa_id", None)
        if sid is not None:
            return sid
        return getattr(node, "ssa_id", None)

    def _terminal_condition_var_v58(self, cfg_node):
        block = getattr(cfg_node, "block", None) if cfg_node is not None else None
        term = getattr(block, "terminator", None) if block is not None else None
        if term is None or getattr(term, "opcode", None) != "CBRANCH":
            return None

        cond = getattr(term, "condition", None)
        if cond is not None:
            return cond

        inputs = list(getattr(term, "inputs", []) or [])
        return inputs[1] if len(inputs) >= 2 else None

    def _input_formula_node_v58(self, value):
        if value is None:
            return None
        if hasattr(value, "opcode") and hasattr(value, "var"):
            return value
        sid = getattr(value, "ssa_id", None)
        return self._formula_node_for_sid_v58(sid)

    def _condition_dependency_cone_v58(self, cfg_node):
        cond_var = self._terminal_condition_var_v58(cfg_node)
        cond_sid = getattr(cond_var, "ssa_id", None)
        if cond_sid is None and hasattr(cond_var, "var"):
            cond_sid = getattr(getattr(cond_var, "var", None), "ssa_id", None)

        # Prefer SemanticGraph's exact block->condition index.  It is keyed by
        # the concrete CFG block address and avoids SID representation drift.
        block_addr = getattr(cfg_node, "addr", None)
        block_conditions = getattr(self.func, "block_condition_nodes", {}) or {}
        root = None
        for key in (block_addr, str(block_addr), self._hex_v26(block_addr)):
            try:
                if key in block_conditions:
                    root = block_conditions.get(key)
                    break
            except Exception:
                pass
        if root is None:
            root = self._formula_node_for_sid_v58(cond_sid)

        cone_nodes = set()
        cone_sids = set()
        work = [root] if root is not None else []

        while work:
            node = work.pop()
            if node is None or node in cone_nodes:
                continue
            cone_nodes.add(node)

            sid = self._formula_node_sid_v58(node)
            if sid is not None:
                cone_sids.add(sid)
                cone_sids.add(str(sid))

            inputs = list(getattr(node, "inputs", []) or [])
            if not inputs:
                op = getattr(node, "op", None)
                inputs = list(getattr(op, "inputs", []) or [])

            for inp in inputs:
                dep = self._input_formula_node_v58(inp)
                if dep is not None and dep not in cone_nodes:
                    work.append(dep)

        return {
            "condition_sid": cond_sid,
            "root": root,
            "root_sid": self._formula_node_sid_v58(root),
            "nodes": cone_nodes,
            "sids": cone_sids,
            "proven": bool(root is not None),
        }

    def _uses_for_sid_v58(self, sid):
        table = getattr(self.func, "uses_by_sid", {}) or {}
        out = []
        seen = set()
        for key in self._sid_variants_v58(sid):
            for user in list(table.get(key, []) or []):
                ident = id(user)
                if ident in seen:
                    continue
                seen.add(ident)
                out.append(user)
        return out

    def _output_is_temporary_v58(self, output):
        if output is None:
            return False

        if any(bool(getattr(output, attr, False)) for attr in (
            "is_stack", "is_global", "is_parameter", "is_param",
            "is_persistent", "is_storage", "is_memory",
        )):
            return False

        name = str(getattr(output, "name", "") or "")
        if name.startswith(("local_", "param_", "global_")):
            return False

        sid = getattr(output, "ssa_id", None)
        var_map = getattr(self.func, "var_map", {}) or {}
        mapped = None
        for key in self._sid_variants_v58(sid):
            try:
                if key in var_map:
                    mapped = var_map.get(key)
                    break
            except Exception:
                pass
        mapped_name = str(getattr(mapped, "name", mapped) or "")
        if mapped_name.startswith(("local_", "param_", "global_")):
            return False

        space = str(
            getattr(output, "space", None)
            or getattr(output, "address_space", None)
            or ""
        ).lower()
        if any(token in space for token in ("stack", "ram", "global", "mem")):
            return False

        return bool(
            name.startswith("v_")
            or bool(getattr(output, "is_unique", False))
            or "unique" in space
        )

    def _carrier_opcode_v58(self, opcode):
        return opcode in {
            "COPY", "CAST", "INT_ZEXT", "INT_SEXT", "SUBPIECE", "TRUNC", "PIECE",
            "INT_ADD", "INT_SUB", "INT_MULT", "INT_DIV", "INT_SDIV",
            "INT_REM", "INT_SREM", "INT_NEGATE", "INT_2COMP",
            "INT_AND", "INT_OR", "INT_XOR", "INT_LEFT", "INT_RIGHT",
            "INT_SRIGHT", "INT_CARRY", "INT_SCARRY", "INT_SBORROW",
            "INT_EQUAL", "INT_NOTEQUAL", "INT_LESS", "INT_SLESS",
            "INT_LESSEQUAL", "INT_SLESSEQUAL",
            "BOOL_NEGATE", "BOOL_AND", "BOOL_OR", "BOOL_XOR",
        }

    def _effectful_condition_opcode_v58(self, opcode):
        # LOAD is deliberately conservative until inline-read volatility and
        # memory custody are proved independently.
        return opcode in {
            "CALL", "CALLIND", "CALLOTHER", "STORE", "INDIRECT", "LOAD",
        }

    def _condition_external_uses_v58(self, sid, cone_sids):
        external = []
        for user in self._uses_for_sid_v58(sid):
            user_sid = self._formula_node_sid_v58(user)
            if user_sid in cone_sids or str(user_sid) in cone_sids:
                continue
            external.append({
                "sid": user_sid,
                "opcode": getattr(user, "opcode", None),
                "block": getattr(user, "block_addr", None),
            })
        return external

    def _record_condition_carrier_event_v58(self, kind, **fields):
        rec = {"kind": kind}
        rec.update(fields)
        self.condition_carrier_events.append(rec)
        try:
            self._record_metadata_event_v43(dict(rec))
        except Exception:
            pass
        return rec

    def _classify_condition_block_v58(self, cfg_node):
        if cfg_node is None:
            return {
                "block": None,
                "condition_only": False,
                "cone_proven": False,
                "carrier_sids": [],
                "payload_sids": [],
            }

        cache_key = id(cfg_node)
        cached = self.condition_carrier_cache.get(cache_key)
        if cached is not None:
            return cached

        block = getattr(cfg_node, "block", None)
        cone = self._condition_dependency_cone_v58(cfg_node)
        cone_sids = set(cone.get("sids") or set())

        carriers = []
        payload = []
        op_records = []

        for op in list(getattr(block, "ops", []) or []):
            opcode = str(getattr(op, "opcode", "") or "")

            # Structural graph/terminal wrappers are audited elsewhere.
            if opcode == "MULTIEQUAL" or opcode in {
                "CBRANCH", "BRANCH", "BRANCHIND", "RETURN",
            }:
                continue

            output = getattr(op, "output", None)
            sid = getattr(output, "ssa_id", None)
            in_cone = sid in cone_sids or str(sid) in cone_sids

            rec = {
                "opcode": opcode,
                "sid": sid,
                "in_condition_cone": bool(in_cone),
                "temporary_output": bool(self._output_is_temporary_v58(output)),
                "external_uses": [],
            }

            if self._effectful_condition_opcode_v58(opcode):
                rec["classification"] = "payload_effectful"
                payload.append(sid)
                op_records.append(rec)
                self._record_condition_carrier_event_v58(
                    "condition_carrier_effectful_op_rejected_v58",
                    block=getattr(cfg_node, "addr", None),
                    opcode=opcode,
                    sid=sid,
                )
                continue

            if not in_cone:
                rec["classification"] = "payload_outside_condition_cone"
                payload.append(sid)
                op_records.append(rec)
                continue

            if not self._carrier_opcode_v58(opcode):
                rec["classification"] = "payload_unproven_opcode"
                payload.append(sid)
                op_records.append(rec)
                continue

            if not self._output_is_temporary_v58(output):
                rec["classification"] = "payload_persistent_output"
                payload.append(sid)
                op_records.append(rec)
                continue

            external = self._condition_external_uses_v58(sid, cone_sids)
            rec["external_uses"] = external
            if external:
                rec["classification"] = "payload_external_use"
                payload.append(sid)
                op_records.append(rec)
                self._record_condition_carrier_event_v58(
                    "condition_carrier_external_use_rejected_v58",
                    block=getattr(cfg_node, "addr", None),
                    opcode=opcode,
                    sid=sid,
                    external_uses=list(external),
                )
                continue

            rec["classification"] = "control_carrier"
            carriers.append(sid)
            op_records.append(rec)
            self._record_condition_carrier_event_v58(
                "condition_carrier_cone_classified_v58",
                block=getattr(cfg_node, "addr", None),
                opcode=opcode,
                sid=sid,
                condition_sid=cone.get("condition_sid"),
            )

        result = {
            "block": getattr(cfg_node, "addr", None),
            "condition_sid": cone.get("condition_sid"),
            "condition_root_sid": cone.get("root_sid"),
            "cone_proven": bool(cone.get("proven")),
            "cone_sids": sorted(str(x) for x in cone_sids),
            "condition_only": bool(cone.get("proven") and not payload),
            "carrier_sids": [x for x in carriers if x is not None],
            "payload_sids": [x for x in payload if x is not None],
            "ops": op_records,
        }
        self.condition_carrier_cache[cache_key] = result
        return result

    def _record_composite_condition_sources_v58(
        self,
        exec_if,
        source_nodes,
        source_kind,
    ):
        nodes = tuple(n for n in list(source_nodes or []) if n is not None)
        if exec_if is None or not nodes:
            return

        exec_if.condition_source_nodes_v58 = nodes
        exec_if.condition_source_kind_v58 = str(source_kind)
        self.composite_condition_sources[exec_if] = nodes

        owner = getattr(getattr(exec_if, "cfg_node", None), "addr", None)
        for cfg_node in nodes:
            self._record_condition_carrier_event_v58(
                "composite_condition_source_owned_v58",
                block=getattr(cfg_node, "addr", None),
                owner=owner,
                source_kind=str(source_kind),
            )

    def _refresh_exec_tree_condition_custody_v58(self):
        direct = set()
        composite = set()

        def add_direct(value):
            if value is not None:
                direct.add(value)

        def walk(node):
            if node is None:
                return

            kind = getattr(node, "kind", None)
            if kind == "if":
                add_direct(getattr(node, "cfg_node", None))
            elif kind == "loop":
                add_direct(
                    getattr(node, "header", None)
                    or getattr(node, "cfg_node", None)
                )
                add_direct(getattr(node, "guard_node", None))

            # Synthetic tail/latch ExecIf nodes use cfg_node=None but retain
            # the concrete condition source in one of these fields.
            add_direct(getattr(node, "tail_test_node", None))
            add_direct(getattr(node, "latch_test_node", None))

            sources = getattr(node, "condition_source_nodes_v58", None)
            if sources is None:
                sources = self.composite_condition_sources.get(node, ())
            for source in list(sources or []):
                if source is not None:
                    composite.add(source)

            for child in list(getattr(node, "children", []) or []):
                walk(child)

        walk(self.root)
        self.condition_control_owned = set(direct) | set(composite)
        return direct, composite

    def _audit_exec_tree_condition_custody_v58(self):
        direct, composite = self._refresh_exec_tree_condition_custody_v58()
        reachable = self._reachable_cfg_nodes_v55()
        missing = []
        details = []

        for cfg_node in self._ordered_nodes(reachable):
            if self._get_condition(cfg_node) is None:
                continue

            classification = self._classify_condition_block_v58(cfg_node)
            direct_owned = cfg_node in direct
            composite_owned = cfg_node in composite

            detail = {
                "block": getattr(cfg_node, "addr", None),
                "direct_control_owned": bool(direct_owned),
                "composite_control_owned": bool(composite_owned),
                "cone_proven": bool(classification.get("cone_proven")),
                "condition_only": bool(classification.get("condition_only")),
                "carrier_sids": list(classification.get("carrier_sids") or []),
                "payload_sids": list(classification.get("payload_sids") or []),
            }
            details.append(detail)

            if not (direct_owned or composite_owned):
                missing.append({
                    "block": getattr(cfg_node, "addr", None),
                    "reason": "no_explicit_or_composite_condition_owner",
                })
                continue

            if composite_owned and not classification.get("cone_proven"):
                missing.append({
                    "block": getattr(cfg_node, "addr", None),
                    "reason": "composite_condition_cone_unproven",
                })
                continue

            if composite_owned and not classification.get("condition_only"):
                missing.append({
                    "block": getattr(cfg_node, "addr", None),
                    "reason": "composite_condition_source_has_payload",
                    "payload_sids": list(
                        classification.get("payload_sids") or []
                    ),
                })
                continue

            self._record_condition_carrier_event_v58(
                "condition_carrier_control_owned_v58",
                block=getattr(cfg_node, "addr", None),
                owner=("direct" if direct_owned else "composite"),
                carrier_sids=list(classification.get("carrier_sids") or []),
            )

        audit = {
            "kind": (
                "exec_tree_condition_custody_verified_v58"
                if not missing
                else "exec_tree_condition_custody_missing_v58"
            ),
            "reachable_blocks": len(reachable),
            "conditional_blocks": len(details),
            "direct_condition_owners": len(direct),
            "composite_condition_owners": len(composite),
            "details": details,
            "missing": missing,
        }
        self.condition_custody_audit = audit
        self.condition_carrier_events.append(dict(audit))

        try:
            self.func.sgl_condition_control_owned = [
                getattr(n, "addr", None)
                for n in self._ordered_nodes(self.condition_control_owned)
            ]
            self.func.sgl_condition_carrier_events = list(
                self.condition_carrier_events
            )
            self.func.sgl_condition_custody_audit = dict(audit)
        except Exception:
            pass

        if missing:
            labels = [self._hex_v26(rec.get("block")) for rec in missing]
            raise RuntimeError(
                "PALSGL v58 condition custody audit failed; block(s): %s"
                % ", ".join(labels)
            )
        return audit

    # ---------------------------------------------------------------------
    # v55: conditional payload / control dual custody
    # ---------------------------------------------------------------------

    def _conditional_payload_required_v55(self, cfg_node):
        """Return True when a conditional block owns executable prebranch work."""
        return bool(
            cfg_node is not None
            and self._get_condition(cfg_node) is not None
            and self._conditional_header_has_prebranch_payload_v43(cfg_node)
        )

    def _emit_conditional_payload_v55(
        self,
        cfg_node,
        parent,
        context,
        owner_loop=None,
    ):
        """Materialize a conditional block's payload exactly once.

        Control ownership and payload ownership are intentionally separate.
        ``visited`` may already be about to claim the CFG node for an ExecIf,
        but the state-producing operations before its terminal CBRANCH still
        require an ExecBlock owner.
        """
        if cfg_node is None or parent is None:
            return False
        if cfg_node in self.payload_emitted:
            return False
        if not self._conditional_payload_required_v55(cfg_node):
            return False

        parent.add(ExecBlock(cfg_node))
        self.payload_emitted.add(cfg_node)

        rec = {
            "kind": "conditional_payload_preserved_v55",
            "block": getattr(cfg_node, "addr", None),
            "loop": getattr(owner_loop, "addr", None),
            "context": str(context or "conditional"),
            "reason": "executable_ops_before_control_terminator",
            "opcodes": self._node_payload_opcodes_v55(cfg_node),
        }
        self.payload_custody_events.append(rec)
        self._record_metadata_event_v43(dict(rec))
        return True

    def _node_payload_opcodes_v55(self, cfg_node):
        block = getattr(cfg_node, "block", None) if cfg_node is not None else None
        out = []
        for op in list(getattr(block, "ops", []) or []):
            opcode = getattr(op, "opcode", None)
            if opcode is not None:
                value = str(opcode)
                if value not in out:
                    out.append(value)
        return out

    def _node_payload_reasons_v55(self, cfg_node):
        """Explain why a reachable block requires an ExecBlock owner."""
        if cfg_node is None:
            return []

        block = getattr(cfg_node, "block", None)
        if block is None:
            return []

        reasons = []
        side_effect_ops = {
            "CALL", "CALLIND", "CALLOTHER", "STORE",
        }
        uses_by_sid = getattr(self.func, "uses_by_sid", {}) or {}

        for op in list(getattr(block, "ops", []) or []):
            opcode = str(getattr(op, "opcode", "") or "")
            if opcode in side_effect_ops:
                token = "side_effect:%s" % opcode
                if token not in reasons:
                    reasons.append(token)

            output = getattr(op, "output", None)
            sid = getattr(output, "ssa_id", None)
            if sid is None:
                continue

            use_records = None
            for key in (sid, str(sid), "v_%s" % sid):
                try:
                    if key in uses_by_sid:
                        use_records = uses_by_sid.get(key)
                        break
                except Exception:
                    pass
            try:
                has_uses = bool(list(use_records or []))
            except Exception:
                has_uses = bool(use_records)
            if has_uses:
                token = "downstream_used_definition:%s" % sid
                if token not in reasons:
                    reasons.append(token)

        if not reasons and self._node_requires_payload_custody_v55(cfg_node):
            reasons.append("executable_ops")
        return reasons

    def _node_requires_payload_custody_v55(self, cfg_node):
        if cfg_node is None:
            return False
        if self._get_condition(cfg_node) is not None:
            return self._conditional_payload_required_v55(cfg_node)
        return bool(self._node_has_executable_ops_cfg(cfg_node))

    def _refresh_exec_tree_custody_v55(self):
        """Rebuild payload/control ownership from the actual completed tree."""
        payload = set()
        control = set()

        def walk(node):
            if node is None:
                return
            kind = getattr(node, "kind", None)
            if kind == "block":
                cfg_node = getattr(node, "cfg_node", None)
                if cfg_node is not None:
                    payload.add(cfg_node)
            elif kind == "if":
                cfg_node = getattr(node, "cfg_node", None)
                if cfg_node is not None:
                    control.add(cfg_node)
            elif kind == "loop":
                cfg_node = (
                    getattr(node, "header", None)
                    or getattr(node, "cfg_node", None)
                )
                if cfg_node is not None:
                    control.add(cfg_node)

            for child in list(getattr(node, "children", []) or []):
                walk(child)

        walk(self.root)
        self.payload_emitted = payload
        self.control_emitted = control
        return payload, control

    def _reachable_cfg_nodes_v55(self):
        entry = getattr(self.cfg, "entry", None)
        if entry is None:
            return set()

        reached = set()
        work = [entry]
        while work:
            node = work.pop()
            if node is None or node in reached:
                continue
            reached.add(node)
            for succ in list(self._successors(node) or []):
                if succ is not None and succ not in reached:
                    work.append(succ)
        return reached

    def _audit_exec_tree_payload_custody_v55(self):
        """Fail closed when reachable executable payload vanished from ExecTree."""
        payload, control = self._refresh_exec_tree_custody_v55()
        reachable = self._reachable_cfg_nodes_v55()
        missing = []

        for cfg_node in self._ordered_nodes(reachable):
            if cfg_node in payload:
                continue
            if not self._node_requires_payload_custody_v55(cfg_node):
                continue
            missing.append({
                "block": getattr(cfg_node, "addr", None),
                "control_owned": bool(cfg_node in control),
                "reasons": self._node_payload_reasons_v55(cfg_node),
                "opcodes": self._node_payload_opcodes_v55(cfg_node),
            })

        audit = {
            "kind": (
                "exec_tree_payload_custody_verified_v55"
                if not missing
                else "exec_tree_payload_custody_missing_v55"
            ),
            "reachable_blocks": len(reachable),
            "payload_blocks": len(payload),
            "control_blocks": len(control),
            "missing": missing,
        }
        self.payload_custody_audit = audit
        self.payload_custody_events.append(dict(audit))
        try:
            self.func.sgl_payload_custody_audit = dict(audit)
            self.func.sgl_payload_custody_events = list(
                self.payload_custody_events
            )
        except Exception:
            pass

        if missing:
            labels = []
            for rec in missing:
                addr = rec.get("block")
                labels.append(hex(addr) if isinstance(addr, int) else str(addr))
            raise RuntimeError(
                "PALSGL v55 payload custody audit failed; reachable "
                "executable block(s) absent from ExecTree: %s"
                % ", ".join(labels)
            )
        return audit

    # ---------------------------------------------------------------------
    # v56: direct RETURN / terminal-action custody
    # ---------------------------------------------------------------------

    def _node_terminator_opcode_v56(self, cfg_node):
        """Return a normalized terminal opcode for one concrete CFG block."""
        if cfg_node is None:
            return ""

        block = getattr(cfg_node, "block", None)
        term = getattr(block, "terminator", None) if block is not None else None
        opcode = getattr(term, "opcode", None)

        if opcode is None and block is not None:
            # Older PAL block adapters may expose RETURN only in the op list.
            for op in reversed(list(getattr(block, "ops", []) or [])):
                candidate = getattr(op, "opcode", None)
                if candidate is not None:
                    opcode = candidate
                    break

        text = str(opcode or "").strip().upper()
        if "." in text:
            text = text.rsplit(".", 1)[-1]
        return text

    def _target_is_direct_return_boundary_v56(self, target_node):
        """True only for a concrete block whose own terminator is RETURN."""
        return self._node_terminator_opcode_v56(target_node) == "RETURN"

    def _target_is_explicit_no_return_terminal_v56(self, target_node):
        """Recognize only explicitly proven no-return terminal actions.

        This helper deliberately does not infer no-return behavior from a call
        name.  It accepts only flags already frozen on the CFG node, block,
        terminator, or call op by upstream ABI/compute analysis.
        """
        if target_node is None:
            return False

        block = getattr(target_node, "block", None)
        term = getattr(block, "terminator", None) if block is not None else None
        owners = [target_node, block, term]

        for owner in owners:
            if owner is None:
                continue
            for attr in (
                "no_return", "noreturn", "is_no_return",
                "terminates_function", "function_terminating",
            ):
                try:
                    if getattr(owner, attr, False) is True:
                        return True
                except Exception:
                    pass

        if block is not None:
            for op in list(getattr(block, "ops", []) or []):
                opcode = str(getattr(op, "opcode", "") or "").upper()
                if opcode not in ("CALL", "CALLIND", "CALLOTHER"):
                    continue
                for attr in (
                    "no_return", "noreturn", "is_no_return",
                    "terminates_function",
                ):
                    try:
                        if getattr(op, attr, False) is True:
                            return True
                    except Exception:
                        pass

        return False

    def _terminal_target_kind_v56(self, target_node):
        if self._target_is_direct_return_boundary_v56(target_node):
            return "return"
        if self._target_is_explicit_no_return_terminal_v56(target_node):
            return "no_return"
        return None

    def _path_local_terminal_block_v56(
        self,
        from_node,
        target_node,
        owner_loop,
        source,
        arm=None,
    ):
        """Return a path-local ExecBlock for a concrete terminal target.

        A loop-exit edge to a RETURN block is not equivalent to ``break``.
        The terminal block is emitted on the exact branch path and is not
        entered into the global ``visited`` set, because the same return block
        may also remain the normal post-loop owner for another path.
        """
        terminal_kind = self._terminal_target_kind_v56(target_node)
        if terminal_kind is None:
            return None

        node = ExecBlock(target_node)
        try:
            node.force_emit = True
            node.path_local_duplicate = True
            node.sgl_terminal_boundary_v56 = True
            node.terminal_kind_v56 = terminal_kind
            node.reason = str(source or "path_local_terminal_v56")
            node.owner_loop = owner_loop
            node.source_cfg_node = from_node
        except Exception:
            pass

        base = {
            "from": getattr(from_node, "addr", None),
            "to": getattr(target_node, "addr", None),
            "loop": getattr(owner_loop, "addr", None),
            "arm": arm,
            "terminal_kind": terminal_kind,
            "source": str(source or "path_local_terminal_v56"),
            "terminator": self._node_terminator_opcode_v56(target_node),
            "opcodes": self._node_payload_opcodes_v55(target_node),
        }

        preserve_kind = (
            "loop_exit_direct_return_preserved_v56"
            if terminal_kind == "return"
            else "loop_exit_no_return_terminal_preserved_v56"
        )
        preserve = dict(base)
        preserve["kind"] = preserve_kind
        self.terminal_custody_events.append(preserve)
        self.branch_control_events.append(dict(preserve))
        self._record_metadata_event_v43(dict(preserve))

        reject = dict(base)
        reject["kind"] = (
            "loop_break_rejected_direct_return_v56"
            if terminal_kind == "return"
            else "loop_break_rejected_no_return_terminal_v56"
        )
        reject["reason"] = "terminal_edge_is_not_loop_fallthrough"
        self.terminal_custody_events.append(reject)
        self._record_metadata_event_v43(dict(reject))

        return node

    def _refresh_exec_tree_terminal_custody_v56(self):
        owners = set()

        def walk(node):
            if node is None:
                return
            if getattr(node, "kind", None) == "block":
                cfg_node = getattr(node, "cfg_node", None)
                if cfg_node is not None and self._terminal_target_kind_v56(cfg_node):
                    owners.add(cfg_node)
            for child in list(getattr(node, "children", []) or []):
                walk(child)

        walk(self.root)
        return owners

    def _audit_exec_tree_terminal_custody_v56(self):
        """Fail closed when a reachable concrete terminal block disappeared."""
        owners = self._refresh_exec_tree_terminal_custody_v56()
        reachable = self._reachable_cfg_nodes_v55()
        required = []
        missing = []

        for cfg_node in self._ordered_nodes(reachable):
            terminal_kind = self._terminal_target_kind_v56(cfg_node)
            if terminal_kind is None:
                continue

            rec = {
                "block": getattr(cfg_node, "addr", None),
                "terminal_kind": terminal_kind,
                "terminator": self._node_terminator_opcode_v56(cfg_node),
                "opcodes": self._node_payload_opcodes_v55(cfg_node),
            }
            required.append(rec)
            if cfg_node not in owners:
                missing.append(dict(rec))

        audit = {
            "kind": (
                "exec_tree_terminal_custody_verified_v56"
                if not missing
                else "exec_tree_terminal_custody_missing_v56"
            ),
            "reachable_terminal_blocks": len(required),
            "owned_terminal_blocks": len(owners),
            "required": required,
            "missing": missing,
        }
        self.terminal_custody_audit = audit
        self.terminal_custody_events.append(dict(audit))

        try:
            self.func.sgl_terminal_custody_audit = dict(audit)
            self.func.sgl_terminal_custody_events = list(
                self.terminal_custody_events
            )
        except Exception:
            pass

        if missing:
            labels = []
            for rec in missing:
                addr = rec.get("block")
                label = hex(addr) if isinstance(addr, int) else str(addr)
                labels.append("%s[%s]" % (label, rec.get("terminal_kind")))
            raise RuntimeError(
                "PALSGL v56 terminal custody audit failed; reachable "
                "terminal block(s) absent from ExecTree: %s"
                % ", ".join(labels)
            )

        return audit

    # ---------------------------------------------------------------------
    # v60: non-void function return-frontier custody
    # ---------------------------------------------------------------------

    @staticmethod
    def _positive_int_v60(value):
        try:
            value = int(value)
        except (TypeError, ValueError):
            return None
        return value if value > 0 else None

    def _function_return_contract_v60(self):
        """
        Resolve only already-published return authority.

        ABI-D is primary.  Function-signature and return-var evidence are
        compatibility fallbacks for older stacks.  This method never guesses
        a return value from Python syntax or a function name.
        """
        plan = dict(
            getattr(self.func, "function_entry_abi_plan", {})
            or getattr(self.func, "phi_function_entry_abi_plan", {})
            or {}
        )
        contract = dict(plan.get("return_contract") or {})

        no_return = bool(
            plan.get("no_return") is True
            or contract.get("no_return") is True
            or contract.get("returns") == "no_return"
        )

        width = None
        width_key = None
        for key in (
            "logical_result_width_bits",
            "effective_result_width_bits",
            "result_width_bits",
            "transport_width_bits",
            "return_width_bits",
        ):
            candidate = self._positive_int_v60(contract.get(key))
            if candidate is not None:
                width = candidate
                width_key = "return_contract.%s" % key
                break
        if width is None:
            candidate = self._positive_int_v60(plan.get("result_width_bits"))
            if candidate is not None:
                width = candidate
                width_key = "entry_plan.result_width_bits"

        carriers = list(contract.get("carrier_pieces") or [])
        explicit_void = bool(
            contract.get("void") is True
            or contract.get("returns_void") is True
            or str(contract.get("kind") or "").lower() == "void"
        )

        signature = dict(getattr(self.func, "function_signature", {}) or {})
        signature_return = (
            signature.get("return_type")
            or signature.get("return")
            or signature.get("result_type")
        )
        signature_text = str(signature_return or "").strip().lower()
        if signature_text in ("void", "undefined", "none"):
            explicit_void = True

        return_vars = list(getattr(self.func, "return_vars", []) or [])
        nonvoid = bool(
            not no_return
            and not explicit_void
            and (
                width is not None
                or bool(carriers)
                or bool(return_vars)
            )
        )
        if width is not None:
            authority = width_key
        elif carriers:
            authority = "return_contract.carrier_pieces"
        elif return_vars:
            authority = "pal_function.return_vars"
        elif explicit_void:
            authority = "explicit_void_contract"
        elif no_return:
            authority = "explicit_no_return_contract"
        else:
            authority = "return_contract_unknown"

        return {
            "entry_plan_id": plan.get("plan_id"),
            "nonvoid_required": nonvoid,
            "no_return_function": no_return,
            "explicit_void": explicit_void,
            "width_bits": width,
            "carrier_count": len(carriers),
            "return_var_count": len(return_vars),
            "authority": authority,
        }

    @staticmethod
    def _frontier_record_v60(kind, path, **details):
        record = {
            "kind": str(kind),
            "path": list(path or ()),
        }
        record.update(details)
        return record


    # ---------------------------------------------------------------------
    # v62a: frontier-local concrete terminal-corridor custody
    # ---------------------------------------------------------------------

    def _record_synthetic_exit_occurrence_v62a(
        self,
        cfg_node,
        parent=None,
        path=(),
    ):
        record = {
            "kind": "synthetic_exit_occurrence_pruned_v62a",
            "version": self.sgl_version,
            "exit": getattr(cfg_node, "addr", None),
            "parent_kind": getattr(parent, "kind", None),
            "path": list(path or ()),
            "terminal_authority_granted": False,
            "policy": (
                "synthetic_EXIT_is_topology_only_and_cannot_close_"
                "a_structured_frontier"
            ),
        }
        self.synthetic_exit_occurrence_events_v62a.append(record)
        self.function_return_frontier_events.append(dict(record))
        return record

    def _prune_executable_synthetic_exits_v62a(self):
        """Remove only ExecBlock instances that wrap PAL's synthetic EXIT.

        The v61 construction tree is otherwise left untouched. Removing the
        sentinel is semantics-neutral because it has no native operations; any
        resulting open path must later acquire a concrete terminal corridor or
        fail the existing non-void frontier audit.
        """
        removed = []

        def walk(node, path=()):
            if node is None:
                return
            children = list(getattr(node, "children", []) or [])
            kept = []
            for ordinal, child in enumerate(children):
                child_path = tuple(path or ()) + (
                    "%s.child[%d]" % (
                        getattr(node, "kind", "unknown"), ordinal
                    ),
                )
                is_exit = bool(
                    getattr(child, "kind", None) == "block"
                    and self._is_synthetic_function_exit_node_v61(
                        getattr(child, "cfg_node", None)
                    )
                )
                if is_exit:
                    cfg_node = getattr(child, "cfg_node", None)
                    removed.append({
                        "exit": getattr(cfg_node, "addr", None),
                        "parent_kind": getattr(node, "kind", None),
                        "path": list(child_path),
                    })
                    self._record_synthetic_exit_occurrence_v62a(
                        cfg_node,
                        parent=node,
                        path=child_path,
                    )
                    continue
                kept.append(child)
                walk(child, child_path)
            if len(kept) != len(children):
                node.children = kept
                for child in kept:
                    try:
                        child.parent = node
                    except Exception:
                        pass

        walk(self.root, ())
        return removed

    def _empty_branch_direct_join_target_v62a(self, branch):
        """Return one exact target recorded by v51 for an empty branch.

        No branch polarity or topology is recomputed here. The mature v61
        structurer already froze direct-join ownership on the branch container.
        Ambiguous or absent records remain unresolved.
        """
        records = list(getattr(branch, "direct_join_edges", []) or [])
        targets = []
        for record in records:
            if not isinstance(record, dict):
                continue
            addr = record.get("to")
            node = self._node_by_addr_v27(addr)
            if node is not None and node not in targets:
                targets.append(node)
        if len(targets) == 1:
            return targets[0]
        return None

    def _frontier_states_v62a(self, node, incoming=None, path=()):
        """Propagate concrete fallthrough states through the completed tree.

        Each state identifies the exact ExecNode container where a proven
        terminal corridor may be appended and the last concrete CFG block on
        that structured path. Terminal outcomes return no state.
        """
        if incoming is None:
            states = [{
                "anchor": None,
                "container": self.root,
                "path": list(path or ()),
                "source": "root_entry",
            }]
        else:
            states = list(incoming)
        if node is None:
            return states

        kind = str(getattr(node, "kind", "") or "unknown")
        cfg_node = getattr(node, "cfg_node", None)
        addr = getattr(cfg_node, "addr", None)
        token = "%s%s" % (
            kind,
            "@%s" % (
                hex(addr) if isinstance(addr, int) else str(addr)
            ) if addr is not None else "",
        )
        here = tuple(path or ()) + (token,)

        if kind == "block":
            if self._is_synthetic_function_exit_node_v61(cfg_node):
                return states
            terminal_kind = self._terminal_target_kind_v56(cfg_node)
            if terminal_kind in ("return", "no_return"):
                return []
            container = getattr(node, "parent", None) or self.root
            return [{
                "anchor": cfg_node,
                "container": container,
                "path": list(here),
                "source": "ordinary_block_frontier",
            } for unused in states]

        if kind in ("break", "continue"):
            return []

        if kind == "if":
            outputs = []
            branches = (
                ("then", getattr(node, "then_branch", None)),
                ("else", getattr(node, "else_branch", None)),
            )
            for label, branch in branches:
                if branch is None:
                    continue
                children = list(getattr(branch, "children", []) or [])
                if children:
                    outputs.extend(
                        self._frontier_states_v62a(
                            branch,
                            incoming=states,
                            path=here + (label,),
                        )
                    )
                    continue
                target = self._empty_branch_direct_join_target_v62a(branch)
                outputs.extend({
                    "anchor": target,
                    "container": branch,
                    "path": list(here + (label, "empty_branch")),
                    "source": (
                        "empty_direct_join_branch"
                        if target is not None
                        else "empty_branch_without_exact_target"
                    ),
                } for unused in states)
            return outputs

        if kind == "dispatch":
            outputs = []
            arms = list(getattr(node, "cases", []) or [])
            default_case = getattr(node, "default_case", None)
            if default_case is not None:
                arms.append(default_case)
            if not arms:
                return [{
                    "anchor": None,
                    "container": getattr(node, "parent", None) or self.root,
                    "path": list(here + ("missing_dispatch_arm",)),
                    "source": "dispatch_without_arms",
                } for unused in states]
            for ordinal, arm in enumerate(arms):
                outputs.extend(
                    self._frontier_states_v62a(
                        arm,
                        incoming=states,
                        path=here + ("arm[%d]" % ordinal,),
                    )
                )
            return outputs

        if kind in ("case", "default"):
            body = getattr(node, "body", None)
            if body is None:
                children = list(getattr(node, "children", []) or [])
                body = children[0] if children else None
            return self._frontier_states_v62a(body, states, here)

        if kind == "loop":
            condition_role = str(
                getattr(node, "condition_role", None)
                or getattr(node, "emit_condition_mode", None)
                or ""
            )
            body = getattr(node, "body", None)
            body_outcomes = self._exec_frontier_outcomes_v60(
                body, here + ("body_probe",)
            )
            has_break = any(
                item.get("kind") == "break" for item in body_outcomes
            )
            transaction = getattr(node, "condition_transaction", None)
            may_exit = bool(
                condition_role != "true"
                or transaction is not None
                or has_break
            )
            if not may_exit:
                return []

            header = getattr(node, "header", None) or cfg_node
            exits = list(
                self._ordered_nodes(
                    set(self.loop_normal_exits.get(header, set()) or set())
                )
            ) if header is not None else []
            anchor = exits[0] if len(exits) == 1 else None
            container = getattr(node, "parent", None) or self.root
            return [{
                "anchor": anchor,
                "container": container,
                "path": list(here + ("loop_exit",)),
                "source": (
                    "unique_loop_normal_exit"
                    if anchor is not None
                    else "loop_exit_without_unique_anchor"
                ),
            } for unused in states]

        children = list(getattr(node, "children", []) or [])
        if children or kind in (
            "sequence", "then", "else", "loop_body",
            "case_body", "loop_condition_transaction",
        ):
            current = states
            for ordinal, child in enumerate(children):
                if not current:
                    break
                current = self._frontier_states_v62a(
                    child,
                    incoming=current,
                    path=here + ("child[%d]" % ordinal,),
                )
            if children:
                return current
            return [{
                "anchor": state.get("anchor"),
                "container": node,
                "path": list(here + ("empty_sequence",)),
                "source": state.get("source") or "empty_sequence",
            } for state in states]

        return [{
            "anchor": None,
            "container": getattr(node, "parent", None) or self.root,
            "path": list(here),
            "source": "unknown_exec_node_kind",
        } for unused in states]

    def _continuation_successor_v62a(self, cfg_node):
        """Return one unambiguous concrete successor, or a rejection reason."""
        successors = []
        for successor in list(self._successors(cfg_node) or []):
            if successor is not None and successor not in successors:
                successors.append(successor)

        concrete = [
            node for node in successors
            if not self._is_synthetic_function_exit_node_v61(node)
        ]
        synthetic = [
            node for node in successors
            if self._is_synthetic_function_exit_node_v61(node)
        ]

        if len(concrete) == 1:
            # Synthetic sidecars are tolerated only when they are exact
            # function-exit topology edges. The concrete successor remains the
            # execution path.
            for sentinel in synthetic:
                try:
                    if not self._edge_is_function_exit(cfg_node, sentinel):
                        return None, "synthetic_peer_not_function_exit_edge"
                except Exception:
                    return None, "synthetic_peer_edge_unresolved"
            return concrete[0], None
        if not concrete:
            return None, (
                "synthetic_exit_only_successor"
                if synthetic else "no_successor"
            )
        return None, "multiple_concrete_successors"

    def _prove_linear_terminal_corridor_v62a(
        self,
        anchor,
        include_anchor=False,
        max_nodes=32,
    ):
        """Prove a unique non-branching CFG corridor to concrete termination."""
        if anchor is None:
            return {
                "status": "unresolved",
                "reason": "missing_frontier_anchor",
                "corridor": [],
            }

        corridor = []
        seen = set()
        current = anchor if include_anchor else None
        previous = None

        if not include_anchor:
            current, reason = self._continuation_successor_v62a(anchor)
            if current is None:
                return {
                    "status": "unresolved",
                    "reason": reason,
                    "anchor": getattr(anchor, "addr", None),
                    "corridor": [],
                }
            previous = anchor

        for ordinal in range(max_nodes):
            if current is None:
                break
            if current in seen:
                return {
                    "status": "unresolved",
                    "reason": "corridor_cycle",
                    "anchor": getattr(anchor, "addr", None),
                    "corridor": [getattr(n, "addr", None) for n in corridor],
                }
            seen.add(current)

            if self._is_synthetic_function_exit_node_v61(current):
                return {
                    "status": "unresolved",
                    "reason": "corridor_reached_synthetic_exit",
                    "anchor": getattr(anchor, "addr", None),
                    "corridor": [getattr(n, "addr", None) for n in corridor],
                }

            terminal_kind = self._terminal_target_kind_v56(current)
            if terminal_kind in ("return", "no_return"):
                corridor.append(current)
                return {
                    "status": "resolved",
                    "reason": "unique_linear_terminal_corridor",
                    "anchor": getattr(anchor, "addr", None),
                    "terminal_kind": terminal_kind,
                    "terminal": getattr(current, "addr", None),
                    "corridor": corridor,
                }

            if current in set(getattr(self, "loop_headers", set()) or set()):
                return {
                    "status": "unresolved",
                    "reason": "corridor_enters_loop_header",
                    "anchor": getattr(anchor, "addr", None),
                    "corridor": [getattr(n, "addr", None) for n in corridor],
                }
            if self._get_condition(current) is not None:
                return {
                    "status": "unresolved",
                    "reason": "corridor_requires_conditional_structure",
                    "anchor": getattr(anchor, "addr", None),
                    "corridor": [getattr(n, "addr", None) for n in corridor],
                }
            if self._physical_multiway_dispatch_v57(current):
                return {
                    "status": "unresolved",
                    "reason": "corridor_requires_multiway_structure",
                    "anchor": getattr(anchor, "addr", None),
                    "corridor": [getattr(n, "addr", None) for n in corridor],
                }
            if self._target_is_loop_tail_chain_node(current):
                return {
                    "status": "unresolved",
                    "reason": "corridor_enters_loop_tail_chain",
                    "anchor": getattr(anchor, "addr", None),
                    "corridor": [getattr(n, "addr", None) for n in corridor],
                }

            corridor.append(current)
            next_node, reason = self._continuation_successor_v62a(current)
            if next_node is None:
                return {
                    "status": "unresolved",
                    "reason": reason,
                    "anchor": getattr(anchor, "addr", None),
                    "corridor": [getattr(n, "addr", None) for n in corridor],
                }
            previous = current
            current = next_node

        return {
            "status": "unresolved",
            "reason": "corridor_depth_limit",
            "anchor": getattr(anchor, "addr", None),
            "corridor": [getattr(n, "addr", None) for n in corridor],
        }

    def _append_terminal_corridor_v62a(self, state, proof):
        container = state.get("container")
        corridor = list(proof.get("corridor") or [])
        if container is None or not corridor:
            return False

        anchor = state.get("anchor")
        key = (
            id(container),
            getattr(anchor, "addr", None),
            tuple(getattr(node, "addr", None) for node in corridor),
        )
        if key in self._return_frontier_corridor_keys_v62a:
            return False
        self._return_frontier_corridor_keys_v62a.add(key)

        previous = anchor
        emitted = []
        for cfg_node in corridor:
            exec_block = ExecBlock(cfg_node)
            exec_block.force_emit = True
            exec_block.path_local_duplicate = True
            exec_block.sgl_return_frontier_corridor_v62a = True
            exec_block.source_cfg_node = previous
            exec_block.reason = "frontier_local_terminal_corridor_v62a"
            terminal_kind = self._terminal_target_kind_v56(cfg_node)
            if terminal_kind in ("return", "no_return"):
                exec_block.sgl_terminal_boundary_v56 = True
                exec_block.terminal_kind_v56 = terminal_kind
            container.add(exec_block)
            emitted.append(getattr(cfg_node, "addr", None))
            previous = cfg_node

        event = {
            "kind": "return_frontier_terminal_corridor_preserved_v62a",
            "version": self.sgl_version,
            "frontier_path": list(state.get("path") or []),
            "frontier_source": state.get("source"),
            "anchor": getattr(anchor, "addr", None),
            "container_kind": getattr(container, "kind", None),
            "corridor": emitted,
            "terminal": proof.get("terminal"),
            "terminal_kind": proof.get("terminal_kind"),
            "global_visited_claimed": False,
            "rule": (
                "completed_tree_frontier_plus_unique_single_successor_CFG_"
                "corridor_to_concrete_terminal"
            ),
        }
        self.return_frontier_corridor_events_v62a.append(event)
        self.terminal_custody_events.append(dict(event))
        self.function_return_frontier_events.append(dict(event))
        self._record_metadata_event_v43(dict(event))
        return True

    def _repair_return_frontier_corridors_v62a(self):
        """Repair only completed-tree frontiers; never rewrite construction."""
        removed = self._prune_executable_synthetic_exits_v62a()
        passes = []
        unresolved = []
        repaired_total = 0

        for pass_index in range(4):
            states = self._frontier_states_v62a(self.root, path=())
            if not states:
                passes.append({
                    "pass": pass_index,
                    "frontiers": 0,
                    "repaired": 0,
                    "unresolved": 0,
                })
                unresolved = []
                break

            repaired = 0
            current_unresolved = []
            for state in states:
                anchor = state.get("anchor")
                include_anchor = bool(
                    state.get("source") == "empty_direct_join_branch"
                )
                proof = self._prove_linear_terminal_corridor_v62a(
                    anchor,
                    include_anchor=include_anchor,
                )
                if proof.get("status") == "resolved":
                    if self._append_terminal_corridor_v62a(state, proof):
                        repaired += 1
                        repaired_total += 1
                        continue
                current_unresolved.append({
                    "path": list(state.get("path") or []),
                    "source": state.get("source"),
                    "anchor": getattr(anchor, "addr", None),
                    "container_kind": getattr(
                        state.get("container"), "kind", None
                    ),
                    "proof": {
                        key: value for key, value in proof.items()
                        if key != "corridor"
                    },
                    "corridor": [
                        (
                            node
                            if isinstance(node, (int, str))
                            else getattr(node, "addr", None)
                        )
                        for node in list(proof.get("corridor") or [])
                    ],
                })

            passes.append({
                "pass": pass_index,
                "frontiers": len(states),
                "repaired": repaired,
                "unresolved": len(current_unresolved),
            })
            unresolved = current_unresolved
            if repaired == 0:
                break

        audit = {
            "kind": (
                "return_frontier_corridor_repair_complete_v62a"
                if not unresolved
                else "return_frontier_corridor_repair_partial_v62a"
            ),
            "version": self.sgl_version,
            "synthetic_exit_occurrences_pruned": len(removed),
            "corridors_preserved": repaired_total,
            "passes": passes,
            "unresolved": unresolved,
            "construction_methods_modified": False,
            "rule": (
                "repair_only_completed_ExecTree_frontiers_with_unique_linear_"
                "CFG_corridors_to_concrete_RETURN_or_no_return"
            ),
        }
        self.return_frontier_corridor_audit_v62a = audit
        self.return_frontier_corridor_events_v62a.append(dict(audit))
        self.function_return_frontier_events.append(dict(audit))
        try:
            self.func.sgl_return_frontier_corridor_audit_v62a = dict(audit)
            self.func.sgl_return_frontier_corridor_events_v62a = list(
                self.return_frontier_corridor_events_v62a
            )
            self.func.sgl_synthetic_exit_occurrence_events_v62a = list(
                self.synthetic_exit_occurrence_events_v62a
            )
        except Exception:
            pass
        return audit

    def _audit_no_executable_synthetic_exit_v62a(self):
        leaks = []

        def walk(node, path=()):
            if node is None:
                return
            kind = str(getattr(node, "kind", "") or "unknown")
            cfg_node = getattr(node, "cfg_node", None)
            addr = getattr(cfg_node, "addr", None)
            token = "%s%s" % (
                kind,
                "@%s" % (
                    hex(addr) if isinstance(addr, int) else str(addr)
                ) if addr is not None else "",
            )
            here = tuple(path or ()) + (token,)
            if (
                kind == "block"
                and self._is_synthetic_function_exit_node_v61(cfg_node)
            ):
                leaks.append({
                    "path": list(here),
                    "exit": addr,
                })
            for child in list(getattr(node, "children", []) or []):
                walk(child, here)

        walk(self.root, ())
        audit = {
            "kind": (
                "exec_tree_synthetic_exit_absent_v62a"
                if not leaks
                else "exec_tree_synthetic_exit_leak_v62a"
            ),
            "version": self.sgl_version,
            "leaks": leaks,
            "pruned_occurrences": len(
                self.synthetic_exit_occurrence_events_v62a
            ),
            "rule": "synthetic_CFG_EXIT_must_not_survive_as_ExecBlock",
        }
        self.synthetic_exit_exec_audit_v62a = audit
        self.function_return_frontier_events.append(dict(audit))
        try:
            self.func.sgl_synthetic_exit_exec_audit_v62a = dict(audit)
        except Exception:
            pass
        if leaks:
            paths = [
                " -> ".join(str(part) for part in item.get("path", []))
                for item in leaks[:8]
            ]
            raise RuntimeError(
                "PALSGL v62a executable synthetic EXIT custody failed: %s"
                % (" | ".join(paths) or "<unknown>")
            )
        return audit

    def _is_synthetic_function_exit_node_v61(self, cfg_node):
        """True only for PAL's synthetic function EXIT sentinel.

        Concrete RETURN blocks remain owned by v56.  v61 never classifies a
        real block as synthetic merely because it belongs to ``exit_nodes``.
        """
        if cfg_node is None:
            return False

        addr = getattr(cfg_node, "addr", None)
        if str(addr).strip().upper() == "EXIT":
            return True

        cfg_exit = getattr(self.cfg, "exit", None)
        if cfg_node is cfg_exit:
            return not bool(
                self._target_is_direct_return_boundary_v56(cfg_node)
                or self._target_is_explicit_no_return_terminal_v56(cfg_node)
            )

        for attr in (
            "synthetic_exit",
            "is_synthetic_exit",
            "virtual_exit",
            "is_virtual_exit",
        ):
            try:
                if getattr(cfg_node, attr, False) is True:
                    return True
            except Exception:
                pass

        return False

    def _synthetic_exit_frontier_contract_v61(self, cfg_node):
        """Prove whether a synthetic EXIT is backed only by terminal preds.

        The sentinel itself has no native execution semantics.  It may close a
        non-void structured path only when its complete incoming CFG frontier
        is non-empty and every predecessor is an exact direct RETURN or an
        explicitly proven no-return terminal.  Any ordinary, missing, or
        ambiguous predecessor keeps the audit fail-closed.
        """
        if not self._is_synthetic_function_exit_node_v61(cfg_node):
            return {
                "kind": "synthetic_exit_frontier_not_applicable_v61",
                "substantiated": False,
                "status": "not_synthetic_exit",
                "exit": getattr(cfg_node, "addr", None),
                "predecessors": [],
            }

        cache_key = id(cfg_node)
        cached = self.synthetic_exit_frontier_contracts_v61.get(cache_key)
        if isinstance(cached, dict):
            return cached

        predecessors = []
        for pred in list(self._predecessors(cfg_node) or []):
            terminal_kind = self._terminal_target_kind_v56(pred)
            pred_addr = getattr(pred, "addr", None)
            edge_function_exit = False
            try:
                edge_function_exit = bool(
                    self._edge_is_function_exit(pred, cfg_node)
                )
            except Exception:
                edge_function_exit = False

            accepted = terminal_kind in ("return", "no_return")
            predecessors.append({
                "block": pred_addr,
                "block_hex": (
                    hex(pred_addr)
                    if isinstance(pred_addr, int)
                    else str(pred_addr)
                ),
                "terminal_kind": terminal_kind,
                "terminator": self._node_terminator_opcode_v56(pred),
                "edge_is_function_exit": edge_function_exit,
                "accepted": bool(accepted),
                "opcodes": self._node_payload_opcodes_v55(pred),
            })

        if not predecessors:
            status = "missing_predecessor_frontier"
            substantiated = False
            outcome_kind = "unknown"
        elif all(rec.get("accepted") for rec in predecessors):
            status = "all_predecessors_terminal"
            substantiated = True
            outcome_kind = "substantiated_exit"
        else:
            status = "nonterminal_predecessor_present"
            substantiated = False
            outcome_kind = "fallthrough"

        contract = {
            "kind": (
                "synthetic_exit_frontier_substantiated_v61"
                if substantiated
                else "synthetic_exit_frontier_unsubstantiated_v61"
            ),
            "version": self.sgl_version,
            "exit": getattr(cfg_node, "addr", None),
            "status": status,
            "substantiated": bool(substantiated),
            "outcome_kind": outcome_kind,
            "predecessor_count": len(predecessors),
            "terminal_predecessor_count": sum(
                1 for rec in predecessors if rec.get("accepted")
            ),
            "predecessors": predecessors,
            "rule": (
                "synthetic_EXIT_closes_frontier_only_when_every_concrete_"
                "incoming_predecessor_is_return_or_proven_no_return"
            ),
        }
        self.synthetic_exit_frontier_contracts_v61[cache_key] = contract
        self.function_return_frontier_events.append(dict(contract))
        return contract

    def _exec_frontier_outcomes_v60(self, node, path=()):
        """
        Return structured control outcomes for one ExecTree subtree.

        The analysis is deliberately syntax-independent and address-agnostic.
        It consumes only the explicit ExecNode classes already produced by SGL.
        """
        if node is None:
            return [self._frontier_record_v60("fallthrough", path, reason="missing_node")]

        kind = str(getattr(node, "kind", "") or "unknown")
        cfg_node = getattr(node, "cfg_node", None)
        addr = getattr(cfg_node, "addr", None)
        token = "%s%s" % (
            kind,
            "@%s" % (hex(addr) if isinstance(addr, int) else str(addr))
            if addr is not None else "",
        )
        here = tuple(path or ()) + (token,)

        if kind == "block":
            if self._is_synthetic_function_exit_node_v61(cfg_node):
                contract = self._synthetic_exit_frontier_contract_v61(
                    cfg_node
                )
                outcome_kind = contract.get("outcome_kind")
                if contract.get("substantiated") is True:
                    return [
                        self._frontier_record_v60(
                            "substantiated_exit",
                            here,
                            block=addr,
                            reason=(
                                "synthetic_exit_all_incoming_predecessors_"
                                "terminal_v61"
                            ),
                            synthetic_exit_contract=dict(contract),
                        )
                    ]
                if outcome_kind == "unknown":
                    return [
                        self._frontier_record_v60(
                            "unknown",
                            here,
                            block=addr,
                            reason=contract.get("status"),
                            synthetic_exit_contract=dict(contract),
                        )
                    ]
                return [
                    self._frontier_record_v60(
                        "fallthrough",
                        here,
                        block=addr,
                        reason=contract.get("status"),
                        synthetic_exit_contract=dict(contract),
                    )
                ]

            terminal_kind = self._terminal_target_kind_v56(cfg_node)
            if terminal_kind in ("return", "no_return"):
                return [
                    self._frontier_record_v60(
                        terminal_kind,
                        here,
                        block=addr,
                        terminator=self._node_terminator_opcode_v56(cfg_node),
                    )
                ]
            return [
                self._frontier_record_v60(
                    "fallthrough", here, block=addr, reason="ordinary_block"
                )
            ]

        if kind == "break":
            return [self._frontier_record_v60("break", here)]
        if kind == "continue":
            return [self._frontier_record_v60("continue", here)]

        if kind == "if":
            then_branch = getattr(node, "then_branch", None)
            else_branch = getattr(node, "else_branch", None)
            then_out = self._exec_frontier_outcomes_v60(
                then_branch, here + ("then",)
            )
            else_out = self._exec_frontier_outcomes_v60(
                else_branch, here + ("else",)
            )
            return then_out + else_out

        if kind == "dispatch":
            outcomes = []
            cases = list(getattr(node, "cases", []) or [])
            default_case = getattr(node, "default_case", None)
            for ordinal, case in enumerate(cases):
                outcomes.extend(
                    self._exec_frontier_outcomes_v60(
                        case, here + ("case[%d]" % ordinal,)
                    )
                )
            if default_case is not None:
                outcomes.extend(
                    self._exec_frontier_outcomes_v60(
                        default_case, here + ("default",)
                    )
                )
            else:
                outcomes.append(
                    self._frontier_record_v60(
                        "fallthrough",
                        here + ("missing_default",),
                        reason="dispatch_without_default",
                    )
                )
            return outcomes

        if kind in ("case", "default"):
            body = getattr(node, "body", None)
            if body is None:
                children = list(getattr(node, "children", []) or [])
                body = children[0] if children else None
            return self._exec_frontier_outcomes_v60(body, here)

        if kind == "loop":
            body = getattr(node, "body", None)
            body_outcomes = self._exec_frontier_outcomes_v60(
                body, here + ("body",)
            )
            outcomes = [
                item for item in body_outcomes
                if item.get("kind") in ("return", "no_return")
            ]
            has_break = any(
                item.get("kind") == "break" for item in body_outcomes
            )
            condition_role = str(
                getattr(node, "condition_role", None)
                or getattr(node, "emit_condition_mode", None)
                or ""
            )
            transaction = getattr(node, "condition_transaction", None)
            may_test_exit = bool(
                condition_role != "true"
                or transaction is not None
                or has_break
            )
            if may_test_exit:
                outcomes.append(
                    self._frontier_record_v60(
                        "fallthrough",
                        here + ("loop_exit",),
                        reason="loop_may_exit",
                        condition_role=condition_role,
                        has_break=has_break,
                    )
                )
            else:
                outcomes.append(
                    self._frontier_record_v60(
                        "infinite_loop",
                        here,
                        reason="explicit_true_loop_without_break",
                    )
                )
            return outcomes

        if kind == "loop_condition_transaction":
            return self._exec_sequence_outcomes_v60(
                list(getattr(node, "children", []) or []), here
            )

        children = list(getattr(node, "children", []) or [])
        if children or kind in (
            "sequence", "then", "else", "loop_body", "case_body"
        ):
            return self._exec_sequence_outcomes_v60(children, here)

        return [
            self._frontier_record_v60(
                "fallthrough", here, reason="unknown_exec_node_kind"
            )
        ]

    def _exec_sequence_outcomes_v60(self, children, path):
        outcomes = [self._frontier_record_v60("fallthrough", path)]
        for ordinal, child in enumerate(list(children or [])):
            updated = []
            for outcome in outcomes:
                if outcome.get("kind") != "fallthrough":
                    updated.append(outcome)
                    continue
                updated.extend(
                    self._exec_frontier_outcomes_v60(
                        child, tuple(path or ()) + ("child[%d]" % ordinal,)
                    )
                )
            outcomes = updated
        return outcomes

    def _audit_function_return_frontiers_v60(self):
        """Compatibility wrapper for callers pinned to the v60 method name."""
        return self._audit_function_return_frontiers_v61()

    def _audit_function_return_frontiers_v61(self):
        contract = self._function_return_contract_v60()
        outcomes = self._exec_frontier_outcomes_v60(self.root, ())
        fallthrough = [
            item for item in outcomes if item.get("kind") == "fallthrough"
        ]
        unresolved = [
            item for item in outcomes if item.get("kind") == "unknown"
        ]
        terminal = [
            item for item in outcomes
            if item.get("kind") in (
                "return",
                "no_return",
                "infinite_loop",
                "substantiated_exit",
            )
        ]

        required = bool(contract.get("nonvoid_required"))
        issues = []
        if required and fallthrough:
            issues.append("nonvoid_root_path_can_fallthrough")
        if required and unresolved:
            issues.append("nonvoid_root_path_unresolved")

        audit = {
            "kind": (
                "function_return_frontier_verified_v61"
                if not issues
                else "function_return_frontier_missing_v61"
            ),
            "version": self.sgl_version,
            "contract": contract,
            "outcomes": outcomes,
            "terminal_outcomes": terminal,
            "fallthrough_outcomes": fallthrough,
            "unresolved_outcomes": unresolved,
            "synthetic_exit_frontier_contracts_v61": list(
                self.synthetic_exit_frontier_contracts_v61.values()
            ),
            "issues": issues,
            "rule": (
                "nonvoid_root_paths_must_end_in_return_no_return_"
                "proven_infinite_loop_or_substantiated_synthetic_EXIT"
            ),
        }
        self.function_return_frontier_audit = audit
        self.function_return_frontier_events.append(dict(audit))

        try:
            self.func.sgl_function_return_frontier_audit = dict(audit)
            self.func.sgl_function_return_frontier_events = list(
                self.function_return_frontier_events
            )
        except Exception:
            pass

        if issues:
            paths = [
                " -> ".join(str(part) for part in item.get("path", []))
                for item in fallthrough[:8]
            ]
            raise RuntimeError(
                "PALSGL v61 non-void return frontier custody failed; "
                "structured path(s) can fall out of the function: %s"
                % (" | ".join(paths) or "<unresolved>")
            )
        return audit

    def _loop_early_exit_stay_continuation_v55(
        self,
        owner_loop,
        from_node,
        stay_target,
        break_target,
        parent,
        stop_nodes,
    ):
        """Emit the non-exit path after a structured early break.

        Once the exit edge is rendered as ``if predicate: break``, the peer
        edge is ordinary fallthrough within the same loop.  It must be
        traversed from the parent sequence rather than reduced to an empty
        branch arm or one isolated action block.
        """
        if (
            owner_loop is None
            or from_node is None
            or stay_target is None
            or parent is None
        ):
            return False
        if stay_target is owner_loop:
            return False
        if not self._target_stays_in_loop_v44(owner_loop, stay_target):
            return False

        # Preserve the established single-owner iterator/latch epilogue path.
        if self._conditional_latch_target_is_loop_owned_epilogue_v52(
            owner_loop,
            from_node,
            stay_target,
        ):
            return False

        local_stops = set(stop_nodes or set())
        local_stops.add(owner_loop)
        if break_target is not None:
            local_stops.add(break_target)

        self._emit_node(
            stay_target,
            parent,
            stop_nodes=local_stops,
        )
        rec = {
            "kind": "loop_early_exit_fallthrough_structured_v55",
            "from": getattr(from_node, "addr", None),
            "loop": getattr(owner_loop, "addr", None),
            "break_target": getattr(break_target, "addr", None),
            "continuation_target": getattr(stay_target, "addr", None),
            "reason": "exit_arm_break_then_descend_peer_path",
        }
        self.payload_custody_events.append(rec)
        self.branch_control_events.append(dict(rec))
        self._record_metadata_event_v43(dict(rec))
        return True


    def _node_has_executable_ops_cfg(self, cfg_node):
        if hasattr(self.cfg, "block_has_executable_ops"):
            try:
                return bool(self.cfg.block_has_executable_ops(cfg_node))
            except Exception:
                pass

        return self._node_has_executable_ops(cfg_node)


    def _innermost_loop_for_node(self, node):
        """
        Return the smallest natural loop containing node.
        """

        best = None
        best_size = None

        for header, nodes in self.loop_nodes.items():
            if node not in nodes:
                continue

            size = len(nodes)

            if best is None or size < best_size:
                best = header
                best_size = size

        return best

    def _edge_exits_loop(self, from_node, to_node):
        """
        Use CFG metadata first. Fallback to natural-loop containment.

        Returns the innermost loop header exited by edge from_node -> to_node,
        or None.
        """

        if from_node is None or to_node is None:
            return None

        if self._edge_is_loop_exit(from_node, to_node):
            loop = self._innermost_loop_for_node(from_node)
            if loop is not None:
                return loop

        loop = self._innermost_loop_for_node(from_node)

        if loop is None:
            return None

        if to_node not in self.loop_nodes.get(loop, set()):
            return loop

        return None


    def _edge_continues_loop(self, from_node, to_node):
        """
        Only direct edges to loop headers are structural continue.

        Latch/update nodes are executable epilogues; they must be emitted, not
        replaced by continue.
        """

        loop = self._innermost_loop_for_node(from_node)

        if loop is None or to_node is None:
            return None

        if to_node is loop:
            return loop

        return None


    def _node_has_executable_ops(self, cfg_node):
        if cfg_node is None:
            return False

        # Prefer FunctionCFG's centralized definition if available.
        if hasattr(self.cfg, "block_has_executable_ops"):
            try:
                return bool(self.cfg.block_has_executable_ops(cfg_node))
            except Exception:
                pass

        block = getattr(cfg_node, "block", None)
        if block is None:
            return False

        term = getattr(block, "terminator", None)
        term_cond = getattr(term, "condition", None)
        cond_sid = getattr(term_cond, "ssa_id", None)

        for op in list(getattr(block, "ops", []) or []):
            opcode = getattr(op, "opcode", None)
            if opcode == "MULTIEQUAL":
                continue

            out = getattr(op, "output", None)
            out_sid = getattr(out, "ssa_id", None)

            # A compare feeding only the branch terminator is structural.
            if cond_sid is not None and out_sid == cond_sid:
                continue

            if opcode in ("INT_EQUAL", "INT_NOTEQUAL", "INT_LESS", "INT_SLESS",
                          "INT_LESSEQUAL", "INT_SLESSEQUAL", "BOOL_NEGATE"):
                if term is not None and getattr(term, "opcode", None) == "CBRANCH":
                    continue

            # COPY may be executable state transfer, especially local swaps.
            return True

        return False


    def _latch_update_then_continue_node(self, latch_node, loop, reason):
        """
        Lower an executable latch/update block into an explicit continuation
        epilogue:

            sequence
              block [latch_node]
              continue

        This keeps SGL semantic truth visible for nodes such as alpha_four
        0x10126b:
            update local_10
            backedge to 0x10126f

        v13 often left these as ordinary branch bodies, relying on fall-through.
        """

        seq = ExecNode("sequence")

        if latch_node is not None and self._node_has_executable_ops(latch_node):
            seq.add(ExecBlock(latch_node))
            self.visited.add(latch_node)

        seq.add(ExecContinue(loop, reason))
        return seq

    def _is_executable_latch_update_node(self, loop_header, node):
        """
        True for an executable loop latch/update node with a direct edge back
        to loop_header. Uses SGL metadata sandwiches and CFG metadata, then
        falls back to the local loop_latches map.
        """

        if loop_header is None or node is None:
            return False

        if not self._target_is_loop_latch_node(loop_header, node):
            return False

        # Tail-chain members have their own condition/fallthrough semantics.
        # They must be emitted by _emit_tail_chain_for_loop(), not collapsed
        # into block+continue.
        if self._is_loop_tail_chain_member(node):
            return False

        if not self._node_has_executable_ops_cfg(node):
            return False

        succs = list(self._successors(node) or [])

        # A simple latch/update block returns directly to the loop header.
        # Conservative rule: only promote if every successor is the header.
        # This preserves 0x10126b -> 0x10126f, while rejecting nodes such as
        # 0x10129b that also fall through to another tail condition.
        if succs and all(s is loop_header for s in succs):
            return True

        return False

    def _branch_reaches_latch_update(self, loop_header, target_node):
        """
        Detect a branch arm that reaches the loop's executable latch/update
        block through zero or one simple action blocks. Conservative by design.

        Returns (action_prefix_nodes, latch_node) or (None, None).
        """

        if loop_header is None or target_node is None:
            return None, None

        if self._is_executable_latch_update_node(loop_header, target_node):
            return [], target_node

        # v27 generic safety: do not summarize branch arms rooted at
        # conditional nodes or shared continuation gateways as action+latch.
        # Those roots may represent switch/range ladders, short-circuit tests,
        # or post-loop continuation gates and must be structured normally.
        if self._get_condition(target_node) is not None:
            self._metadata_record_event_v26(
                "branch_latch_reject_structured_target_v27",
                loop=self._addr_v26(loop_header),
                target=self._addr_v26(target_node),
            )
            return None, None

        if self._metadata_target_is_continuation_gateway_v26(target_node, owner_loop=loop_header):
            self._metadata_record_event_v26(
                "branch_latch_reject_gateway_target_v27",
                loop=self._addr_v26(loop_header),
                target=self._addr_v26(target_node),
            )
            return None, None

        # One-step action -> latch update. This catches alpha_four:
        #   0x101200 -> 0x10126b
        # without trying to solve arbitrary path convergence.
        nxts = self._successors(target_node)

        if len(nxts) == 1:
            nxt = nxts[0]

            # Do not treat action -> tail-chain as action+latch+continue.
            # Example: 0x101289 -> 0x10129b. The latter must still run its
            # false/fallthrough tail path to 0x1012a9.
            if self._is_loop_tail_chain_member(nxt):
                return None, None

            if self._is_executable_latch_update_node(loop_header, nxt):
                return [target_node], nxt

        # v26 metadata-guided bounded fallback.  This catches optimized CFGs
        # where the update/latch is known by GraphBuilder but not visible through
        # the older one-step SGL pattern.
        action_nodes, latch = self._metadata_action_reaches_latch_update_v26(loop_header, target_node)
        if latch is not None:
            self._metadata_record_event_v26(
                "metadata_action_reaches_latch_update",
                loop=self._addr_v26(loop_header),
                target=self._addr_v26(target_node),
                latch=self._addr_v26(latch),
                actions=[self._addr_v26(n) for n in (action_nodes or [])],
            )
            return action_nodes or [], latch

        return None, None

    def _action_latch_continue_node(self, action_nodes, latch_node, loop, reason):
        seq = ExecNode("sequence")

        for n in action_nodes or []:
            if n is not None and self._node_has_executable_ops_cfg(n):
                seq.add(ExecBlock(n))
                self.visited.add(n)

        if latch_node is not None and self._node_has_executable_ops_cfg(latch_node):
            seq.add(ExecBlock(latch_node))
            self.visited.add(latch_node)

        seq.add(ExecContinue(loop, reason))
        return seq


    def _action_then_break_node(self, action_node, loop, reason, from_node=None, arm=None):
        seq = ExecNode("sequence")

        # v37 safety net at the final action+break constructor.  This catches
        # older branch paths that bypass the conditional-latch arm populator but
        # still carry from_node + reason context.
        if (
            from_node is not None
            and isinstance(reason, str)
            and (reason.startswith("conditional_latch") or reason == "action_edge_exits_loop")
        ):
            v37_loop = self._conditional_latch_gateway_override_loop_v37(
                from_node,
                action_node,
                preferred_loop=loop,
                arm=arm,
                source="action_then_break_safety_net_v37:%s" % reason,
                record=True,
            )
            if v37_loop is not None:
                seq.add(ExecBreak(v37_loop, "conditional_latch_to_peer_gateway_v37"))
                self.branch_control_events.append({
                    "kind": "conditional_latch_peer_gateway_deferred_v37",
                    "arm": arm,
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(action_node, "addr", None),
                    "loop": getattr(v37_loop, "addr", None),
                    "preferred_loop": getattr(loop, "addr", None),
                    "source": "action_then_break_safety_net_v37",
                })
                return seq

        # v34 safety net: some older loop-exit arm paths reach this generic
        # action+break constructor directly.  Keep the rule narrow by firing
        # only for conditional-latch action exits with a known source node.
        if (
            from_node is not None
            and isinstance(reason, str)
            and (
                reason.startswith("conditional_latch")
                or reason == "action_edge_exits_loop"
            )
            and (
                self._conditional_latch_arm_should_defer_gateway_v34(
                    loop,
                    from_node,
                    action_node,
                    arm=arm,
                    reason="action_then_break_safety_net_v34:%s" % reason,
                )
                or self._loop_exit_action_gateway_should_defer_v35(
                    loop,
                    from_node,
                    action_node,
                    source="action_then_break_safety_net_v35:%s" % reason,
                )
            )
        ):
            seq.add(ExecBreak(loop, "conditional_latch_exit_to_structural_gateway_v34"))
            self.branch_control_events.append({
                "kind": "conditional_latch_structural_gateway_deferred_v34",
                "arm": arm,
                "from": getattr(from_node, "addr", None),
                "to": getattr(action_node, "addr", None),
                "loop": getattr(loop, "addr", None),
                "source": "action_then_break_safety_net_v34_v35",
            })
            return seq

        if action_node is not None and self._node_has_executable_ops(action_node):
            seq.add(ExecBlock(action_node))
            self.visited.add(action_node)

        seq.add(ExecBreak(loop, reason))
        return seq



    def _conditional_latch_target_is_deferred_normal_gateway_v36(self, owner_loop, from_node, target_node, arm=None, source=None):
        """
        v36: consume loop-normal-exit gateway facts at the actual latch-arm site.

        Earlier v32 logic correctly classified targets such as a post-region
        continuation condition as normal exits of the inner loop.  But the arm
        populator later used the static loop_normal_exits table and could still
        inline the target as:

            block[target]
            break

        This helper is intentionally narrow and is called only from conditional
        latch / loop-exit branch-arm population.  It does not rewrite ordinary
        switch/range arms.

        Required generic shape:
          * from_node is inside owner_loop and is not the loop header itself;
          * target_node is outside owner_loop;
          * target_node appears in the dynamically computed normal exits for
            owner_loop, which includes semantic-graph and structural gateway
            facts;
          * target_node has continuation-gateway structure for owner_loop.

        Action for caller: emit break(owner_loop) only, do not inline target,
        do not mark target visited.  The enclosing region/join traversal owns
        target_node.
        """
        if owner_loop is None or from_node is None or target_node is None:
            return False

        # Header guard exits are normal loop exits, but they are not branch-arm
        # action blocks.  This helper is only for body/latch arms.
        if from_node is owner_loop:
            return False

        owner_nodes = set(self.loop_nodes.get(owner_loop, set()) or set())
        if not owner_nodes:
            self._metadata_record_event_v26(
                "conditional_latch_normal_gateway_rejected_v36",
                reason="owner_loop_has_no_nodes",
                source=source or "conditional_latch_arm_v36",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                owner_loop=self._addr_v26(owner_loop),
                arm=arm,
            )
            return False

        if from_node not in owner_nodes:
            self._metadata_record_event_v26(
                "conditional_latch_normal_gateway_rejected_v36",
                reason="from_not_in_owner_loop",
                source=source or "conditional_latch_arm_v36",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                owner_loop=self._addr_v26(owner_loop),
                arm=arm,
            )
            return False

        if target_node in owner_nodes:
            return False
        if target_node in self.loop_headers:
            return False
        if self._target_is_loop_tail_chain_node(target_node):
            return False
        if self._target_is_function_exit_block(target_node):
            return False

        # Dynamic normal exits are stronger than the stored table because
        # _get_loop_normal_exits() adds metadata/structural continuation
        # gateways discovered after initial loop discovery.
        try:
            dynamic_normals = set(self._get_loop_normal_exits(owner_loop) or set())
        except Exception:
            dynamic_normals = set(self.loop_normal_exits.get(owner_loop, set()) or set())

        if target_node not in dynamic_normals:
            self._metadata_record_event_v26(
                "conditional_latch_normal_gateway_rejected_v36",
                reason="target_not_dynamic_normal_exit",
                source=source or "conditional_latch_arm_v36",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                owner_loop=self._addr_v26(owner_loop),
                arm=arm,
                dynamic_normals=[self._addr_v26(n) for n in self._ordered_nodes(dynamic_normals)],
            )
            return False

        # Confirm continuation-gateway structure with the exact latch/body edge
        # when possible, but also accept loop-level proof.  The important
        # generic invariant is: normal-exit gateway of this loop, reached from
        # a body/latch edge, not a private executable cleanup block.
        gateway = False
        try:
            gateway = bool(self._metadata_target_is_continuation_gateway_v26(
                target_node, owner_loop=owner_loop, from_node=from_node
            ))
        except Exception:
            gateway = False

        if not gateway:
            try:
                gateway = bool(self._structural_target_is_continuation_gateway_v32(
                    target_node, owner_loop=owner_loop, from_node=from_node
                ))
            except Exception:
                gateway = False

        if not gateway:
            # Loop-level normal-exit proof can be enough when the exact latch
            # edge has raw/HF normalization oddities.  Require condition/shared
            # join shape so private action blocks are not stolen.
            preds = list(self._predecessors(target_node) or [])
            pred_set = set(preds)
            outside_preds = [p for p in preds if p not in owner_nodes]
            is_condition = self._get_condition(target_node) is not None
            shared_pred = len(pred_set) >= 2 and bool(outside_preds)
            ipdom_join = False
            try:
                for n in self._real_nodes():
                    if n is target_node or n in owner_nodes:
                        continue
                    if getattr(n, "ipdom", None) is not target_node:
                        continue
                    if self._reaches(n, from_node):
                        ipdom_join = True
                        break
            except Exception:
                ipdom_join = False

            gateway = bool(is_condition or shared_pred or ipdom_join)

        if not gateway:
            self._metadata_record_event_v26(
                "conditional_latch_normal_gateway_rejected_v36",
                reason="target_not_gateway_shaped",
                source=source or "conditional_latch_arm_v36",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                owner_loop=self._addr_v26(owner_loop),
                arm=arm,
            )
            return False

        self._metadata_record_event_v26(
            "conditional_latch_normal_gateway_deferred_v36",
            source=source or "conditional_latch_arm_v36",
            from_addr=self._addr_v26(from_node),
            target=self._addr_v26(target_node),
            owner_loop=self._addr_v26(owner_loop),
            arm=arm,
            dynamic_normal_exit=True,
        )
        return True

    def _loop_exit_action_gateway_should_defer_v35(self, br_loop, from_node, target_node, source=None):
        """
        v35: final consumption guard for loop-exit branch arms.

        v32 correctly detects structural continuation gateways, but some paths
        do not pass through the conditional-latch-specific arm populator.  In
        particular, normal branch-arm control may classify an edge leaving the
        innermost loop as:

            executable target -> action block ; break

        That is correct for private cleanup/action blocks, but wrong for a
        shared conditional/ipdom continuation gateway that belongs to an
        enclosing region.  This helper is deliberately narrow:

          * it is called only after a br_loop has already been found;
          * from_node must be inside br_loop and target_node outside it;
          * target_node must not be a loop header, tail-chain node, or function
            exit;
          * target_node must have structural continuation-gateway evidence from
            metadata or the v32 CFG/ipdom fallback.

        The caller must emit only break(br_loop), must not inline target_node,
        and must not mark target_node visited.
        """
        if br_loop is None or from_node is None or target_node is None:
            return False

        owner_nodes = set(self.loop_nodes.get(br_loop, set()) or set())
        if not owner_nodes:
            self._metadata_record_event_v26(
                "loop_exit_action_gateway_rejected_v35",
                reason="owner_loop_has_no_nodes",
                source=source or "loop_exit_action_path",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                loop=self._addr_v26(br_loop),
            )
            return False

        if from_node not in owner_nodes:
            self._metadata_record_event_v26(
                "loop_exit_action_gateway_rejected_v35",
                reason="from_not_in_owner_loop",
                source=source or "loop_exit_action_path",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                loop=self._addr_v26(br_loop),
            )
            return False

        if target_node in owner_nodes:
            return False

        if target_node in self.loop_headers:
            return False

        if self._target_is_loop_tail_chain_node(target_node):
            return False

        if self._target_is_function_exit_block(target_node):
            return False

        # Confirm this really is a loop-exit edge.  At this callsite br_loop
        # should already come from _edge_exits_loop(), but verify defensively.
        exits_by_metadata = False
        try:
            exits_by_metadata = (self._edge_exits_loop(from_node, target_node) is br_loop)
        except Exception:
            exits_by_metadata = False

        exits_by_containment = bool(from_node in owner_nodes and target_node not in owner_nodes)
        if not (exits_by_metadata or exits_by_containment):
            return False

        # Require structural continuation evidence.  This intentionally reuses
        # the v32 detector rather than introducing address/sample-specific
        # rules.  It allows previously recorded metadata, semantic-graph gateway
        # facts, or CFG/ipdom fallback to prove the target belongs outside the
        # inner loop's local action arm.
        gateway = False
        try:
            gateway = bool(self._metadata_target_is_continuation_gateway_v26(target_node, owner_loop=br_loop, from_node=from_node))
        except Exception:
            gateway = False

        if not gateway:
            try:
                gateway = bool(self._structural_target_is_continuation_gateway_v32(target_node, owner_loop=br_loop, from_node=from_node))
            except Exception:
                gateway = False

        if not gateway:
            self._metadata_record_event_v26(
                "loop_exit_action_gateway_rejected_v35",
                reason="target_not_structural_gateway",
                source=source or "loop_exit_action_path",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                loop=self._addr_v26(br_loop),
            )
            return False

        # A private non-conditional cleanup block can still be action+break.
        # A conditional/shared/ipdom gateway should be deferred.
        is_condition = self._get_condition(target_node) is not None
        preds = list(self._predecessors(target_node) or [])
        pred_set = set(preds)
        outside_preds = [p for p in preds if p not in owner_nodes]
        inside_preds = [p for p in preds if p in owner_nodes]
        shared_pred = len(pred_set) >= 2 and bool(outside_preds)

        ipdom_join = False
        try:
            for n in self._real_nodes():
                if n is target_node or n in owner_nodes:
                    continue
                if getattr(n, "ipdom", None) is not target_node:
                    continue
                if self._reaches(n, from_node):
                    ipdom_join = True
                    break
        except Exception:
            ipdom_join = False

        if self._node_has_executable_ops_cfg(target_node) and not (is_condition or shared_pred or ipdom_join):
            self._metadata_record_event_v26(
                "loop_exit_action_gateway_rejected_v35",
                reason="private_executable_action_block",
                source=source or "loop_exit_action_path",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                loop=self._addr_v26(br_loop),
            )
            return False

        self._metadata_record_event_v26(
            "loop_exit_action_gateway_deferred_v35",
            source=source or "loop_exit_action_path",
            from_addr=self._addr_v26(from_node),
            target=self._addr_v26(target_node),
            loop=self._addr_v26(br_loop),
            is_condition=is_condition,
            shared_pred=shared_pred,
            ipdom_join=ipdom_join,
            pred_count=len(pred_set),
            outside_pred_count=len(outside_preds),
            inside_pred_count=len(inside_preds),
        )
        return True

    def _branch_arm_control_node(self, from_node, target_node):
        """
        Convert only true structural loop-control branch arms.

        v11 metadata rules:
          - direct target == loop header -> continue
          - target is loop-exit function-exit/post-loop block -> break only
          - target exits loop and has executable ops -> emit action block; break
          - target is loop latch/update node -> NOT control; caller emits block
        """

        if target_node is None:
            return None

        # Shared executable latch/update epilogue. This is not a plain branch
        # body; it is the continuation update before returning to the loop
        # header. Make the control explicit in the ExecTree.
        loop = self._innermost_loop_for_node(from_node)
        action_nodes, latch_node = self._branch_reaches_latch_update(loop, target_node)

        if latch_node is not None:
            self.branch_control_events.append({
                "kind": "latch_update_continue",
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "latch": getattr(latch_node, "addr", None),
                "loop": getattr(loop, "addr", None),
                "source": "cfg_metadata_v19",
            })
            return self._action_latch_continue_node(
                action_nodes,
                latch_node,
                loop,
                "latch_update_continue",
            )

        cont_loop = self._edge_continues_loop(from_node, target_node)

        if cont_loop is not None:
            self.branch_control_events.append({
                "kind": "continue",
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "loop": getattr(cont_loop, "addr", None),
                "source": "cfg_metadata_v19",
            })
            return ExecContinue(cont_loop, "edge_to_loop_header")

        br_loop = self._edge_exits_loop(from_node, target_node)

        if br_loop is not None:

            # v37: generic branch-arm loop-exit path.  Some conditional latch
            # exits are structured as ordinary if-branch arms before reaching
            # _populate_conditional_latch_arm.  Use the same peer-backedge
            # proof to prevent shared continuation gateways from becoming
            # executable action+break blocks.
            v37_loop = self._conditional_latch_gateway_override_loop_v37(
                from_node,
                target_node,
                preferred_loop=br_loop,
                arm="branch_arm_control",
                source="branch_arm_control_loop_exit_v37",
                record=True,
            )
            if v37_loop is not None:
                self.branch_control_events.append({
                    "kind": "conditional_latch_peer_gateway_deferred_v37",
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(v37_loop, "addr", None),
                    "preferred_loop": getattr(br_loop, "addr", None),
                    "source": "branch_arm_control_loop_exit_v37",
                })
                return ExecBreak(v37_loop, "edge_to_peer_gateway_v37")

            # v35: consume structural continuation gateways at the generic
            # loop-exit branch-arm control path.  Earlier v33/v34 hooks were
            # too narrow for optimized conditional-latch exits that arrive here
            # as action_edge_exits_loop.  Keep it tight: br_loop is known, the
            # edge must leave that loop by containment/metadata, and the target
            # must prove itself as a structural continuation gateway.
            if self._loop_exit_action_gateway_should_defer_v35(
                br_loop,
                from_node,
                target_node,
                source="branch_arm_control_loop_exit_v35",
            ):
                self.branch_control_events.append({
                    "kind": "loop_exit_action_gateway_deferred_v35",
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(br_loop, "addr", None),
                    "source": "branch_arm_control_loop_exit_v35",
                })
                return ExecBreak(br_loop, "edge_to_structural_continuation_gateway_v35")

            if self._metadata_target_is_continuation_gateway_v26(target_node, owner_loop=br_loop, from_node=from_node):
                self.branch_control_events.append({
                    "kind": "metadata_gateway_break",
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(br_loop, "addr", None),
                    "source": "semantic_graph_metadata_v26",
                })
                return ExecBreak(br_loop, "edge_to_metadata_gateway")

            # v56: a concrete RETURN/no-return target is path-local terminal
            # control, not loop fallthrough.  Preserve the target block on this
            # exact arm and leave the shared post-loop owner unvisited.
            terminal = self._path_local_terminal_block_v56(
                from_node,
                target_node,
                br_loop,
                source="branch_arm_control_loop_exit_v56",
                arm="branch_arm_control",
            )
            if terminal is not None:
                return terminal

            # Synthetic CFG EXIT sentinels have no concrete block to emit.
            # Retain the legacy break only for that non-materializable class;
            # concrete return boundaries were consumed above.
            if self._edge_is_function_exit(from_node, target_node) or self._target_is_function_exit_block(target_node):
                self.branch_control_events.append({
                    "kind": "synthetic_function_exit_break_v56",
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(br_loop, "addr", None),
                    "source": "branch_arm_control_loop_exit_v56",
                })
                return ExecBreak(br_loop, "edge_to_synthetic_function_exit_v56")

            if self._node_has_executable_ops_cfg(target_node):
                self.branch_control_events.append({
                    "kind": "action_break",
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(br_loop, "addr", None),
                    "source": "cfg_metadata_v19",
                })
                return self._action_then_break_node(target_node, br_loop, "action_edge_exits_loop")

            self.branch_control_events.append({
                "kind": "break",
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "loop": getattr(br_loop, "addr", None),
                "source": "cfg_metadata_v19",
            })
            return ExecBreak(br_loop, "edge_exits_loop")

        return None


    def _can_branch_arm_absorb_linear_tail(self, from_node, target_node, stop_nodes):
        """
        Return True when a branch arm target is a plain linear action chain that
        should be emitted as path-local code even if some blocks are shared with
        other arms.

        This fixes lowered switch/fallthrough meshes such as:

            0x101216 false -> 0x10121b -> 0x10122f -> join
            0x101221 true  -> 0x10122f -> join

        Global visited ownership would otherwise make the 0x10121b arm lose the
        shared 0x10122f action tail. For execution truth, that tail belongs to
        both paths.
        """

        if target_node is None:
            return False

        loop = self._innermost_loop_for_node(from_node)
        if self._metadata_target_is_continuation_gateway_v26(target_node, owner_loop=loop, from_node=from_node):
            return False

        if target_node in set(stop_nodes or set()):
            return False

        if target_node in self.loop_headers:
            return False

        if self._get_condition(target_node) is not None:
            return False

        if self._target_is_loop_tail_chain_node(target_node):
            return False

        loop = self._innermost_loop_for_node(from_node)

        if loop is not None and self._target_is_loop_latch_node(loop, target_node):
            return False

        # Only absorb real action/copy blocks. Empty routing blocks should stay
        # under the ordinary traversal/control logic.
        if not self._node_has_executable_ops_cfg(target_node):
            return False

        # If this node is already globally visited, ordinary traversal would
        # suppress it. Branch arms are path-local, so this is exactly where the
        # helper is useful.
        if target_node in self.visited:
            return True

        # Also fire when the arm has at least one plain uncond successor before
        # the join/stop. This captures switch fallthrough action tails before
        # global visited can erase them.
        nxt = self._next_linear(target_node)

        if nxt is None:
            return False

        if nxt in set(stop_nodes or set()):
            return False

        if nxt in self.loop_headers:
            return False

        if self._get_condition(nxt) is not None:
            return False

        if self._target_is_loop_tail_chain_node(nxt):
            return False

        if loop is not None and self._target_is_loop_latch_node(loop, nxt):
            return False

        return self._node_has_executable_ops_cfg(nxt)

    def _emit_branch_arm_linear_tail(self, from_node, target_node, parent, stop_nodes, max_nodes=8):
        """
        Emit a short plain linear action chain as a branch-local sequence,
        intentionally allowing shared blocks to appear in multiple branch arms.

        This is not a general region duplication pass. It stops at joins,
        conditions, loops, tail-chain nodes, and latch/update nodes.
        """

        if not self._can_branch_arm_absorb_linear_tail(from_node, target_node, stop_nodes):
            return False

        stop_nodes = set(stop_nodes or set())
        loop = self._innermost_loop_for_node(from_node)

        seq = ExecNode("sequence")
        cur = target_node
        emitted = []
        count = 0

        while cur is not None and count < max_nodes:
            if cur in stop_nodes:
                break

            if cur in self.loop_headers:
                break

            if self._metadata_target_is_continuation_gateway_v26(cur, owner_loop=loop, from_node=from_node):
                break

            if self._get_condition(cur) is not None:
                break

            if self._target_is_loop_tail_chain_node(cur):
                break

            if loop is not None and self._target_is_loop_latch_node(loop, cur):
                break

            if self._node_has_executable_ops_cfg(cur):
                seq.add(ExecBlock(cur))
                emitted.append(cur)

            nxt = self._next_linear(cur)

            if nxt is None:
                break

            if nxt in stop_nodes:
                break

            if nxt in self.loop_headers:
                break

            if self._metadata_target_is_continuation_gateway_v26(nxt, owner_loop=loop, from_node=from_node):
                break

            if self._get_condition(nxt) is not None:
                break

            if self._target_is_loop_tail_chain_node(nxt):
                break

            if loop is not None and self._target_is_loop_latch_node(loop, nxt):
                break

            cur = nxt
            count += 1

        if not emitted:
            return False

        parent.add(seq)

        self.branch_control_events.append({
            "kind": "branch_arm_linear_tail",
            "from": getattr(from_node, "addr", None),
            "to": getattr(target_node, "addr", None),
            "emitted": [getattr(n, "addr", None) for n in emitted],
            "join_stops": [getattr(n, "addr", None) for n in stop_nodes],
            "source": "cfg_metadata_v19",
        })

        # Do NOT mark emitted blocks visited here. Branch arm tails are path-
        # local projections of the CFG and may legitimately be shared/fallthrough
        # actions. Global ownership would recreate the disappearance bug.
        return True




    # =========================================================================
    # v71 COOK-EMPEROR TYPED DIRECT-JOIN STRUCTURAL OWNERSHIP
    # =========================================================================

    @staticmethod
    def _cook_emperor_fact_is_frozen_v71(record):
        if not isinstance(record, dict):
            return False
        if record.get("edge_identity_frozen") is True:
            return True
        return bool(
            record.get("id_schema") == "cfg_edge_identity_v1"
            and str(record.get("kind") or "").startswith(
                "cfg_edge_identity_fact"
            )
        )

    def _refresh_cook_emperor_direct_join_facts_v71(self):
        """Copy every frozen FunctionCFG direct-to-join fact verbatim.

        Upstream edge records are never rewritten.  SGL interpretation is
        published separately as typed structural-owner records.
        """
        sources = []
        for owner, attr in (
            (self.func, "cfg_direct_join_edges"),
            (self.cfg, "direct_join_edges"),
        ):
            try:
                values = getattr(owner, attr, None)
            except Exception:
                values = None
            for rec in list(values or []):
                if isinstance(rec, dict):
                    sources.append(dict(rec))

        if not sources:
            sources = [
                dict(rec)
                for rec in list(
                    getattr(
                        self,
                        "bohdi_emperor_cfg_direct_join_edges_v70",
                        [],
                    ) or []
                )
                if isinstance(rec, dict)
            ]

        facts = {}
        warnings = []
        for rec in sources:
            pair = self._bohdi_emperor_edge_pair_v70(rec)
            if pair is None or not rec.get("direct_to_join"):
                continue
            if not self._cook_emperor_fact_is_frozen_v71(rec):
                warnings.append({
                    "kind": "cook_emperor_unfrozen_direct_join_fact_ignored_v71",
                    "edge_identity": pair,
                    "record": dict(rec),
                })
                continue

            prior = facts.get(pair)
            if prior is not None and prior != rec:
                warnings.append({
                    "kind": "cook_emperor_conflicting_direct_join_fact_v71",
                    "edge_identity": pair,
                    "prior": dict(prior),
                    "duplicate": dict(rec),
                })
                continue

            normalized = dict(rec)
            normalized["edge_id"] = [pair[0], pair[1]]
            normalized["edge_identity"] = pair
            normalized["edge_identity_frozen"] = True
            normalized["cook_emperor_interpretation_mutates_upstream"] = False
            facts[pair] = normalized

        self.cook_emperor_cfg_direct_join_facts_by_edge_v71 = facts
        self.cook_emperor_cfg_direct_join_facts_v71 = [
            dict(facts[pair])
            for pair in sorted(
                facts,
                key=lambda value: (str(value[0]), str(value[1])),
            )
        ]
        for warning in warnings:
            if warning not in self.cook_emperor_warnings_v71:
                self.cook_emperor_warnings_v71.append(warning)
        return facts

    def _cook_emperor_fact_for_edge_v71(self, from_node, target_node):
        pair = (
            self._unbound_emperor_addr_v69(from_node),
            self._unbound_emperor_addr_v69(target_node),
        )
        rec = self.cook_emperor_cfg_direct_join_facts_by_edge_v71.get(pair)
        if isinstance(rec, dict):
            return rec
        self._refresh_cook_emperor_direct_join_facts_v71()
        rec = self.cook_emperor_cfg_direct_join_facts_by_edge_v71.get(pair)
        return rec if isinstance(rec, dict) else None

    def _stamp_exec_if_edge_targets_v71(
        self,
        if_node,
        then_node,
        else_node,
        join_node,
        source_kind=None,
    ):
        """Persist exact CFG targets on one structured conditional."""
        if if_node is None:
            return None

        then_addr = self._unbound_emperor_addr_v69(then_node)
        else_addr = self._unbound_emperor_addr_v69(else_node)
        join_addr = self._unbound_emperor_addr_v69(join_node)

        if_node.then_target_addr_v71 = then_addr
        if_node.else_target_addr_v71 = else_addr
        if_node.join_addr_v71 = join_addr
        if_node.edge_target_source_kind_v71 = str(
            source_kind or "structured_if"
        )

        if_node.then_branch.target_addr_v71 = then_addr
        if_node.then_branch.join_addr_hint_v71 = join_addr
        if_node.else_branch.target_addr_v71 = else_addr
        if_node.else_branch.join_addr_hint_v71 = join_addr

        return {
            "then_target": then_addr,
            "else_target": else_addr,
            "join": join_addr,
            "source_kind": if_node.edge_target_source_kind_v71,
        }

    def _register_cook_emperor_route_hint_v71(
        self,
        from_node,
        target_node,
        owner_kind,
        owner_node=None,
        reason=None,
        evidence=None,
    ):
        """Record an early-return ownership hint without making it authority."""
        pred_addr = self._unbound_emperor_addr_v69(from_node)
        join_addr = self._unbound_emperor_addr_v69(target_node)
        if pred_addr is None or join_addr is None:
            return None
        if target_node is not getattr(from_node, "ipdom", None):
            return None

        pair = (pred_addr, join_addr)
        fact = self._cook_emperor_fact_for_edge_v71(from_node, target_node)
        if not isinstance(fact, dict):
            return None

        owner_cfg = getattr(owner_node, "cfg_node", None)
        if getattr(owner_node, "kind", None) == "loop":
            owner_cfg = getattr(owner_node, "header", None)

        rec = {
            "kind": "cook_emperor_direct_join_route_hint_v71",
            "version": self.cook_emperor_version_v71,
            "edge_identity": pair,
            "owner_kind": str(owner_kind),
            "owner_node_kind": getattr(owner_node, "kind", None),
            "owner_cfg_addr": self._unbound_emperor_addr_v69(owner_cfg),
            "reason": str(reason or "structuring_route"),
            "evidence": dict(evidence or {}),
            "authoritative": False,
        }
        key = (
            pair,
            rec["owner_kind"],
            rec["owner_node_kind"],
            rec["owner_cfg_addr"],
            rec["reason"],
        )
        existing = {
            (
                tuple(item.get("edge_identity") or ()),
                item.get("owner_kind"),
                item.get("owner_node_kind"),
                item.get("owner_cfg_addr"),
                item.get("reason"),
            )
            for item in self.cook_emperor_direct_join_route_hints_v71
            if isinstance(item, dict)
        }
        if key not in existing:
            self.cook_emperor_direct_join_route_hints_v71.append(rec)
            self.cook_emperor_direct_join_route_hints_by_edge_v71.setdefault(
                pair, []
            ).append(dict(rec))
        return rec

    def _cook_emperor_exec_tree_index_v71(self):
        index = {
            "ifs_by_cfg_addr": {},
            "loops_by_header_addr": {},
            "blocks_by_cfg_addr": {},
            "condition_owners_by_source_addr": {},
            "paths_by_object_id": {},
        }

        def add(table, key, value):
            if key is None:
                return
            table.setdefault(key, []).append(value)

        def walk(node, path):
            if node is None:
                return

            index["paths_by_object_id"][id(node)] = tuple(path)
            kind = getattr(node, "kind", None)

            if kind == "if":
                cfg_node = getattr(node, "cfg_node", None)
                cfg_addr = self._unbound_emperor_addr_v69(cfg_node)
                add(index["ifs_by_cfg_addr"], cfg_addr, node)

                sources = list(
                    getattr(node, "condition_source_nodes_v58", ()) or ()
                )
                source_kind = getattr(
                    node, "condition_source_kind_v58", None
                )
                if not sources and cfg_node is not None:
                    sources = [cfg_node]
                for source in sources:
                    source_addr = self._unbound_emperor_addr_v69(source)
                    add(
                        index["condition_owners_by_source_addr"],
                        source_addr,
                        {
                            "owner": node,
                            "source_kind": source_kind,
                            "source_count": len(sources),
                            "owner_cfg_addr": cfg_addr,
                        },
                    )

            elif kind == "loop":
                header = (
                    getattr(node, "header", None)
                    or getattr(node, "cfg_node", None)
                )
                add(
                    index["loops_by_header_addr"],
                    self._unbound_emperor_addr_v69(header),
                    node,
                )

            elif kind == "block":
                cfg_node = getattr(node, "cfg_node", None)
                add(
                    index["blocks_by_cfg_addr"],
                    self._unbound_emperor_addr_v69(cfg_node),
                    node,
                )

            for ordinal, child in enumerate(
                list(getattr(node, "children", []) or [])
            ):
                walk(
                    child,
                    path + (
                        "%s[%d]" % (
                            getattr(child, "kind", "node"),
                            ordinal,
                        ),
                    ),
                )

        walk(self.root, ("root",))
        return index

    def _cook_emperor_path_for_node_v71(self, index, node):
        return list(
            index.get("paths_by_object_id", {}).get(id(node), ())
        )

    def _cook_emperor_arms_for_edge_v71(
        self,
        index,
        pred_addr,
        join_addr,
    ):
        matches = []
        seen = set()

        for if_node in list(
            index.get("ifs_by_cfg_addr", {}).get(pred_addr, []) or []
        ):
            candidates = (
                (
                    getattr(if_node, "then_target_addr_v71", None),
                    getattr(if_node, "then_branch", None),
                ),
                (
                    getattr(if_node, "else_target_addr_v71", None),
                    getattr(if_node, "else_branch", None),
                ),
            )
            for target_addr, arm in candidates:
                if target_addr != join_addr or arm is None:
                    continue
                if id(arm) in seen:
                    continue
                seen.add(id(arm))
                matches.append((if_node, arm))

        # Compatibility with v69/v70 arms built before target stamping.
        def walk(node):
            if node is None:
                return
            if getattr(node, "kind", None) in ("then", "else"):
                pair = getattr(node, "edge_identity", None)
                if isinstance(pair, list):
                    pair = tuple(pair)
                if pair == (pred_addr, join_addr) and id(node) not in seen:
                    seen.add(id(node))
                    matches.append((getattr(node, "parent", None), node))
            for child in list(getattr(node, "children", []) or []):
                walk(child)

        walk(self.root)
        return matches

    def _cook_emperor_composite_owners_for_edge_v71(
        self,
        index,
        pred_addr,
    ):
        out = []
        seen = set()
        for rec in list(
            index.get(
                "condition_owners_by_source_addr", {}
            ).get(pred_addr, []) or []
        ):
            owner = rec.get("owner")
            source_count = int(rec.get("source_count") or 0)
            source_kind = rec.get("source_kind")
            owner_cfg_addr = rec.get("owner_cfg_addr")

            is_composite = bool(
                source_count > 1
                or source_kind
                in (
                    "shared_condition_diamond_v49",
                    "short_circuit_or_and_legacy",
                )
                or owner_cfg_addr != pred_addr
            )
            if not is_composite or owner is None or id(owner) in seen:
                continue
            seen.add(id(owner))
            out.append((owner, dict(rec)))
        return out

    def _classify_direct_join_owner_kind_v71(
        self,
        from_node,
        target_node,
        parent_arm=None,
        loop=None,
        fact=None,
        exec_index=None,
    ):
        """Return one non-mutating SGL interpretation of a frozen edge."""
        pred_addr = self._unbound_emperor_addr_v69(from_node)
        join_addr = self._unbound_emperor_addr_v69(target_node)
        pair = (pred_addr, join_addr)

        evidence = {
            "edge_identity": pair,
            "target_is_ipdom": bool(
                from_node is not None
                and target_node is getattr(from_node, "ipdom", None)
            ),
            "upstream_owner_kind": (
                fact.get("direct_join_owner_kind")
                if isinstance(fact, dict) else None
            ),
            "upstream_empty_arm_candidate": bool(
                isinstance(fact, dict)
                and fact.get("direct_join_empty_arm_candidate")
            ),
        }

        if from_node is None or target_node is None:
            return {
                "owner_kind": None,
                "reason": "missing_cfg_endpoint",
                "evidence": evidence,
            }
        if target_node is not getattr(from_node, "ipdom", None):
            return {
                "owner_kind": None,
                "reason": "target_not_source_ipdom",
                "evidence": evidence,
            }

        upstream_kind = evidence["upstream_owner_kind"]
        if upstream_kind == "loop_header_exit_edge":
            return {
                "owner_kind": "loop_exit",
                "reason": "FunctionCFG_loop_header_exit_edge",
                "evidence": evidence,
            }

        if from_node in set(getattr(self, "loop_headers", set()) or set()):
            nodes = set(self.loop_nodes.get(from_node, set()) or set())
            if target_node not in nodes:
                evidence["loop_header"] = pred_addr
                return {
                    "owner_kind": "loop_exit",
                    "reason": "SGL_loop_header_direct_exit",
                    "evidence": evidence,
                }

        if exec_index is not None:
            composite = self._cook_emperor_composite_owners_for_edge_v71(
                exec_index,
                pred_addr,
            )
            if composite:
                evidence["composite_owner_count"] = len(composite)
                return {
                    "owner_kind": "predicate_composition",
                    "reason": "condition_source_consumed_by_composite_owner",
                    "evidence": evidence,
                }

        try:
            gateway = self._metadata_target_is_continuation_gateway_v26(
                target_node,
                owner_loop=loop,
                from_node=from_node,
            )
        except Exception:
            gateway = False
        evidence["continuation_gateway"] = bool(gateway)

        if parent_arm is not None and self._direct_join_single_owner_eligible_v51(
            from_node,
            target_node,
            loop,
        ):
            return {
                "owner_kind": "empty_branch_arm",
                "reason": "v51_direct_join_single_owner_eligible",
                "evidence": evidence,
            }

        # The v51 empty-arm gate deliberately excludes loop machinery.  Those
        # direct-IPDOM edges are still structurally owned, but by ExecLoop
        # rather than by a synthetic empty then/else arm.
        if loop is not None:
            loop_nodes = set(self.loop_nodes.get(loop, set()) or set())
            target_is_loop_control = bool(
                target_node is loop
                or target_node in set(
                    getattr(self, "loop_tail_test_nodes", set()) or set()
                )
                or self._target_is_loop_tail_chain_node(target_node)
                or self._target_is_loop_latch_node(loop, target_node)
                or self._is_executable_latch_update_node(loop, target_node)
                or target_node not in loop_nodes
            )
            if target_is_loop_control:
                evidence["loop_header_addr"] = (
                    self._unbound_emperor_addr_v69(loop)
                )
                evidence["target_is_loop_control"] = True
                return {
                    "owner_kind": "loop_exit",
                    "reason": "SGL_loop_control_direct_join",
                    "evidence": evidence,
                }

        if gateway:
            return {
                "owner_kind": "continuation_gateway",
                "reason": "semantic_or_structural_continuation_gateway",
                "evidence": evidence,
            }

        if exec_index is not None:
            arm_matches = self._cook_emperor_arms_for_edge_v71(
                exec_index,
                pred_addr,
                join_addr,
            )
            evidence["exact_arm_target_count"] = len(arm_matches)
            if len(arm_matches) == 1:
                _if_node, arm = arm_matches[0]
                if not list(getattr(arm, "children", []) or []):
                    return {
                        "owner_kind": "empty_branch_arm",
                        "reason": "completed_tree_exact_empty_arm",
                        "evidence": evidence,
                    }

        return {
            "owner_kind": None,
            "reason": "no_proven_typed_structural_owner",
            "evidence": evidence,
        }

    def _cook_emperor_attach_edge_to_owner_v71(
        self,
        owner_node,
        owner_kind,
        record,
    ):
        if owner_node is None:
            return

        attr = {
            "predicate_composition": (
                "direct_join_predicate_edges_v71"
            ),
            "continuation_gateway": (
                "direct_join_gateway_edges_v71"
            ),
            "loop_exit": "direct_join_loop_exit_edges_v71",
        }.get(owner_kind)
        if attr:
            values = list(getattr(owner_node, attr, []) or [])
            pair = tuple(record.get("edge_identity") or ())
            if not any(
                tuple(item.get("edge_identity") or ()) == pair
                for item in values
                if isinstance(item, dict)
            ):
                values.append(dict(record))
            setattr(owner_node, attr, values)

    def _cook_emperor_owner_record_v71(
        self,
        fact,
        owner_kind,
        owner_node,
        index,
        reason,
        evidence=None,
        arm=None,
    ):
        pair = tuple(fact.get("edge_identity") or ())
        owner_cfg_node = getattr(owner_node, "cfg_node", None)
        if getattr(owner_node, "kind", None) == "loop":
            owner_cfg_node = getattr(owner_node, "header", None)

        record = {
            "kind": "sgl_direct_join_structural_owner_v71",
            "owner_schema": "sgl_direct_join_structural_owner_v1",
            "version": self.cook_emperor_version_v71,
            "edge_identity": pair,
            "edge_id": pair,
            "edge_id_schema": "cfg_edge_identity_v1",
            "pred_addr": pair[0] if len(pair) == 2 else None,
            "join_addr": pair[1] if len(pair) == 2 else None,
            "owner_kind": owner_kind,
            "owner_node_kind": getattr(owner_node, "kind", None),
            "owner_cfg_addr": self._unbound_emperor_addr_v69(
                owner_cfg_node
            ),
            "owner_path": self._cook_emperor_path_for_node_v71(
                index, owner_node
            ),
            "branch_kind": getattr(arm, "kind", None),
            "reason": str(reason),
            "classification_evidence": dict(evidence or {}),
            "FunctionCFG_fact": dict(fact),
            "sgl_emits_phi_assignments": False,
            "topology_rewritten": False,
            "branch_polarity_rewritten": False,
        }

        self._cook_emperor_attach_edge_to_owner_v71(
            owner_node,
            owner_kind,
            record,
        )

        if arm is not None:
            arm.cook_emperor_owner_kind_v71 = owner_kind
            arm.cook_emperor_owner_record_v71 = dict(record)

        return record

    def _cook_emperor_select_gateway_owner_v71(
        self,
        index,
        pred_addr,
        join_addr,
    ):
        """Return only the strongest available gateway-owner tier.

        Conditional gateway blocks can have both an ExecBlock payload owner
        and an ExecIf control owner under v55 dual custody.  Those are not two
        competing structural owners.  Prefer control ownership, then loop
        ownership, then a lone payload block, and finally the predecessor's
        enclosing conditional.
        """
        tiers = (
            list(index.get("ifs_by_cfg_addr", {}).get(join_addr, []) or []),
            list(
                index.get("loops_by_header_addr", {}).get(
                    join_addr, []
                ) or []
            ),
            list(
                index.get("blocks_by_cfg_addr", {}).get(
                    join_addr, []
                ) or []
            ),
            list(index.get("ifs_by_cfg_addr", {}).get(pred_addr, []) or []),
        )

        for tier in tiers:
            out = []
            seen = set()
            for node in tier:
                if node is None or id(node) in seen:
                    continue
                seen.add(id(node))
                out.append(node)
            if out:
                return out
        return []

    def _audit_cook_emperor_typed_direct_join_ownership_v71(self):
        facts = self._refresh_cook_emperor_direct_join_facts_v71()
        index = self._cook_emperor_exec_tree_index_v71()

        owners_by_edge = {}
        owner_records = []
        failures = []
        details = []

        for pair, fact in sorted(
            facts.items(),
            key=lambda item: (str(item[0][0]), str(item[0][1])),
        ):
            pred_addr, join_addr = pair
            from_node = self._node_by_addr_v27(pred_addr)
            target_node = self._node_by_addr_v27(join_addr)
            loop = (
                self._innermost_loop_for_node(from_node)
                if from_node is not None else None
            )
            arm_matches = self._cook_emperor_arms_for_edge_v71(
                index,
                pred_addr,
                join_addr,
            )
            composite_matches = (
                self._cook_emperor_composite_owners_for_edge_v71(
                    index,
                    pred_addr,
                )
            )
            route_hints = list(
                self.cook_emperor_direct_join_route_hints_by_edge_v71.get(
                    pair, []
                ) or []
            )

            detail = {
                "edge_identity": pair,
                "FunctionCFG_fact": dict(fact),
                "exact_arm_target_count": len(arm_matches),
                "composite_owner_count": len(composite_matches),
                "route_hints": route_hints,
                "owners": [],
            }

            if from_node is None or target_node is None:
                failures.append({
                    "kind": "cook_emperor_direct_join_cfg_endpoint_missing_v71",
                    "edge_identity": pair,
                    "source_found": from_node is not None,
                    "target_found": target_node is not None,
                })
                details.append(detail)
                continue

            classification = self._classify_direct_join_owner_kind_v71(
                from_node,
                target_node,
                loop=loop,
                fact=fact,
                exec_index=index,
            )
            owner_kind = classification.get("owner_kind")
            owner_node = None
            owner_arm = None
            reason = classification.get("reason")

            # Existing exact arm ownership is strongest and remains the only
            # route that exposes the PALemitter direct-join attachment surface.
            exact_direct = [
                (if_node, arm)
                for if_node, arm in arm_matches
                if bool(getattr(arm, "direct_join", False))
                and tuple(getattr(arm, "edge_identity", ()) or ()) == pair
            ]
            if len(exact_direct) > 1:
                failures.append({
                    "kind": (
                        "cook_emperor_direct_join_has_multiple_structural_"
                        "owners_v71"
                    ),
                    "edge_identity": pair,
                    "owner_kind": "empty_branch_arm",
                    "owner_count": len(exact_direct),
                })
                details.append(detail)
                continue

            if len(exact_direct) == 1:
                owner_node, owner_arm = exact_direct[0]
                owner_kind = "empty_branch_arm"
                reason = "existing_v69_v70_exact_empty_arm"
            elif owner_kind == "empty_branch_arm":
                if len(arm_matches) != 1:
                    failures.append({
                        "kind": (
                            "cook_emperor_empty_arm_contract_missing_v71"
                        ),
                        "edge_identity": pair,
                        "arm_target_count": len(arm_matches),
                    })
                    details.append(detail)
                    continue
                owner_node, owner_arm = arm_matches[0]
                if list(getattr(owner_arm, "children", []) or []):
                    failures.append({
                        "kind": (
                            "cook_emperor_empty_arm_contract_missing_v71"
                        ),
                        "edge_identity": pair,
                        "reason": "exact_branch_arm_is_not_structurally_empty",
                        "child_kinds": [
                            getattr(child, "kind", None)
                            for child in list(
                                getattr(owner_arm, "children", []) or []
                            )
                        ],
                    })
                    details.append(detail)
                    continue

                self._register_unbound_emperor_direct_join_edge_v69(
                    from_node,
                    target_node,
                    owner_arm,
                    loop,
                )
                index = self._cook_emperor_exec_tree_index_v71()
                reason = "completed_tree_empty_arm_stamped_v71"

            elif owner_kind == "predicate_composition":
                if len(composite_matches) != 1:
                    failures.append({
                        "kind": (
                            "cook_emperor_direct_join_has_multiple_structural_"
                            "owners_v71"
                            if len(composite_matches) > 1 else
                            "cook_emperor_direct_join_has_no_structural_owner_v71"
                        ),
                        "edge_identity": pair,
                        "owner_kind": "predicate_composition",
                        "owner_count": len(composite_matches),
                    })
                    details.append(detail)
                    continue
                owner_node = composite_matches[0][0]

            elif owner_kind == "loop_exit":
                loop_header_addr = pred_addr
                evidence_loop_addr = (
                    classification.get("evidence", {}).get(
                        "loop_header_addr"
                    )
                )
                if evidence_loop_addr is not None:
                    loop_header_addr = evidence_loop_addr
                elif fact.get("direct_join_owner_kind") != "loop_header_exit_edge":
                    edge_loop = self._edge_exits_loop(
                        from_node,
                        target_node,
                    )
                    if edge_loop is not None:
                        loop_header_addr = self._unbound_emperor_addr_v69(
                            edge_loop
                        )
                    elif loop is not None:
                        loop_header_addr = self._unbound_emperor_addr_v69(
                            loop
                        )

                loop_owners = list(
                    index.get("loops_by_header_addr", {}).get(
                        loop_header_addr, []
                    ) or []
                )
                if len(loop_owners) != 1:
                    failures.append({
                        "kind": (
                            "cook_emperor_direct_join_has_no_structural_owner_v71"
                            if not loop_owners else
                            "cook_emperor_direct_join_has_multiple_structural_"
                            "owners_v71"
                        ),
                        "edge_identity": pair,
                        "owner_kind": "loop_exit",
                        "owner_count": len(loop_owners),
                    })
                    details.append(detail)
                    continue
                owner_node = loop_owners[0]

            elif owner_kind == "continuation_gateway":
                gateway_owners = self._cook_emperor_select_gateway_owner_v71(
                    index,
                    pred_addr,
                    join_addr,
                )
                # Prefer the concrete join owner, then the owning conditional.
                concrete_join = [
                    node for node in gateway_owners
                    if self._unbound_emperor_addr_v69(
                        getattr(node, "cfg_node", None)
                    ) == join_addr
                ]
                selected = concrete_join or gateway_owners
                if len(selected) != 1:
                    failures.append({
                        "kind": (
                            "cook_emperor_direct_join_has_no_structural_owner_v71"
                            if not selected else
                            "cook_emperor_direct_join_has_multiple_structural_"
                            "owners_v71"
                        ),
                        "edge_identity": pair,
                        "owner_kind": "continuation_gateway",
                        "owner_count": len(selected),
                    })
                    details.append(detail)
                    continue
                owner_node = selected[0]

            else:
                failures.append({
                    "kind": (
                        "cook_emperor_direct_join_has_no_structural_owner_v71"
                    ),
                    "edge_identity": pair,
                    "classification": classification,
                })
                details.append(detail)
                continue

            record = self._cook_emperor_owner_record_v71(
                fact,
                owner_kind,
                owner_node,
                index,
                reason,
                evidence=classification.get("evidence"),
                arm=owner_arm,
            )
            owners_by_edge.setdefault(pair, []).append(record)
            owner_records.append(record)
            detail["owners"].append(dict(record))

            if owner_kind == "empty_branch_arm":
                gates = {
                    "branch_is_then_or_else": getattr(
                        owner_arm, "kind", None
                    ) in ("then", "else"),
                    "branch_direct_join_flag": bool(
                        getattr(owner_arm, "direct_join", False)
                    ),
                    "branch_edge_identity_exact": tuple(
                        getattr(owner_arm, "edge_identity", ()) or ()
                    ) == pair,
                    "branch_pred_addr_exact": getattr(
                        owner_arm, "pred_addr", None
                    ) == pred_addr,
                    "branch_join_addr_exact": getattr(
                        owner_arm, "join_addr", None
                    ) == join_addr,
                    "branch_structurally_empty_at_SGL": not bool(
                        list(getattr(owner_arm, "children", []) or [])
                    ),
                    "join_block_not_nested_in_arm": not (
                        self._bohdi_emperor_arm_contains_join_block_v70(
                            owner_arm,
                            join_addr,
                        )
                    ),
                    "SGL_emits_no_PHI_assignments": not bool(
                        getattr(
                            owner_arm,
                            "sgl_emits_phi_assignments",
                            False,
                        )
                    ),
                }
                failed_gates = [
                    name for name, passed in gates.items() if not passed
                ]
                detail["empty_arm_gates"] = gates
                if failed_gates:
                    failures.append({
                        "kind": (
                            "cook_emperor_empty_arm_contract_missing_v71"
                        ),
                        "edge_identity": pair,
                        "failed_gates": failed_gates,
                    })

        for pair, matches in owners_by_edge.items():
            if len(matches) != 1:
                failures.append({
                    "kind": (
                        "cook_emperor_direct_join_has_multiple_structural_"
                        "owners_v71"
                    ),
                    "edge_identity": pair,
                    "owner_count": len(matches),
                })

        # Unexpected legacy direct_join arm owners remain invalid: no SGL path
        # may invent edge identity outside the FunctionCFG frozen inventory.
        legacy_owners = self._bohdi_emperor_direct_join_arm_owners_v70()
        for pair, matches in legacy_owners.items():
            if pair in facts:
                continue
            failures.append({
                "kind": "cook_emperor_unfrozen_arm_owner_v71",
                "edge_identity": pair,
                "owner_count": len(matches),
            })

        self.cook_emperor_direct_join_owners_v71 = owner_records
        self.cook_emperor_direct_join_owners_by_edge_v71 = {
            pair: [dict(rec) for rec in records]
            for pair, records in owners_by_edge.items()
        }
        self.cook_emperor_empty_arm_owners_v71 = [
            dict(rec)
            for rec in owner_records
            if rec.get("owner_kind") == "empty_branch_arm"
        ]
        self.cook_emperor_predicate_owners_v71 = [
            dict(rec)
            for rec in owner_records
            if rec.get("owner_kind") == "predicate_composition"
        ]
        self.cook_emperor_gateway_owners_v71 = [
            dict(rec)
            for rec in owner_records
            if rec.get("owner_kind") == "continuation_gateway"
        ]
        self.cook_emperor_loop_exit_owners_v71 = [
            dict(rec)
            for rec in owner_records
            if rec.get("owner_kind") == "loop_exit"
        ]

        # v71 may stamp a previously implicit empty branch after the original
        # v69 build-time audit.  Refresh the compatibility audit so its
        # contract inventory is not stale.
        if not failures:
            self._audit_unbound_emperor_direct_join_edges_v69()

        audit = {
            "kind": (
                "sgl_cook_emperor_direct_join_ownership_verified_v71"
                if not failures else
                "sgl_cook_emperor_direct_join_ownership_failed_v71"
            ),
            "version": self.cook_emperor_version_v71,
            "frozen_direct_join_facts": len(facts),
            "typed_owner_edges": len(owners_by_edge),
            "typed_owner_records": len(owner_records),
            "empty_branch_arm_owners": len(
                self.cook_emperor_empty_arm_owners_v71
            ),
            "predicate_composition_owners": len(
                self.cook_emperor_predicate_owners_v71
            ),
            "continuation_gateway_owners": len(
                self.cook_emperor_gateway_owners_v71
            ),
            "loop_exit_owners": len(
                self.cook_emperor_loop_exit_owners_v71
            ),
            "details": details,
            "warnings": list(self.cook_emperor_warnings_v71),
            "failures": failures,
            "rule": (
                "every_FunctionCFG_frozen_direct_to_join_edge_has_exactly_"
                "one_typed_SGL_structural_owner_and_only_genuine_empty_arms_"
                "publish_the_PALemitter_attachment_surface"
            ),
            "topology_rewritten": False,
            "branch_polarity_rewritten": False,
            "phi_assignments_emitted_by_SGL": False,
        }
        self.cook_emperor_failures_v71 = failures
        self.cook_emperor_audit_v71 = audit
        self.cook_emperor_events_v71.append(dict(audit))

        # v70 compatibility is a derived empty-arm subset, not an independent
        # authority.  This keeps PALPHIfolder/PALemitter consumers stable.
        empty_pairs = {
            tuple(rec.get("edge_identity") or ())
            for rec in self.cook_emperor_empty_arm_owners_v71
        }
        self.bohdi_emperor_expected_empty_arm_edges_v70 = {
            pair: dict(fact)
            for pair, fact in facts.items()
            if pair in empty_pairs
        }
        self._bohdi_emperor_direct_join_arm_owners_v70()
        self.bohdi_emperor_failures_v70 = list(failures)
        self.bohdi_emperor_audit_v70 = {
            "kind": (
                "sgl_bohdi_emperor_empty_arm_ownership_verified_v70"
                if not failures else
                "sgl_bohdi_emperor_empty_arm_ownership_failed_v70"
            ),
            "version": self.bohdi_emperor_version_v70,
            "compatibility_source": self.cook_emperor_version_v71,
            "expected_binary_empty_arm_edges": len(empty_pairs),
            "structured_owner_edges": len(
                self.bohdi_emperor_empty_arm_owners_by_edge_v70
            ),
            "failures": list(failures),
            "typed_non_arm_edges_excluded": len(facts) - len(empty_pairs),
            "topology_rewritten": False,
            "branch_polarity_rewritten": False,
            "phi_assignments_emitted_by_SGL": False,
        }
        self.bohdi_emperor_events_v70.append(
            dict(self.bohdi_emperor_audit_v70)
        )

        if failures:
            raise RuntimeError(
                "PALSGLdecomp v71 cook-emperor typed direct-join ownership "
                "failed: %s" % failures
            )
        return audit

    def _publish_cook_emperor_handoff_v71(self):
        payload = {
            "cook_emperor_version_v71": self.cook_emperor_version_v71,
            "cook_emperor_cfg_direct_join_facts_v71": list(
                self.cook_emperor_cfg_direct_join_facts_v71
            ),
            "cook_emperor_cfg_direct_join_facts_by_edge_v71": dict(
                self.cook_emperor_cfg_direct_join_facts_by_edge_v71
            ),
            "cook_emperor_direct_join_route_hints_v71": list(
                self.cook_emperor_direct_join_route_hints_v71
            ),
            "cook_emperor_direct_join_owners_v71": list(
                self.cook_emperor_direct_join_owners_v71
            ),
            "cook_emperor_direct_join_owners_by_edge_v71": dict(
                self.cook_emperor_direct_join_owners_by_edge_v71
            ),
            "cook_emperor_empty_arm_owners_v71": list(
                self.cook_emperor_empty_arm_owners_v71
            ),
            "cook_emperor_predicate_owners_v71": list(
                self.cook_emperor_predicate_owners_v71
            ),
            "cook_emperor_gateway_owners_v71": list(
                self.cook_emperor_gateway_owners_v71
            ),
            "cook_emperor_loop_exit_owners_v71": list(
                self.cook_emperor_loop_exit_owners_v71
            ),
            "cook_emperor_events_v71": list(
                self.cook_emperor_events_v71
            ),
            "cook_emperor_warnings_v71": list(
                self.cook_emperor_warnings_v71
            ),
            "cook_emperor_failures_v71": list(
                self.cook_emperor_failures_v71
            ),
            "cook_emperor_audit_v71": dict(
                self.cook_emperor_audit_v71 or {}
            ),
        }

        for key, value in payload.items():
            setattr(self.func, "sgl_" + key, value)

        handoff = getattr(self.func, "sgl_metadata_handoff", None)
        if isinstance(handoff, dict):
            handoff.update(payload)

        debug = getattr(self.func, "sgl_loop_debug", None)
        if isinstance(debug, dict):
            debug.update(payload)

        return payload


    # =========================================================================
    # v69 UNBOUND-EMPEROR DIRECT-JOIN EDGE CUSTODY
    # =========================================================================

    @staticmethod
    def _unbound_emperor_addr_v69(value):
        if value is None:
            return None
        if isinstance(value, int):
            return value
        return getattr(value, "addr", None)

    def _unbound_emperor_direct_join_key_v69(self, record):
        if not isinstance(record, dict):
            return None
        return (
            record.get("condition_block_addr") or record.get("from"),
            record.get("branch_kind"),
            record.get("pred_addr") or record.get("from"),
            record.get("join_addr") or record.get("join") or record.get("to"),
        )

    @staticmethod
    def _bohdi_emperor_edge_pair_v70(record):
        if not isinstance(record, dict):
            return None
        edge_id = list(record.get("edge_id", []) or [])
        if len(edge_id) == 2:
            return (edge_id[0], edge_id[1])
        src = record.get("src_addr")
        dst = record.get("dst_addr")
        if src is None:
            src = record.get("branch_owner_addr")
        if dst is None:
            dst = record.get("join_addr")
        if src is None or dst is None:
            return None
        return (src, dst)

    def _refresh_bohdi_emperor_expected_empty_arm_edges_v70(self):
        """Compile FunctionCFG's exact binary direct-to-IPDOM inventory.

        The source list is authoritative only when the record carries the v23
        frozen edge marker.  Loop-header direct joins are deliberately excluded
        from empty-arm ownership; they remain ExecLoop exit edges.
        """
        sources = []
        for owner, attr in (
            (self.func, "cfg_direct_join_edges"),
            (self.cfg, "direct_join_edges"),
        ):
            try:
                values = getattr(owner, attr, None)
            except Exception:
                values = None
            for rec in list(values or []):
                if isinstance(rec, dict):
                    sources.append(dict(rec))

        # Preserve the constructor snapshot for diagnostics, but deduplicate by
        # canonical edge identity rather than object identity or list position.
        if not sources:
            sources = [
                dict(rec) for rec in list(
                    self.bohdi_emperor_cfg_direct_join_edges_v70 or []
                ) if isinstance(rec, dict)
            ]

        unique_sources = {}
        duplicate_conflicts = []
        for rec in sources:
            pair = self._bohdi_emperor_edge_pair_v70(rec)
            if pair is None:
                continue
            prior = unique_sources.get(pair)
            if prior is not None and prior != rec:
                duplicate_conflicts.append({
                    "kind": "bohdi_emperor_duplicate_CFG_direct_join_fact_v70",
                    "edge_identity": pair,
                    "prior": prior,
                    "duplicate": rec,
                })
                continue
            unique_sources[pair] = rec
        sources = list(unique_sources.values())
        self.bohdi_emperor_cfg_direct_join_edges_v70 = list(sources)

        expected = {}
        for rec in sources:
            pair = self._bohdi_emperor_edge_pair_v70(rec)
            if pair is None or not rec.get("direct_to_join"):
                continue
            owner_kind = rec.get("direct_join_owner_kind")
            empty_candidate = bool(
                rec.get("direct_join_empty_arm_candidate")
            )
            if not (
                empty_candidate
                or owner_kind == "binary_branch_arm"
            ):
                continue

            frozen = bool(rec.get("edge_identity_frozen"))
            if not frozen:
                frozen = bool(
                    rec.get("id_schema") == "cfg_edge_identity_v1"
                    and str(rec.get("kind") or "").startswith(
                        "cfg_edge_identity_fact"
                    )
                )
            normalized = dict(rec)
            normalized["edge_id"] = [pair[0], pair[1]]
            normalized["edge_identity_frozen"] = frozen
            normalized["direct_join_empty_arm_candidate"] = True
            normalized["direct_join_owner_kind"] = "binary_branch_arm"

            prior = expected.get(pair)
            if prior is not None and prior != normalized:
                duplicate_conflicts.append({
                    "kind": "bohdi_emperor_duplicate_CFG_direct_join_fact_v70",
                    "edge_identity": pair,
                    "prior": prior,
                    "duplicate": normalized,
                })
                continue
            expected[pair] = normalized

        self.bohdi_emperor_expected_empty_arm_edges_v70 = expected
        self.bohdi_emperor_warnings_v70.extend(duplicate_conflicts)
        return expected

    def _bohdi_emperor_cfg_direct_join_fact_v70(self, pred_addr, join_addr):
        pair = (pred_addr, join_addr)
        rec = self.bohdi_emperor_expected_empty_arm_edges_v70.get(pair)
        if isinstance(rec, dict):
            return rec
        self._refresh_bohdi_emperor_expected_empty_arm_edges_v70()
        rec = self.bohdi_emperor_expected_empty_arm_edges_v70.get(pair)
        return rec if isinstance(rec, dict) else None

    def _register_unbound_emperor_direct_join_edge_v69(
        self, from_node, target_node, branch, loop,
    ):
        """Attach one exact direct-to-IPDOM edge to its empty Exec arm.

        The edge is executable custody even when the arm has no CFG payload.
        Later PHI lowering may place predecessor-local transitions in this
        branch container without duplicating the IPDOM block itself.
        """
        pred_addr = self._unbound_emperor_addr_v69(from_node)
        join_addr = self._unbound_emperor_addr_v69(target_node)
        owner_if = getattr(branch, "parent", None)
        condition_addr = self._unbound_emperor_addr_v69(
            getattr(owner_if, "cfg_node", None)
        )
        branch_kind = getattr(branch, "kind", None)
        edge_identity = (pred_addr, join_addr)
        cfg_fact = self._bohdi_emperor_cfg_direct_join_fact_v70(
            pred_addr, join_addr
        )
        contract_id = (
            condition_addr, branch_kind, pred_addr, join_addr,
        )
        record = {
            "kind": "sgl_direct_join_empty_arm_edge_contract_v69",
            "version": self.unbound_emperor_version_v69,
            "contract_id": contract_id,
            "condition_block_addr": condition_addr,
            "branch_kind": branch_kind,
            "pred_addr": pred_addr,
            "join_addr": join_addr,
            "edge_identity": edge_identity,
            # Compatibility with v51/v62a consumers.
            "from": pred_addr,
            "to": join_addr,
            "join": join_addr,
            "loop": self._unbound_emperor_addr_v69(loop),
            "legacy_kind": "direct_join_empty_arm_v51",
            "execution_owner": "empty_structured_branch_edge",
            "join_block_owner": "single_post_branch_owner",
            "phi_transition_placement_authority": "PALPHIfolder",
            "emitter_lowering_authority": "PALemitter",
            "source_order_or_phi_ordinal_used": False,
            # v70 exact upstream authority and branch-container surface.
            "bohdi_emperor_version_v70": self.bohdi_emperor_version_v70,
            "edge_id_schema": (
                cfg_fact.get("id_schema")
                if isinstance(cfg_fact, dict) else
                "cfg_edge_identity_v1"
            ),
            "edge_identity_frozen": bool(
                isinstance(cfg_fact, dict)
                and cfg_fact.get("edge_identity_frozen")
            ),
            "direct_join": True,
            "direct_join_empty_arm_candidate": bool(
                isinstance(cfg_fact, dict)
                and cfg_fact.get("direct_join_empty_arm_candidate")
            ),
            "functioncfg_direct_join_fact": (
                dict(cfg_fact) if isinstance(cfg_fact, dict) else None
            ),
            "structured_arm_owner_schema": (
                "sgl_direct_join_arm_owner_v1"
            ),
            "sgl_emits_phi_assignments": False,
        }

        # v70: stable direct attributes are the downstream attachment surface.
        # SGL preserves the edge and emits no PHI assignment itself.
        branch.edge_identity = edge_identity
        branch.pred_addr = pred_addr
        branch.join_addr = join_addr
        branch.direct_join = True
        branch.direct_join_contract = dict(record)
        branch.direct_join_edge_fact = (
            dict(cfg_fact) if isinstance(cfg_fact, dict) else None
        )
        branch.direct_join_owner_schema = "sgl_direct_join_arm_owner_v1"
        branch.sgl_emits_phi_assignments = False
        branch.phi_transition_attachment_authority = "PALPHIfolder"

        if owner_if is not None:
            by_edge = dict(
                getattr(owner_if, "direct_join_arms_by_edge_v70", {}) or {}
            )
            by_edge[edge_identity] = branch
            owner_if.direct_join_arms_by_edge_v70 = by_edge

        existing = list(getattr(branch, "direct_join_edges", []) or [])
        if not any(
            self._unbound_emperor_direct_join_key_v69(item) == contract_id
            for item in existing if isinstance(item, dict)
        ):
            existing.append(dict(record))
        branch.direct_join_edges = existing
        branch.direct_join_edge_contracts_v69 = list(existing)

        if not any(
            self._unbound_emperor_direct_join_key_v69(item) == contract_id
            for item in self.unbound_emperor_direct_join_edge_contracts_v69
        ):
            self.unbound_emperor_direct_join_edge_contracts_v69.append(
                dict(record)
            )
        self.unbound_emperor_direct_join_edge_contracts_by_edge_v69.setdefault(
            edge_identity, []
        )
        if not any(
            self._unbound_emperor_direct_join_key_v69(item) == contract_id
            for item in self.unbound_emperor_direct_join_edge_contracts_by_edge_v69[
                edge_identity
            ]
        ):
            self.unbound_emperor_direct_join_edge_contracts_by_edge_v69[
                edge_identity
            ].append(dict(record))

        event = {
            "kind": "unbound_emperor_direct_join_edge_registered_v69",
            "version": self.unbound_emperor_version_v69,
            "contract_id": contract_id,
            "edge_identity": edge_identity,
            "branch_kind": branch_kind,
            "condition_block_addr": condition_addr,
        }
        if event not in self.unbound_emperor_direct_join_edge_events_v69:
            self.unbound_emperor_direct_join_edge_events_v69.append(event)
        return record

    def _unbound_emperor_direct_join_branch_owners_v69(self):
        owners = {}

        def walk(node):
            if node is None:
                return
            if getattr(node, "kind", None) in ("then", "else"):
                for record in list(
                    getattr(node, "direct_join_edges", []) or []
                ):
                    if not isinstance(record, dict):
                        continue
                    key = self._unbound_emperor_direct_join_key_v69(record)
                    owners.setdefault(key, []).append((node, record))
            for child in list(getattr(node, "children", []) or []):
                walk(child)

        walk(self.root)
        return owners

    def _audit_unbound_emperor_direct_join_edges_v69(self):
        owners = self._unbound_emperor_direct_join_branch_owners_v69()
        failures = []
        details = []

        for record in list(
            self.unbound_emperor_direct_join_edge_contracts_v69 or []
        ):
            key = self._unbound_emperor_direct_join_key_v69(record)
            matches = list(owners.get(key, []) or [])
            detail = {
                "contract_id": record.get("contract_id"),
                "edge_identity": record.get("edge_identity"),
                "branch_kind": record.get("branch_kind"),
                "owner_count": len(matches),
                "owners": [],
            }
            if not matches:
                failures.append({
                    "contract_id": record.get("contract_id"),
                    "reason": "direct_join_edge_has_no_exec_branch_owner",
                })
            for branch, branch_record in matches:
                parent = getattr(branch, "parent", None)
                parent_addr = self._unbound_emperor_addr_v69(
                    getattr(parent, "cfg_node", None)
                )
                gates = {
                    "branch_kind_matches": getattr(branch, "kind", None)
                    == record.get("branch_kind"),
                    "parent_is_if": getattr(parent, "kind", None) == "if",
                    "condition_addr_matches": parent_addr
                    == record.get("condition_block_addr"),
                    "pred_matches_condition": record.get("pred_addr")
                    == record.get("condition_block_addr"),
                    "join_is_direct_target": record.get("join_addr")
                    == record.get("to"),
                }
                detail["owners"].append({
                    "branch_kind": getattr(branch, "kind", None),
                    "condition_block_addr": parent_addr,
                    "gates": gates,
                })
                failed = [name for name, ok in gates.items() if not ok]
                if failed:
                    failures.append({
                        "contract_id": record.get("contract_id"),
                        "reason": "direct_join_branch_owner_gate_failure",
                        "failed_gates": failed,
                    })
            details.append(detail)

        audit = {
            "kind": (
                "sgl_unbound_emperor_direct_join_edge_custody_verified_v69"
                if not failures else
                "sgl_unbound_emperor_direct_join_edge_custody_failed_v69"
            ),
            "version": self.unbound_emperor_version_v69,
            "active": bool(
                self.unbound_emperor_direct_join_edge_contracts_v69
            ),
            "contracts": len(
                self.unbound_emperor_direct_join_edge_contracts_v69
            ),
            "edge_keys": len(
                self.unbound_emperor_direct_join_edge_contracts_by_edge_v69
            ),
            "branch_owner_keys": len(owners),
            "details": details,
            "failures": failures,
            "rule": (
                "direct_to_ipdom_edge_remains_owned_by_exact_empty_"
                "structured_branch_container"
            ),
        }
        self.unbound_emperor_direct_join_edge_failures_v69 = failures
        self.unbound_emperor_direct_join_edge_audit_v69 = audit
        self.unbound_emperor_direct_join_edge_events_v69.append(dict(audit))
        if failures:
            raise RuntimeError(
                "PALSGLdecomp v69 direct-join edge custody failed: %s"
                % failures
            )
        return audit

    def _bohdi_emperor_direct_join_arm_owners_v70(self):
        owners = {}
        owner_records = []

        def walk(node):
            if node is None:
                return
            if getattr(node, "kind", None) in ("then", "else"):
                if bool(getattr(node, "direct_join", False)):
                    pair = getattr(node, "edge_identity", None)
                    if isinstance(pair, list):
                        pair = tuple(pair)
                    if not (
                        isinstance(pair, tuple) and len(pair) == 2
                    ):
                        pair = (
                            getattr(node, "pred_addr", None),
                            getattr(node, "join_addr", None),
                        )
                    record = {
                        "kind": "sgl_direct_join_arm_owner_v70",
                        "version": self.bohdi_emperor_version_v70,
                        "edge_identity": pair,
                        "pred_addr": getattr(node, "pred_addr", None),
                        "join_addr": getattr(node, "join_addr", None),
                        "branch_kind": getattr(node, "kind", None),
                        "condition_block_addr": self._unbound_emperor_addr_v69(
                            getattr(getattr(node, "parent", None), "cfg_node", None)
                        ),
                        "child_kinds": [
                            getattr(child, "kind", None)
                            for child in list(getattr(node, "children", []) or [])
                        ],
                        "structurally_empty_at_SGL": not bool(
                            list(getattr(node, "children", []) or [])
                        ),
                        "sgl_emits_phi_assignments": bool(
                            getattr(node, "sgl_emits_phi_assignments", False)
                        ),
                        "owner_schema": getattr(
                            node, "direct_join_owner_schema", None
                        ),
                    }
                    owners.setdefault(pair, []).append((node, record))
                    owner_records.append(record)
            for child in list(getattr(node, "children", []) or []):
                walk(child)

        walk(self.root)
        self.bohdi_emperor_empty_arm_owners_v70 = owner_records
        self.bohdi_emperor_empty_arm_owners_by_edge_v70 = {
            pair: [dict(record) for _node, record in matches]
            for pair, matches in owners.items()
        }
        return owners

    def _bohdi_emperor_arm_contains_join_block_v70(self, arm, join_addr):
        found = []

        def walk(node):
            if node is None:
                return
            if getattr(node, "kind", None) == "block":
                addr = self._unbound_emperor_addr_v69(
                    getattr(node, "cfg_node", None)
                )
                if addr == join_addr:
                    found.append(addr)
            for child in list(getattr(node, "children", []) or []):
                walk(child)

        for child in list(getattr(arm, "children", []) or []):
            walk(child)
        return bool(found)

    def _audit_bohdi_emperor_empty_arm_ownership_v70(self):
        expected = self._refresh_bohdi_emperor_expected_empty_arm_edges_v70()
        owners = self._bohdi_emperor_direct_join_arm_owners_v70()
        failures = []
        details = []

        cfg_direct_total = len(self.bohdi_emperor_cfg_direct_join_edges_v70)
        excluded_loop_edges = sum(
            1 for rec in self.bohdi_emperor_cfg_direct_join_edges_v70
            if isinstance(rec, dict)
            and rec.get("direct_to_join")
            and not (
                rec.get("direct_join_empty_arm_candidate")
                or rec.get("direct_join_owner_kind") == "binary_branch_arm"
            )
        )

        for pair, fact in sorted(
            expected.items(),
            key=lambda item: (str(item[0][0]), str(item[0][1])),
        ):
            matches = list(owners.get(pair, []) or [])
            detail = {
                "edge_identity": pair,
                "FunctionCFG_fact": dict(fact),
                "owner_count": len(matches),
                "owners": [],
            }
            if len(matches) != 1:
                failures.append({
                    "kind": "bohdi_emperor_direct_join_owner_count_failure_v70",
                    "edge_identity": pair,
                    "owner_count": len(matches),
                    "expected_owner_count": 1,
                })

            for branch, owner_record in matches:
                parent = getattr(branch, "parent", None)
                parent_addr = self._unbound_emperor_addr_v69(
                    getattr(parent, "cfg_node", None)
                )
                gates = {
                    "FunctionCFG_edge_identity_frozen": bool(
                        fact.get("edge_identity_frozen")
                    ),
                    "FunctionCFG_direct_to_join": bool(
                        fact.get("direct_to_join")
                    ),
                    "FunctionCFG_binary_empty_arm": bool(
                        fact.get("direct_join_empty_arm_candidate")
                        or fact.get("direct_join_owner_kind")
                        == "binary_branch_arm"
                    ),
                    "branch_is_then_or_else": getattr(
                        branch, "kind", None
                    ) in ("then", "else"),
                    "branch_direct_join_flag": bool(
                        getattr(branch, "direct_join", False)
                    ),
                    "branch_edge_identity_exact": tuple(
                        getattr(branch, "edge_identity", ()) or ()
                    ) == pair,
                    "branch_pred_addr_exact": getattr(
                        branch, "pred_addr", None
                    ) == pair[0],
                    "branch_join_addr_exact": getattr(
                        branch, "join_addr", None
                    ) == pair[1],
                    "parent_is_ExecIf": getattr(parent, "kind", None) == "if",
                    "parent_condition_is_predecessor": parent_addr == pair[0],
                    "branch_structurally_empty_at_SGL": not bool(
                        list(getattr(branch, "children", []) or [])
                    ),
                    "join_block_not_nested_in_arm": not (
                        self._bohdi_emperor_arm_contains_join_block_v70(
                            branch, pair[1]
                        )
                    ),
                    "SGL_emits_no_PHI_assignments": not bool(
                        getattr(branch, "sgl_emits_phi_assignments", False)
                    ),
                    "owner_schema_exact": getattr(
                        branch, "direct_join_owner_schema", None
                    ) == "sgl_direct_join_arm_owner_v1",
                }
                detail["owners"].append({
                    "record": dict(owner_record),
                    "gates": gates,
                })
                failed = [name for name, ok in gates.items() if not ok]
                if failed:
                    failures.append({
                        "kind": "bohdi_emperor_direct_join_owner_gate_failure_v70",
                        "edge_identity": pair,
                        "branch_kind": getattr(branch, "kind", None),
                        "failed_gates": failed,
                    })
            details.append(detail)

        for pair, matches in owners.items():
            if pair in expected:
                continue
            failures.append({
                "kind": "bohdi_emperor_unfrozen_or_unexpected_arm_owner_v70",
                "edge_identity": pair,
                "owner_count": len(matches),
                "reason": (
                    "structured direct-join arm has no matching FunctionCFG "
                    "v23 frozen binary direct-join fact"
                ),
            })

        audit = {
            "kind": (
                "sgl_bohdi_emperor_empty_arm_ownership_verified_v70"
                if not failures else
                "sgl_bohdi_emperor_empty_arm_ownership_failed_v70"
            ),
            "version": self.bohdi_emperor_version_v70,
            "cfg_direct_join_edges_total": cfg_direct_total,
            "cfg_loop_header_direct_join_edges_excluded": excluded_loop_edges,
            "expected_binary_empty_arm_edges": len(expected),
            "structured_owner_edges": len(owners),
            "structured_owner_records": sum(len(v) for v in owners.values()),
            "details": details,
            "failures": failures,
            "rule": (
                "every_FunctionCFG_frozen_binary_direct_to_IPDOM_edge_has_"
                "exactly_one_empty_ExecIf_arm_owner_and_SGL_emits_no_PHI"
            ),
            "topology_rewritten": False,
            "branch_polarity_rewritten": False,
            "phi_assignments_emitted_by_SGL": False,
        }
        self.bohdi_emperor_failures_v70 = failures
        self.bohdi_emperor_audit_v70 = audit
        self.bohdi_emperor_events_v70.append(dict(audit))
        if failures:
            raise RuntimeError(
                "PALSGLdecomp v70 bohdi-emperor empty-arm ownership failed: %s"
                % failures
            )
        return audit

    def _direct_join_single_owner_eligible_v51(self, from_node, target_node, loop):
        """
        True only for an ordinary branch-local IPDOM which can be emitted once
        after the conditional.

        Loop headers, latches, executable latch updates, and tail-test/chain
        nodes are control transfers rather than ordinary joins.  Their direct
        edges must remain under the established loop machinery or iterator
        updates can disappear from one path.
        """
        if from_node is None or target_node is None:
            return False
        if target_node is not getattr(from_node, "ipdom", None):
            return False

        if target_node in set(getattr(self, "loop_headers", set()) or set()):
            return False
        if target_node in set(getattr(self, "loop_tail_test_nodes", set()) or set()):
            return False
        if self._target_is_loop_tail_chain_node(target_node):
            return False

        if loop is None:
            return True

        try:
            if target_node is loop or target_node not in set(self.loop_nodes.get(loop, set()) or set()):
                return False
        except Exception:
            return False

        try:
            if self._target_is_loop_latch_node(loop, target_node):
                return False
        except Exception:
            return False

        try:
            if self._is_executable_latch_update_node(loop, target_node):
                return False
        except Exception:
            return False

        return True

    def _emit_branch_arm(self, from_node, target_node, parent, stop_nodes):
        if target_node is None:
            return

        loop = self._innermost_loop_for_node(from_node)

        # v51: an ordinary branch's own IPDOM is a structural boundary, never arm-local
        # content.  A direct edge to that join represents an empty arm; the
        # enclosing conditional emits the join exactly once after both arms.
        #
        # Keep loop-exit custody on the established v33-v44 paths: this rule is
        # limited to joins which remain inside the same innermost loop region.
        # The direct edge itself is retained on the empty Exec arm so PHI
        # lowering can later attach predecessor-specific assignments without
        # reintroducing the join block inside the arm.
        branch_join = getattr(from_node, "ipdom", None)
        direct_join_classification_v71 = (
            self._classify_direct_join_owner_kind_v71(
                from_node,
                target_node,
                parent_arm=parent,
                loop=loop,
            )
        )
        if (
            direct_join_classification_v71.get("owner_kind")
            == "empty_branch_arm"
        ):
            edge_rec = self._register_unbound_emperor_direct_join_edge_v69(
                from_node, target_node, parent, loop
            )
            self._register_cook_emperor_route_hint_v71(
                from_node,
                target_node,
                "empty_branch_arm",
                owner_node=parent,
                reason="emit_branch_arm_direct_ipdom_v71",
                evidence=direct_join_classification_v71,
            )

            self._metadata_record_event_v26(
                "direct_join_arm_deferred_v51",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                join=self._addr_v26(branch_join),
                loop=self._addr_v26(loop),
                target_exec=bool(self._node_has_executable_ops_cfg(target_node)),
                reason="branch_ipdom_has_single_post_branch_owner",
            )
            self.branch_control_events.append({
                "kind": "direct_join_arm_deferred_v51",
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "join": getattr(branch_join, "addr", None),
                "loop": getattr(loop, "addr", None),
                "source": "ipdom_single_owner_v51",
            })
            return

        # v26: Shared continuation gateways/join conditions must be emitted by
        # their owning continuation path, not duplicated as branch-local action.
        if self._metadata_target_is_continuation_gateway_v26(target_node, owner_loop=loop, from_node=from_node):
            if target_node in set(stop_nodes or set()):
                self.branch_control_events.append({
                    "kind": "metadata_gateway_arm_deferred",
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(loop, "addr", None),
                    "source": "semantic_graph_metadata_v26",
                })
                self._register_cook_emperor_route_hint_v71(
                    from_node,
                    target_node,
                    "continuation_gateway",
                    owner_node=getattr(parent, "parent", None),
                    reason="metadata_gateway_arm_deferred_v71",
                )
                return

        # Body-header loop tail-chain nodes are emitted once in the loop
        # epilogue/tail position. They must not become optional branch arms,
        # even when they contain executable update ops such as local_14++.
        if self._target_is_loop_tail_chain_node(target_node):
            self.branch_control_events.append({
                "kind": "tail_chain_arm_deferred",
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "tail_header": getattr(self._loop_tail_header_for_node(target_node), "addr", None),
                "source": "cfg_metadata_v19",
            })
            self._register_cook_emperor_route_hint_v71(
                from_node,
                target_node,
                "loop_exit",
                owner_node=self.loop_nodes.get(
                    self._loop_tail_header_for_node(target_node)
                ),
                reason="tail_chain_arm_deferred_v71",
            )
            return

        # Latch/update blocks are executable loop epilogues. They may be
        # reached from multiple branch arms and must not be erased by global
        # visited. In v19, lower them as block + explicit continue so the
        # ExecTree carries state-machine truth instead of relying on fall-through.
        if loop is not None and self._target_is_loop_latch_node(loop, target_node):
            if self._node_has_executable_ops_cfg(target_node):
                parent.add(self._latch_update_then_continue_node(
                    target_node,
                    loop,
                    "latch_update_branch_arm",
                ))
                self.branch_control_events.append({
                    "kind": "latch_update_continue",
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(loop, "addr", None),
                    "source": "cfg_metadata_v19",
                })
                return

        # If the target is a structured join/fallthrough, suppress only when
        # it is truly non-executable. Executable joins/latches must survive,
        # except for known tail-chain nodes handled above.
        if target_node in set(stop_nodes or set()):
            # v38: this is the bypass that can glue a shared executable join
            # into a branch arm before _branch_arm_control_node(),
            # _populate_conditional_latch_arm(), or _action_then_break_node()
            # can apply the v33-v37 loop-exit gateway guards.
            #
            # Keep the override narrow:
            #   * only at the stop-node/join bypass;
            #   * only when v37 can recover a conditional-latch peer/backedge
            #     owner or prove the target as a shared continuation gateway;
            #   * emit break for the recovered loop and leave the stop node for
            #     the enclosing continuation traversal.
            try:
                peer_loop_v38 = self._conditional_latch_peer_backedge_owner_v37(from_node, target_node)
            except Exception:
                peer_loop_v38 = None
            try:
                gateway_loop_v38 = peer_loop_v38 or loop
                gateway_shape_v38 = bool(
                    gateway_loop_v38 is not None
                    and self._target_gateway_shape_for_loop_v37(gateway_loop_v38, from_node, target_node)
                )
            except Exception:
                gateway_shape_v38 = False

            self._metadata_record_event_v26(
                "emit_branch_arm_stop_node_probe_v38",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                loop=self._addr_v26(loop),
                peer_loop=self._addr_v26(peer_loop_v38),
                target_exec=bool(self._node_has_executable_ops_cfg(target_node)),
                target_cond=bool(self._get_condition(target_node) is not None),
                gateway_shape=bool(gateway_shape_v38),
                stop_nodes=[self._addr_v26(n) for n in list(stop_nodes or set())],
            )

            v38_loop = self._conditional_latch_gateway_override_loop_v37(
                from_node,
                target_node,
                preferred_loop=loop,
                arm="stop_node",
                source="emit_branch_arm_stop_node_gateway_v38",
                record=True,
            )
            if v38_loop is not None:
                parent.add(ExecBreak(v38_loop, "stop_node_peer_gateway_v38"))
                self.branch_control_events.append({
                    "kind": "emit_branch_arm_stop_node_gateway_deferred_v38",
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(v38_loop, "addr", None),
                    "preferred_loop": getattr(loop, "addr", None),
                    "source": "emit_branch_arm_stop_node_gateway_v38",
                })
                self._metadata_record_event_v26(
                    "emit_branch_arm_stop_node_gateway_deferred_v38",
                    from_addr=self._addr_v26(from_node),
                    target=self._addr_v26(target_node),
                    selected_loop=self._addr_v26(v38_loop),
                    preferred_loop=self._addr_v26(loop),
                    peer_loop=self._addr_v26(peer_loop_v38),
                    gateway_shape=bool(gateway_shape_v38),
                )
                self._register_cook_emperor_route_hint_v71(
                    from_node,
                    target_node,
                    "continuation_gateway",
                    owner_node=getattr(parent, "parent", None),
                    reason="stop_node_peer_gateway_v38_v71",
                )
                return

            if self._metadata_target_is_continuation_gateway_v26(target_node, owner_loop=loop, from_node=from_node):
                self.branch_control_events.append({
                    "kind": "metadata_gateway_stop_deferred",
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(loop, "addr", None),
                    "source": "semantic_graph_metadata_v26",
                })
                self._register_cook_emperor_route_hint_v71(
                    from_node,
                    target_node,
                    "continuation_gateway",
                    owner_node=getattr(parent, "parent", None),
                    reason="metadata_gateway_stop_deferred_v71",
                )
                return
            if self._node_has_executable_ops_cfg(target_node):
                parent.add(ExecBlock(target_node))
            return

        ctrl = self._branch_arm_control_node(from_node, target_node)

        if ctrl is not None:
            parent.add(ctrl)
            return

        # v19: switch/fallthrough meshes can share an executable linear tail
        # between branch arms. Ordinary _emit_node/_emit_linear_sequence uses
        # global visited and may erase that tail on the second path. Emit these
        # short action chains as path-local branch content instead.
        if self._emit_branch_arm_linear_tail(from_node, target_node, parent, stop_nodes):
            return

        self._emit_node(target_node, parent, stop_nodes=stop_nodes)


    def _make_tail_chain_node(self, header, index=0):
        chain = list(self.loop_tail_chains.get(header, []) or [])

        if index >= len(chain):
            return None

        node = chain[index]
        cond = self._get_condition(node)

        if cond is None:
            return None

        true_node = self._true_edge(node)
        false_node = self._false_edge(node)

        cond = self._condition_for_branch_then(node, true_node, cond)

        if_node = ExecIf(None, cond)
        if_node.tail_test_node = node
        if_node.tail_test_header = header
        if_node.raw_polarity_consumed = True
        if_node.edge_condition_source_v25 = getattr(cond, "reason", None)

        self._populate_tail_arm(if_node.then_branch, header, chain, index, true_node)
        self._populate_tail_arm(if_node.else_branch, header, chain, index, false_node)

        return if_node

    def _tail_target_is_deferred_normal_gateway_v39(self, header, node, target, source=None):
        """
        v39: final owner fix for body-header tail-chain arms.

        VT01 proved the glued 0x10125c block was not inserted through the
        conditional-latch branch-arm consumers.  It was inserted by
        _action_then_break_node(reason='tail_action_exit') from
        _populate_tail_arm(), with from_node=None.  Therefore all v33-v38
        conditional-latch guards missed it.

        Generic rule:
            A target outside a body-header loop that is already a normal
            loop exit or shared continuation gateway is not branch-local
            action.  Emit only break(header) and let the enclosing traversal
            emit that target after the loop.

        This keeps private executable cleanup/action exits intact: only
        normal exits / structural gateways are deferred.
        """
        if header is None or target is None:
            return False

        hnodes = set(self.loop_nodes.get(header, set()) or set())
        target_outside = bool(target not in hnodes)
        if not target_outside:
            return False

        if target in self.loop_headers:
            return False

        if self._target_is_loop_tail_chain_node(target):
            return False

        if self._target_is_function_exit_block(target):
            return False

        static_normal = False
        dynamic_normal = False
        gateway = False
        structural_gateway = False

        try:
            static_normal = target in set(self.loop_normal_exits.get(header, set()) or set())
        except Exception:
            static_normal = False

        try:
            dynamic_normal = target in set(self._get_loop_normal_exits(header) or set())
        except Exception:
            dynamic_normal = False

        try:
            gateway = bool(self._metadata_target_is_continuation_gateway_v26(target, owner_loop=header, from_node=node))
        except Exception:
            gateway = False

        try:
            structural_gateway = bool(self._structural_target_is_continuation_gateway_v32(target, owner_loop=header, from_node=node))
        except Exception:
            structural_gateway = False

        is_condition = self._get_condition(target) is not None
        has_exec = self._node_has_executable_ops_cfg(target)

        should_defer = bool(
            target_outside
            and (static_normal or dynamic_normal or gateway or structural_gateway)
            and (is_condition or gateway or structural_gateway or dynamic_normal or static_normal)
        )

        # Keep the debug narrow: record full rejection details only for the
        # glued class we are chasing, or when the rule actually fires.
        relevant = (
            should_defer
            or self._addr_v26(target) == 0x10125c
            or self._addr_v26(node) == 0x101235
        )
        if relevant:
            self._metadata_record_event_v26(
                "tail_normal_gateway_%s_v39" % ("deferred" if should_defer else "rejected"),
                source=source or "populate_tail_arm_v39",
                node=self._addr_v26(node),
                target=self._addr_v26(target),
                header=self._addr_v26(header),
                target_outside=target_outside,
                static_normal=static_normal,
                dynamic_normal=dynamic_normal,
                gateway=gateway,
                structural_gateway=structural_gateway,
                is_condition=is_condition,
                has_executable_ops=has_exec,
                pred_addrs=[self._addr_v26(p) for p in list(self._predecessors(target) or [])],
                succ_addrs=[self._addr_v26(s) for s in list(self._successors(target) or [])],
            )

        return should_defer

    def _populate_tail_arm(self, branch, header, chain, index, target):
        if target is None:
            return

        node = chain[index] if 0 <= index < len(chain) else None

        if target is header:
            branch.add(ExecContinue(header, "tail_backedge"))
            self.branch_control_events.append({
                "kind": "tail_continue",
                "from": getattr(node, "addr", None),
                "to": getattr(target, "addr", None),
                "loop": getattr(header, "addr", None),
                "source": "cfg_metadata_v19",
            })
            return

        if index + 1 < len(chain) and target is chain[index + 1]:
            nxt = self._make_tail_chain_node(header, index + 1)
            if nxt is not None:
                branch.add(nxt)
            return

        # Target outside the loop.  A concrete RETURN/no-return block is a
        # path-local terminal action, not a break to ordinary post-loop code.
        if target not in self.loop_nodes.get(header, set()):
            terminal = self._path_local_terminal_block_v56(
                node,
                target,
                header,
                source="tail_chain_terminal_exit_v56",
                arm="tail",
            )
            if terminal is not None:
                branch.add(terminal)
                return

            if node is not None and (self._edge_is_function_exit(node, target) or self._target_is_function_exit_block(target)):
                branch.add(ExecBreak(header, "tail_to_synthetic_function_exit_v56"))
                self.branch_control_events.append({
                    "kind": "tail_synthetic_function_exit_break_v56",
                    "from": getattr(node, "addr", None),
                    "to": getattr(target, "addr", None),
                    "loop": getattr(header, "addr", None),
                    "source": "tail_chain_terminal_exit_v56",
                })
                return

            # v39: a body-header tail-chain arm that reaches a normal
            # loop-exit / shared continuation gateway must not inline that
            # gateway as branch-local action.  VT01 showed the glued block
            # reached _action_then_break_node with reason='tail_action_exit'
            # and from_node=None, bypassing all conditional-latch guards.
            if self._tail_target_is_deferred_normal_gateway_v39(
                header,
                node,
                target,
                source="populate_tail_arm_outside_target_v39",
            ):
                branch.add(ExecBreak(header, "tail_to_normal_gateway_v39"))
                self.branch_control_events.append({
                    "kind": "tail_normal_gateway_deferred_v39",
                    "from": getattr(node, "addr", None),
                    "to": getattr(target, "addr", None),
                    "loop": getattr(header, "addr", None),
                    "source": "populate_tail_arm_outside_target_v39",
                })
                return

            if self._node_has_executable_ops_cfg(target):
                branch.add(self._action_then_break_node(target, header, "tail_action_exit"))
            else:
                branch.add(ExecBreak(header, "tail_exit"))
            return

        # Conservative fallback: ordinary block/flow inside loop.
        if self._node_has_executable_ops_cfg(target):
            branch.add(ExecBlock(target))
            self.visited.add(target)


    def _emit_tail_chain_for_loop(self, header, loop):
        chain = list(self.loop_tail_chains.get(header, []) or [])

        if not chain:
            return

        first = chain[0]

        if self._node_has_executable_ops(first) and first not in self.visited:
            self.visited.add(first)
            loop.body.add(ExecBlock(first))
            self.branch_control_events.append({
                "kind": "tail_epilogue_block",
                "node": getattr(first, "addr", None),
                "loop": getattr(header, "addr", None),
                "source": "cfg_metadata_v19",
            })

        tail_if = self._make_tail_chain_node(header, 0)

        if tail_if is not None:
            loop.body.add(tail_if)

        for n in chain:
            self.visited.add(n)




    def _conditional_latch_peer_backedge_owner_v37(self, from_node, target_node=None):
        """
        Recover the true small-loop owner for a conditional latch/body test by
        looking at the *peer* successor that continues to a loop header.

        This is needed when natural-loop membership is incomplete for an
        optimized/raw-normalized latch block: from_node may not be recorded in
        loop_nodes[small_header], so _edge_exits_loop(from_node, target) can
        return the enclosing loop or None.  The local CFG still proves the
        latch shape when one successor is a loop header/backedge and the other
        successor is the candidate exit/gateway.

        Generic shape:
            conditional node N
              edge A -> loop header H       (continue/backedge peer)
              edge B -> target outside H    (exit/gateway candidate)

        Return H, preferring the smallest candidate loop.  This helper does not
        itself decide whether the target is a gateway; consumers must prove that
        separately before using the owner override.
        """
        if from_node is None:
            return None
        if self._get_condition(from_node) is None:
            return None

        candidates = []
        for peer in list(self._successors(from_node) or []):
            if peer is None or peer is target_node:
                continue

            # Direct backedge/continue to a known loop header is the strongest
            # local proof.  This catches the gamma latch peer -> 0x10124a form.
            if peer in self.loop_headers:
                candidates.append(peer)

            # Metadata/CFG continue helper when it is available and precise.
            try:
                cont = self._edge_continues_loop(from_node, peer)
                if cont is not None:
                    candidates.append(cont)
            except Exception:
                pass

            # Executable latch/update peer that returns to a loop header.  Keep
            # this conservative: all successors of the peer must be that header.
            try:
                for h in list(self.loop_headers or []):
                    if self._is_executable_latch_update_node(h, peer):
                        candidates.append(h)
            except Exception:
                pass

        # Unique, smallest loop first.
        uniq = []
        seen = set()
        for c in candidates:
            if c is None or c in seen:
                continue
            seen.add(c)
            uniq.append(c)

        uniq.sort(key=lambda h: len(set(self.loop_nodes.get(h, set()) or set())) or 10**9)
        return uniq[0] if uniq else None

    def _target_gateway_shape_for_loop_v37(self, loop_header, from_node, target_node):
        """
        Return True when target_node is a shared conditional/ipdom continuation
        gateway for loop_header.  This deliberately accepts proof through the
        loop header itself when the exact latch/body from_node is missing from
        loop_nodes[loop_header].
        """
        if loop_header is None or target_node is None:
            return False
        if target_node in self.loop_headers:
            return False
        if self._target_is_loop_tail_chain_node(target_node):
            return False
        if self._target_is_function_exit_block(target_node):
            return False

        # First consume metadata/structural gateway facts with the exact edge.
        for proof_from in (from_node, loop_header):
            if proof_from is None:
                continue
            try:
                if self._metadata_target_is_continuation_gateway_v26(
                    target_node,
                    owner_loop=loop_header,
                    from_node=proof_from,
                ):
                    return True
            except Exception:
                pass
            try:
                if self._structural_target_is_continuation_gateway_v32(
                    target_node,
                    owner_loop=loop_header,
                    from_node=proof_from,
                ):
                    return True
            except Exception:
                pass

        # Local shape fallback: conditional/shared/ipdom target with incoming
        # paths both from inside and outside the small loop.  This is still
        # generic and does not depend on addresses or constants.
        owner_nodes = set(self.loop_nodes.get(loop_header, set()) or set())
        preds = list(self._predecessors(target_node) or [])
        pred_set = set(preds)
        outside_preds = [p for p in preds if p not in owner_nodes]
        inside_preds = [p for p in preds if p in owner_nodes]
        is_condition = self._get_condition(target_node) is not None
        shared_pred = len(pred_set) >= 2 and bool(outside_preds)

        ipdom_join = False
        try:
            for n in self._real_nodes():
                if n is target_node:
                    continue
                # Prefer enclosing decision nodes outside the small loop, but
                # do not require perfect natural-loop membership.
                if owner_nodes and n in owner_nodes and n is not loop_header:
                    continue
                if getattr(n, "ipdom", None) is not target_node:
                    continue
                if from_node is None or self._reaches(n, from_node) or self._reaches(n, loop_header):
                    ipdom_join = True
                    break
        except Exception:
            ipdom_join = False

        return bool(is_condition and (shared_pred or ipdom_join or inside_preds or outside_preds))

    def _conditional_latch_gateway_override_loop_v37(self, from_node, target_node, preferred_loop=None, arm=None, source=None, record=True):
        """
        Final guarded override for the glued latch-tail class.

        Use only at conditional-latch / loop-exit branch-arm consumers.  It
        recovers the true inner loop from the peer backedge/continue successor,
        then lets shared continuation-gateway metadata beat the older
        executable-target => action+break harness.

        Returns the loop that should be broken, or None.
        """
        if from_node is None or target_node is None:
            return None
        if self._get_condition(from_node) is None:
            return None

        peer_loop = self._conditional_latch_peer_backedge_owner_v37(from_node, target_node)
        candidates = []
        if peer_loop is not None:
            candidates.append(peer_loop)
        if preferred_loop is not None and preferred_loop not in candidates:
            candidates.append(preferred_loop)

        for loop_header in candidates:
            if loop_header is None:
                continue
            if target_node is loop_header:
                continue
            if target_node in self.loop_headers:
                continue
            if self._target_is_loop_tail_chain_node(target_node):
                continue
            if self._target_is_function_exit_block(target_node):
                continue

            owner_nodes = set(self.loop_nodes.get(loop_header, set()) or set())
            peer_proves_owner = (loop_header is peer_loop)

            # If the exact from_node is absent from the natural-loop node set,
            # the peer-backedge proof is allowed to stand in for membership.
            from_inside = bool(from_node in owner_nodes or peer_proves_owner)
            target_outside = bool(target_node not in owner_nodes)

            gateway = self._target_gateway_shape_for_loop_v37(loop_header, from_node, target_node)

            if from_inside and gateway and (target_outside or peer_proves_owner):
                if record:
                    self._metadata_record_event_v26(
                        "conditional_latch_peer_gateway_deferred_v37",
                        source=source or "conditional_latch_gateway_override_v37",
                        from_addr=self._addr_v26(from_node),
                        target=self._addr_v26(target_node),
                        selected_loop=self._addr_v26(loop_header),
                        preferred_loop=self._addr_v26(preferred_loop),
                        peer_loop=self._addr_v26(peer_loop),
                        arm=arm,
                        from_inside=from_inside,
                        target_outside=target_outside,
                        gateway=True,
                    )
                return loop_header

            if record:
                self._metadata_record_event_v26(
                    "conditional_latch_peer_gateway_rejected_v37",
                    source=source or "conditional_latch_gateway_override_v37",
                    from_addr=self._addr_v26(from_node),
                    target=self._addr_v26(target_node),
                    candidate_loop=self._addr_v26(loop_header),
                    preferred_loop=self._addr_v26(preferred_loop),
                    peer_loop=self._addr_v26(peer_loop),
                    arm=arm,
                    from_inside=from_inside,
                    target_outside=target_outside,
                    gateway=bool(gateway),
                    target_is_loop_header=bool(target_node in self.loop_headers),
                    target_is_tail=bool(self._target_is_loop_tail_chain_node(target_node)),
                    target_is_function_exit=bool(self._target_is_function_exit_block(target_node)),
                )

        return None

    def _emit_conditional_latch_test_node(self, node, parent):
        """
        Emit a conditional latch-test block while binding the printed condition
        to the edge that actually controls loop exit/continuation.

        v28 generalization:
          - classify true/false successors as exit/continue/body relative to
            the owner loop;
          - when one edge exits and the other continues, print the predicate for
            the exit edge and put that edge in the then arm, regardless of CFG
            raw true/false naming;
          - use metadata/mnemonic/opcode custody to invert JZ+NOTEQUAL and
            related raw/HF complement pairs.
        """

        if node is None:
            return False

        if self._target_is_loop_tail_chain_node(node):
            return False

        raw_cond = self._get_condition(node)
        if raw_cond is None:
            return False

        true_node = self._true_edge(node)
        false_node = self._false_edge(node)

        if true_node is None and false_node is None:
            return False

        true_cont = self._edge_continues_loop(node, true_node) if true_node is not None else None
        false_cont = self._edge_continues_loop(node, false_node) if false_node is not None else None
        true_exit = self._edge_exits_loop(node, true_node) if true_node is not None else None
        false_exit = self._edge_exits_loop(node, false_node) if false_node is not None else None

        owner = true_cont or false_cont or true_exit or false_exit
        if owner is None:
            owner = self._innermost_loop_for_node(node)

        # v37: natural-loop metadata can miss the latch/body node in optimized
        # raw/HF-normalized loops.  Recover the small-loop owner from a peer
        # successor that backedges directly to a loop header and whose opposite
        # successor is a shared continuation gateway.
        owner_override = (
            self._conditional_latch_gateway_override_loop_v37(
                node, true_node, preferred_loop=owner, arm="true",
                source="emit_conditional_latch_owner_probe_true_v37",
                record=False,
            )
            or self._conditional_latch_gateway_override_loop_v37(
                node, false_node, preferred_loop=owner, arm="false",
                source="emit_conditional_latch_owner_probe_false_v37",
                record=False,
            )
        )
        if owner_override is not None:
            owner = owner_override
            self._metadata_record_event_v26(
                "conditional_latch_owner_recovered_from_peer_v37",
                node=self._addr_v26(node),
                owner_loop=self._addr_v26(owner),
                true=self._addr_v26(true_node),
                false=self._addr_v26(false_node),
            )

        if owner is None:
            return False

        participates = bool(
            true_cont or false_cont or true_exit or false_exit or
            self._target_is_loop_latch_node(owner, node)
        )
        if not participates:
            return False

        true_kind = self._conditional_latch_edge_kind_v28(node, true_node, owner)
        false_kind = self._conditional_latch_edge_kind_v28(node, false_node, owner)

        # v37: if the owner was recovered from a peer backedge, the ordinary
        # containment-based classifier may still return None because from_node
        # is absent from loop_nodes[owner].  Override only this local
        # conditional-latch shape: peer-to-header is continue; opposite shared
        # gateway is exit.
        if true_node is owner:
            true_kind = "continue"
        elif self._conditional_latch_gateway_override_loop_v37(
            node, true_node, preferred_loop=owner, arm="true",
            source="emit_conditional_latch_kind_true_v37", record=False,
        ) is owner:
            true_kind = "exit"

        if false_node is owner:
            false_kind = "continue"
        elif self._conditional_latch_gateway_override_loop_v37(
            node, false_node, preferred_loop=owner, arm="false",
            source="emit_conditional_latch_kind_false_v37", record=False,
        ) is owner:
            false_kind = "exit"

        then_target = true_node
        else_target = false_node
        cond = None
        orientation = "raw_true_then"

        # Prefer a source-like latch decision: if <exit-predicate>: break else continue.
        # This is executable truth, not prettification: the then condition must be
        # true exactly when the then edge is taken.
        if true_kind == "exit" and false_kind == "continue":
            then_target = true_node
            else_target = false_node
            cond = self._condition_for_conditional_latch_edge_v28(
                node, then_target, cond=raw_cond, exit_kind="exit", continue_peer=false_node
            )
            orientation = "exit_true_continue_false_v28"
        elif false_kind == "exit" and true_kind == "continue":
            then_target = false_node
            else_target = true_node
            cond = self._condition_for_conditional_latch_edge_v28(
                node, then_target, cond=raw_cond, exit_kind="exit", continue_peer=true_node
            )
            orientation = "exit_false_continue_true_swapped_v28"
        else:
            cond = self._condition_for_branch_then(node, then_target, raw_cond)
            cond = self._repair_conditional_latch_break_condition_v19(
                node, owner, then_target, else_target, cond
            )

        self.visited.add(node)

        # Preserve legacy latch ExecBlock ownership, while recording true
        # payload custody through the v55 helper when the latch performs work
        # before its terminal test.
        if not self._emit_conditional_payload_v55(
            node,
            parent,
            context="conditional_latch_test",
            owner_loop=owner,
        ):
            parent.add(ExecBlock(node))
            self.payload_emitted.add(node)

        if_node = ExecIf(node, cond)
        if_node.latch_test_node = node
        if_node.latch_test_header = owner
        if_node.latch_test_v19 = True
        if_node.latch_test_v28 = True
        if_node.raw_polarity_consumed = True
        if_node.latch_orientation_v28 = orientation

        parent.add(if_node)

        self._populate_conditional_latch_arm(
            if_node.then_branch, owner, node, then_target, "then"
        )
        self._populate_conditional_latch_arm(
            if_node.else_branch, owner, node, else_target, "else"
        )

        self.branch_control_events.append({
            "kind": "conditional_latch_test",
            "node": getattr(node, "addr", None),
            "loop": getattr(owner, "addr", None),
            "true": getattr(true_node, "addr", None),
            "false": getattr(false_node, "addr", None),
            "then": getattr(then_target, "addr", None),
            "else": getattr(else_target, "addr", None),
            "orientation": orientation,
            "cond": getattr(cond, "name", cond),
            "source": "cfg_plus_semantic_metadata_v28",
        })

        return True



    def _conditional_latch_arm_should_defer_gateway_v34(self, owner_loop, from_node, target_node, arm=None, reason=None):
        """
        Narrow consumption guard for conditional-latch / loop-exit branch arms.

        This is intentionally a *consumer* rule, not a global CFG rewrite.
        It may be called only from conditional latch arm population or from the
        conditional-latch action+break constructor.  It prevents an inner loop's
        exit arm from swallowing a shared enclosing continuation condition as a
        branch-local action block.

        Generic shape:
          * from_node is inside owner_loop;
          * target_node is outside owner_loop;
          * the edge therefore exits owner_loop by containment or metadata;
          * target_node is a structural continuation gateway according to the
            same metadata/CFG fallback used by v32; and
          * target_node is not a loop header, tail-chain node, or function exit.

        The caller must emit only break(owner_loop) and must not mark target
        visited.  The enclosing region will emit target_node through normal-exit
        traversal.
        """
        if owner_loop is None or from_node is None or target_node is None:
            return False

        owner_nodes = set(self.loop_nodes.get(owner_loop, set()) or set())
        if not owner_nodes:
            self._metadata_record_event_v26(
                "loop_exit_gateway_defer_rejected_v34",
                reason="owner_loop_has_no_nodes",
                source="conditional_latch_arm_only",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                owner_loop=self._addr_v26(owner_loop),
                arm=arm,
            )
            return False

        if from_node not in owner_nodes:
            self._metadata_record_event_v26(
                "loop_exit_gateway_defer_rejected_v34",
                reason="from_not_in_owner_loop",
                source="conditional_latch_arm_only",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                owner_loop=self._addr_v26(owner_loop),
                arm=arm,
            )
            return False

        if target_node in owner_nodes:
            return False

        if target_node in self.loop_headers:
            return False

        if self._target_is_loop_tail_chain_node(target_node):
            return False

        if self._target_is_function_exit_block(target_node):
            return False

        # Verify loop-exit shape, but do not require older edge metadata to
        # return an exact "exit" string.  v33 was too strict here on some
        # optimized/raw-HF fallback edges.  Containment is sufficient because
        # this helper is called only from the conditional-latch arm consumer.
        edge_kind = None
        try:
            edge_kind = self._conditional_latch_edge_kind_v28(from_node, target_node, owner_loop)
        except Exception:
            edge_kind = None

        exits_by_metadata = False
        try:
            exits_by_metadata = (self._edge_exits_loop(from_node, target_node) is owner_loop)
        except Exception:
            exits_by_metadata = False

        exits_by_containment = bool(from_node in owner_nodes and target_node not in owner_nodes)
        if edge_kind not in ("exit", None, "body") and not exits_by_metadata and not exits_by_containment:
            return False
        if not exits_by_metadata and not exits_by_containment:
            return False

        # Structural gateway evidence.  Prefer the metadata-facing helper, but
        # also call the v32 structural fallback directly so this consumer does
        # not depend on role strings or ownership maps being complete.
        gateway = False
        try:
            gateway = bool(self._metadata_target_is_continuation_gateway_v26(target_node, owner_loop=owner_loop, from_node=from_node))
        except Exception:
            gateway = False

        if not gateway:
            try:
                gateway = bool(self._structural_target_is_continuation_gateway_v32(target_node, owner_loop=owner_loop, from_node=from_node))
            except Exception:
                gateway = False

        if not gateway:
            self._metadata_record_event_v26(
                "loop_exit_gateway_defer_rejected_v34",
                reason="target_not_structural_gateway",
                source="conditional_latch_arm_only",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                owner_loop=self._addr_v26(owner_loop),
                arm=arm,
                edge_kind=edge_kind,
                exits_by_metadata=exits_by_metadata,
                exits_by_containment=exits_by_containment,
            )
            return False

        self._metadata_record_event_v26(
            "loop_exit_branch_arm_structural_gateway_deferred_v34",
            source="conditional_latch_arm_population_only",
            from_addr=self._addr_v26(from_node),
            target=self._addr_v26(target_node),
            owner_loop=self._addr_v26(owner_loop),
            arm=arm,
            edge_kind=edge_kind,
            exits_by_metadata=exits_by_metadata,
            exits_by_containment=exits_by_containment,
            reason=reason,
        )
        return True

    def _loop_exit_branch_arm_structural_gateway_v33(self, owner_loop, from_node, target_node):
        """
        True only for the consumption point that populates a conditional
        latch/loop-exit branch arm.

        This is intentionally narrower than generic continuation-gateway
        detection.  It is not used by ordinary if/switch/range branch arms.

        Required shape:
          * from_node is a latch/body conditional inside owner_loop;
          * target_node is outside owner_loop;
          * the edge is classified as an exit from owner_loop;
          * target_node is a shared conditional/ipdom/join continuation for an
            enclosing region; and
          * target_node is not a loop header, tail-chain node, or function exit.

        Action:
          The branch arm should emit only `break` for owner_loop and leave the
          target unvisited so the enclosing region can emit it at its proper
          structural boundary.
        """
        if owner_loop is None or from_node is None or target_node is None:
            return False

        # This helper is for latch/body loop-exit arms, not loop-header guard
        # exits.  Avoid classifying ordinary loop exits such as header -> after
        # loop as deferred gateway arms.
        if from_node is owner_loop:
            return False

        owner_nodes = set(self.loop_nodes.get(owner_loop, set()) or set())
        if not owner_nodes:
            return False

        if from_node not in owner_nodes:
            return False

        if target_node in owner_nodes:
            return False

        if target_node in self.loop_headers:
            return False

        if self._target_is_loop_tail_chain_node(target_node):
            return False

        if self._target_is_function_exit_block(target_node):
            return False

        # Consume this rule only for loop-exit arm population.  Do not let an
        # ordinary branch or switch arm borrow this classification.
        try:
            edge_kind = self._conditional_latch_edge_kind_v28(from_node, target_node, owner_loop)
        except Exception:
            edge_kind = None
        if edge_kind != "exit":
            return False

        preds = list(self._predecessors(target_node) or [])
        pred_set = set(preds)
        outside_preds = [p for p in preds if p not in owner_nodes]
        inside_preds = [p for p in preds if p in owner_nodes]

        is_condition = self._get_condition(target_node) is not None
        shared_pred = len(pred_set) >= 2 and bool(outside_preds)

        # ipdom/enclosing-region evidence: some conditional/dispatch node
        # outside this owner loop uses target as join and reaches from_node.
        ipdom_join = False
        try:
            for n in self._real_nodes():
                if n is target_node or n in owner_nodes:
                    continue
                if getattr(n, "ipdom", None) is not target_node:
                    continue
                if self._reaches(n, from_node):
                    ipdom_join = True
                    break
        except Exception:
            ipdom_join = False

        if not (is_condition or shared_pred or ipdom_join):
            return False

        if not (outside_preds or ipdom_join):
            return False

        # A non-conditional executable single-owner cleanup block belongs to
        # the break arm.  A conditional/shared/ipdom target belongs to the
        # enclosing continuation region.
        if self._node_has_executable_ops_cfg(target_node) and not is_condition and not ipdom_join:
            return False

        self._metadata_record_event_v26(
            "loop_exit_branch_arm_structural_gateway_deferred_v33",
            source="conditional_latch_arm_population_only",
            from_addr=self._addr_v26(from_node),
            target=self._addr_v26(target_node),
            owner_loop=self._addr_v26(owner_loop),
            edge_kind=edge_kind,
            is_condition=is_condition,
            shared_pred=shared_pred,
            ipdom_join=ipdom_join,
            pred_count=len(pred_set),
            outside_pred_count=len(outside_preds),
            inside_pred_count=len(inside_preds),
        )
        return True

    def _populate_conditional_latch_arm(self, branch, owner_loop, from_node, target_node, arm):
        """
        Populate a true/false arm for a conditional latch-test node.

        Rules:
            target is loop header/backedge -> continue
            target exits owner loop        -> break, or action+break if executable
            target is tail-chain node      -> ignore here; tail-chain emits later
            target is ordinary in-loop     -> conservative block/flow
        """

        if target_node is None:
            return

        # v52: a direct arm edge to this loop's metadata-proven normal
        # iterator/latch epilogue is an execution edge, not arm-local block
        # ownership.  The loop-level v28/v29 epilogue pass emits that block
        # exactly once after the conditional; terminal peer arms (break or
        # continue) naturally bypass it.  Retain a path record for provenance
        # and PHI/debug consumers without inserting a duplicate ExecBlock.
        if self._conditional_latch_target_is_loop_owned_epilogue_v52(
            owner_loop,
            from_node,
            target_node,
        ):
            edge_rec = {
                "kind": "conditional_latch_normal_epilogue_edge_v52",
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "loop": getattr(owner_loop, "addr", None),
                "arm": arm,
            }
            try:
                records = list(getattr(branch, "normal_epilogue_edges", []) or [])
                records.append(edge_rec)
                branch.normal_epilogue_edges = records
            except Exception:
                pass

            self._metadata_record_event_v26(
                "conditional_latch_normal_epilogue_arm_deferred_v52",
                from_addr=self._addr_v26(from_node),
                target=self._addr_v26(target_node),
                loop=self._addr_v26(owner_loop),
                arm=arm,
                target_exec=bool(self._node_has_executable_ops_cfg(target_node)),
                target_successors=[
                    self._addr_v26(n)
                    for n in list(self._successors(target_node) or [])
                ],
                reason="loop_metadata_assigns_single_normal_epilogue_owner",
            )
            self.branch_control_events.append({
                "kind": "conditional_latch_normal_epilogue_arm_deferred_v52",
                "arm": arm,
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "loop": getattr(owner_loop, "addr", None),
                "source": "loop_normal_epilogue_single_owner_v52",
            })
            return

        # v37: final guarded override at the latch arm consumer.  Recover the
        # actual inner loop from the peer backedge if the owner_loop argument is
        # too broad, then defer shared continuation gateways before executable
        # action+break logic can glue them into the arm.
        v37_loop = self._conditional_latch_gateway_override_loop_v37(
            from_node,
            target_node,
            preferred_loop=owner_loop,
            arm=arm,
            source="populate_conditional_latch_arm_precheck_v37",
            record=True,
        )
        if v37_loop is not None:
            branch.add(ExecBreak(v37_loop, "conditional_latch_to_peer_gateway_v37"))
            self.branch_control_events.append({
                "kind": "conditional_latch_peer_gateway_deferred_v37",
                "arm": arm,
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "loop": getattr(v37_loop, "addr", None),
                "preferred_loop": getattr(owner_loop, "addr", None),
                "source": "populate_conditional_latch_arm_precheck_v37",
            })
            return

        # v36: strongest narrow consumer for the glued gamma-tail class.
        # If the target is already known as a dynamic normal-exit gateway of
        # this owner loop, do not inline it as action+break.
        if self._conditional_latch_target_is_deferred_normal_gateway_v36(
            owner_loop,
            from_node,
            target_node,
            arm=arm,
            source="populate_conditional_latch_arm_precheck_v36",
        ):
            branch.add(ExecBreak(owner_loop, "conditional_latch_to_dynamic_normal_gateway_v36"))
            self.branch_control_events.append({
                "kind": "conditional_latch_normal_gateway_deferred_v36",
                "arm": arm,
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "loop": getattr(owner_loop, "addr", None),
                "source": "populate_conditional_latch_arm_precheck_v36",
            })
            return

        # v34: consume structural continuation gateways only at the loop-exit
        # branch-arm population point.  This is the primary consumer.  It is
        # deliberately more tolerant than v33 about older edge-kind metadata,
        # but still requires from-inside/to-outside loop containment and v32
        # structural gateway evidence.
        if self._conditional_latch_arm_should_defer_gateway_v34(
            owner_loop,
            from_node,
            target_node,
            arm=arm,
            reason="populate_conditional_latch_arm_v34",
        ):
            branch.add(ExecBreak(owner_loop, "conditional_latch_exit_to_structural_gateway_v34"))
            self.branch_control_events.append({
                "kind": "conditional_latch_structural_gateway_deferred_v34",
                "arm": arm,
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "loop": getattr(owner_loop, "addr", None),
                "source": "conditional_latch_arm_population_only_v34",
            })
            return

        # v33 legacy path retained for compatibility with exact edge-kind
        # metadata when present.
        if self._loop_exit_branch_arm_structural_gateway_v33(owner_loop, from_node, target_node):
            branch.add(ExecBreak(owner_loop, "conditional_latch_exit_to_structural_gateway_v33"))
            self.branch_control_events.append({
                "kind": "conditional_latch_structural_gateway_deferred_v33",
                "arm": arm,
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "loop": getattr(owner_loop, "addr", None),
                "source": "conditional_latch_arm_population_only_v33",
            })
            return

        if target_node is owner_loop:
            branch.add(ExecContinue(owner_loop, "conditional_latch_backedge"))
            self.branch_control_events.append({
                "kind": "conditional_latch_continue",
                "arm": arm,
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "loop": getattr(owner_loop, "addr", None),
                "source": "cfg_metadata_v19",
            })
            return

        cont_loop = self._edge_continues_loop(from_node, target_node)

        if cont_loop is not None:
            branch.add(ExecContinue(cont_loop, "conditional_latch_continue_edge"))
            self.branch_control_events.append({
                "kind": "conditional_latch_continue",
                "arm": arm,
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "loop": getattr(cont_loop, "addr", None),
                "source": "cfg_metadata_v19",
            })
            return

        # Exit from the immediate loop. For nested loops, this means "break the
        # small loop"; the enclosing loop will continue traversal from the
        # join/next node already present in the SGL tree.
        br_loop = self._edge_exits_loop(from_node, target_node)

        if br_loop is not None:
            # v37: same final override with the br_loop discovered by the
            # containment/metadata helper.  This is intentionally before any
            # executable-target fallback.
            v37_loop = self._conditional_latch_gateway_override_loop_v37(
                from_node,
                target_node,
                preferred_loop=br_loop,
                arm=arm,
                source="populate_conditional_latch_arm_br_loop_v37",
                record=True,
            )
            if v37_loop is not None:
                branch.add(ExecBreak(v37_loop, "conditional_latch_to_peer_gateway_v37"))
                self.branch_control_events.append({
                    "kind": "conditional_latch_peer_gateway_deferred_v37",
                    "arm": arm,
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(v37_loop, "addr", None),
                    "preferred_loop": getattr(br_loop, "addr", None),
                    "source": "populate_conditional_latch_arm_br_loop_v37",
                })
                return

            # v36: repeat with the exact br_loop returned by CFG/containment.
            # This catches body/latch exits whose initial owner_loop argument
            # was incomplete or came through a normalized raw/HF edge.
            if self._conditional_latch_target_is_deferred_normal_gateway_v36(
                br_loop,
                from_node,
                target_node,
                arm=arm,
                source="br_loop_branch_precheck_v36",
            ):
                branch.add(ExecBreak(br_loop, "conditional_latch_to_dynamic_normal_gateway_v36"))
                self.branch_control_events.append({
                    "kind": "conditional_latch_normal_gateway_deferred_v36",
                    "arm": arm,
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(br_loop, "addr", None),
                    "source": "br_loop_branch_precheck_v36",
                })
                return

            # v34: second consumption point.  If the exact br_loop is known only
            # after _edge_exits_loop(), apply the same loop-exit-gateway rule
            # here before the older executable action+break fallback.
            if self._conditional_latch_arm_should_defer_gateway_v34(
                br_loop,
                from_node,
                target_node,
                arm=arm,
                reason="br_loop_branch_v34",
            ):
                branch.add(ExecBreak(br_loop, "conditional_latch_exit_to_structural_gateway_v34"))
                self.branch_control_events.append({
                    "kind": "conditional_latch_structural_gateway_deferred_v34",
                    "arm": arm,
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(br_loop, "addr", None),
                    "source": "br_loop_branch_v34",
                })
                return

            # v26: if the destination is a shared continuation/condition gateway
            # for an enclosing construct, do not inline it as branch-local
            # action.  This is the alpha_four O3 0x101235 -> 0x10125c class.
            if self._metadata_target_is_continuation_gateway_v26(target_node, owner_loop=br_loop, from_node=from_node):
                branch.add(ExecBreak(br_loop, "conditional_latch_to_metadata_gateway"))
                self.branch_control_events.append({
                    "kind": "conditional_latch_metadata_gateway_break",
                    "arm": arm,
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(br_loop, "addr", None),
                    "source": "semantic_graph_metadata_v26",
                })
                return

            terminal = self._path_local_terminal_block_v56(
                from_node,
                target_node,
                br_loop,
                source="conditional_latch_loop_exit_v56",
                arm=arm,
            )
            if terminal is not None:
                branch.add(terminal)
                self.branch_control_events.append({
                    "kind": "conditional_latch_terminal_owned_v56",
                    "arm": arm,
                    "from": getattr(from_node, "addr", None),
                    "to": getattr(target_node, "addr", None),
                    "loop": getattr(br_loop, "addr", None),
                    "terminal_kind": getattr(terminal, "terminal_kind_v56", None),
                    "source": "conditional_latch_loop_exit_v56",
                })
                return

            if self._edge_is_function_exit(from_node, target_node) or self._target_is_function_exit_block(target_node):
                branch.add(ExecBreak(br_loop, "conditional_latch_to_synthetic_function_exit_v56"))
            elif self._node_has_executable_ops_cfg(target_node) and target_node not in set(self.loop_normal_exits.get(br_loop, set()) or set()):
                branch.add(self._action_then_break_node(target_node, br_loop, "conditional_latch_action_exit", from_node=from_node, arm=arm))
            else:
                branch.add(ExecBreak(br_loop, "conditional_latch_exit"))

            self.branch_control_events.append({
                "kind": "conditional_latch_break",
                "arm": arm,
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "loop": getattr(br_loop, "addr", None),
                "source": "cfg_metadata_v19_v56",
            })
            return

        if self._target_is_loop_tail_chain_node(target_node):
            return

        # v37 last-ditch path: if the edge was not classified as a loop exit
        # because natural-loop membership is incomplete, peer-backedge recovery
        # can still prove this is an inner-loop break to a shared gateway.
        v37_loop = self._conditional_latch_gateway_override_loop_v37(
            from_node,
            target_node,
            preferred_loop=owner_loop,
            arm=arm,
            source="populate_conditional_latch_arm_final_executable_guard_v37",
            record=True,
        )
        if v37_loop is not None:
            branch.add(ExecBreak(v37_loop, "conditional_latch_to_peer_gateway_v37"))
            self.branch_control_events.append({
                "kind": "conditional_latch_peer_gateway_deferred_v37",
                "arm": arm,
                "from": getattr(from_node, "addr", None),
                "to": getattr(target_node, "addr", None),
                "loop": getattr(v37_loop, "addr", None),
                "preferred_loop": getattr(owner_loop, "addr", None),
                "source": "populate_conditional_latch_arm_final_executable_guard_v37",
            })
            return

        if self._node_has_executable_ops_cfg(target_node):
            branch.add(ExecBlock(target_node))
            self.visited.add(target_node)



    # ---------------------------------------------------------------------
    # v44: loop-internal conditional break recovery
    # ---------------------------------------------------------------------

    def _target_stays_in_loop_v44(self, owner_loop, target_node):
        if owner_loop is None or target_node is None:
            return False
        if target_node is owner_loop:
            return True
        if self._edge_continues_loop(owner_loop, target_node) is owner_loop:
            return True
        try:
            return target_node in set(self.loop_nodes.get(owner_loop, set()) or set())
        except Exception:
            return False

    def _try_emit_loop_internal_conditional_break_v44(self, node, parent, stop_nodes, cond):
        """
        v44: Some branch blocks inside a loop are not pre-classified as
        loop_tail_test_nodes, but their two outgoing edges still mean:

            one edge exits/breaks the innermost loop
            the peer edge remains in that same loop

        The ordinary if emitter attaches the condition to the raw then edge and
        can therefore print the peer/continue predicate as a break predicate in
        optimized-vs-O0 variants.  Recover these as conditional-latch style
        nodes locally: make the then arm the loop-exit edge and ask EdgeTruth
        for the predicate of that exact exit edge.
        """
        if node is None or parent is None:
            return False

        owner = self._innermost_loop_for_node(node)
        if owner is None or node is owner:
            return False

        true_node = self._true_edge(node)
        false_node = self._false_edge(node)
        if true_node is None or false_node is None:
            return False

        true_exits = self._edge_exits_loop(node, true_node) is owner
        false_exits = self._edge_exits_loop(node, false_node) is owner

        # Need exactly one loop-exit edge.
        if true_exits == false_exits:
            return False

        true_stays = self._target_stays_in_loop_v44(owner, true_node)
        false_stays = self._target_stays_in_loop_v44(owner, false_node)

        # The peer must remain in the same loop.  Otherwise this is an ordinary
        # if/else whose two arms leave the loop nest in different ways.
        if true_exits and not false_stays:
            return False
        if false_exits and not true_stays:
            return False

        if true_exits:
            break_target = true_node
            stay_target = false_node
            orientation = "true_exit_false_stays_v44"
        else:
            break_target = false_node
            stay_target = true_node
            orientation = "false_exit_true_stays_v44"

        edge_cond = self._condition_for_conditional_latch_edge_v28(
            node,
            break_target,
            cond=cond,
            exit_kind="exit",
            continue_peer=stay_target,
        )

        payload_preserved = self._emit_conditional_payload_v55(
            node,
            parent,
            context="loop_internal_early_exit",
            owner_loop=owner,
        )
        self.visited.add(node)

        if_node = ExecIf(node, edge_cond)
        if_node.latch_test_node = node
        if_node.latch_test_header = owner
        if_node.loop_internal_conditional_break_v44 = True
        if_node.raw_polarity_consumed = True
        if_node.latch_orientation_v28 = orientation
        parent.add(if_node)

        self._populate_conditional_latch_arm(
            if_node.then_branch, owner, node, break_target, "then"
        )

        # v55: after an early-exit ``break`` the peer edge is ordinary
        # same-loop fallthrough.  Traverse it from the parent sequence so the
        # entire remaining body path survives (including a second conditional
        # and later side-effect blocks), rather than reducing it to one arm
        # placeholder.
        continuation_structured = self._loop_early_exit_stay_continuation_v55(
            owner,
            node,
            stay_target,
            break_target,
            parent,
            stop_nodes,
        )
        if not continuation_structured:
            self._populate_conditional_latch_arm(
                if_node.else_branch, owner, node, stay_target, "else"
            )

        if payload_preserved:
            rec = {
                "kind": "loop_early_exit_payload_preserved_v55",
                "block": getattr(node, "addr", None),
                "loop": getattr(owner, "addr", None),
                "exit_target": getattr(break_target, "addr", None),
                "continuation_target": getattr(stay_target, "addr", None),
                "opcodes": self._node_payload_opcodes_v55(node),
            }
            self.payload_custody_events.append(rec)
            self.branch_control_events.append(dict(rec))
            self._record_metadata_event_v43(dict(rec))

        self.branch_control_events.append({
            "kind": "loop_internal_conditional_break_recovered_v44",
            "from": getattr(node, "addr", None),
            "loop": getattr(owner, "addr", None),
            "true": getattr(true_node, "addr", None),
            "false": getattr(false_node, "addr", None),
            "break_target": getattr(break_target, "addr", None),
            "stay_target": getattr(stay_target, "addr", None),
            "orientation": orientation,
            "cond": self._cond_to_string_v19(edge_cond),
        })
        return True

    # =========================================================================
    # NODE EMISSION
    # =========================================================================

    def _closed_in_loop_diamond_arm_v53(self, start, join, loop_header):
        """
        Prove that every path from one candidate arm reaches ``join`` before
        crossing any loop-control boundary.

        This deliberately recognizes an acyclic, closed payload region rather
        than merely asking whether ``join`` is reachable.  A permissive
        reachability test can walk through a latch, revisit the loop header,
        and eventually find the join on a later iteration; that would mistake
        loop continuation for a same-iteration diamond arm.

        Returns ``(proved, region_nodes, reason)``.  ``join`` itself is not in
        ``region_nodes`` because it has single post-diamond ownership.
        """
        if start is None or join is None or loop_header is None:
            return False, set(), "missing_endpoint"

        if start is join:
            return True, set(), "direct_join_arm"

        loop_nodes = set(self.loop_nodes.get(loop_header, set()) or set())
        if not loop_nodes:
            return False, set(), "missing_natural_loop_region"

        latches = set(self.loop_latches.get(loop_header, []) or [])
        exits = set(self.loop_exits.get(loop_header, set()) or set())
        forbidden = {loop_header} | latches | exits

        region = set()
        adjacency = {}
        work = [start]

        # The bound is defensive only.  A valid region cannot contain more
        # nodes than its owning natural loop.
        budget = max(1, len(loop_nodes) + 1)

        while work:
            node = work.pop()

            if node is join:
                continue
            if node in region:
                continue
            if len(region) >= budget:
                return False, region, "region_budget_exceeded"
            if node not in loop_nodes:
                return False, region, "arm_leaves_natural_loop"
            if node in forbidden:
                return False, region, "arm_crosses_loop_control_boundary"
            if node in self.loop_headers:
                return False, region, "arm_enters_nested_or_owner_loop_header"

            succs = []
            for succ in self._successors(node):
                if succ is not None and succ not in succs:
                    succs.append(succ)

            if not succs:
                return False, region, "arm_has_non_join_terminal_frontier"

            region.add(node)
            adjacency[node] = []

            for succ in succs:
                if succ is join:
                    continue
                if succ not in loop_nodes:
                    return False, region, "arm_has_external_frontier"
                if succ in forbidden:
                    return False, region, "arm_reaches_latch_header_or_exit"
                adjacency[node].append(succ)
                if succ not in region:
                    work.append(succ)

        # A closed region can still contain a cycle which never reaches the
        # join at runtime.  Reject such regions; nested loops retain their own
        # established structuring path.
        visiting = set()
        visited = set()

        def has_cycle(node):
            if node in visiting:
                return True
            if node in visited:
                return False

            visiting.add(node)
            for succ in adjacency.get(node, []):
                if succ in region and has_cycle(succ):
                    return True
            visiting.remove(node)
            visited.add(node)
            return False

        for node in list(region):
            if has_cycle(node):
                return False, region, "arm_region_contains_cycle"

        return True, region, "closed_acyclic_arm_to_internal_ipdom"

    def _loop_header_payload_diamond_contract_v53(self, header):
        """
        Return a proved contract when a natural-loop header has two roles:

          * it owns the loop iteration/body entry; and
          * its terminal condition selects an in-loop payload diamond.

        The rule is topology-only.  It does not depend on addresses,
        mnemonics, constants, variable names, or source-language spelling.
        Ordinary pre-test loop headers are excluded because at least one of
        their successors leaves the natural loop.  Latch/exit diamonds and
        nested cyclic regions are also excluded.
        """
        if header is None:
            return None
        if header not in self.loop_headers:
            return None
        if header not in self.loop_body_headers:
            return None
        if self._get_condition(header) is None:
            return None

        successors = []
        for succ in self._successors(header):
            if succ is not None and succ not in successors:
                successors.append(succ)

        if len(successors) != 2 or successors[0] is successors[1]:
            return None

        loop_nodes = set(self.loop_nodes.get(header, set()) or set())
        if not loop_nodes:
            return None
        if any(succ is header or succ not in loop_nodes for succ in successors):
            return None

        join = getattr(header, "ipdom", None)
        if join is None or join is header or join not in loop_nodes:
            return None
        if join in set(self.loop_latches.get(header, []) or []):
            return None
        if join in set(self.loop_exits.get(header, set()) or set()):
            return None
        if join in self.loop_headers:
            return None
        if self._target_is_loop_tail_chain_node(join):
            return None

        arm_regions = []
        arm_reasons = []
        for succ in successors:
            proved, region, reason = self._closed_in_loop_diamond_arm_v53(
                succ,
                join,
                header,
            )
            if not proved:
                return None
            arm_regions.append(set(region))
            arm_reasons.append(reason)

        # Before the IPDOM, distinct diamond arms must not overlap.  Shared
        # ownership belongs to the join and everything after it.
        if arm_regions[0] & arm_regions[1]:
            return None

        return {
            "kind": "loop_header_payload_diamond_contract_v53",
            "header": header,
            "successors": tuple(successors),
            "join": join,
            "arm_regions": tuple(arm_regions),
            "arm_reasons": tuple(arm_reasons),
            "proof": "two_internal_successors_closed_to_internal_ipdom_before_loop_control",
        }

    def _emit_loop_header_payload_diamond_v53(self, header, loop, stop_nodes):
        """
        Emit a proved header-local diamond inside ``loop.body`` and then emit
        its join exactly once.

        Header executable operations have already been placed in the loop body
        by the caller.  This method owns only the header's conditional payload
        role, preserving the existing branch-arm suppressors and direct-join
        PHI edge records through ``_emit_branch_arm``.
        """
        contract = self._loop_header_payload_diamond_contract_v53(header)
        if contract is None:
            return False

        then_node, else_node, join_node = self._get_if_branches(header)
        expected_join = contract.get("join")
        expected_successors = set(contract.get("successors") or ())

        if (
            join_node is not expected_join
            or then_node not in expected_successors
            or else_node not in expected_successors
            or then_node is else_node
        ):
            return False

        cond = self._get_condition(header)
        edge_cond = self._condition_for_branch_then(header, then_node, cond)
        if_node = ExecIf(header, edge_cond)
        if_node.loop_header_payload_diamond_v53 = True
        if_node.loop_header_owner = header
        if_node.payload_join = join_node
        loop.body.add(if_node)

        branch_stops = set(stop_nodes or set())
        branch_stops.add(header)
        branch_stops.add(join_node)

        self._emit_branch_arm(
            header,
            then_node,
            if_node.then_branch,
            branch_stops,
        )
        self._emit_branch_arm(
            header,
            else_node,
            if_node.else_branch,
            branch_stops,
        )

        event = {
            "kind": "loop_header_payload_diamond_v53_consumed",
            "header": getattr(header, "addr", None),
            "then_root": getattr(then_node, "addr", None),
            "else_root": getattr(else_node, "addr", None),
            "join": getattr(join_node, "addr", None),
            "loop": getattr(header, "addr", None),
            "condition": self._cond_to_string_v19(edge_cond),
            "arm_regions": [
                [getattr(n, "addr", None) for n in self._ordered_nodes(region)]
                for region in contract.get("arm_regions", ())
            ],
            "arm_reasons": list(contract.get("arm_reasons", ())),
            "proof": contract.get("proof"),
        }
        self.loop_contract_events.append(event)
        self.branch_control_events.append(dict(event))
        self._record_metadata_event_v43(dict(event))

        # The IPDOM is the first ordinary body node after the payload choice.
        # It is deliberately outside both arms so predecessor-specific PHI
        # drop-ins remain attached to their incoming edges while the join block
        # itself has one execution owner.
        self._emit_node(join_node, loop.body, stop_nodes=set(stop_nodes or set()))
        return True

    def _emit_node(self, node, parent, stop_nodes=None):

        if node is None:
            return

        if stop_nodes is None:
            stop_nodes = set()

        if node in stop_nodes:
            return

        if node in self.visited:
            return

        # -----------------------------------------------------
        # LOOP HEADER
        # -----------------------------------------------------
        if node in self.loop_headers:

            self.visited.add(node)

            cond, cond_role = self._get_loop_condition_and_role_for_header(node)

            # v21c last-mile guard: some older loop construction paths can
            # still return an exit-shaped predicate under role=body. Normalize
            # once more at the exact ExecLoop construction boundary.
            cond, cond_role = self._normalize_loop_condition_role_v20(node, cond, cond_role)

            # v73: when canonical EdgeTruth and natural-loop topology jointly
            # prove one body edge and one exit edge, bind the exact body-edge
            # predicate before ExecLoop is created.  Legacy role heuristics are
            # absence-only after this point.
            cond, cond_role, edge_contract = (
                self._bind_loop_edge_role_contract_v73(
                    node,
                    cond,
                    cond_role,
                    phase="exec_loop_construction",
                )
            )

            loop = ExecLoop(node, cond, cond_role)
            self._apply_loop_edge_role_contract_v73(loop, edge_contract)
            loop.header_is_body = bool(node in self.loop_body_headers)
            loop.guard_node = self.loop_guard_nodes.get(node)
            parent.add(loop)

            # v59: a conditional header with executable pre-branch work is a
            # repeating condition transaction, not ordinary loop-body payload.
            # Insert the transaction before the body in the ExecTree so generic
            # custody walkers see its exact execution owner.
            if node in self.loop_condition_transaction_headers:
                transaction = ExecConditionTransaction(node)
                transaction.condition_semantics = getattr(
                    loop, "condition_semantics", None
                )
                transaction.continue_edge_key = getattr(
                    loop, "continue_edge_key", None
                )
                transaction.exit_edge_key = getattr(
                    loop, "exit_edge_key", None
                )
                transaction.selected_condition_edge_key = getattr(
                    loop, "selected_condition_edge_key", None
                )
                transaction.selected_edge_invert = getattr(
                    loop, "selected_edge_invert", None
                )
                transaction.edge_role_authority = getattr(
                    loop, "edge_role_authority", None
                )
                transaction.loop_edge_role_contract_v73 = dict(
                    getattr(loop, "loop_edge_role_contract_v73", None) or {}
                )
                transaction.add(ExecBlock(node))
                transaction.parent = loop
                loop.children.insert(0, transaction)
                loop.condition_transaction = transaction
                loop.condition_evaluation_order = (
                    "transaction_then_predicate"
                )
                loop.header_is_body = False
                event = {
                    "kind": (
                        "loop_header_condition_transaction_attached_v59"
                    ),
                    "header": getattr(node, "addr", None),
                    "condition_role": cond_role,
                    "condition": self._cond_to_string_v19(cond),
                    "execution_order": (
                        "transaction_then_predicate_every_test"
                    ),
                    "condition_semantics": getattr(
                        loop, "condition_semantics", None
                    ),
                    "continue_edge_key": getattr(
                        loop, "continue_edge_key", None
                    ),
                    "exit_edge_key": getattr(loop, "exit_edge_key", None),
                    "selected_condition_edge_key": getattr(
                        loop, "selected_condition_edge_key", None
                    ),
                    "selected_edge_invert": getattr(
                        loop, "selected_edge_invert", None
                    ),
                    "edge_role_authority": getattr(
                        loop, "edge_role_authority", None
                    ),
                }
                self.loop_condition_transaction_events.append(event)
                self.loop_contract_events.append(dict(event))
            elif node in self.loop_body_headers:
                # Genuine body-header loops retain the historical body owner.
                loop.body.add(ExecBlock(node))

            exit_nodes = self._get_loop_exits(node)
            normal_exit_nodes = self._get_loop_normal_exits(node)

            local_stops = set(stop_nodes)
            local_stops.add(node)
            local_stops |= set(normal_exit_nodes)

            guard = self.loop_guard_nodes.get(node)
            if guard is not None:
                local_stops.add(guard)

            payload_diamond_emitted = self._emit_loop_header_payload_diamond_v53(
                node,
                loop,
                local_stops,
            )

            if not payload_diamond_emitted:
                body = self._get_loop_body(node)
                if body is not None:
                    self._emit_node(body, loop.body, stop_nodes=local_stops)

            # v28: ordinary fallthrough completion of a lowered for-like loop
            # must execute the iterator/latch update even when explicit continue
            # arms already carry action+latch+continue.  This is loop-level
            # epilogue structure, not branch-arm summarization.
            self._emit_normal_latch_epilogue_for_loop_v28(node, loop)

            # Preserve/lower body-header latch/tail condition chains as
            # explicit continue/break tests. The first tail node may also
            # contain executable update work, so emit its body ops before the
            # synthetic tail-if.
            self._emit_tail_chain_for_loop(node, loop)

            for exit_node in self._ordered_nodes(normal_exit_nodes):
                self._emit_node(exit_node, parent, stop_nodes=stop_nodes)

            return

        # -----------------------------------------------------
        # LOOP TAIL / LATCH TEST NODE
        # -----------------------------------------------------
        if node in self.loop_tail_test_nodes:
            if self._emit_conditional_latch_test_node(node, parent):
                return

            self.visited.add(node)
            parent.add(ExecBlock(node))
            return

        # -----------------------------------------------------
        # MULTIWAY / BRANCHIND DISPATCH NODE
        # -----------------------------------------------------
        # This must precede binary-condition and linear fallback.  BRANCHIND
        # normally has no CBRANCH condition, and _next_linear() cannot choose
        # one successor from a true multiway node.
        if self._try_emit_multiway_dispatch_v57(node, parent, stop_nodes):
            return

        # -----------------------------------------------------
        # CONDITIONAL IF NODE
        # -----------------------------------------------------
        cond = self._get_condition(node)

        if cond is not None:

            # v44: if this is a loop-internal conditional where one edge breaks
            # the innermost loop and the peer remains in that same loop, consume
            # it as a conditional-latch break even if older discovery did not
            # pre-classify it as a loop_tail_test_node.
            if self._try_emit_loop_internal_conditional_break_v44(node, parent, stop_nodes, cond):
                return

            # Recognize lowered short-circuit chains like:
            #     A || (B && C)
            # and emit a single ExecIf with a composite raw condition.
            # This preserves execution truth without duplicating shared THEN/ELSE bodies.
            if self._try_emit_short_circuit_if(node, parent, stop_nodes):
                return

            # v55: claim payload custody before visited/control custody.
            # The helper is idempotent and records the exact reason/opcodes.
            self._emit_conditional_payload_v55(
                node,
                parent,
                context="ordinary_if",
                owner_loop=self._innermost_loop_for_node(node),
            )
            self.visited.add(node)

            then_node, else_node, join_node = self._get_if_branches(node)

            # v72: resolve and validate the exact binary EdgeTruth contract
            # before an executable ExecIf is attached to the tree.
            edge_cond = self._condition_for_branch_then(
                node, then_node, cond
            )
            if_node = ExecIf(node, edge_cond)
            parent.add(if_node)
            self._stamp_exec_if_edge_targets_v71(
                if_node,
                then_node,
                else_node,
                join_node,
                source_kind="ordinary_if",
            )

            branch_stops = set(stop_nodes)

            if join_node is not None:
                branch_stops.add(join_node)

            if then_node is not None:
                self._emit_branch_arm(node, then_node, if_node.then_branch, branch_stops)

            if else_node is not None:
                self._emit_branch_arm(node, else_node, if_node.else_branch, branch_stops)

            if join_node is not None:
                self._emit_node(join_node, parent, stop_nodes=stop_nodes)

            return

        # -----------------------------------------------------
        # LINEAR SEQUENCE
        # -----------------------------------------------------
        self._emit_linear_sequence(node, parent, stop_nodes)

    # ----------------------------------------------------------------

    def _emit_linear_sequence(self, start, parent, stop_nodes):

        seq = ExecNode("sequence")
        parent.add(seq)

        cur = start

        while cur is not None:

            if cur in stop_nodes:
                break

            if cur in self.visited:
                break

            if cur in self.loop_headers:
                break

            if self._get_condition(cur) is not None:
                break

            seq.add(ExecBlock(cur))
            self.visited.add(cur)

            term = getattr(cur.block, "terminator", None)

            if term is not None and getattr(term, "opcode", None) == "RETURN":
                return

            nxt = self._next_linear(cur)

            if nxt is None:
                break

            # Linear action -> latch/update -> loop header. Do not absorb the
            # latch as ordinary linear code; lower it as explicit continuation.
            loop = self._innermost_loop_for_node(cur)
            if (
                loop is not None
                and not self._is_loop_tail_chain_member(nxt)
                and self._is_executable_latch_update_node(loop, nxt)
            ):
                seq.add(ExecBlock(nxt))
                self.visited.add(nxt)
                seq.add(ExecContinue(loop, "linear_latch_update_continue"))
                self.branch_control_events.append({
                    "kind": "linear_latch_update_continue",
                    "from": getattr(cur, "addr", None),
                    "to": getattr(nxt, "addr", None),
                    "loop": getattr(loop, "addr", None),
                    "source": "cfg_metadata_v19",
                })
                return

            if (
                nxt in self.loop_headers
                or self._get_condition(nxt) is not None
                or self._physical_multiway_dispatch_v57(nxt)
            ):
                self._emit_node(nxt, parent, stop_nodes=stop_nodes)
                return

            cur = nxt

        if not seq.children:
            try:
                parent.children.remove(seq)
            except Exception:
                pass

    # =========================================================================
    # STRUCTURE HELPERS
    # =========================================================================

    # =========================================================================
    # SHORT-CIRCUIT BOOLEAN CHAINS
    # =========================================================================

    def _short_circuit_condition_node_is_pure_v49(self, cfg_node):
        """Prove that a condition node may be folded into composite control.

        v49's broad "not effectful and not local" test admitted values without
        proving their complete custody.  v58 delegates to the same dependency-
        cone classifier used by the payload audit, so composite structuring and
        payload custody cannot disagree about CAST or any other carrier op.
        """
        if cfg_node is None:
            return False
        return bool(
            self._classify_condition_block_v58(cfg_node).get("condition_only")
        )


    def _canonical_edge_truth_expr_v49(self, src, dst):
        """Return authoritative canonical EdgeTruth text for one exact edge."""
        rec = self._edge_truth_record_v40(src, dst)
        if not isinstance(rec, dict):
            return None
        self._require_binary_edge_truth_pair_v72(
            src,
            consumer="canonical_edge_truth_expr_v49",
        )
        cond = self._authoritative_edgetruth_condition_v72(
            src,
            dst,
            cond=self._get_condition(src),
            consumer="canonical_edge_truth_expr_v49",
        )
        text = self._cond_to_string_v19(cond)
        return str(text).strip() if text else None

    def _try_emit_shared_condition_diamond_v49(self, node, parent, stop_nodes):
        """
        Recognize the edge-truth-backed short-circuit diamond:

            A -> B / C
            B -> THEN / C
            C -> THEN / ELSE

        If P, Q, and R are the exact predicates for A->B, B->THEN,
        and C->THEN, the complete condition for reaching THEN is:

            (P and Q) or R

        This is topology-driven.  It does not depend on block ordering,
        comparison spelling, variable names, constants, or raw true/false
        labels.  Exact canonical EdgeTruth owns every predicate.
        """
        if node is None or node in self.visited or not self._is_conditional_node(node):
            return False

        a_succs = self._successors(node)
        if len(a_succs) != 2 or not all(self._is_conditional_node(s) for s in a_succs):
            return False

        match = None
        for b_node, c_node in ((a_succs[0], a_succs[1]), (a_succs[1], a_succs[0])):
            b_succs = self._successors(b_node)
            c_succs = self._successors(c_node)
            if len(b_succs) != 2 or len(c_succs) != 2:
                continue
            if c_node not in b_succs:
                continue

            b_other = [s for s in b_succs if s is not c_node]
            if len(b_other) != 1:
                continue
            then_root = b_other[0]
            if then_root not in c_succs:
                continue

            else_roots = [s for s in c_succs if s is not then_root]
            if len(else_roots) != 1:
                continue
            else_root = else_roots[0]
            if else_root is node or else_root is b_node or else_root is c_node:
                continue

            match = (b_node, c_node, then_root, else_root)
            break

        if match is None:
            return False

        b_node, c_node, then_root, else_root = match
        join = getattr(node, "ipdom", None)
        if join is None:
            self._sc_reject(node, "shared diamond missing join")
            return False

        if not self._reaches(then_root, join) or not self._reaches(else_root, join):
            self._sc_reject(node, "shared diamond result root does not reach join")
            return False

        if self._looks_like_switch_decision_chain(node, b_node, c_node):
            self._sc_reject(node, "shared diamond looks like switch decision chain")
            return False

        if not all(self._short_circuit_condition_node_is_pure_v49(n) for n in (node, b_node, c_node)):
            self._sc_reject(node, "shared diamond condition block has observable payload")
            return False

        p_expr = self._canonical_edge_truth_expr_v49(node, b_node)
        q_expr = self._canonical_edge_truth_expr_v49(b_node, then_root)
        r_expr = self._canonical_edge_truth_expr_v49(c_node, then_root)
        if not p_expr or not q_expr or not r_expr:
            self._sc_reject(node, "shared diamond lacks authoritative canonical EdgeTruth")
            return False

        composite = RawCond(
            "((%s) and (%s)) or (%s)" % (p_expr, q_expr, r_expr),
            reason="edge_truth_shared_condition_diamond_v49",
        )

        self.visited.add(node)
        self.visited.add(b_node)
        self.visited.add(c_node)

        if_node = ExecIf(node, composite)
        parent.add(if_node)
        self._stamp_exec_if_edge_targets_v71(
            if_node,
            then_root,
            else_root,
            join,
            source_kind="shared_condition_diamond_v49",
        )
        self._record_composite_condition_sources_v58(
            if_node,
            (node, b_node, c_node),
            "shared_condition_diamond_v49",
        )

        branch_stops = set(stop_nodes)
        branch_stops.add(join)

        self._metadata_record_event_v26(
            "shared_condition_diamond_v49_consumed",
            entry=self._addr_v26(node),
            second=self._addr_v26(b_node),
            shared=self._addr_v26(c_node),
            then_root=self._addr_v26(then_root),
            else_root=self._addr_v26(else_root),
            join=self._addr_v26(join),
            p=p_expr,
            q=q_expr,
            r=r_expr,
            composite=self._cond_to_string_v19(composite),
        )

        self._record_branch_event(
            node,
            getattr(node.block, "terminator", None),
            then_root,
            else_root,
            join,
            "short_circuit_shared_condition_diamond_v49_edge_truth",
        )

        self._emit_node(then_root, if_node.then_branch, stop_nodes=branch_stops)
        self._emit_node(else_root, if_node.else_branch, stop_nodes=branch_stops)
        self._emit_node(join, parent, stop_nodes=stop_nodes)
        return True

    def _try_emit_short_circuit_if(self, node, parent, stop_nodes):
        """
        Terminal-based recognizer for the lowered CFG shape of:

            A || (B && C)

        This version is intentionally specific to the observed GCC/O0 pattern.

        Important:
            The previous version recognized the topology but inverted B/C by
            trusting CFG edge labels. For this recognized form, we preserve the
            raw condition formulas:

                A or (B and C)

            because the CFG labels are not reliable enough here and Ghidra's
            recovered execution condition confirms the non-inverted form.
        """

        if self._try_emit_shared_condition_diamond_v49(node, parent, stop_nodes):
            return True

        if node in self.visited:
            return False

        if not self._is_conditional_node(node):
            return False

        a_succs = self._successors(node)

        if len(a_succs) != 2:
            self._sc_reject(node, "A does not have two successors")
            return False

        b_node = None
        then_terminal = None

        for s in a_succs:
            if self._is_conditional_node(s):
                b_node = s
            else:
                then_terminal = s

        if b_node is None or then_terminal is None:
            self._sc_reject(node, "A lacks conditional B or concrete THEN root")
            return False

        b_succs = self._successors(b_node)

        if len(b_succs) != 2:
            self._sc_reject(node, "B does not have two successors")
            return False

        c_node = None
        else_terminal = None

        for s in b_succs:
            if self._is_conditional_node(s):
                ss = self._successors(s)
                if then_terminal in ss:
                    c_node = s
                else:
                    else_terminal = s
            else:
                else_terminal = s

        if c_node is None or else_terminal is None:
            self._sc_reject(node, "could not distinguish C from ELSE root")
            return False

        c_succs = self._successors(c_node)

        if len(c_succs) != 2:
            self._sc_reject(node, "C does not have two successors")
            return False

        if not (then_terminal in c_succs and else_terminal in c_succs):
            self._sc_reject(node, "C successors are not THEN/ELSE roots")
            return False

        join = getattr(node, "ipdom", None)

        if join is None:
            self._sc_reject(node, "missing join")
            return False

        if self._looks_like_switch_decision_chain(node, b_node, c_node):
            self._sc_reject(node, "looks like switch decision chain")
            return False

        if not all(
            self._short_circuit_condition_node_is_pure_v49(n)
            for n in (node, b_node, c_node)
        ):
            self._sc_reject(
                node,
                "legacy short-circuit condition block has observable payload",
            )
            return False

        # Use raw condition formulas. Do not invert B/C in this recognized
        # OR-AND shape.
        a_expr = self._cond_expr_raw(node)
        b_expr = self._cond_expr_raw(b_node)
        c_expr = self._cond_expr_raw(c_node)

        if not a_expr or not b_expr or not c_expr:
            self._sc_reject(node, "missing raw condition expression")
            return False

        composite = RawCond("(%s) or ((%s) and (%s))" % (a_expr, b_expr, c_expr))

        self.visited.add(node)
        self.visited.add(b_node)
        self.visited.add(c_node)

        if_node = ExecIf(node, composite)
        parent.add(if_node)
        self._stamp_exec_if_edge_targets_v71(
            if_node,
            then_terminal,
            else_terminal,
            join,
            source_kind="short_circuit_or_and_legacy",
        )
        self._record_composite_condition_sources_v58(
            if_node,
            (node, b_node, c_node),
            "short_circuit_or_and_legacy",
        )

        branch_stops = set(stop_nodes)
        branch_stops.add(join)

        self._record_branch_event(
            node,
            getattr(node.block, "terminator", None),
            then_terminal,
            else_terminal,
            join,
            "short_circuit_or_and_raw_v3",
        )

        self._emit_node(then_terminal, if_node.then_branch, stop_nodes=branch_stops)
        self._emit_node(else_terminal, if_node.else_branch, stop_nodes=branch_stops)

        self._emit_node(join, parent, stop_nodes=stop_nodes)

        return True

    def _sc_reject(self, node, reason):
        """
        Debug-only record for why short-circuit recognition failed.
        """

        try:
            self.branch_events.append({
                "block": getattr(node, "addr", None),
                "mode": "short_circuit_reject:" + str(reason),
                "target_addr": None,
                "then": None,
                "else": None,
                "join": getattr(getattr(node, "ipdom", None), "addr", None),
            })
        except Exception:
            pass

    def _expr_for_edge_to_terminal(self, cfg_node, desired_terminal, expr):
        """
        Return expr or not(expr), depending on whether the CFG true edge reaches
        the desired terminal.

        This is intentionally edge-label aware only at this local point: the
        terminal relation determines whether the printed condition must be
        inverted.
        """

        true_node = self._true_edge(cfg_node)
        false_node = self._false_edge(cfg_node)

        if true_node is desired_terminal:
            return expr

        if false_node is desired_terminal:
            return "not (%s)" % expr

        # Sometimes the desired target is the next conditional, not a terminal.
        if true_node is not None and true_node is desired_terminal:
            return expr

        if false_node is not None and false_node is desired_terminal:
            return "not (%s)" % expr

        # Fallback: if true reaches desired and false does not, keep expr.
        if true_node is not None and self._reaches(true_node, desired_terminal):
            if false_node is None or not self._reaches(false_node, desired_terminal):
                return expr

        if false_node is not None and self._reaches(false_node, desired_terminal):
            if true_node is None or not self._reaches(true_node, desired_terminal):
                return "not (%s)" % expr

        return expr

    def _looks_like_switch_decision_chain(self, a_node, b_node, c_node):
        """
        Prevent the short-circuit recognizer from stealing switch decision trees.
        If the three conditions all compare the same computed expression /
        dispatch temp, treat it as switch-like, not boolean short-circuit.
        """

        sigs = []

        for n in (a_node, b_node, c_node):
            cond = self._condition_formula_node(n)
            sig = self._primary_nonconst_input_signature(cond)
            if sig is not None:
                sigs.append(sig)

        if len(sigs) < 2:
            return False

        return len(set(sigs)) == 1

    def _primary_nonconst_input_signature(self, cond_node):
        if cond_node is None:
            return None

        inputs = list(getattr(cond_node, "inputs", []) or [])

        for inp in inputs:
            if getattr(inp, "is_constant", False):
                continue

            sid = getattr(inp, "ssa_id", None)
            if sid is not None:
                return ("sid", sid)

            name = getattr(inp, "name", None)
            if name:
                return ("name", str(name))

        return None

    def _successors(self, cfg_node):
        """
        v22 compatibility helper for CFG successors.
        """
        if cfg_node is None:
            return []

        try:
            succs = getattr(cfg_node, "successors", None)
            if callable(succs):
                return [s for s in list(succs() or []) if s is not None]
            if succs is not None:
                return [s for s in list(succs or []) if s is not None]
        except Exception:
            pass

        out = []
        try:
            for e in list(getattr(cfg_node, "out_edges", []) or []):
                dst = getattr(e, "dst", None)
                if dst is not None:
                    out.append(dst)
        except Exception:
            pass

        return out

    # ----------------------------------------------------------------
    # v66 ERASE-EMPEROR TEMPORAL SNAPSHOT CUSTODY
    # ----------------------------------------------------------------

    def _snapshot_value_v66(self, value):
        if value is None:
            return None
        if hasattr(value, "var"):
            return getattr(value, "var", value)
        if hasattr(value, "output") and not hasattr(value, "ssa_id"):
            return getattr(value, "output", value)
        return value

    def _snapshot_sid_variants_v66(self, value):
        value = self._snapshot_value_v66(value)
        sid = getattr(value, "ssa_id", value)
        if sid is None:
            return []
        text = str(sid)
        out = [sid, text]
        if text.startswith("v_") and text[2:].isdigit():
            out.extend([text[2:], int(text[2:])])
        elif text.isdigit():
            out.extend([int(text), "v_%s" % text])
        deduped = []
        for item in out:
            if item not in deduped:
                deduped.append(item)
        return deduped

    def _snapshot_contract_for_v66(self, value):
        if value is None:
            return None

        direct = getattr(value, "snapshot_copy_contract_v35", None)
        if isinstance(direct, dict):
            return direct

        node = (
            value
            if hasattr(value, "opcode") and hasattr(value, "var")
            else self._formula_node_for_value_v64(value)
        )
        if node is not None:
            direct = getattr(node, "snapshot_copy_contract_v35", None)
            if isinstance(direct, dict):
                return direct
            var = getattr(node, "var", None)
            direct = getattr(var, "snapshot_copy_contract_v35", None)
            if isinstance(direct, dict):
                return direct

        var = self._snapshot_value_v66(value)
        direct = getattr(var, "snapshot_copy_contract_v35", None)
        if isinstance(direct, dict):
            return direct

        for key in self._snapshot_sid_variants_v66(var):
            try:
                rec = self.snapshot_copy_contracts_v35.get(key)
            except Exception:
                rec = None
            if isinstance(rec, dict):
                return rec
            try:
                rec = self.snapshot_copy_contracts_v35.get(str(key))
            except Exception:
                rec = None
            if isinstance(rec, dict):
                return rec
        return None

    def _snapshot_projection_name_v66(self, value):
        rec = self._snapshot_contract_for_v66(value)
        if not isinstance(rec, dict):
            return None
        if not bool(rec.get("materialization_required", True)):
            return None
        if bool(rec.get("transparent_copy_allowed", False)):
            return None

        name = rec.get("projection_name")
        if not name:
            for key in self._snapshot_sid_variants_v66(value):
                try:
                    name = self.snapshot_copy_projection_names_by_sid_v35.get(
                        str(key)
                    )
                except Exception:
                    name = None
                if name:
                    break
        return str(name) if name else None

    def _snapshot_formula_node_v66(self, sid):
        nodes = self._formula_nodes()
        for key in self._snapshot_sid_variants_v66(sid):
            try:
                node = nodes.get(key)
            except Exception:
                node = None
            if node is not None:
                return node
            try:
                node = nodes.get(str(key))
            except Exception:
                node = None
            if node is not None:
                return node
        return None

    def _record_snapshot_consumption_v66(self, value, renderer, projection):
        rec = self._snapshot_contract_for_v66(value)
        if not isinstance(rec, dict):
            return
        sid = str(
            rec.get("snapshot_sid")
            or self._projection_sid_text_v64(self._snapshot_value_v66(value))
        )
        key = (sid, str(renderer), str(projection))
        if key in self._snapshot_copy_event_keys_v66:
            return
        self._snapshot_copy_event_keys_v66.add(key)
        self._snapshot_copy_consumed_sids_v66.add(sid)
        event = {
            "kind": "erase_emperor_temporal_snapshot_consumed_v66",
            "snapshot_sid": sid,
            "source_sid": rec.get("source_sid"),
            "projection_name": str(projection),
            "renderer": str(renderer),
            "materialization_required": bool(
                rec.get("materialization_required", True)
            ),
            "transparent_copy_allowed": bool(
                rec.get("transparent_copy_allowed", False)
            ),
            "reason": (
                "protected historical SSA epoch must remain distinct from "
                "later PHI state"
            ),
        }
        self.snapshot_copy_consumption_events_v66.append(event)
        self._record_metadata_event_v43(dict(event))

    def _snapshot_render_boundary_v66(self, value, renderer):
        rec = self._snapshot_contract_for_v66(value)
        if not isinstance(rec, dict):
            return None
        projection = self._snapshot_projection_name_v66(value)
        if not projection:
            failure = {
                "kind": "erase_emperor_snapshot_projection_missing_v66",
                "snapshot_sid": rec.get("snapshot_sid"),
                "source_sid": rec.get("source_sid"),
                "renderer": str(renderer),
                "reason": (
                    "SemanticGraph protected a temporal snapshot but did not "
                    "publish an independent projection name"
                ),
            }
            self.snapshot_copy_failures_v66.append(failure)
            raise RuntimeError(
                "PALSGL v66 temporal snapshot custody failed: %s" % failure
            )
        self._record_snapshot_consumption_v66(value, renderer, projection)
        return projection

    def _formula_contains_snapshot_contract_v66(self, node, seen=None):
        if node is None:
            return False
        if seen is None:
            seen = set()
        sid = self._projection_sid_text_v64(
            getattr(node, "var", getattr(node, "output", None))
        )
        marker = (sid, id(node))
        if marker in seen:
            return False
        seen.add(marker)
        if isinstance(self._snapshot_contract_for_v66(node), dict):
            return True
        for operand in list(getattr(node, "inputs", []) or []):
            child = self._formula_node_for_value_v64(operand)
            if child is not None and self._formula_contains_snapshot_contract_v66(
                child, seen
            ):
                return True
        return False

    def _audit_temporal_snapshot_custody_v66(self):
        unique = {}
        for rec in self.snapshot_copy_contracts_v35.values():
            if not isinstance(rec, dict):
                continue
            sid = str(rec.get("snapshot_sid") or "")
            if sid:
                unique[sid] = rec

        failures = list(self.snapshot_copy_failures_v66)
        checked = []
        for sid, rec in sorted(unique.items(), key=lambda item: item[0]):
            projection = str(rec.get("projection_name") or "")
            node = self._snapshot_formula_node_v66(sid)
            item = {
                "snapshot_sid": sid,
                "source_sid": rec.get("source_sid"),
                "projection_name": projection or None,
                "formula_node_found": node is not None,
                "opcode": getattr(node, "opcode", None) if node is not None else None,
            }
            checked.append(item)
            if not projection:
                failures.append({
                    "kind": "erase_emperor_snapshot_contract_missing_projection_v66",
                    **item,
                })
                continue
            if node is None or getattr(node, "opcode", None) != "COPY":
                failures.append({
                    "kind": "erase_emperor_snapshot_formula_node_missing_v66",
                    **item,
                })
                continue

            rendered = self._formula_expr(node)
            resolved = self._resolve_transparent_formula(
                node, self._formula_nodes()
            )
            item["rendered"] = rendered
            item["transparent_resolver_stopped"] = resolved is node
            if str(rendered) != projection:
                failures.append({
                    "kind": "erase_emperor_snapshot_still_rendered_transparently_v66",
                    **item,
                })
            if resolved is not node:
                failures.append({
                    "kind": "erase_emperor_snapshot_transparent_resolver_bypass_v66",
                    **item,
                })

        self.snapshot_copy_failures_v66 = failures
        audit = {
            "kind": (
                "erase_emperor_temporal_snapshot_custody_verified_v66"
                if not failures
                else "erase_emperor_temporal_snapshot_custody_failed_v66"
            ),
            "version": self.sgl_version,
            "semantic_snapshot_version": self.snapshot_copy_version_v35,
            "contracts": len(unique),
            "checked": checked,
            "consumed_snapshot_sids": sorted(
                self._snapshot_copy_consumed_sids_v66, key=str
            ),
            "consumption_events": len(
                self.snapshot_copy_consumption_events_v66
            ),
            "failures": list(failures),
            "global_storage_renames": 0,
            "global_phi_family_renames": 0,
            "rule": (
                "protected_COPY_output_is_exact_temporal_identity_boundary_"
                "in_every_SGL_renderer"
            ),
        }
        self.snapshot_copy_custody_audit_v66 = audit
        self.snapshot_copy_consumption_events_v66.append(dict(audit))
        if failures:
            raise RuntimeError(
                "PALSGL v66 erase-emperor custody failed: %s" % audit
            )
        return audit

    # ----------------------------------------------------------------
    # v67 NULL-EMPEROR MATERIALIZED DERIVED-VALUE BOUNDARIES
    # ----------------------------------------------------------------


    # =========================================================================
    # v68 GHOST-EMPEROR LOOP-EXIT SNAPSHOT REBINDING
    # =========================================================================

    @staticmethod
    def _ghost_emperor_sid_v68(value):
        if value is None:
            return None
        if hasattr(value, "var"):
            value = getattr(value, "var", value)
        sid = getattr(value, "ssa_id", None)
        if sid is not None:
            value = sid
        text = str(value)
        if text.startswith(("v_", "c_")):
            return text
        if text.isdigit():
            return "v_%s" % text
        return text

    def _ghost_emperor_formula_node_v68(self, sid):
        sid = self._ghost_emperor_sid_v68(sid)
        nodes = getattr(self.func, "formula_nodes", {}) or {}
        for key in (sid, str(sid)):
            if key in nodes:
                return nodes.get(key)
        for node in nodes.values():
            if self._ghost_emperor_sid_v68(
                getattr(node, "var", None)
            ) == sid:
                return node
        return None

    def _ghost_emperor_exec_loops_v68(self):
        loops = []
        self._walk_exec_tree_v22(
            self.root,
            lambda node: loops.append(node)
            if getattr(node, "kind", None) == "loop" else None,
        )
        return loops

    def _ghost_emperor_loop_cfg_addrs_v68(self, loop_node):
        header = getattr(loop_node, "header", None)
        nodes = set(self.loop_nodes.get(header, set()) or set())
        nodes.add(header)
        return {
            getattr(node, "addr", None)
            for node in nodes if node is not None
        }

    def _ghost_emperor_body_breaks_v68(self, loop_node):
        breaks = []
        header = getattr(loop_node, "header", None)

        def visit(node):
            if getattr(node, "kind", None) != "break":
                return
            target = getattr(node, "target_loop", None)
            if target in (None, loop_node, header):
                breaks.append(node)

        self._walk_exec_tree_v22(getattr(loop_node, "body", None), visit)
        return breaks

    def _compile_ghost_emperor_loop_exit_rebindings_v68(self):
        """Prove last-write-wins snapshot equivalence at one loop exit.

        A native COPY in a repeating condition transaction may be relocated to
        immediately after the loop only when every direct snapshot use is
        outside the natural loop. The final failed predicate evaluation then
        guarantees that the copied PHI epoch equals the loop-exit state.
        """
        self.ghost_emperor_loop_exit_snapshot_bindings_v68 = {}
        self.ghost_emperor_native_capture_suppressions_v68 = {}
        self.ghost_emperor_events_v68 = []
        self.ghost_emperor_failures_v68 = []

        unique = {}
        for record in list(self.snapshot_copy_contracts_v35.values()):
            if not isinstance(record, dict):
                continue
            sid = self._ghost_emperor_sid_v68(record.get("snapshot_sid"))
            if sid is not None:
                unique[sid] = record

        loops = self._ghost_emperor_exec_loops_v68()
        by_header = {}
        for loop in loops:
            addr = getattr(getattr(loop, "header", None), "addr", None)
            by_header.setdefault(addr, []).append(loop)

        for snapshot_sid, record in sorted(unique.items(), key=lambda item: str(item[0])):
            source_sid = self._ghost_emperor_sid_v68(record.get("source_sid"))
            capture_addr = record.get("capture_block_addr")
            candidates = list(by_header.get(capture_addr, []) or [])
            snapshot_node = self._ghost_emperor_formula_node_v68(snapshot_sid)
            source_node = self._ghost_emperor_formula_node_v68(source_sid)
            downstream = list(record.get("downstream_uses", []) or [])

            gates = {
                "single_structured_loop_owner": len(candidates) == 1,
                "repeatable_condition_transaction": bool(
                    len(candidates) == 1
                    and getattr(candidates[0], "condition_transaction", None)
                    is not None
                ),
                "snapshot_is_copy": bool(
                    snapshot_node is not None
                    and getattr(snapshot_node, "opcode", None) == "COPY"
                ),
                "source_is_phi_epoch": bool(
                    source_node is not None
                    and (
                        getattr(source_node, "opcode", None) == "MULTIEQUAL"
                        or bool(getattr(source_node, "is_phi", False))
                    )
                ),
                "direct_uses_known": bool(downstream),
                "single_normal_loop_exit": bool(
                    len(candidates) == 1
                    and len(
                        set(
                            self.loop_normal_exits.get(
                                getattr(candidates[0], "header", None), set()
                            ) or set()
                        )
                    ) == 1
                ),
                "no_body_break_exit": bool(
                    len(candidates) == 1
                    and not self._ghost_emperor_body_breaks_v68(candidates[0])
                ),
            }

            loop_addrs = set()
            internal_uses = []
            unknown_uses = []
            if len(candidates) == 1:
                loop_addrs = self._ghost_emperor_loop_cfg_addrs_v68(candidates[0])
                for use in downstream:
                    addr = use.get("block_addr") if isinstance(use, dict) else None
                    if addr is None:
                        unknown_uses.append(use)
                    elif addr in loop_addrs:
                        internal_uses.append(use)
            gates["no_unknown_use_location"] = not unknown_uses
            gates["no_loop_internal_snapshot_read"] = not internal_uses
            gates["semantic_contract_allows_structural_placement"] = bool(
                record.get("structural_relocation_candidate", True)
                and record.get("execution_placement_authority", "PALSGLdecomp")
                == "PALSGLdecomp"
            )

            failed = [name for name, ok in gates.items() if not ok]
            if failed:
                self.ghost_emperor_events_v68.append({
                    "kind": "ghost_emperor_loop_exit_rebinding_not_applicable_v68",
                    "snapshot_sid": snapshot_sid,
                    "source_sid": source_sid,
                    "capture_block_addr": capture_addr,
                    "failed_gates": failed,
                    "internal_uses": internal_uses,
                    "unknown_uses": unknown_uses,
                    "compilation_failure": False,
                })
                continue

            loop = candidates[0]
            op_id = getattr(snapshot_node, "op_id", None)
            binding = {
                "kind": "ghost_emperor_loop_exit_snapshot_binding_v68",
                "version": self.ghost_emperor_version_v68,
                "snapshot_sid": snapshot_sid,
                "source_sid": source_sid,
                "projection_name": (
                    record.get("projection_name") or snapshot_sid
                ),
                "loop_header_addr": capture_addr,
                "capture_block_addr": capture_addr,
                "native_capture_op_id": (
                    str(op_id) if op_id is not None
                    else record.get("native_capture_op_id")
                ),
                "native_producer_emit": False,
                "synthetic_loop_exit_owner_required": True,
                "placement": "immediately_after_structured_loop",
                "source_value_at_placement": "loop_exit_phi_epoch",
                "downstream_uses": downstream,
                "proof": {
                    "repeatable_condition_transaction": True,
                    "last_write_wins": True,
                    "final_failed_predicate_evaluation_executes_capture": True,
                    "no_loop_internal_snapshot_read": True,
                    "all_direct_uses_outside_natural_loop": True,
                },
                "authority": (
                    "SemanticGraph_snapshot_identity_plus_"
                    "SGL_exact_loop_and_liveness_custody"
                ),
            }
            loop.loop_exit_snapshot_bindings_v68.append(binding)
            self.ghost_emperor_loop_exit_snapshot_bindings_v68[
                snapshot_sid
            ] = binding
            suppression_key = (
                snapshot_sid,
                capture_addr,
                binding.get("native_capture_op_id"),
            )
            self.ghost_emperor_native_capture_suppressions_v68[
                snapshot_sid
            ] = {
                "snapshot_sid": snapshot_sid,
                "capture_block_addr": capture_addr,
                "native_capture_op_id": binding.get("native_capture_op_id"),
                "suppression_key": suppression_key,
                "replacement_owner": "loop_exit_snapshot_binding",
            }
            self.ghost_emperor_events_v68.append({
                "kind": "ghost_emperor_loop_exit_rebinding_proven_v68",
                "snapshot_sid": snapshot_sid,
                "source_sid": source_sid,
                "loop_header_addr": capture_addr,
                "native_capture_op_id": binding.get("native_capture_op_id"),
                "direct_use_count": len(downstream),
            })

    def _audit_ghost_emperor_loop_exit_rebindings_v68(self):
        failures = []
        loops = self._ghost_emperor_exec_loops_v68()
        owner_counts = {}
        for loop in loops:
            for binding in list(
                getattr(loop, "loop_exit_snapshot_bindings_v68", []) or []
            ):
                sid = self._ghost_emperor_sid_v68(binding.get("snapshot_sid"))
                owner_counts[sid] = owner_counts.get(sid, 0) + 1

        for sid, binding in sorted(
            self.ghost_emperor_loop_exit_snapshot_bindings_v68.items(),
            key=lambda item: str(item[0]),
        ):
            gates = {
                "one_loop_owner": owner_counts.get(sid, 0) == 1,
                "native_producer_suppressed": (
                    binding.get("native_producer_emit") is False
                ),
                "synthetic_owner_required": (
                    binding.get("synthetic_loop_exit_owner_required") is True
                ),
                "source_sid_present": bool(binding.get("source_sid")),
                "projection_present": bool(binding.get("projection_name")),
            }
            failed = [name for name, ok in gates.items() if not ok]
            if failed:
                failures.append({
                    "kind": "ghost_emperor_loop_exit_rebinding_audit_failure_v68",
                    "snapshot_sid": sid,
                    "failed_gates": failed,
                    "binding": dict(binding),
                })

        audit = {
            "kind": (
                "ghost_emperor_loop_exit_rebinding_verified_v68"
                if not failures else
                "ghost_emperor_loop_exit_rebinding_failed_v68"
            ),
            "version": self.ghost_emperor_version_v68,
            "active": bool(self.ghost_emperor_loop_exit_snapshot_bindings_v68),
            "bindings": len(self.ghost_emperor_loop_exit_snapshot_bindings_v68),
            "non_applicable_snapshots": sum(
                1 for event in self.ghost_emperor_events_v68
                if event.get("kind")
                == "ghost_emperor_loop_exit_rebinding_not_applicable_v68"
            ),
            "owner_counts": owner_counts,
            "failures": failures,
            "rule": (
                "repeatable_header_COPY_with_no_loop_internal_reads_"
                "rebounds_once_at_exact_structured_loop_exit"
            ),
        }
        self.ghost_emperor_audit_v68 = audit
        self.ghost_emperor_events_v68.append(dict(audit))
        if failures:
            raise RuntimeError(
                "PALSGLdecomp v68 ghost-emperor custody failed: %s"
                % failures
            )
        return audit

    def _compile_null_emperor_derived_boundaries_v67(self):
        contracts = {}
        projections = {}
        result_sids = set()

        for snapshot in list(self.snapshot_copy_contracts_v35.values()):
            if not isinstance(snapshot, dict):
                continue
            snapshot_sid = self._projection_sid_text_v64(
                snapshot.get("snapshot_sid")
            )
            for joint in list(snapshot.get("joint_consumers", []) or []):
                if not isinstance(joint, dict):
                    continue
                result_sid = self._projection_sid_text_v64(
                    joint.get("consumer_sid")
                )
                if result_sid is None:
                    continue
                opcode = str(joint.get("consumer_opcode") or "").upper()
                if opcode not in {
                    "INT_SUB", "INT_DIV", "INT_SDIV", "INT_REM",
                    "INT_SREM", "INT_LEFT", "INT_RIGHT",
                    "INT_SRIGHT", "INT_LESS", "INT_SLESS",
                    "INT_LESSEQUAL", "INT_SLESSEQUAL",
                    "PTRADD", "PTRSUB",
                }:
                    continue

                projection = (
                    joint.get("result_projection_name")
                    or joint.get("projection_name")
                    or result_sid
                )
                rec = contracts.setdefault(result_sid, {
                    "kind": "null_emperor_derived_value_boundary_v67",
                    "version": self.null_emperor_version_v67,
                    "result_sid": result_sid,
                    "projection_name": str(projection),
                    "consumer_opcode": opcode,
                    "snapshot_sids": [],
                    "source_sids": [],
                    "later_epoch_sids": [],
                    "joint_consumers": [],
                    "materialization_required": True,
                    "formula_inline_allowed": False,
                    "authority": (
                        "SemanticGraph_v35_joint_consumer_temporal_identity_"
                        "plus_SGL_v67_exact_result_boundary"
                    ),
                })
                if snapshot_sid and snapshot_sid not in rec["snapshot_sids"]:
                    rec["snapshot_sids"].append(snapshot_sid)
                source_sid = self._projection_sid_text_v64(
                    snapshot.get("source_sid")
                )
                if source_sid and source_sid not in rec["source_sids"]:
                    rec["source_sids"].append(source_sid)
                later_sid = self._projection_sid_text_v64(
                    joint.get("later_epoch_sid")
                )
                if later_sid and later_sid not in rec["later_epoch_sids"]:
                    rec["later_epoch_sids"].append(later_sid)
                rec["joint_consumers"].append(dict(joint))
                projections[result_sid] = str(projection)
                result_sids.add(result_sid)

        self.null_emperor_derived_contracts_v67 = contracts
        self.null_emperor_derived_result_sids_v67 = result_sids
        self.null_emperor_derived_projection_names_by_sid_v67 = projections
        return contracts

    def _null_emperor_contract_for_v67(self, value):
        sid = self._projection_sid_text_v64(value)
        if sid is None:
            return None
        rec = self.null_emperor_derived_contracts_v67.get(sid)
        return rec if isinstance(rec, dict) else None

    def _null_emperor_projection_v67(self, value):
        rec = self._null_emperor_contract_for_v67(value)
        if not isinstance(rec, dict):
            return None
        if not bool(rec.get("materialization_required", True)):
            return None
        if bool(rec.get("formula_inline_allowed", False)):
            return None
        return str(rec.get("projection_name") or rec.get("result_sid"))

    def _null_emperor_render_boundary_v67(self, value, renderer):
        projection = self._null_emperor_projection_v67(value)
        if projection is None:
            return None
        sid = self._projection_sid_text_v64(value)
        marker = (sid, str(renderer), projection)
        if marker not in self._null_emperor_event_keys_v67:
            self._null_emperor_event_keys_v67.add(marker)
            event = {
                "kind": "null_emperor_derived_boundary_consumed_v67",
                "version": self.null_emperor_version_v67,
                "result_sid": sid,
                "projection_name": projection,
                "renderer": str(renderer),
                "reason": (
                    "materialized snapshot-derived result is an exact value "
                    "boundary and must not be recursively recomputed"
                ),
            }
            self.null_emperor_derived_events_v67.append(event)
            self._record_metadata_event_v43(dict(event))
        return projection

    def _formula_contains_null_emperor_boundary_v67(self, node, seen=None):
        if node is None:
            return False
        if seen is None:
            seen = set()
        marker = id(node)
        if marker in seen:
            return False
        seen.add(marker)
        if isinstance(self._null_emperor_contract_for_v67(node), dict):
            return True
        for operand in list(getattr(node, "inputs", []) or []):
            child = self._formula_node_for_value_v64(operand)
            if child is not None and self._formula_contains_null_emperor_boundary_v67(
                child, seen
            ):
                return True
        return False

    def _audit_null_emperor_derived_boundaries_v67(self):
        self._compile_null_emperor_derived_boundaries_v67()
        failures = list(self.null_emperor_derived_failures_v67)
        checked = []
        for sid, rec in sorted(
            self.null_emperor_derived_contracts_v67.items(),
            key=lambda item: str(item[0]),
        ):
            node = self._snapshot_formula_node_v66(sid)
            projection = str(rec.get("projection_name") or sid)
            rendered = self._formula_expr(node) if node is not None else None
            item = {
                "result_sid": sid,
                "projection_name": projection,
                "node_found": node is not None,
                "opcode": getattr(node, "opcode", None) if node else None,
                "rendered": rendered,
                "snapshot_sids": list(rec.get("snapshot_sids", []) or []),
                "later_epoch_sids": list(
                    rec.get("later_epoch_sids", []) or []
                ),
            }
            checked.append(item)
            if node is None:
                failures.append({
                    "kind": "null_emperor_derived_formula_node_missing_v67",
                    **item,
                })
            elif str(rendered) != projection:
                failures.append({
                    "kind": "null_emperor_derived_value_reexpanded_v67",
                    **item,
                })

        audit = {
            "kind": (
                "null_emperor_derived_boundary_verified_v67"
                if not failures
                else "null_emperor_derived_boundary_failed_v67"
            ),
            "version": self.null_emperor_version_v67,
            "active": bool(self.null_emperor_derived_contracts_v67),
            "contracts": len(self.null_emperor_derived_contracts_v67),
            "checked": checked,
            "failures": failures,
            "rule": (
                "materialized_snapshot_derived_result_is_terminal_SGL_"
                "formula_identity"
            ),
        }
        self.null_emperor_derived_failures_v67 = failures
        self.null_emperor_derived_audit_v67 = audit
        self.null_emperor_derived_events_v67.append(dict(audit))
        if failures:
            raise RuntimeError(
                "PALSGL v67 null-emperor derived boundary failed: %s"
                % failures
            )
        return audit

    def _projection_sid_text_v64(self, value):
        if value is None:
            return None
        if hasattr(value, "var"):
            value = getattr(value, "var", value)
        elif hasattr(value, "output") and not hasattr(value, "ssa_id"):
            value = getattr(value, "output", value)
        sid = getattr(value, "ssa_id", value)
        return None if sid is None else str(sid)

    # Compatibility name retained for external diagnostics/tests.
    def _projection_sid_text_v63(self, value):
        return self._projection_sid_text_v64(value)

    def _projection_sid_variants_v64(self, value):
        text = self._projection_sid_text_v64(value)
        if text is None:
            return []
        out = [text]
        raw = value
        if hasattr(raw, "var"):
            raw = getattr(raw, "var", raw)
        elif hasattr(raw, "output") and not hasattr(raw, "ssa_id"):
            raw = getattr(raw, "output", raw)
        raw_sid = getattr(raw, "ssa_id", None)
        if raw_sid is not None and raw_sid not in out:
            out.insert(0, raw_sid)
        if text.startswith("v_") and text[2:].isdigit():
            for candidate in (text[2:], int(text[2:])):
                if candidate not in out:
                    out.append(candidate)
        elif text.isdigit():
            for candidate in ("v_" + text, int(text)):
                if candidate not in out:
                    out.append(candidate)
        return out

    def _consumer_output_v64(self, consumer):
        if consumer is None:
            return None
        value = getattr(consumer, "var", None)
        if value is not None:
            return value
        return getattr(consumer, "output", None)

    def _normalize_stack_key_v64(self, key):
        if key is None:
            return None
        try:
            parts = list(key)
        except Exception:
            return None
        if len(parts) < 3:
            return None
        tag = str(parts[0]).lower()
        if tag == "space" and len(parts) >= 4:
            if str(parts[1]).lower() != "stack":
                return None
            off, size = parts[2], parts[3]
        elif tag == "stack":
            off, size = parts[1], parts[2]
        else:
            return None
        try:
            return ("stack", int(off), int(size or 0))
        except Exception:
            return None

    def _concrete_stack_key_v64(self, value):
        if hasattr(value, "var"):
            value = value.var
        if value is None:
            return None
        space = (
            getattr(value, "storage_space", None)
            or getattr(value, "space", None)
        )
        if str(space or "").lower() != "stack":
            return None
        off = getattr(value, "storage_offset", None)
        if off is None:
            off = getattr(value, "offset", None)
        if off is None:
            return None
        size = getattr(value, "storage_size", None)
        if size is None:
            size = getattr(value, "size", None)
        try:
            return ("stack", int(off), int(size or 0))
        except Exception:
            return None

    # Compatibility name retained for older consumers/tests.
    def _concrete_stack_key_v63(self, value):
        return self._concrete_stack_key_v64(value)

    def _projection_name_for_stack_key_v64(self, key):
        key = self._normalize_stack_key_v64(key)
        if key is None:
            return None
        off = key[1]
        return "local_%x" % abs(int(off))

    def _legacy_var_expr_v64(self, value):
        """Stable renderer authority with no global projection side effect."""
        if value is None:
            return "None"
        snapshot = self._snapshot_render_boundary_v66(
            value, "legacy_var"
        )
        if snapshot is not None:
            return snapshot
        if hasattr(value, "var"):
            value = value.var
        if getattr(value, "is_constant", False):
            return self._const_expr(value)
        sid = getattr(value, "ssa_id", None)
        var_map = getattr(self.func, "var_map", {}) or {}
        for key in self._projection_sid_variants_v64(value):
            try:
                if key in var_map:
                    return str(var_map.get(key))
            except Exception:
                pass
        name = getattr(value, "name", None)
        if name:
            return str(name)
        if sid is not None:
            return str(sid)
        return str(value)

    def _formula_node_for_value_v64(self, value):
        if value is None:
            return None
        if hasattr(value, "opcode") and hasattr(value, "var"):
            return value
        nodes = self._formula_nodes()
        for key in self._projection_sid_variants_v64(value):
            try:
                if key in nodes:
                    return nodes.get(key)
            except Exception:
                pass
        return None

    def _consumer_raw_inputs_v65(self, consumer):
        """Return the original PAL operands paired with linked FormulaNode inputs.

        SemanticGraph deliberately retains ``FormulaNode.raw_inputs`` before
        replacing same-SID operands with FormulaNodes.  Storage identity can
        live only on those original PALVariable objects.  v64 inspected only
        linked ``inputs`` and therefore silently lost the exact stack offsets
        needed to distinguish cursor, snapshot, and result state.
        """
        if consumer is None:
            return []

        raw = getattr(consumer, "raw_inputs", None)
        if raw is None or (not raw and getattr(consumer, "inputs", None)):
            op = getattr(consumer, "op", None)
            if op is not None:
                raw = getattr(op, "inputs", None)
        if raw is None:
            raw = getattr(consumer, "inputs", None)
        try:
            return list(raw or [])
        except Exception:
            return []

    def _consumer_raw_output_v65(self, consumer):
        if consumer is None:
            return None
        op = getattr(consumer, "op", None)
        raw = getattr(op, "output", None) if op is not None else None
        if raw is not None:
            return raw
        return getattr(consumer, "output", None)

    def _raw_operand_hint_v65(self, consumer, operand_index, fallback=None):
        try:
            raw_inputs = self._consumer_raw_inputs_v65(consumer)
            raw = raw_inputs[int(operand_index)]
            return raw if raw is not None else fallback
        except Exception:
            return fallback

    def _record_raw_operand_evidence_v65(
        self,
        consumer,
        operand_index,
        linked_value,
        raw_hint,
        storage_key,
        source,
    ):
        if raw_hint is None or storage_key is None:
            return
        consumer_sid = self._projection_sid_text_v64(
            self._consumer_output_v64(consumer)
        ) if consumer is not None else None
        key = (
            consumer_sid,
            int(operand_index) if operand_index is not None else None,
            self._projection_sid_text_v64(linked_value),
            self._projection_sid_text_v64(raw_hint),
            tuple(storage_key),
            str(source),
        )
        if key in self._operand_projection_raw_evidence_keys_v65:
            return
        self._operand_projection_raw_evidence_keys_v65.add(key)
        self.operand_projection_raw_evidence_events_v65.append({
            "kind": "raw_operand_storage_evidence_consumed_v65",
            "consumer_sid": consumer_sid,
            "consumer_opcode": getattr(consumer, "opcode", None),
            "operand_index": (
                int(operand_index) if operand_index is not None else None
            ),
            "linked_sid": self._projection_sid_text_v64(linked_value),
            "raw_sid": self._projection_sid_text_v64(raw_hint),
            "storage_key": storage_key,
            "source": str(source),
            "reason": (
                "original PAL operand retains storage identity after semantic "
                "input linking"
            ),
        })

    def _resolve_stack_source_v64(
        self,
        value,
        seen=None,
        depth=0,
        raw_hint=None,
        consumer=None,
        operand_index=None,
    ):
        """Resolve one value to concrete stack storage using paired raw inputs.

        Linked FormulaNode inputs remain the expression/SSA authority.  Their
        positionally paired ``raw_inputs`` are the storage authority.  Only
        transparent transports and identity PHIs may propagate that evidence.
        """
        if value is None or depth > 10:
            return None
        if seen is None:
            seen = set()

        raw_value = value
        node = self._formula_node_for_value_v64(value)
        var = getattr(node, "var", None) if node is not None else None
        if var is None:
            var = getattr(value, "var", value)

        raw_sid = self._projection_sid_text_v64(raw_value)
        hint_sid = self._projection_sid_text_v64(raw_hint)
        marker = (
            raw_sid,
            hint_sid,
            id(node) if node is not None else id(var),
        )
        if marker in seen:
            return None
        seen.add(marker)

        hint_var = getattr(raw_hint, "var", raw_hint)
        hint_direct = self._concrete_stack_key_v64(hint_var)
        if hint_direct is not None:
            self._record_raw_operand_evidence_v65(
                consumer,
                operand_index,
                raw_value,
                raw_hint,
                hint_direct,
                "paired_consumer_raw_input",
            )
            lineage = []
            for sid in (raw_sid, hint_sid):
                if sid is not None and sid not in lineage:
                    lineage.append(sid)
            return {
                "operand_sid": raw_sid,
                "source_sid": hint_sid or raw_sid,
                "linked_source_sid": raw_sid,
                "raw_source_sid": hint_sid,
                "storage_key": hint_direct,
                "evidence_sid": hint_sid,
                "evidence_var": hint_var,
                "evidence_source": "paired_consumer_raw_input",
                "lineage_sids": lineage,
            }

        direct = self._concrete_stack_key_v64(var)
        if direct is not None:
            return {
                "operand_sid": raw_sid,
                "source_sid": raw_sid,
                "linked_source_sid": raw_sid,
                "raw_source_sid": hint_sid,
                "storage_key": direct,
                "evidence_sid": self._projection_sid_text_v64(var),
                "evidence_var": var,
                "evidence_source": "linked_value_direct_storage",
                "lineage_sids": [raw_sid] if raw_sid is not None else [],
            }

        if node is None:
            return None

        opcode = str(getattr(node, "opcode", "") or "")
        inputs = list(getattr(node, "inputs", []) or [])
        raw_inputs = self._consumer_raw_inputs_v65(node)
        transparent = {
            "COPY", "CAST", "INT_ZEXT", "INT_SEXT", "TRUNC", "SUBPIECE",
        }
        if opcode == "COPY" and isinstance(
            self._snapshot_contract_for_v66(node), dict
        ):
            # Temporal snapshots intentionally terminate storage-family
            # tracing. Following the COPY source would launder the historical
            # epoch back into the live PHI state.
            return None
        if opcode in transparent and inputs:
            child_raw = raw_inputs[0] if raw_inputs else None
            result = self._resolve_stack_source_v64(
                inputs[0],
                seen=set(seen),
                depth=depth + 1,
                raw_hint=child_raw,
                consumer=node,
                operand_index=0,
            )
            if result is not None and raw_sid is not None:
                lineage = list(result.get("lineage_sids", []) or [])
                if raw_sid not in lineage:
                    lineage.insert(0, raw_sid)
                result = dict(result)
                result["operand_sid"] = raw_sid
                result["linked_source_sid"] = raw_sid
                result["lineage_sids"] = lineage
            return result

        if opcode == "MULTIEQUAL" and inputs:
            resolved = []
            for index, operand in enumerate(inputs):
                if getattr(operand, "is_constant", False):
                    return None
                child_raw = raw_inputs[index] if index < len(raw_inputs) else None
                item = self._resolve_stack_source_v64(
                    operand,
                    seen=set(seen),
                    depth=depth + 1,
                    raw_hint=child_raw,
                    consumer=node,
                    operand_index=index,
                )
                if item is None:
                    return None
                resolved.append(item)
            keys = {item.get("storage_key") for item in resolved}
            if len(keys) != 1:
                return None
            first = dict(resolved[0])
            lineage = []
            for item in resolved:
                for sid in list(item.get("lineage_sids", []) or []):
                    if sid is not None and sid not in lineage:
                        lineage.append(sid)
            for sid in (raw_sid, hint_sid):
                if sid is not None and sid not in lineage:
                    lineage.insert(0, sid)
            first["operand_sid"] = raw_sid
            first["linked_source_sid"] = raw_sid
            first["lineage_sids"] = lineage
            return first

        return None

    def _lookup_operand_projection_contract_v64(self, consumer, operand_index):
        index = int(operand_index)
        variants = self._projection_sid_variants_v64(
            self._consumer_output_v64(consumer)
        )
        matches = []
        for key, rec in list(self.operand_projection_contracts.items()):
            if not isinstance(rec, dict):
                continue
            key_consumer = None
            key_index = None
            if isinstance(key, tuple) and len(key) == 2:
                key_consumer, key_index = key
            rec_consumer = rec.get("consumer_sid")
            rec_index = rec.get("operand_index")
            candidate_consumer = (
                key_consumer if key_consumer is not None else rec_consumer
            )
            candidate_index = key_index if key_index is not None else rec_index
            try:
                candidate_index = int(candidate_index)
            except Exception:
                continue
            if candidate_index != index:
                continue
            if str(candidate_consumer) not in {str(v) for v in variants}:
                continue
            matches.append((key, rec))

        if not matches:
            return None, None
        unique = {
            (
                str(rec.get("projection_name")),
                str(rec.get("source_sid")),
                str(self._normalize_stack_key_v64(rec.get("storage_key"))),
            )
            for _key, rec in matches
        }
        if len(unique) > 1:
            failure = {
                "kind": "operand_projection_contract_conflict_v64",
                "consumer_sid": self._projection_sid_text_v64(
                    self._consumer_output_v64(consumer)
                ),
                "operand_index": index,
                "contracts": [dict(rec) for _key, rec in matches],
            }
            self._operand_projection_failures_v64.append(failure)
            raise RuntimeError(
                "PALSGL v65 conflicting operand projection contracts: %s"
                % failure
            )
        return matches[0][1], matches[0][0]

    def _legacy_operand_name_v64(self, value, evidence=None):
        rendered = self._legacy_var_expr_v64(value)
        if rendered not in (None, ""):
            return str(rendered)
        if isinstance(evidence, dict):
            return self._legacy_var_expr_v64(evidence.get("evidence_var"))
        return None

    def _compile_local_consumer_projection_v64(self, consumer):
        output = self._consumer_output_v64(consumer)
        consumer_sid = self._projection_sid_text_v64(output)
        cache_key = (consumer_sid, id(consumer))
        if cache_key in self._operand_projection_compile_cache_v64:
            return self._operand_projection_compile_cache_v64[cache_key]

        opcode = str(getattr(consumer, "opcode", "") or "")
        inputs = list(getattr(consumer, "inputs", []) or [])
        raw_inputs = self._consumer_raw_inputs_v65(consumer)
        supported = {
            "INT_ADD", "INT_SUB", "INT_MULT", "INT_DIV", "INT_SDIV",
            "INT_REM", "INT_SREM", "INT_AND", "INT_OR", "INT_XOR",
            "INT_LEFT", "INT_RIGHT", "INT_SRIGHT", "INT_EQUAL",
            "INT_NOTEQUAL", "INT_LESS", "INT_SLESS", "INT_LESSEQUAL",
            "INT_SLESSEQUAL", "BOOL_AND", "BOOL_OR", "BOOL_XOR",
        }
        if consumer_sid is None or opcode not in supported or len(inputs) != 2:
            self._operand_projection_compile_cache_v64[cache_key] = []
            return []

        participants = []
        for index, operand in enumerate(inputs):
            if getattr(operand, "is_constant", False):
                continue
            raw_hint = (
                raw_inputs[index] if index < len(raw_inputs) else None
            )
            evidence = self._resolve_stack_source_v64(
                operand, raw_hint=raw_hint, consumer=consumer,
                operand_index=index,
            )
            if evidence is None:
                continue
            baseline = self._legacy_operand_name_v64(operand, evidence)
            if not baseline:
                continue
            participants.append({
                "operand_index": index,
                "operand": operand,
                "source_sid": (
                    evidence.get("source_sid")
                    or self._projection_sid_text_v64(operand)
                ),
                "linked_source_sid": self._projection_sid_text_v64(operand),
                "raw_source_sid": self._projection_sid_text_v64(raw_hint),
                "storage_key": evidence.get("storage_key"),
                "evidence": evidence,
                "baseline_name": baseline,
            })

        compiled = []
        by_name = {}
        for item in participants:
            by_name.setdefault(item["baseline_name"], []).append(item)

        for collision_name, items in by_name.items():
            keys = {item["storage_key"] for item in items}
            offsets = {key[1] for key in keys if key is not None}
            if len(items) < 2 or len(keys) < 2 or len(offsets) < 2:
                continue
            names = {
                key: self._projection_name_for_stack_key_v64(key)
                for key in keys
            }
            if any(not name for name in names.values()):
                continue
            if len(set(names.values())) != len(names):
                continue

            collision = {
                "kind": "joint_consumer_distinct_stack_name_collision_v65",
                "version": self.sgl_version,
                "consumer_sid": consumer_sid,
                "consumer_opcode": opcode,
                "collision_name": collision_name,
                "distinct_stack_offsets": sorted(offsets),
                "participants": [],
                "reason": (
                    "SGL live consumer maps distinct concrete stack operands "
                    "to one legacy text"
                ),
            }
            for item in items:
                key = item["storage_key"]
                rec = {
                    "kind": "joint_consumer_operand_projection_contract_v65",
                    "version": self.sgl_version,
                    "consumer_sid": consumer_sid,
                    "consumer_opcode": opcode,
                    "consumer_block_addr": getattr(consumer, "block_addr", None),
                    "operand_index": int(item["operand_index"]),
                    # PHIfolder validates this against the live consumer input.
                    "source_sid": item["source_sid"],
                    "linked_source_sid": item.get("linked_source_sid"),
                    "raw_source_sid": item.get("raw_source_sid"),
                    "storage_key": key,
                    "storage_evidence_source": item["evidence"].get(
                        "evidence_source"
                    ),
                    "baseline_name": item["baseline_name"],
                    "projection_name": names[key],
                    "projection_role": "exact_consumer_stack_operand",
                    "projection_scope": "consumer_sid_plus_operand_index_only",
                    "renderer_authority": "func.var_map_then_var.name_then_SSA",
                    "producer": "PALSGLdecomp_v65_raw_operand_exact_fallback",
                    "reason": collision["reason"],
                }
                contract_key = (consumer_sid, int(item["operand_index"]))
                existing, _existing_key = self._lookup_operand_projection_contract_v64(
                    consumer, item["operand_index"]
                )
                if existing is None:
                    self.operand_projection_contracts[contract_key] = rec
                    self.operand_projection_synthesized_contracts_v64[
                        contract_key
                    ] = rec
                    compiled.append(rec)
                    collision["participants"].append(dict(rec))
                elif (
                    str(existing.get("projection_name"))
                    == str(rec.get("projection_name"))
                    and self._normalize_stack_key_v64(existing.get("storage_key"))
                    == key
                ):
                    collision["participants"].append(dict(existing))

            if collision["participants"]:
                self.operand_projection_collision_events_v64.append(collision)
                self.operand_projection_consumption_events.append({
                    "kind": "joint_consumer_operand_projection_synthesized_v65",
                    "consumer_sid": consumer_sid,
                    "consumer_opcode": opcode,
                    "collision_name": collision_name,
                    "contracts": len(collision["participants"]),
                    "global_storage_projections": 0,
                    "global_sid_projections": 0,
                })

        self._operand_projection_compile_cache_v64[cache_key] = compiled
        return compiled

    def _validate_operand_projection_contract_v64(
        self, rec, value, consumer=None, operand_index=None,
    ):
        raw_hint = self._raw_operand_hint_v65(
            consumer, operand_index, fallback=None
        ) if consumer is not None else None
        evidence = self._resolve_stack_source_v64(
            value, raw_hint=raw_hint, consumer=consumer,
            operand_index=operand_index,
        )
        actual_sid = self._projection_sid_text_v64(value)
        raw_sid = self._projection_sid_text_v64(raw_hint)
        expected_sid = self._projection_sid_text_v64(rec.get("source_sid"))
        actual_key = evidence.get("storage_key") if evidence else None
        expected_key = self._normalize_stack_key_v64(rec.get("storage_key"))
        lineage = {
            str(sid) for sid in list((evidence or {}).get("lineage_sids", []) or [])
            if sid is not None
        }
        gates = {
            "storage_key_matches": bool(
                actual_key is not None and actual_key == expected_key
            ),
            "source_sid_matches": bool(
                expected_sid is not None
                and (
                    expected_sid == actual_sid
                    or expected_sid == raw_sid
                    or expected_sid in lineage
                )
            ),
            "projection_name_present": bool(rec.get("projection_name")),
        }
        return all(gates.values()), {
            "actual_source_sid": actual_sid,
            "actual_raw_source_sid": raw_sid,
            "expected_source_sid": expected_sid,
            "actual_storage_key": actual_key,
            "expected_storage_key": expected_key,
            "lineage_sids": sorted(lineage),
            "gates": gates,
        }

    def _operand_projection_for_v64(
        self,
        consumer,
        operand_index,
        value,
        renderer,
    ):
        rec, contract_key = self._lookup_operand_projection_contract_v64(
            consumer, operand_index
        )
        if rec is None:
            self._compile_local_consumer_projection_v64(consumer)
            rec, contract_key = self._lookup_operand_projection_contract_v64(
                consumer, operand_index
            )
        if not isinstance(rec, dict):
            return None

        valid, evidence = self._validate_operand_projection_contract_v64(
            rec, value, consumer=consumer, operand_index=operand_index
        )
        if not valid:
            failure = {
                "kind": "operand_projection_live_identity_mismatch_v64",
                "consumer_sid": self._projection_sid_text_v64(
                    self._consumer_output_v64(consumer)
                ),
                "consumer_opcode": getattr(consumer, "opcode", None),
                "operand_index": int(operand_index),
                "renderer": renderer,
                "contract": dict(rec),
                "evidence": evidence,
            }
            self._operand_projection_failures_v64.append(failure)
            raise RuntimeError(
                "PALSGL v65 exact operand projection identity mismatch: %s"
                % failure
            )

        name = str(rec.get("projection_name"))
        normalized_key = (
            self._projection_sid_text_v64(self._consumer_output_v64(consumer)),
            int(operand_index),
        )
        self._operand_projection_consumed_keys_v64.add(normalized_key)
        event = {
            "kind": "joint_consumer_operand_projection_consumed_v64",
            "consumer_sid": normalized_key[0],
            "consumer_opcode": getattr(consumer, "opcode", None),
            "operand_index": normalized_key[1],
            "source_sid": rec.get("source_sid"),
            "storage_key": self._normalize_stack_key_v64(
                rec.get("storage_key")
            ),
            "projection_name": name,
            "renderer": renderer,
            "producer": rec.get("producer") or "PALSemanticGraphBuilder",
            "contract_key": contract_key,
        }
        signature = (
            event["consumer_sid"], event["operand_index"], name, renderer
        )
        if not any(
            (
                item.get("consumer_sid"),
                item.get("operand_index"),
                item.get("projection_name"),
                item.get("renderer"),
            ) == signature
            for item in self.operand_projection_consumption_events
            if isinstance(item, dict)
        ):
            self.operand_projection_consumption_events.append(event)
        return name

    # Compatibility wrapper. v64 callers should pass the live operand.
    def _operand_projection_for_v63(self, consumer, operand_index):
        inputs = list(getattr(consumer, "inputs", []) or [])
        try:
            value = inputs[int(operand_index)]
        except Exception:
            return None
        return self._operand_projection_for_v64(
            consumer, operand_index, value, renderer="v63_compat"
        )

    def _state_update_owner_key_v64(self, node_or_op):
        output = self._consumer_output_v64(node_or_op)
        direct = self._concrete_stack_key_v64(output)
        if direct is not None:
            return direct

        output_sid = self._projection_sid_text_v64(output)
        if output_sid is None:
            return None

        phi_keys = set()
        candidates = []
        uses = getattr(self.func, "uses_by_sid", {}) or {}
        for key in self._projection_sid_variants_v64(output):
            try:
                candidates.extend(list(uses.get(key, []) or []))
            except Exception:
                pass
        for candidate in list(self._formula_nodes().values()):
            if getattr(candidate, "opcode", None) != "MULTIEQUAL":
                continue
            if any(
                self._projection_sid_text_v64(inp) == output_sid
                for inp in list(getattr(candidate, "inputs", []) or [])
            ):
                candidates.append(candidate)

        seen = set()
        for candidate in candidates:
            if id(candidate) in seen:
                continue
            seen.add(id(candidate))
            if getattr(candidate, "opcode", None) != "MULTIEQUAL":
                continue
            out = self._consumer_output_v64(candidate)
            key = self._concrete_stack_key_v64(out)
            if key is not None:
                phi_keys.add(key)
        return next(iter(phi_keys)) if len(phi_keys) == 1 else None

    def _node_is_self_update_alias_v64(self, node_or_op):
        if node_or_op is None:
            return False
        opcode = getattr(node_or_op, "opcode", None)
        if opcode not in ("INT_ADD", "INT_SUB"):
            return False
        inputs = list(getattr(node_or_op, "inputs", []) or [])
        if len(inputs) != 2:
            return False

        output = self._consumer_output_v64(node_or_op)
        raw_output = self._consumer_raw_output_v65(node_or_op)
        owner_key = (
            self._concrete_stack_key_v64(raw_output)
            or self._state_update_owner_key_v64(node_or_op)
        )
        output_name = self._legacy_var_expr_v64(output)
        text_matches = []
        input_keys = []

        raw_inputs = self._consumer_raw_inputs_v65(node_or_op)
        for index, operand in enumerate(inputs):
            if getattr(operand, "is_constant", False):
                continue
            raw_hint = raw_inputs[index] if index < len(raw_inputs) else None
            evidence = self._resolve_stack_source_v64(
                operand, raw_hint=raw_hint, consumer=node_or_op,
                operand_index=index,
            )
            key = evidence.get("storage_key") if evidence else None
            input_keys.append(key)
            if owner_key is not None and key == owner_key:
                return True
            if self._legacy_var_expr_v64(operand) == output_name:
                text_matches.append(self._projection_sid_text_v64(operand))

        # This is the precise v63 failure class: the old shortcut would have
        # accepted the update solely because names matched.  Record the reject
        # so parser/PHI diagnostics can show that storage custody overruled
        # presentation text.
        if text_matches:
            event = {
                "kind": "textual_self_update_alias_rejected_v64",
                "consumer_sid": self._projection_sid_text_v64(output),
                "consumer_opcode": opcode,
                "output_name": output_name,
                "output_storage_key": (
                    self._concrete_stack_key_v64(raw_output)
                    or self._concrete_stack_key_v64(output)
                ),
                "state_owner_key": owner_key,
                "matching_input_sids": list(text_matches),
                "input_storage_keys": list(input_keys),
                "reason": (
                    "rendered_name_equality_without_same_concrete_or_PHI_owned_"
                    "stack_state"
                ),
            }
            signature = (
                event["consumer_sid"],
                tuple(event["matching_input_sids"]),
                tuple(event["input_storage_keys"]),
            )
            if not any(
                (
                    item.get("consumer_sid"),
                    tuple(item.get("matching_input_sids", []) or []),
                    tuple(item.get("input_storage_keys", []) or []),
                ) == signature
                for item in self.operand_projection_collision_events_v64
                if isinstance(item, dict)
                and item.get("kind") == "textual_self_update_alias_rejected_v64"
            ):
                self.operand_projection_collision_events_v64.append(event)
        return False

    def _audit_binary_projection_render_v64(
        self,
        consumer,
        inputs,
        rendered,
        renderer,
    ):
        opcode = str(getattr(consumer, "opcode", "") or "")
        noncommutative = {
            "INT_SUB", "INT_DIV", "INT_SDIV", "INT_REM", "INT_SREM",
            "INT_LEFT", "INT_RIGHT", "INT_SRIGHT",
            "INT_LESS", "INT_SLESS", "INT_LESSEQUAL", "INT_SLESSEQUAL",
        }
        if opcode not in noncommutative or len(inputs) != 2:
            return

        snapshot_indexes = [
            index for index, value in enumerate(inputs)
            if isinstance(self._snapshot_contract_for_v66(value), dict)
        ]
        operand_sids = [
            self._projection_sid_text_v64(value) for value in inputs
        ]
        if (
            snapshot_indexes
            and len(set(str(sid) for sid in operand_sids)) > 1
            and str(rendered[0]) == str(rendered[1])
        ):
            failure = {
                "kind": "erase_emperor_snapshot_render_collision_v66",
                "consumer_sid": self._projection_sid_text_v64(
                    self._consumer_output_v64(consumer)
                ),
                "consumer_opcode": opcode,
                "renderer": renderer,
                "operand_sids": operand_sids,
                "snapshot_operand_indexes": snapshot_indexes,
                "rendered_operands": list(rendered),
                "reason": (
                    "protected temporal snapshot collapsed into a distinct "
                    "later SSA epoch at an order-sensitive consumer"
                ),
            }
            self.snapshot_copy_failures_v66.append(failure)
            raise RuntimeError(
                "PALSGL v66 erase-emperor render collision: %s" % failure
            )

        raw_inputs = self._consumer_raw_inputs_v65(consumer)
        evidence = [
            self._resolve_stack_source_v64(
                value,
                raw_hint=(raw_inputs[index] if index < len(raw_inputs) else None),
                consumer=consumer,
                operand_index=index,
            )
            for index, value in enumerate(inputs)
        ]
        if any(item is None for item in evidence):
            return
        keys = [item.get("storage_key") for item in evidence]
        if keys[0] == keys[1]:
            return
        if str(rendered[0]) != str(rendered[1]):
            return
        failure = {
            "kind": "noncommutative_distinct_operand_render_collision_v64",
            "consumer_sid": self._projection_sid_text_v64(
                self._consumer_output_v64(consumer)
            ),
            "consumer_opcode": opcode,
            "renderer": renderer,
            "operand_sids": [
                self._projection_sid_text_v64(v) for v in inputs
            ],
            "storage_keys": keys,
            "rendered_operands": list(rendered),
            "reason": (
                "distinct concrete stack operands remain textually equal "
                "after exact-consumer projection"
            ),
        }
        self._operand_projection_failures_v64.append(failure)
        self.operand_projection_collision_events_v64.append(dict(failure))
        raise RuntimeError(
            "PALSGL v66 noncommutative operand custody failed: %s" % failure
        )

    def _formula_contains_projection_contract_v64(self, node, seen=None):
        if node is None:
            return False
        if seen is None:
            seen = set()
        sid = self._projection_sid_text_v64(self._consumer_output_v64(node))
        marker = (sid, id(node))
        if marker in seen:
            return False
        seen.add(marker)
        inputs = list(getattr(node, "inputs", []) or [])
        for index in range(len(inputs)):
            rec, _key = self._lookup_operand_projection_contract_v64(node, index)
            if isinstance(rec, dict):
                return True
        for operand in inputs:
            child = self._formula_node_for_value_v64(operand)
            if child is not None and self._formula_contains_projection_contract_v64(
                child, seen
            ):
                return True
        return False

    def _refresh_edge_projection_expr_v64(self, src, rec, current_expr):
        if not self._metadata_record_is_canonical_edge_truth_v40(rec):
            return current_expr
        invert_for_edge = rec.get("invert_for_edge")
        if not isinstance(invert_for_edge, bool):
            # v72: projection refresh may update expression identity, never
            # manufacture predicate orientation from unresolved tri-state.
            return current_expr
        node = self._condition_formula_node(src)
        if node is None:
            return current_expr

        # Compile locally before asking whether the dependency cone is covered.
        work = [node]
        seen = set()
        while work:
            current = work.pop()
            if current is None or id(current) in seen:
                continue
            seen.add(id(current))
            self._compile_local_consumer_projection_v64(current)
            for operand in list(getattr(current, "inputs", []) or []):
                child = self._formula_node_for_value_v64(operand)
                if child is not None:
                    work.append(child)

        has_operand_projection = self._formula_contains_projection_contract_v64(
            node
        )
        has_snapshot_boundary = self._formula_contains_snapshot_contract_v66(
            node
        )
        has_derived_boundary = (
            self._formula_contains_null_emperor_boundary_v67(node)
        )
        if not (
            has_operand_projection
            or has_snapshot_boundary
            or has_derived_boundary
        ):
            return current_expr

        corrected_hf = self._formula_expr(node)
        if not corrected_hf:
            return current_expr
        corrected_edge = (
            "not (%s)" % corrected_hf
            if invert_for_edge
            else corrected_hf
        )
        if str(corrected_edge) == str(current_expr):
            return current_expr

        event_kind = (
            "edge_condition_null_emperor_derived_boundary_refreshed_v67"
            if has_derived_boundary
            else (
                "edge_condition_erase_emperor_snapshot_refreshed_v66"
                if has_snapshot_boundary
                else "edge_condition_exact_operand_projection_refreshed_v65"
            )
        )
        event = {
            "kind": event_kind,
            "src": self._addr_v26(src),
            "condition_sid": rec.get("condition_sid"),
            "condition_opcode": rec.get("condition_opcode"),
            "old_hf_expr": rec.get("hf_expr"),
            "old_edge_expr": current_expr,
            "new_hf_expr": corrected_hf,
            "new_edge_expr": corrected_edge,
            "invert_for_edge": invert_for_edge,
            "authority": (
                "canonical_EdgeTruth_polarity_plus_live_formula_exact_operand_"
                "projection"
            ),
        }
        signature = (
            event["src"], event["new_edge_expr"], event["invert_for_edge"]
        )
        if not any(
            (
                item.get("src"),
                item.get("new_edge_expr"),
                item.get("invert_for_edge"),
            ) == signature
            for item in self.operand_projection_metadata_refresh_events_v64
        ):
            self.operand_projection_metadata_refresh_events_v64.append(event)
            self._metadata_record_event_v26(
                event_kind,
                **{k: v for k, v in event.items() if k != "kind"}
            )
        return corrected_edge

    def _audit_operand_projection_custody_v64(self):
        contracts = [
            dict(rec) for rec in self.operand_projection_contracts.values()
            if isinstance(rec, dict)
        ]
        failures = list(self._operand_projection_failures_v64)
        audit = {
            "kind": (
                "sgl_exact_operand_projection_custody_verified_v65"
                if not failures else
                "sgl_exact_operand_projection_custody_failed_v65"
            ),
            "version": self.sgl_version,
            "active": bool(contracts),
            "input_and_synthesized_contracts": len(contracts),
            "synthesized_contracts": len(
                self.operand_projection_synthesized_contracts_v64
            ),
            "consumed_contract_keys": sorted(
                self._operand_projection_consumed_keys_v64, key=str
            ),
            "consumption_events": len(
                self.operand_projection_consumption_events
            ),
            "collision_events": len(
                self.operand_projection_collision_events_v64
            ),
            "edge_predicates_refreshed": len(
                self.operand_projection_metadata_refresh_events_v64
            ),
            "raw_operand_storage_evidence_consumed_v65": len(
                self.operand_projection_raw_evidence_events_v65
            ),
            "global_storage_projection_reads": 0,
            "global_sid_projection_reads": 0,
            "failures": failures,
            "acceptance_gate": (
                "exact consumer and operand identity must match live stack "
                "evidence; distinct noncommutative operands may not freeze "
                "to one textual name"
            ),
        }
        self.operand_projection_custody_audit_v64 = audit
        self.operand_projection_consumption_events.append(dict(audit))
        if failures:
            raise RuntimeError(
                "PALSGL v65 exact operand projection audit failed: %s"
                % failures
            )
        return audit

    def _storage_projection_for_v63(self, value):
        """Compatibility no-op: v64 forbids global projection in _var_expr."""
        return None

    def _cond_expr_raw(self, cfg_node):
        """
        Render the raw condition formula for a CFG conditional block.

        Unlike _cond_expr(), this is allowed to reconstruct the condition
        directly from the block's own ops if the semantic formula graph lookup
        cannot resolve the condition SSA temp. This is what prevents output
        such as v_295/v_348/v_392 in composite short-circuit conditions.
        """

        cond = self._get_condition(cfg_node)

        if cond is None:
            return None

        # Prefer semantic graph node when available.
        node = self._condition_formula_node(cfg_node)
        if node is not None:
            expr = self._formula_expr(node)
            if expr and not self._looks_like_unexpanded_condition_tmp(expr):
                return expr

        # Fallback: reconstruct from block-local op chain ending at cond.
        expr = self._block_local_expr_for_var(cfg_node, cond, seen=set())
        if expr:
            return expr

        return self._var_expr(cond)

    def _looks_like_unexpanded_condition_tmp(self, expr):
        if expr is None:
            return True

        s = str(expr)

        if s.startswith("v_") and all(ch.isalnum() or ch == "_" for ch in s):
            return True

        return False

    def _block_local_expr_for_var(self, cfg_node, var, seen=None):
        """
        Render expression for var by following definitions inside cfg_node.block.ops.

        This is intentionally local to the condition block; it does not inline
        calls from predecessor blocks. It is safe for conditions such as:
            v_263 = v_2683 & 1
            v_295 = v_263 == 0
        """

        if seen is None:
            seen = set()

        if var is None:
            return None

        if getattr(var, "is_constant", False):
            return self._const_expr(var)

        sid = getattr(var, "ssa_id", None)

        if sid is not None:
            if sid in seen:
                return self._var_expr(var)
            seen.add(sid)

        op = self._find_block_def_op(cfg_node, var)

        if op is None:
            return self._var_expr(var)

        return self._block_local_expr_for_op(cfg_node, op, seen)

    def _find_block_def_op(self, cfg_node, var):
        block = getattr(cfg_node, "block", None)

        if block is None:
            return None

        sid = getattr(var, "ssa_id", None)

        for op in list(getattr(block, "ops", []) or []):
            out = getattr(op, "output", None)

            if out is None:
                continue

            if sid is not None and getattr(out, "ssa_id", None) == sid:
                return op

            if out is var:
                return op

        return None

    def _block_local_expr_for_op(self, cfg_node, op, seen):
        opcode = getattr(op, "opcode", None)
        inputs = list(getattr(op, "inputs", []) or [])

        if opcode == "COPY":
            snapshot = self._snapshot_render_boundary_v66(
                op, "block_local_copy"
            )
            if snapshot is not None:
                return snapshot
        if opcode in ("COPY", "CAST", "INT_ZEXT", "INT_SEXT", "TRUNC") and inputs:
            return self._block_local_expr_for_var(cfg_node, inputs[0], seen)

        binops = {
            "INT_ADD": "+",
            "INT_SUB": "-",
            "INT_MULT": "*",
            "INT_DIV": "//",
            "INT_SDIV": "//",
            "INT_REM": "%",
            "INT_SREM": "%",
            "INT_AND": "&",
            "INT_OR": "|",
            "INT_XOR": "^",
            "INT_LEFT": "<<",
            "INT_RIGHT": ">>",
            "INT_SRIGHT": ">>",
            "INT_EQUAL": "==",
            "INT_NOTEQUAL": "!=",
            "INT_LESS": "<",
            "INT_SLESS": "<",
            "INT_LESSEQUAL": "<=",
            "INT_SLESSEQUAL": "<=",
        }

        if opcode in binops and len(inputs) == 2:
            a = self._block_local_value_expr(
                cfg_node, inputs[0], seen.copy(),
                consumer=op, operand_index=0,
            )
            b = self._block_local_value_expr(
                cfg_node, inputs[1], seen.copy(),
                consumer=op, operand_index=1,
            )
            self._audit_binary_projection_render_v64(
                op, inputs, (a, b), "block_local"
            )
            return "(%s %s %s)" % (a, binops[opcode], b)

        if opcode == "BOOL_NEGATE" and inputs:
            a = self._block_local_value_expr(cfg_node, inputs[0], seen.copy(), consumer=op, operand_index=0)
            return "not (%s)" % a

        if opcode in ("CALL", "CALLIND"):
            # Do not inline calls here unless the call is local to this block
            # and unavoidable. Conditions in this test do not require it.
            out = getattr(op, "output", None)
            return self._var_expr(out)

        out = getattr(op, "output", None)
        return self._var_expr(out)

    def _block_local_value_expr(self, cfg_node, v, seen, consumer=None, operand_index=None):
        if v is None:
            return "None"
        derived = self._null_emperor_render_boundary_v67(
            v, "block_local_value"
        )
        if derived is not None:
            return derived
        snapshot = self._snapshot_render_boundary_v66(
            v, "block_local_value"
        )
        if snapshot is not None:
            return snapshot
        if consumer is not None and operand_index is not None:
            projected = self._operand_projection_for_v64(
                consumer,
                operand_index,
                v,
                renderer="block_local",
            )
            if projected:
                return projected

        if getattr(v, "is_constant", False):
            return self._const_expr(v)

        op = self._find_block_def_op(cfg_node, v)
        if op is not None:
            opcode = getattr(op, "opcode", None)

            if opcode in ("CALL", "CALLIND"):
                return self._var_expr(getattr(op, "output", v))

            # v64: text equality is not state identity.  Shorten only when
            # the output's direct/PHI-owned stack cell is the same concrete
            # cell as one nonconstant input.
            out = getattr(op, "output", None)
            if out is not None and self._node_is_self_update_alias_v64(op):
                return self._legacy_var_expr_v64(out)

            return self._block_local_expr_for_op(cfg_node, op, seen)

        return self._var_expr(v)


    def _cond_expr(self, cfg_node):
        cond = self._get_condition(cfg_node)

        if cond is None:
            return None

        node = self._condition_formula_node(cfg_node)

        if node is not None:
            expr = self._formula_expr(node)
            if expr and not self._looks_like_unexpanded_condition_tmp(expr):
                return expr

        return self._cond_expr_raw(cfg_node)

    def _formula_expr(self, node):
        if node is None:
            return None

        derived = self._null_emperor_render_boundary_v67(
            node, "formula_node"
        )
        if derived is not None:
            return derived

        opcode = getattr(node, "opcode", None)
        inputs = list(getattr(node, "inputs", []) or [])

        if opcode == "COPY":
            snapshot = self._snapshot_render_boundary_v66(
                node, "formula_copy"
            )
            if snapshot is not None:
                return snapshot
        if opcode in ("COPY", "CAST", "INT_ZEXT", "INT_SEXT", "TRUNC") and inputs:
            src_node = self._node_for_var(inputs[0])
            if src_node is not None:
                return self._formula_expr(src_node)
            return self._var_expr(inputs[0])

        binops = {
            "INT_ADD": "+",
            "INT_SUB": "-",
            "INT_MULT": "*",
            "INT_DIV": "//",
            "INT_SDIV": "//",
            "INT_REM": "%",
            "INT_SREM": "%",
            "INT_AND": "&",
            "INT_OR": "|",
            "INT_XOR": "^",
            "INT_LEFT": "<<",
            "INT_RIGHT": ">>",
            "INT_SRIGHT": ">>",
            "INT_EQUAL": "==",
            "INT_NOTEQUAL": "!=",
            "INT_LESS": "<",
            "INT_SLESS": "<",
            "INT_LESSEQUAL": "<=",
            "INT_SLESSEQUAL": "<=",
        }

        if opcode in binops and len(inputs) == 2:
            a = self._value_expr(
                inputs[0], consumer=node, operand_index=0
            )
            b = self._value_expr(
                inputs[1], consumer=node, operand_index=1
            )
            self._audit_binary_projection_render_v64(
                node, inputs, (a, b), "formula"
            )
            return "(%s %s %s)" % (a, binops[opcode], b)

        if opcode == "BOOL_NEGATE" and inputs:
            return "not (%s)" % self._value_expr(inputs[0], consumer=node, operand_index=0)

        if opcode in ("CALL", "CALLIND"):
            # v19/PALRAW: never inline side-effectful calls into branch
            # conditions.  The call result should already have been emitted
            # as an SSA/temp/local assignment, e.g. v_1736 = feedback(...).
            return self._var_expr(getattr(node, "var", None))

        return self._var_expr(getattr(node, "var", None))

    def _value_expr(self, v, consumer=None, operand_index=None):
        derived = self._null_emperor_render_boundary_v67(
            v, "formula_value"
        )
        if derived is not None:
            return derived
        snapshot = self._snapshot_render_boundary_v66(v, "formula_value")
        if snapshot is not None:
            return snapshot
        if consumer is not None and operand_index is not None:
            projected = self._operand_projection_for_v64(
                consumer,
                operand_index,
                v,
                renderer="formula",
            )
            if projected:
                return projected
        node = self._node_for_var(v)

        if node is not None:
            opcode = getattr(node, "opcode", None)

            # v19: never inline call results into expressions; this prevents
            # condition rendering from re-calling feedback()/mutate().
            if opcode in ("CALL", "CALLIND"):
                return self._var_expr(getattr(node, "var", v))

            # v19: if a formula node represents an already-materialized
            # state update, use the canonical output name rather than
            # re-expanding it.  This prevents emitted tails like:
            #     local_14 += 1
            #     if 4 < (local_14 + 1):
            if self._node_is_self_update_alias(node):
                return self._var_expr(getattr(node, "var", v))

            return self._formula_expr(node)

        return self._var_expr(v)

    def _node_is_self_update_alias(self, node):
        """Storage/PHI-proven state-update shortening only.

        v63 and older accepted textual equality between the output and one
        input.  That is unsafe when resolver/PHI presentation maps distinct
        stack cells to the same local name.  v64 delegates to concrete output
        or unique PHI-target storage ownership.
        """
        return self._node_is_self_update_alias_v64(node)

    def _node_for_var(self, v):
        if v is None:
            return None

        sid = getattr(v, "ssa_id", None)

        if sid is None:
            return None

        return self._formula_nodes().get(sid)

    def _var_expr(self, v):
        # v64: exact projections are consumed only at
        # (consumer SID, operand index).  Never apply a storage- or SID-wide
        # projection from generic variable rendering.
        return self._legacy_var_expr_v64(v)

    def _const_expr(self, v):
        for attr in ("const_value", "value", "offset"):
            val = getattr(v, attr, None)
            if val is not None:
                try:
                    if isinstance(val, int) and abs(val) >= 10:
                        return hex(val)
                except Exception:
                    pass
                return str(val)

        return "0"


    def _get_loop_body(self, header):
        """
        Pick a loop-internal successor.
        """

        guard_body = self._loop_guard_chain_body(header)
        if guard_body is not None:
            return guard_body

        nodes = self.loop_nodes.get(header, set())

        for e in getattr(header, "out_edges", []):

            dst = getattr(e, "dst", None)

            if dst is None:
                continue

            if dst in nodes and dst is not header:
                return dst

        for e in getattr(header, "out_edges", []):

            dst = getattr(e, "dst", None)

            if dst is not None and self._reaches(dst, header):
                return dst

        return None

    def _get_loop_exits(self, header):
        """
        Return all natural-loop exits. Multiple exits are common in lowered
        do/while and short-circuit loops.
        """

        exits = set(self.loop_exits.get(header, set()) or set())

        if exits:
            return exits

        out = set()

        for e in getattr(header, "out_edges", []):

            dst = getattr(e, "dst", None)

            if dst is not None and not self._reaches(dst, header):
                out.add(dst)

        return out

    def _get_loop_normal_exits(self, header):
        normals = set(self.loop_normal_exits.get(header, set()) or set())

        # v27: GraphBuilder may know that some loop exits are shared
        # continuation/gateway blocks.  Add them to normal exits so they are
        # emitted after the loop rather than swallowed as branch-local action
        # by an inner conditional-latch test.
        for n in self._metadata_loop_continuation_gateway_nodes_v27(header):
            if n is not None:
                normals.add(n)

        # v32: even when GraphBuilder did not pre-label the gateway, CFG/ipdom
        # structure can show that an exit target is a shared continuation of an
        # enclosing region.  Treat such targets as normal loop exits so they are
        # emitted immediately after the nested loop, not consumed by a break arm.
        hnodes = set(self.loop_nodes.get(header, set()) or set())
        for ex in list(self._get_loop_exits(header) or set()):
            for pred in list(self._predecessors(ex) or []):
                if pred not in hnodes:
                    continue
                if self._structural_target_is_continuation_gateway_v32(
                    ex,
                    owner_loop=header,
                    from_node=pred,
                ):
                    normals.add(ex)
                    break

        if normals:
            return normals

        return self._get_loop_exits(header)


    def _get_loop_exit(self, header):
        exits = self._get_loop_exits(header)

        if not exits:
            return None

        return self._ordered_nodes(exits)[0]

    def _single_exit_header_condition_is_exit_test(self, header):
        """
        Decide whether a single-exit loop header condition is an exit test
        or a continue/body test.

        v16 unconditionally returned not(raw_cond), which inverted alpha_four
        0x10124a:
            INT_SLESS [local_18, 1]
            true  -> body
            false -> loop exit

        That condition is a continue/body test and should be emitted raw.

        Conservative rule:
          - const < var forms are usually guard/exit tests in these GCC/O0
            do/while tails, so invert them.
          - var < const forms are usually body tests, so keep raw.
          - If CFG metadata says the true edge is loop_exit and false is body,
            also treat as exit test.
        """

        cond_node = self._condition_formula_node(header)

        if cond_node is None:
            return False

        opcode = getattr(cond_node, "opcode", None)
        inputs = list(getattr(cond_node, "inputs", []) or [])

        true_node = self._true_edge(header)
        false_node = self._false_edge(header)

        true_exits = self._edge_exits_loop(header, true_node) is header
        false_exits = self._edge_exits_loop(header, false_node) is header

        if true_exits and not false_exits:
            return True

        if false_exits and not true_exits:
            # Prefer formula polarity for less-than forms below.
            pass

        if opcode in ("INT_LESS", "INT_SLESS", "INT_LESSEQUAL", "INT_SLESSEQUAL"):
            if len(inputs) == 2:
                left, right = inputs[0], inputs[1]
                left_const = bool(getattr(left, "is_constant", False))
                right_const = bool(getattr(right, "is_constant", False))

                if left_const and not right_const:
                    return True

                if not left_const and right_const:
                    return False

        return False


    def _get_loop_condition_for_header(self, header):
        """
        Backward-compatible condition-only API.
        """
        cond, role = self._get_loop_condition_and_role_for_header(header)
        return cond

    def _get_loop_condition_and_role_for_header(self, header):
        """
        Return (condition, condition_role) for an ExecLoop.

        Roles:
            true -> emit while True
            body -> emit while condition
            exit -> emit while not(condition)

        v20b invariant:
            body predicates must admit the loop body.
            exit predicates must describe loop exit.
        """

        def done(cond, role):
            return self._normalize_loop_condition_role_v20(header, cond, role)

        chained = self._loop_guard_chain_condition(header)
        if chained is not None:
            # Guard chains represent loop-exit disjunctions.
            return done(chained, "exit")

        if header in self.loop_single_exit_tests:
            body_cond = self._condition_for_loop_body_edge(header)
            if body_cond is not None:
                return done(body_cond, "body")

            exit_cond = self._condition_for_loop_exit_edge(header)
            if exit_cond is not None:
                return done(exit_cond, "exit")

            raw = self._cond_expr_raw(header)

            if self._single_exit_header_condition_is_exit_test(header):
                return done(RawCond(raw, reason="v20_single_exit_header_exit_predicate"), "exit")

            return done(RawCond(raw, reason="v20_single_exit_header_body_predicate"), "body")

        if header in self.loop_body_headers:
            return done(None, "true")

        cond = self._get_condition(header)
        if cond is None:
            return done(None, "true")

        body_node = self._first_body_node_for_header_v19b(header)
        explicit_target = self._true_edge(header)

        if explicit_target is not None and body_node is not None:
            if explicit_target is body_node:
                return done(cond, "body")
            return done(cond, "exit")

        return done(cond, "body")

    def _first_body_node_for_header_v19b(self, header):
        if header is None:
            return None

        nodes = set(self.loop_nodes.get(header, set()) or set())
        nodes.discard(header)

        if not nodes:
            return None

        for succ in list(getattr(header, "successors", []) or []):
            if succ in nodes:
                return succ

        ordered = self._ordered_nodes(nodes)
        return ordered[0] if ordered else None


    def _ordered_nodes(self, nodes):
        return sorted(
            [n for n in nodes if n is not None],
            key=lambda n: getattr(n, "addr", 0) if isinstance(getattr(n, "addr", 0), int) else 0,
        )


    def _edge_role_pair_is_raw_locked(self, node, true_node, false_node):
        """
        v19: raw CFG custody outranks expression-shape repair heuristics.

        If PALlibrary provided one raw_true_explicit_target edge and one
        raw_false_fallthrough edge, the then/else orientation is already
        grounded in the CBRANCH target. SGL may still prettify the expression
        later, but it must not swap branch bodies here.
        """
        if node is None or true_node is None or false_node is None:
            return False

        true_role = None
        false_role = None

        for e in self._as_list(getattr(node, "out_edges", None)):
            dst = getattr(e, "dst", None)
            role = getattr(e, "role", None)
            raw = getattr(e, "raw_type", None)

            if dst is true_node:
                true_role = role or raw
            elif dst is false_node:
                false_role = role or raw

        if true_role == "raw_true_explicit_target" and false_role == "raw_false_fallthrough":
            return True

        # Some PALlibrary versions expose flags rather than role strings.
        true_explicit = False
        false_fallthrough = False
        for e in self._as_list(getattr(node, "out_edges", None)):
            dst = getattr(e, "dst", None)
            if dst is true_node:
                true_explicit = bool(getattr(e, "explicit_target", False) or getattr(e, "is_explicit_target", False))
            elif dst is false_node:
                false_fallthrough = bool(getattr(e, "fallthrough", False) or getattr(e, "is_fallthrough", False))

        return true_explicit and false_fallthrough

    def _get_if_branches(self, node):
        """
        Return then/else/join for a conditional node.

        Baseline:
            use CFG true/false labels.

        Then repair only narrow, observed polarity mistakes.
        """

        term = getattr(node.block, "terminator", None)

        if not term or getattr(term, "opcode", None) != "CBRANCH":
            return None, None, None

        join = getattr(node, "ipdom", None)

        true_node = self._true_edge(node)
        false_node = self._false_edge(node)

        mode = "cfg_true_false"

        if true_node is None and false_node is None:
            explicit = self._explicit_branch_successor(node, term)
            fallthrough = self._fallthrough_successor(node, explicit)
            true_node, false_node = explicit, fallthrough
            mode = "explicit_true"

        # v19/PALRAW:
        # Edge ownership remains raw-CFG based.  Polarity repair is now
        # condition-side, not body-swap-side, when PALlibrary exposes raw
        # condition polarity.
        if self._edge_role_pair_is_raw_locked(node, true_node, false_node):
            then_node, else_node, reason = true_node, false_node, "raw_edge_locked"
        else:
            then_node, else_node, reason = self._repair_branch_polarity(
                node,
                true_node,
                false_node,
                join,
            )

        if reason:
            mode += "+" + reason

        self._record_branch_event(node, term, then_node, else_node, join, mode)

        return then_node, else_node, join

    # ----------------------------------------------------------------

    def _loop_internal_notequal_should_keep_raw_v45(self, node, true_node, false_node):
        """
        v45: Do not apply switch/default INT_NOTEQUAL body-swap heuristics to
        loop-internal conditional latch/break tests.

        The old rule D was built for lowered switch dispatch:

            if x != 1: default/action
            else:      case-1 conditional

        It swaps when the raw true edge is conditional and the false edge is an
        action block.  In alpha_four O0, the inner mutate loop also has an
        INT_NOTEQUAL terminal condition where one successor is a post-loop / loop
        exit continuation and the peer remains inside the inner loop.  Swapping
        those arms changes:

            if v != 0xf: break

        into:

            if not(v != 0xf): break

        This guard keeps raw CFG true/false orientation whenever an INT_NOTEQUAL
        block is inside a loop and its two successors split between "stay in this
        innermost loop" and "leave this innermost loop".  It is generic: no
        address or constant is mentioned.
        """
        if node is None or true_node is None or false_node is None:
            return False

        owner = self._innermost_loop_for_node(node)
        if owner is None:
            return False

        def stays(t):
            if t is None:
                return False
            if t is owner:
                return True
            try:
                if self._edge_continues_loop(node, t) is owner:
                    return True
            except Exception:
                pass
            try:
                return t in set(self.loop_nodes.get(owner, set()) or set())
            except Exception:
                return False

        def leaves(t):
            if t is None:
                return False
            try:
                if self._edge_exits_loop(node, t) is owner:
                    return True
            except Exception:
                pass
            return not stays(t)

        true_stays = stays(true_node)
        false_stays = stays(false_node)
        true_leaves = leaves(true_node)
        false_leaves = leaves(false_node)

        return bool((true_stays and false_leaves) or (false_stays and true_leaves))

    def _repair_branch_polarity(self, node, true_node, false_node, join):
        """
        Narrow branch-polarity repairs.

        These rules are local and conservative. They avoid duplication and
        preserve the original stable traversal behavior.
        """

        if true_node is None or false_node is None:
            return true_node, false_node, None

        cond_node = self._condition_formula_node(node)
        opcode = getattr(cond_node, "opcode", None)
        # v46: condition nodes can be rewritten/aliased by PHI/post-update
        # metadata so the direct formula object may no longer expose the
        # original comparison opcode.  Fall back to the block-level condition
        # opcode extractor before applying branch-body repair heuristics.
        if not opcode:
            opcode = self._condition_opcode_for_cfg_node_v19(node)
        if opcode is not None:
            opcode = str(opcode).upper()

        # A. Skip-to-join pattern:
        #      if cond: goto join
        #      else: action
        #
        # Older SGL builds inverted this into "if cond: action", which destroys
        # programmatic truth for cases like alpha_four's optional swap:
        #      true  -> latch/tail join
        #      false -> swap action
        #
        # Keep CFG edge truth. The true arm may be empty/fallthrough; the false
        # arm must still emit if it has executable operations.
        if join is not None and true_node is join and false_node is not join:
            return true_node, false_node, "keep_true_join_skip"

        # B. v19: retired unsafe swap_const_less_var body swap.
        #
        # Constant-less-than-variable expressions such as:
        #
        #     INT_SLESS [0xffffffff, local_20]
        #
        # may look like loop-exit/skip tests, but the raw CBRANCH target already
        # defines which successor is true. Swapping branch bodies here inverts
        # execution at blocks such as 0x10125c. Any later "prettification" must
        # rewrite/negate the condition expression, not exchange then/else arms.
        if opcode in ("INT_LESS", "INT_SLESS", "INT_LESSEQUAL", "INT_SLESSEQUAL"):
            inputs = list(getattr(cond_node, "inputs", []) or [])

            if len(inputs) == 2:
                left, right = inputs[0], inputs[1]

                if getattr(left, "is_constant", False) and not getattr(right, "is_constant", False):
                    return true_node, false_node, "keep_const_less_var_raw"

        # C0. Range-ladder contradiction repair:
        #
        #    if x < 4:
        #        action
        #    else:
        #        if x < 2:    # unreachable under x >= 4
        #            ...
        #
        # This appears in GCC/O0 lowered switch/fallthrough regions. The
        # nested stricter less-than under the false arm would make an entire
        # branch disappear. Swap the parent so the stricter test is inside the
        # looser range arm:
        #
        #    if x < 4:
        #        if x < 2:
        #            ...
        #    else:
        #        action
        #
        # This is deliberately limited to same-value var<const tests with a
        # smaller constant in the conditional false arm.
        if (
            opcode in ("INT_LESS", "INT_SLESS", "INT_LESSEQUAL", "INT_SLESSEQUAL")
            and self._is_conditional_node(false_node)
            and not self._is_conditional_node(true_node)
            and self._is_stricter_less_test_on_same_value(cond_node, false_node)
        ):
            return false_node, true_node, "swap_range_ladder_stricter_false"

        # C. Switch/range tree repair:
        #    if v_1460 < 3:
        #       continue testing cases 0/1
        #    else:
        #       default action
        #
        # Content-based fallback: in this GCC/O0 tree the default action block
        # is INT_LEFT(acc, 1). If the true edge goes to INT_LEFT and the false
        # edge continues to another condition, swap.
        if opcode in ("INT_LESS", "INT_SLESS") or self._block_has_opcode(true_node, "INT_LEFT"):
            true_is_cond = self._is_conditional_node(true_node)
            false_is_cond = self._is_conditional_node(false_node)

            if self._block_has_opcode(true_node, "INT_LEFT") and false_is_cond:
                return false_node, true_node, "swap_less_default_left"

            if not true_is_cond and false_is_cond:
                if self._conditions_probably_share_dispatch(cond_node, false_node):
                    return false_node, true_node, "swap_less_dispatch_cond"

            if true_is_cond and not false_is_cond:
                if self._conditions_probably_share_dispatch(cond_node, true_node):
                    return true_node, false_node, "keep_less_dispatch_cond"

        # v45: INT_NOTEQUAL also appears in loop-internal latch/break
        # tests.  In that shape, rule D's dispatch-oriented body swap can invert
        # the break predicate.  If one successor remains in the innermost loop
        # and the peer leaves it, raw CFG edge orientation is the safer truth.
        if opcode == "INT_NOTEQUAL" and self._loop_internal_notequal_should_keep_raw_v45(node, true_node, false_node):
            return true_node, false_node, "keep_notequal_loop_internal_raw_v46"

        # D. switch x != 1:
        #    if x != 1: default
        #    else: case-1 check_bit path
        #
        # The default block is INT_LEFT(acc, 1). If false goes to that default
        # and true goes to check_bit, swap so the emitted condition x != 1
        # enters default.
        if opcode == "INT_NOTEQUAL" or self._block_has_opcode(false_node, "INT_LEFT"):
            if self._block_has_opcode(false_node, "INT_LEFT") and self._is_conditional_node(true_node):
                return false_node, true_node, "swap_notequal_default_left"

            if self._is_conditional_node(true_node) and not self._is_conditional_node(false_node):
                return false_node, true_node, "swap_notequal_cond_action"

        # E-1/E0 retired in v19.
        #
        # v16 used a broad "negative action vs dispatch" heuristic here:
        #     false branch has add-negative, true branch is conditional
        # and swapped the CFG arms.
        #
        # That broke alpha_four 0x1011c3. The CFG/P-code branch truth is:
        #     INT_EQUAL == 0
        #     true  -> dispatch block 0x101206
        #     false -> negative-update block 0x101200
        #
        # SGL must not rewrite branch polarity merely because one arm contains
        # a negative add. If source-like structure wants the opposite, that is
        # a presentation concern above ground execution, not SGL truth.
        #
        # Keep the old cases documented, but do not fire them.
        if False and self._block_has_add_negative(false_node) and self._is_conditional_node(true_node):
            return false_node, true_node, "swap_negative_action_vs_dispatch_disabled_v19"

        if False and opcode == "INT_EQUAL":
            if self._block_has_add_negative(false_node) and self._is_conditional_node(true_node):
                return false_node, true_node, "swap_equal_negative_continue_disabled_v19"

            if self._path_has_add_negative_before_join(false_node, join) and self._is_conditional_node(true_node):
                return false_node, true_node, "swap_equal_negative_continue_path_disabled_v19"

        # E. check_bit(acc, 3) lowered as check_bit == 0:
        #    source truth:
        #       if check_bit: acc -= 5
        #       else: acc = transform_a(acc)
        #    lowered condition ==0 means true edge is else-source path.
        #    Keep executable truth for the emitted condition v_2712 == 0:
        #       true -> transform_a
        #       false -> subtract
        #    Therefore no swap if true is transform_a and false is add(-5).
        #    But if opposite is detected, swap.
        if opcode == "INT_EQUAL" and self._is_checkbit_eq_zero(cond_node):
            true_call = self._block_has_call_named(true_node, "transform_a")
            false_sub = self._block_has_add_negative(false_node)

            if not (true_call and false_sub):
                false_call = self._block_has_call_named(false_node, "transform_a")
                true_sub = self._block_has_add_negative(true_node)

                if false_call and true_sub:
                    return false_node, true_node, "swap_checkbit_eq0"

        # F. Parity ternary:
        #    condition (i & 1) == 0 should pick transform_b(acc), not
        #    transform_a(i). Use content-based detection so this still works if
        #    formula-node lookup fails.
        if opcode == "INT_EQUAL" or (
            self._block_has_call_named(true_node, "transform_a") and
            self._block_has_call_named(false_node, "transform_b")
        ):
            true_a = self._block_has_call_named(true_node, "transform_a")
            false_b = self._block_has_call_named(false_node, "transform_b")

            if true_a and false_b:
                return false_node, true_node, "swap_parity_ternary_content"

        # G. final state update:
        #    if state == 7: acc -= 100
        #    in CFG true may go to join and false to subtract block.
        #    If false action is negative add and true is join, handled by A.
        #    Extra guard: if true is join-like predecessor and false has
        #    negative add, swap.
        if opcode == "INT_EQUAL":
            if join is not None and self._block_has_add_negative(false_node):
                if true_node is join or self._reaches(true_node, join):
                    return false_node, true_node, "swap_equal_negative_action"

        return true_node, false_node, None

    # =========================================================================
    # v73 EXACT LOOP-EDGE ROLE CUSTODY
    # =========================================================================

    def _loop_edge_key_v73(self, src, dst):
        """Return the JSON-safe exact CFG edge identity used by v73."""
        return [self._addr_v26(src), self._addr_v26(dst)]

    def _record_loop_edge_role_event_v73(self, kind, **fields):
        event = {"kind": kind, "version": self.ingenious_emperor_version_v73}
        event.update(fields)
        key = (
            kind,
            event.get("header"),
            tuple(event.get("continue_edge_key") or []),
            tuple(event.get("exit_edge_key") or []),
            event.get("phase"),
            event.get("reason"),
        )
        if key not in self._loop_edge_role_event_keys_v73:
            self._loop_edge_role_event_keys_v73.add(key)
            self.loop_edge_role_events_v73.append(event)
        return event

    def _loop_header_edge_roles_v73(self, header):
        """
        Return the exact (body successor, exit successor) for a simple pre-test
        loop header, or ``(None, None, reason)``.

        Natural-loop membership owns these roles.  True/false labels and
        predicate shape are deliberately irrelevant: the selected body edge
        may be either the explicit target or fallthrough.
        """
        if header is None:
            return None, None, "header_missing"
        if header in set(self.loop_guard_nodes or {}):
            return None, None, "composite_guard_chain_owned_elsewhere"

        true_node = self._true_edge(header)
        false_node = self._false_edge(header)
        successors = []
        for node in (true_node, false_node):
            if node is not None and node not in successors:
                successors.append(node)
        if len(successors) != 2:
            successors = []
            for node in list(self._successors(header) or []):
                if node is not None and node not in successors:
                    successors.append(node)
        if len(successors) != 2:
            return None, None, "binary_successors_not_exactly_two"

        loop_nodes = set(self.loop_nodes.get(header, set()) or set())
        loop_exits = set(self.loop_exits.get(header, set()) or set())
        if not loop_nodes:
            return None, None, "natural_loop_membership_missing"

        body_nodes = [
            node
            for node in successors
            if node in loop_nodes and node is not header
        ]
        exit_nodes = [
            node
            for node in successors
            if node not in loop_nodes or node in loop_exits
        ]
        if len(body_nodes) != 1 or len(exit_nodes) != 1:
            return (
                None,
                None,
                "body_exit_partition_not_unique:%d:%d"
                % (len(body_nodes), len(exit_nodes)),
            )
        if body_nodes[0] is exit_nodes[0]:
            return None, None, "body_exit_successor_collision"
        return body_nodes[0], exit_nodes[0], "natural_loop_exact_partition"

    def _loop_header_has_canonical_edge_pair_v73(self, header):
        true_node = self._true_edge(header)
        false_node = self._false_edge(header)
        if true_node is None or false_node is None or true_node is false_node:
            return False
        return bool(
            isinstance(self._edge_truth_record_v40(header, true_node), dict)
            or isinstance(self._edge_truth_record_v40(header, false_node), dict)
        )

    def _loop_is_edge_role_candidate_v73(self, header):
        """
        v73 is authoritative only for a simple binary pre-test header with
        canonical EdgeTruth.  Composite guard chains retain their established
        multi-predicate transaction and old stacks without canonical truth
        retain v72's absence-only compatibility behavior.
        """
        if header is None or header in set(self.loop_guard_nodes or {}):
            return False
        if header not in set(self.loop_single_exit_tests or set()):
            return False
        return self._loop_header_has_canonical_edge_pair_v73(header)

    def _bind_loop_edge_role_contract_v73(
        self,
        header,
        cond,
        role,
        phase="loop_contract_binding",
    ):
        """
        Bind one exact body-edge predicate as ``continue_when_true``.

        Canonical EdgeTruth already publishes a predicate that is true exactly
        when its edge is taken.  ``invert_for_edge`` records how that projection
        was derived; SGL records it but never applies a second textual NOT.
        """
        if not self._loop_is_edge_role_candidate_v73(header):
            return cond, role, None

        header_addr = self._addr_v26(header)
        existing = self.loop_edge_role_contracts_by_header_v73.get(header_addr)
        if isinstance(existing, dict):
            selected_expr = existing.get("selected_condition_expr")
            current_expr = self._cond_to_string_v19(cond)
            if (
                selected_expr is not None
                and str(current_expr).strip() != str(selected_expr).strip()
            ):
                cond = RawCond(
                    selected_expr,
                    source=cond,
                    inverted=str(selected_expr).strip().startswith("not "),
                    reason="v73_restore_frozen_body_edge_predicate",
                )
            return cond, "body", existing

        # v72 validates authority, complementarity, condition identity, and
        # exact binary coverage.  A partial/unresolved canonical pair fails
        # before v73 can publish any loop contract.
        self._require_binary_edge_truth_pair_v72(
            header,
            consumer="ingenious_emperor_loop_edge_role_v73",
        )

        body_node, exit_node, partition_reason = (
            self._loop_header_edge_roles_v73(header)
        )
        if body_node is None or exit_node is None:
            failure = {
                "kind": "loop_edge_role_unresolved_v73",
                "version": self.ingenious_emperor_version_v73,
                "header": header_addr,
                "phase": phase,
                "reason": partition_reason,
                "action": (
                    "repair FunctionCFG natural-loop membership; do not infer "
                    "loop predicate role from expression shape"
                ),
            }
            self.loop_edge_role_failures_v73.append(failure)
            self._record_loop_edge_role_event_v73(**failure)
            return cond, role, None

        body_rec = self._edge_truth_record_v40(header, body_node)
        exit_rec = self._edge_truth_record_v40(header, exit_node)
        body_cond = self._authoritative_edgetruth_condition_v72(
            header,
            body_node,
            cond=cond,
            consumer="ingenious_emperor_continue_edge_v73",
        )
        if body_cond is None:
            failure = {
                "kind": "loop_continue_edge_predicate_missing_v73",
                "version": self.ingenious_emperor_version_v73,
                "header": header_addr,
                "phase": phase,
                "continue_edge_key": self._loop_edge_key_v73(
                    header, body_node
                ),
                "exit_edge_key": self._loop_edge_key_v73(
                    header, exit_node
                ),
                "reason": "authoritative_body_edge_projection_missing",
            }
            self.loop_edge_role_failures_v73.append(failure)
            self._record_loop_edge_role_event_v73(**failure)
            return cond, role, None

        body_key = self._loop_edge_key_v73(header, body_node)
        exit_key = self._loop_edge_key_v73(header, exit_node)
        body_invert = (
            body_rec.get("invert_for_edge")
            if isinstance(body_rec, dict) else None
        )
        exit_invert = (
            exit_rec.get("invert_for_edge")
            if isinstance(exit_rec, dict) else None
        )
        selected_expr = self._cond_to_string_v19(body_cond)
        contract = {
            "kind": "exact_loop_edge_role_contract_v73",
            "version": self.ingenious_emperor_version_v73,
            "status": "verified",
            "header": header_addr,
            "condition_semantics": "continue_when_true",
            "condition_role": "body",
            "continue_edge_key": body_key,
            "exit_edge_key": exit_key,
            "selected_condition_edge_key": list(body_key),
            "selected_edge_invert": body_invert,
            "peer_edge_invert": exit_invert,
            "selected_condition_expr": selected_expr,
            "selected_edge_predicate_holds_means_take_edge": bool(
                isinstance(body_rec, dict)
                and body_rec.get("predicate_holds_means_take_edge") is True
            ),
            "edge_role_authority": (
                "FunctionCFG_natural_loop_membership_plus_canonical_EdgeTruth"
            ),
            "topology_partition_reason": partition_reason,
            "projection_rule": (
                "canonical_edge_predicate_is_already_edge_oriented;"
                "record_invert_for_edge_but_do_not_apply_a_second_NOT"
            ),
            "phase": phase,
        }
        self.loop_edge_role_contracts_v73.append(contract)
        self.loop_edge_role_contracts_by_header_v73[header_addr] = contract
        self._record_loop_edge_role_event_v73(
            "loop_continue_edge_bound_v73",
            header=header_addr,
            phase=phase,
            continue_edge_key=body_key,
            exit_edge_key=exit_key,
            selected_condition_edge_key=list(body_key),
            selected_edge_invert=body_invert,
            condition_semantics="continue_when_true",
            condition_expr=selected_expr,
            reason="canonical_body_edge_owns_loop_continuation",
        )
        return body_cond, "body", contract

    def _apply_loop_edge_role_contract_v73(self, loop, contract):
        if loop is None or not isinstance(contract, dict):
            return loop
        loop.condition_role = "body"
        loop.emit_condition_mode = "body"
        loop.condition_semantics = "continue_when_true"
        loop.continue_edge_key = list(contract.get("continue_edge_key") or [])
        loop.exit_edge_key = list(contract.get("exit_edge_key") or [])
        loop.selected_condition_edge_key = list(
            contract.get("selected_condition_edge_key") or []
        )
        loop.selected_edge_invert = contract.get("selected_edge_invert")
        loop.edge_role_authority = contract.get("edge_role_authority")
        loop.loop_edge_role_contract_v73 = dict(contract)
        return loop

    def _publish_ingenious_emperor_handoff_v73(self):
        audit = dict(self.loop_edge_role_audit_v73 or {})
        self.func.sgl_ingenious_emperor_version_v73 = (
            self.ingenious_emperor_version_v73
        )
        self.func.sgl_loop_edge_role_contracts_v73 = list(
            self.loop_edge_role_contracts_v73
        )
        self.func.sgl_loop_edge_role_contracts_by_header_v73 = dict(
            self.loop_edge_role_contracts_by_header_v73
        )
        self.func.sgl_loop_edge_role_events_v73 = list(
            self.loop_edge_role_events_v73
        )
        self.func.sgl_loop_edge_role_failures_v73 = list(
            self.loop_edge_role_failures_v73
        )
        self.func.sgl_loop_edge_role_audit_v73 = audit
        return audit

    def _audit_loop_edge_role_contracts_v73(self):
        """Fail closed if an exact canonical loop lost edge-role custody."""
        loops = []

        def collect(node):
            if node is None:
                return
            if getattr(node, "kind", None) == "loop":
                loops.append(node)
            for child in list(getattr(node, "children", []) or []):
                collect(child)

        collect(self.root)
        issues = list(self.loop_edge_role_failures_v73)
        records = []
        expected_headers = {
            self._addr_v26(header)
            for header in set(self.loop_headers or set())
            if self._loop_is_edge_role_candidate_v73(header)
        }
        seen_headers = set()

        for loop in loops:
            header = getattr(loop, "header", None)
            header_addr = self._addr_v26(header)
            if header_addr not in expected_headers:
                continue
            seen_headers.add(header_addr)
            contract = getattr(loop, "loop_edge_role_contract_v73", None)
            transaction = getattr(loop, "condition_transaction", None)
            body_node, exit_node, partition_reason = (
                self._loop_header_edge_roles_v73(header)
            )
            expected_body_key = (
                self._loop_edge_key_v73(header, body_node)
                if body_node is not None else None
            )
            expected_exit_key = (
                self._loop_edge_key_v73(header, exit_node)
                if exit_node is not None else None
            )
            record = {
                "header": header_addr,
                "condition_role": getattr(loop, "condition_role", None),
                "condition_semantics": getattr(
                    loop, "condition_semantics", None
                ),
                "continue_edge_key": getattr(
                    loop, "continue_edge_key", None
                ),
                "exit_edge_key": getattr(loop, "exit_edge_key", None),
                "selected_condition_edge_key": getattr(
                    loop, "selected_condition_edge_key", None
                ),
                "selected_edge_invert": getattr(
                    loop, "selected_edge_invert", None
                ),
                "condition_expr": self._cond_to_string_v19(
                    getattr(loop, "cond_var", None)
                ),
                "contract_present": isinstance(contract, dict),
                "condition_transaction_present": transaction is not None,
                "condition_transaction_contract_present": isinstance(
                    getattr(
                        transaction,
                        "loop_edge_role_contract_v73",
                        None,
                    ),
                    dict,
                ) if transaction is not None else None,
                "topology_partition_reason": partition_reason,
            }
            records.append(record)

            def issue(reason):
                issues.append({
                    "kind": "loop_edge_role_audit_issue_v73",
                    "version": self.ingenious_emperor_version_v73,
                    "header": header_addr,
                    "reason": reason,
                })

            if not isinstance(contract, dict):
                issue("contract_missing")
                continue
            if getattr(loop, "condition_role", None) != "body":
                issue("condition_role_not_body")
            if getattr(loop, "condition_semantics", None) != (
                "continue_when_true"
            ):
                issue("condition_semantics_not_continue_when_true")
            if getattr(loop, "continue_edge_key", None) != expected_body_key:
                issue("continue_edge_key_mismatch")
            if getattr(loop, "exit_edge_key", None) != expected_exit_key:
                issue("exit_edge_key_mismatch")
            if getattr(loop, "selected_condition_edge_key", None) != (
                expected_body_key
            ):
                issue("selected_edge_is_not_continue_edge")
            if not isinstance(
                getattr(loop, "selected_edge_invert", None), bool
            ):
                issue("selected_edge_invert_not_boolean")
            if contract.get(
                "selected_edge_predicate_holds_means_take_edge"
            ) is not True:
                issue("selected_predicate_not_edge_taking_authority")
            if str(record.get("condition_expr")).strip() != str(
                contract.get("selected_condition_expr")
            ).strip():
                issue("condition_expr_differs_from_selected_edge_predicate")
            if transaction is not None:
                if getattr(
                    transaction, "selected_condition_edge_key", None
                ) != expected_body_key:
                    issue("condition_transaction_selected_edge_mismatch")
                if getattr(
                    transaction, "condition_semantics", None
                ) != "continue_when_true":
                    issue("condition_transaction_semantics_mismatch")
                if not isinstance(
                    getattr(
                        transaction,
                        "loop_edge_role_contract_v73",
                        None,
                    ),
                    dict,
                ):
                    issue("condition_transaction_contract_missing")

        for header_addr in sorted(expected_headers - seen_headers):
            issues.append({
                "kind": "loop_edge_role_audit_issue_v73",
                "version": self.ingenious_emperor_version_v73,
                "header": header_addr,
                "reason": "loop_execution_owner_missing",
            })

        audit = {
            "kind": (
                "ingenious_emperor_loop_edge_role_verified_v73"
                if not issues
                else "ingenious_emperor_loop_edge_role_failed_v73"
            ),
            "version": self.ingenious_emperor_version_v73,
            "status": "verified" if not issues else "failed",
            "expected_headers": len(expected_headers),
            "verified_headers": len(records),
            "records": records,
            "issues": issues,
            "rule": (
                "canonical_loop_condition_is_continue_edge_predicate;"
                "condition_semantics_continue_when_true;"
                "edge_inversion_consumed_exactly_once"
            ),
        }
        self.loop_edge_role_audit_v73 = audit
        self._record_loop_edge_role_event_v73(
            audit["kind"],
            phase="final_exec_tree_audit",
            reason=audit["status"],
        )
        self._publish_ingenious_emperor_handoff_v73()
        if issues:
            raise RuntimeError(
                "PALSGL v73 exact loop-edge role custody failure: %s"
                % issues
            )
        return audit

    # =========================================================================
    # v22 FINAL EXEC TREE CONTRACT VALIDATION
    # =========================================================================

    def _finalize_exec_tree_contracts_v22(self):
        """
        Final post-build invariant pass over ExecLoop nodes.
        """
        self._walk_exec_tree_v22(self.root, self._finalize_loop_node_v22)

    def _walk_exec_tree_v22(self, node, fn):
        if node is None:
            return
        fn(node)
        for child in list(getattr(node, "children", []) or []):
            self._walk_exec_tree_v22(child, fn)

    def _record_loop_contract_v22(self, loop, old_cond, old_role, new_cond, new_role, why):
        try:
            self.loop_contract_events.append({
                "header": getattr(getattr(loop, "header", None), "addr", None),
                "old_role": old_role,
                "old_cond": getattr(old_cond, "name", old_cond),
                "new_role": new_role,
                "new_cond": getattr(new_cond, "name", new_cond),
                "why": why,
            })
        except Exception:
            pass

    def _finalize_loop_node_v22(self, node):
        if getattr(node, "kind", None) != "loop":
            return
        header = getattr(node, "header", None)
        cond = getattr(node, "cond_var", None)
        role = getattr(node, "condition_role", None)
        if role in (None, "true") or cond is None:
            return
        old_cond, old_role = cond, role

        # v73: exact body-edge custody outranks every expression-shape
        # heuristic below.  This is the generic constant-lower-bound class:
        #
        #     body edge predicate: 47 < c
        #     legacy heuristic:    const < var therefore "exit"   (wrong)
        #
        # Once EdgeTruth proves that exact expression admits the body, retain
        # role=body/continue_when_true and never apply emitter-facing inversion.
        cond, role, edge_contract = self._bind_loop_edge_role_contract_v73(
            header,
            cond,
            role,
            phase="final_exec_tree_contract",
        )
        if isinstance(edge_contract, dict):
            node.cond_var = cond
            self._apply_loop_edge_role_contract_v73(node, edge_contract)
            if cond is not old_cond or role != old_role:
                self._record_loop_contract_v22(
                    node,
                    old_cond,
                    old_role,
                    cond,
                    role,
                    "v73_exact_body_edge_continue_when_true",
                )
            return

        cond, role, why = self._loop_contract_repair_v22(header, cond, role)
        if cond is not old_cond or role != old_role:
            node.cond_var = cond
            node.condition_role = role
            node.emit_condition_mode = role
            self._record_loop_contract_v22(node, old_cond, old_role, cond, role, why)

    def _loop_contract_repair_v22(self, header, cond, role):
        s = self._cond_to_string_v19(cond)
        clean = self._strip_redundant_outer_parens_v19(s)
        if not clean or role != "body":
            return cond, role, "unchanged"

        # body-role with const < var is exit-shaped for GCC/O0 counter loops.
        if self._is_const_lt_var_expr_v22(clean):
            return RawCond(clean, source=cond, reason="v22_final_const_lt_var_exit"), "exit", "final_const_lt_var_exit"

        body_node = self._get_loop_body(header)
        try:
            body_edge_invert = self._edge_condition_invert_for_edge(
                header, body_node
            )
        except Exception:
            body_edge_invert = None

        if (
            body_edge_invert is None
            and isinstance(
                self._edge_truth_record_v40(header, body_node), dict
            )
        ):
            return (
                cond,
                role,
                "v72_unresolved_canonical_edge_truth_blocks_loop_repair",
            )

        var_name, inner = self._negated_less_inner_v19(clean)
        if var_name and inner:
            # A simple positive induction variable proves this is an ordinary
            # counter body predicate.  This overrides low-confidence edge
            # inversion because the loop update class is stronger evidence.
            if self._loop_has_positive_induction_update_v19(header, var_name):
                return RawCond(inner, source=cond, reason="v23_final_strip_positive_induction_not_less"), "body", "final_strip_positive_induction_not_less"
            if not body_edge_invert:
                return RawCond(inner, source=cond, reason="v23_final_strip_accidental_not_less"), "body", "final_strip_accidental_not_less"

        lt_inner = self._ge_to_lt_inner_v22(clean)
        if lt_inner:
            ge_var = self._ge_var_name_v23(clean)
            if ge_var and self._loop_has_positive_induction_update_v19(header, ge_var):
                return RawCond(lt_inner, source=cond, reason="v23_final_ge_to_lt_positive_induction_body"), "body", "final_ge_to_lt_positive_induction_body"
            if not body_edge_invert:
                return RawCond(lt_inner, source=cond, reason="v23_final_ge_to_lt_body"), "body", "final_ge_to_lt_body"

        return cond, role, "unchanged"

    def _is_const_lt_var_expr_v22(self, expr):
        expr = self._strip_redundant_outer_parens_v19(expr)
        return bool(re.match(r"^(0x[0-9a-fA-F]+|\d+)\s*<\s*[A-Za-z_][A-Za-z0-9_]*$", expr or ""))

    def _ge_to_lt_inner_v22(self, expr):
        expr = self._strip_redundant_outer_parens_v19(expr)
        if not expr:
            return None
        m = re.match(r"^([A-Za-z_][A-Za-z0-9_]*)\s*>=\s*(0x[0-9a-fA-F]+|\d+)$", expr)
        if not m:
            return None
        return "%s < %s" % (m.group(1), m.group(2))

    def _ge_var_name_v23(self, expr):
        expr = self._strip_redundant_outer_parens_v19(expr)
        if not expr:
            return None
        m = re.match(r"^([A-Za-z_][A-Za-z0-9_]*)\s*>=\s*(0x[0-9a-fA-F]+|\d+)$", expr)
        return m.group(1) if m else None


    # =========================================================================
    # v24/v54 METADATA CONSOLIDATION / PHI-EMITTER HANDOFF
    # =========================================================================

    def _consolidate_metadata_v24(self):
        """
        Build metadata records for downstream layers without changing SGL.

        SGL owns:
          - control structure
          - branch arm orientation
          - loop condition role
          - condition consumer sites

        PHIfolder/emitter should own:
          - exact post-update value alias closure
          - materialization or safe inline of condition temps
          - final expression presentation

        This pass therefore exports facts/candidates, not rewritten code.

        v54 adds a source-aware condition provenance sidecar.  RawCond remains
        the authoritative frozen edge predicate and its textual contract is
        not changed.  The sidecar follows RawCond.source, when present, and
        exports the originating SSA/formula identity plus every structurally
        reachable formula dependency.  Text-derived SID recovery remains a
        separately labelled fallback for synthetic/composite RawCond values.
        """

        self.condition_consumers = []
        self.condition_provenance_sidecars = []
        self.condition_temp_defs = []
        self.post_update_alias_candidates = []
        self.metadata_events = []

        seen_consumers = set()
        seen_temp_defs = set()
        seen_aliases = set()

        for item in self._iter_condition_consumers_v24(self.root):
            cond = item.get("cond")
            expr = self._cond_to_string_v19(cond)
            sidecar = self._condition_provenance_sidecar_v54(cond, expr, item)

            consumer = {
                "kind": item.get("kind"),
                "addr": item.get("addr"),
                "role": item.get("role"),
                "cond_sid": self._sid_of_var_v24(cond),
                "cond_expr": expr,
                "reason": getattr(cond, "reason", None),
                # v54 additive fields.  cond_sid intentionally retains its
                # historical direct-object meaning; downstream layers can
                # opt into source-aware custody through effective_condition_sid.
                "condition_representation": sidecar.get("condition_representation"),
                "source_condition_sid": sidecar.get("source_condition_sid"),
                "effective_condition_sid": sidecar.get("effective_condition_sid"),
                "formula_dependency_sids": list(sidecar.get("formula_dependency_sids", []) or []),
                "text_dependency_sids": list(sidecar.get("text_dependency_sids", []) or []),
                "dependency_authority": sidecar.get("dependency_authority"),
                # v73 additive loop-edge custody.  Non-loop consumers retain
                # None/empty values, preserving the existing schema.
                "condition_semantics": item.get("condition_semantics"),
                "continue_edge_key": item.get("continue_edge_key"),
                "exit_edge_key": item.get("exit_edge_key"),
                "selected_condition_edge_key": item.get(
                    "selected_condition_edge_key"
                ),
                "selected_edge_invert": item.get("selected_edge_invert"),
                "edge_role_authority": item.get("edge_role_authority"),
                "loop_edge_role_contract_v73": dict(
                    item.get("loop_edge_role_contract_v73") or {}
                ),
            }

            key = (
                consumer.get("kind"),
                consumer.get("addr"),
                consumer.get("role"),
                consumer.get("cond_sid"),
                consumer.get("cond_expr"),
            )
            if key not in seen_consumers:
                seen_consumers.add(key)
                provenance_ref = "sgl_condition_provenance:%04d" % len(
                    self.condition_provenance_sidecars
                )
                consumer["provenance_ref"] = provenance_ref
                sidecar["provenance_ref"] = provenance_ref
                sidecar["consumer_kind"] = consumer.get("kind")
                sidecar["consumer_addr"] = consumer.get("addr")
                sidecar["consumer_role"] = consumer.get("role")
                self.condition_consumers.append(consumer)
                self.condition_provenance_sidecars.append(sidecar)

            for rec in self._condition_temp_def_records_v24(expr, consumer):
                rkey = (
                    rec.get("sid"),
                    rec.get("name"),
                    rec.get("consumer_addr"),
                    rec.get("expr"),
                    rec.get("source_addr"),
                )
                if rkey not in seen_temp_defs:
                    seen_temp_defs.add(rkey)
                    self.condition_temp_defs.append(rec)

            for rec in self._post_update_alias_candidate_records_v24(cond, consumer):
                rkey = (
                    rec.get("source_sid"),
                    rec.get("target_name"),
                    rec.get("consumer_addr"),
                    rec.get("expr"),
                )
                if rkey not in seen_aliases:
                    seen_aliases.add(rkey)
                    self.post_update_alias_candidates.append(rec)

        self.metadata_events.append({
            "kind": "metadata_consolidation_v54",
            "condition_consumers": len(self.condition_consumers),
            "condition_provenance_sidecars": len(self.condition_provenance_sidecars),
            "raw_condition_consumers": sum(
                1 for rec in self.condition_provenance_sidecars
                if rec.get("condition_representation") == "raw_condition"
            ),
            "source_sid_recoveries": sum(
                1 for rec in self.condition_provenance_sidecars
                if rec.get("direct_condition_sid") is None
                and rec.get("source_condition_sid") is not None
            ),
            "formula_authoritative_consumers": sum(
                1 for rec in self.condition_provenance_sidecars
                if rec.get("dependency_authority") == "formula_structure"
            ),
            "text_fallback_consumers": sum(
                1 for rec in self.condition_provenance_sidecars
                if rec.get("dependency_authority") == "condition_text_fallback"
            ),
            "condition_temp_defs": len(self.condition_temp_defs),
            "post_update_alias_candidates": len(self.post_update_alias_candidates),
        })

    # =========================================================================
    # v74 / mars — OBSERVATION-ONLY STRUCTURAL STATE-FLOW HANDOFF
    # =========================================================================

    @staticmethod
    def _state_flow_sid_v1(value):
        if value is None:
            return None
        if hasattr(value, "var"):
            value = getattr(value, "var", None)
        sid = getattr(value, "ssa_id", None)
        if sid is None and isinstance(value, (str, int)):
            sid = value
        return str(sid) if sid is not None else None

    @staticmethod
    def _state_flow_addr_v1(value):
        if value is None:
            return None
        if isinstance(value, int):
            return value
        for attr in ("addr", "block_addr", "address"):
            candidate = getattr(value, attr, None)
            if isinstance(candidate, int):
                return candidate
        block = getattr(value, "block", None)
        candidate = getattr(block, "addr", None)
        return candidate if isinstance(candidate, int) else None

    @staticmethod
    def _state_flow_addr_token_v1(value):
        return "0x%x" % value if isinstance(value, int) else str(value)

    @staticmethod
    def _state_flow_type_text_v1(value):
        if value is None:
            return None
        if isinstance(value, (str, int, float, bool)):
            return str(value)
        for attr in ("name", "display_name", "type_name"):
            candidate = getattr(value, attr, None)
            if isinstance(candidate, (str, int, float, bool)):
                return str(candidate)
        return value.__class__.__name__

    @staticmethod
    def _state_flow_stable_unique_v1(values):
        out = []
        seen = set()
        for value in list(values or []):
            marker = repr(value)
            if marker in seen:
                continue
            seen.add(marker)
            out.append(value)
        return out

    def _state_flow_cfg_node_v1(self, addr):
        nodes = getattr(self.cfg, "nodes", None)
        if isinstance(nodes, dict):
            if addr in nodes:
                return nodes.get(addr)
            for key, value in nodes.items():
                if self._state_flow_addr_v1(key) == addr:
                    return value
                if self._state_flow_addr_v1(value) == addr:
                    return value
        for node in self._real_nodes():
            if self._state_flow_addr_v1(node) == addr:
                return node
        return None

    def _state_flow_cfg_edge_exists_v1(self, pred_addr, succ_addr):
        pred = self._state_flow_cfg_node_v1(pred_addr)
        if pred is None:
            return False
        return any(
            self._state_flow_addr_v1(getattr(edge, "dst", None)) == succ_addr
            for edge in list(getattr(pred, "out_edges", []) or [])
        )

    def _state_flow_formula_and_phi_nodes_v1(self):
        formula_nodes = dict(self._formula_nodes() or {})
        raw = getattr(self.func, "var_nodes", None)
        phi_nodes = []
        if isinstance(raw, tuple) and len(raw) >= 2:
            phi_nodes = list(raw[1] or [])
        if not phi_nodes:
            phi_nodes = list(getattr(self.func, "phi_nodes", []) or [])

        # v78: PALPHIfolder synthesizes raw MULTIEQUAL operations that were
        # omitted from the semantic PHI list.  SGL must see the same immutable
        # obligation inventory before it freezes edge epochs, but it must not
        # mutate the producer graph or claim PHI family/storage ownership.
        represented = {
            self._state_flow_sid_v1(
                getattr(phi, "output", None)
                if getattr(phi, "output", None) is not None
                else getattr(phi, "output_sid", None)
            )
            for phi in list(phi_nodes or [])
        }
        represented.discard(None)
        for block in list(getattr(self.func, "blocks", []) or []):
            for op in list(getattr(block, "ops", []) or []):
                if str(getattr(op, "opcode", "") or "").upper() != "MULTIEQUAL":
                    continue
                sid = self._state_flow_sid_v1(getattr(op, "output", None))
                if sid is None or sid in represented:
                    continue
                phi_nodes.append(op)
                represented.add(sid)
        return formula_nodes, phi_nodes
    @staticmethod
    def _state_flow_storage_key_v78(value):
        value = getattr(value, "var", value)
        if value is None:
            return None
        address = getattr(value, "address", None)
        size = getattr(value, "size", None)
        if address is not None:
            return ("addr", address, size)
        space = getattr(value, "space", None)
        offset = getattr(value, "offset", None)
        if space is not None and offset is not None:
            return ("space", space, offset, size)
        return None

    def _state_flow_same_storage_v78(self, left, right):
        left = getattr(left, "var", left)
        right = getattr(right, "var", right)
        if left is None or right is None:
            return False
        if left is right:
            return True
        left_sid = self._state_flow_sid_v1(left)
        right_sid = self._state_flow_sid_v1(right)
        if left_sid is not None and left_sid == right_sid:
            return True
        left_key = self._state_flow_storage_key_v78(left)
        right_key = self._state_flow_storage_key_v78(right)
        return left_key is not None and left_key == right_key

    def _state_flow_defining_block_candidates_v78(
        self, value, formula_nodes, raw_definition_blocks
    ):
        """Return all explicit defining-block addresses for one SSA value."""
        candidates = set()

        def retain(candidate):
            addr = self._state_flow_addr_v1(candidate)
            if addr is not None:
                candidates.add(addr)

        unwrapped = getattr(value, "var", value)
        for obj in (value, unwrapped):
            if obj is None:
                continue
            for attr in (
                "block", "block_region", "defining_block", "def_block",
                "definition_block",
            ):
                retain(getattr(obj, attr, None))
            for attr in ("defining_op", "def_op", "producer_op", "op"):
                op = getattr(obj, attr, None)
                if op is None:
                    continue
                retain(getattr(op, "block", None))
                retain(getattr(op, "block_region", None))

        sid = self._state_flow_sid_v1(value)
        if sid is not None:
            for addr in set(raw_definition_blocks.get(sid, set()) or set()):
                retain(addr)
            for key, node in dict(formula_nodes or {}).items():
                node_sid = self._state_flow_sid_v1(node)
                if node_sid is None:
                    node_sid = self._state_flow_sid_v1(key)
                if node_sid != sid:
                    continue
                retain(getattr(node, "block", None))
                retain(getattr(node, "block_region", None))
                op = getattr(node, "op", None)
                retain(getattr(op, "block", None))
                retain(getattr(op, "block_region", None))
        return sorted(candidates, key=str)

    def _state_flow_original_phi_nodes_v79(self):
        """Return only producer-owned PHI nodes, excluding raw v78 synthesis."""
        raw = getattr(self.func, "var_nodes", None)
        phi_nodes = []
        if isinstance(raw, tuple) and len(raw) >= 2:
            phi_nodes = list(raw[1] or [])
        if not phi_nodes:
            phi_nodes = list(getattr(self.func, "phi_nodes", []) or [])
        return phi_nodes

    def _state_flow_reaches_addr_v79(self, src_addr, dst_addr, stop_addr=None):
        """CFG reachability used only as residual PHI candidate evidence."""
        src = self._state_flow_cfg_node_v1(src_addr)
        dst = self._state_flow_cfg_node_v1(dst_addr)
        if src is None or dst is None:
            return False
        if src is dst:
            return True
        stop = self._state_flow_cfg_node_v1(stop_addr) if stop_addr is not None else None
        work = [src]
        seen = {src}
        while work:
            node = work.pop()
            for edge in list(getattr(node, "out_edges", []) or []):
                nxt = getattr(edge, "dst", None)
                if nxt is None or nxt in seen:
                    continue
                if stop is not None and nxt is stop and nxt is not dst:
                    continue
                if nxt is dst:
                    return True
                seen.add(nxt)
                work.append(nxt)
        return False

    @staticmethod
    def _state_flow_unique_source_map_v79(items, predecessors, solution_limit=128):
        """Return a unique predecessor→source map, ignoring duplicate input identity.

        Multiple perfect matchings are admissible when they induce the same
        predecessor-to-source-SID mapping.  This preserves repeated live-through
        values without importing MULTIEQUAL ordinal as authority.
        """
        predecessors = tuple(sorted(set(predecessors), key=str))
        if len(items) != len(predecessors):
            return None, "residual_input_predecessor_cardinality_mismatch", 0
        normalized = []
        for index, item in enumerate(items):
            candidates = tuple(sorted(set(item.get("candidates") or []), key=str))
            if not candidates:
                return None, "residual_input_has_no_admissible_predecessor", 0
            normalized.append({
                "index": index,
                "source_sid": item.get("source_sid"),
                "candidates": candidates,
            })
        normalized.sort(key=lambda item: (len(item["candidates"]), str(item["source_sid"]), item["index"]))
        maps = set()
        used = set()
        assignment = {}
        explored = 0

        def walk(position):
            nonlocal explored
            if len(maps) > 1 or explored >= solution_limit:
                return
            if position == len(normalized):
                explored += 1
                maps.add(tuple(sorted(
                    ((pred, assignment[pred]) for pred in assignment),
                    key=lambda pair: str(pair[0]),
                )))
                return
            item = normalized[position]
            for pred in item["candidates"]:
                if pred in used:
                    continue
                used.add(pred)
                assignment[pred] = item["source_sid"]
                walk(position + 1)
                assignment.pop(pred, None)
                used.remove(pred)
                if len(maps) > 1 or explored >= solution_limit:
                    return

        walk(0)
        if not maps:
            return None, "no_perfect_residual_predecessor_matching", explored
        if len(maps) != 1:
            return None, "multiple_distinct_residual_source_maps", explored
        return dict(next(iter(maps))), "unique_residual_source_map", explored

    def _state_flow_path_expanded_source_map_v80e(
        self,
        inputs,
        residual_predecessors,
        fixed_by_predecessor,
        target,
        join_addr,
        formula_nodes,
        raw_definition_blocks,
        solution_limit=256,
    ):
        """Resolve path-expanded PHI sources without MULTIEQUAL ordinals.

        HighFunction may publish one SSA input for a value that remains live
        across more than one concrete CFG predecessor.  The v79 matcher
        subtracted that input after the first fixed predecessor, which made a
        second exact edge impossible to resolve.

        v80e gives a non-PHI leaf source one additional residual capacity unit
        for every already-proven fixed predecessor carrying that same SID.
        Candidate preference is semantic:

        1. exact defining block equals predecessor;
        2. definition reaches predecessor without crossing the join;
        3. a previously fixed predecessor carrying the source reaches the
           residual predecessor.

        The minimum-cost predecessor→source map must be unique.  Input order,
        successor order, and ordinal fallback remain forbidden.
        """
        residual_predecessors = tuple(
            sorted(set(residual_predecessors or []), key=str)
        )
        fixed_by_predecessor = dict(fixed_by_predecessor or {})
        if not residual_predecessors:
            return {}, "empty_residual_predecessor_set_v80e", {
                "status": "accepted",
                "source_inventory": [],
                "minimum_score": 0,
                "minimum_maps": 1,
                "solutions_explored": 1,
            }

        phi_output_sids = {
            self._state_flow_sid_v1(
                getattr(phi, "output", None)
                if getattr(phi, "output", None) is not None
                else getattr(phi, "output_sid", None)
            )
            for phi in self._state_flow_original_phi_nodes_v79()
        }
        phi_output_sids.discard(None)

        source_values = {}
        raw_counts = {}
        for value in list(inputs or []):
            sid = self._state_flow_sid_v1(value)
            if sid is None:
                continue
            raw_counts[sid] = raw_counts.get(sid, 0) + 1
            source_values.setdefault(sid, value)

        fixed_counts = {}
        fixed_predecessors_by_sid = {}
        for pred_addr, sid in fixed_by_predecessor.items():
            sid = self._state_flow_sid_v1(sid)
            if sid is None:
                continue
            fixed_counts[sid] = fixed_counts.get(sid, 0) + 1
            fixed_predecessors_by_sid.setdefault(sid, set()).add(pred_addr)

        source_inventory = {}
        for sid, value in source_values.items():
            definitions = self._state_flow_defining_block_candidates_v78(
                value, formula_nodes, raw_definition_blocks
            )
            fixed_count = fixed_counts.get(sid, 0)
            base_remaining = max(raw_counts.get(sid, 0) - fixed_count, 0)
            is_phi_output = sid in phi_output_sids
            live_through_capacity = (
                fixed_count if fixed_count and not is_phi_output else 0
            )
            residual_capacity = base_remaining + live_through_capacity
            source_inventory[sid] = {
                "source_sid": sid,
                "value": value,
                "raw_input_count": raw_counts.get(sid, 0),
                "fixed_predecessor_count": fixed_count,
                "fixed_predecessors": sorted(
                    fixed_predecessors_by_sid.get(sid, set()), key=str
                ),
                "base_remaining_capacity": base_remaining,
                "live_through_capacity": live_through_capacity,
                "residual_capacity": residual_capacity,
                "is_phi_output": is_phi_output,
                "defining_block_candidates": list(definitions),
                "candidate_ranks": {},
            }

        candidates_by_pred = {}
        for pred_addr in residual_predecessors:
            candidates = []
            for sid, info in source_inventory.items():
                if info["residual_capacity"] <= 0:
                    continue
                definitions = list(info["defining_block_candidates"])
                authority = None
                rank = None
                if pred_addr in definitions:
                    authority = "exact_defining_block"
                    rank = 0
                elif any(
                    self._state_flow_reaches_addr_v79(
                        definition, pred_addr, stop_addr=join_addr
                    )
                    for definition in definitions
                    if definition is not None
                ):
                    authority = "definition_reaches_predecessor"
                    rank = 10
                elif any(
                    fixed_pred == pred_addr
                    or self._state_flow_reaches_addr_v79(
                        fixed_pred, pred_addr, stop_addr=join_addr
                    )
                    for fixed_pred in info["fixed_predecessors"]
                ):
                    authority = "fixed_live_through_reaches_predecessor"
                    rank = 20
                if rank is None:
                    continue
                item = {
                    "source_sid": sid,
                    "rank": rank,
                    "authority": authority,
                }
                candidates.append(item)
                info["candidate_ranks"][pred_addr] = dict(item)
            candidates.sort(
                key=lambda item: (
                    item["rank"],
                    str(item["source_sid"]),
                )
            )
            candidates_by_pred[pred_addr] = candidates

        missing = [
            pred for pred, values in candidates_by_pred.items() if not values
        ]
        evidence = {
            "kind": "path_expanded_phi_capacity_evidence_v80e",
            "version": getattr(
                self,
                "mars_path_expanded_phi_capacity_version_v80e",
                "v80e_mars_path_expanded_phi_capacity_v1",
            ),
            "status": "unresolved" if missing else "candidate_space_ready",
            "join_addr": join_addr,
            "target_sid": self._state_flow_sid_v1(target),
            "residual_predecessors": list(residual_predecessors),
            "fixed_by_predecessor": dict(fixed_by_predecessor),
            "source_inventory": [
                {
                    key: value
                    for key, value in info.items()
                    if key != "value"
                }
                for _sid, info in sorted(
                    source_inventory.items(), key=lambda item: str(item[0])
                )
            ],
            "candidates_by_predecessor": {
                pred: list(values)
                for pred, values in candidates_by_pred.items()
            },
            "missing_candidate_predecessors": missing,
            "input_order_used": False,
            "successor_order_used": False,
            "ordinal_fallback_used": False,
        }
        if missing:
            return None, "path_expanded_predecessor_has_no_source_v80e", evidence

        ordered_preds = sorted(
            residual_predecessors,
            key=lambda pred: (
                len(candidates_by_pred[pred]),
                min(item["rank"] for item in candidates_by_pred[pred]),
                str(pred),
            ),
        )
        usage = {sid: 0 for sid in source_inventory}
        assignment = {}
        best_score = None
        best_maps = set()
        explored = 0

        def source_use_penalty(sid, next_usage):
            info = source_inventory[sid]
            if next_usage <= info["base_remaining_capacity"]:
                return 0
            return 2

        def walk(position, score):
            nonlocal best_score, explored
            if explored >= solution_limit:
                return
            if best_score is not None and score > best_score:
                return
            if position == len(ordered_preds):
                explored += 1
                frozen = tuple(
                    sorted(assignment.items(), key=lambda item: str(item[0]))
                )
                if best_score is None or score < best_score:
                    best_score = score
                    best_maps.clear()
                    best_maps.add(frozen)
                elif score == best_score:
                    best_maps.add(frozen)
                return

            pred_addr = ordered_preds[position]
            for candidate in candidates_by_pred[pred_addr]:
                sid = candidate["source_sid"]
                next_usage = usage[sid] + 1
                if next_usage > source_inventory[sid]["residual_capacity"]:
                    continue
                penalty = source_use_penalty(sid, next_usage)
                usage[sid] = next_usage
                assignment[pred_addr] = sid
                walk(position + 1, score + candidate["rank"] + penalty)
                assignment.pop(pred_addr, None)
                usage[sid] -= 1
                if explored >= solution_limit:
                    return

        walk(0, 0)
        evidence["solutions_explored"] = explored
        evidence["minimum_score"] = best_score
        evidence["minimum_maps"] = len(best_maps)
        evidence["solution_limit"] = solution_limit
        if not best_maps:
            evidence["status"] = "unresolved"
            return None, "no_path_expanded_capacity_map_v80e", evidence
        if len(best_maps) != 1:
            evidence["status"] = "ambiguous"
            evidence["minimum_source_maps"] = [
                list(mapping) for mapping in sorted(best_maps, key=str)
            ]
            return None, "multiple_minimum_path_expanded_maps_v80e", evidence

        result = dict(next(iter(best_maps)))
        evidence["status"] = "accepted"
        evidence["selected_source_map"] = dict(result)
        evidence["authority"] = (
            "definition_CFG_reachability_plus_nonPHI_leaf_live_through_"
            "capacity_v80e"
        )
        return (
            result,
            "unique_path_expanded_leaf_source_capacity_map_v80e",
            evidence,
        )

    def _state_flow_v37_binding_is_exact_resolved_v80g(
        self, record, expected_join=None, predecessor_set=None
    ):
        """Recognize an exact PALSemanticGraphBuilder v37 binding.

        Canonical v37 binding records are members of a resolved/partially
        resolved linkage contract, but the individual binding dictionaries do
        not carry `status="resolved"`.  v80f incorrectly required that absent
        field and therefore discarded valid fixed predecessor coverage.

        Explicit rejected/unresolved statuses still fail.  Statusless records
        are accepted only through the complete v37 producer contract:
        frozen CFG edge identity, exact transition/edge schemas, matching token
        fields, direct-to-join authority, and no order-based inference.
        """
        if not isinstance(record, dict):
            return False, {
                "kind": "v37_binding_contract_rejected_v80g",
                "reason": "record_not_dictionary",
            }

        pair = self._state_flow_edge_pair_v1(record)
        target_sid = self._state_flow_sid_v1(record.get("target_sid"))
        source_sid = self._state_flow_sid_v1(record.get("source_sid"))
        status = record.get("status")

        if pair is None:
            return False, {
                "kind": "v37_binding_contract_rejected_v80g",
                "reason": "edge_pair_missing",
            }

        pred_addr, join_addr = pair
        transition_id = (
            record.get("transition_id")
            or record.get("phi_transition_id")
            or record.get("semantic_transition_id")
            or record.get("id")
        )
        try:
            transition_id = tuple(transition_id)
        except Exception:
            transition_id = None

        explicit_status_accepted = status == "resolved"
        statusless_v37_contract = bool(
            status is None
            and record.get("id_schema")
            == "semantic_phi_predecessor_transition_v1"
            and record.get("edge_id_schema") == "cfg_edge_identity_v1"
            and record.get("edge_identity_frozen") is True
            and record.get("direct_to_join") is True
            and isinstance(transition_id, tuple)
            and len(transition_id) == 5
            and transition_id[:4]
            == (join_addr, pred_addr, target_sid, source_sid)
            and record.get("input_order_used") is False
            and record.get("successor_order_used") is False
            and bool(record.get("authority"))
            and bool(record.get("reason"))
        )

        gates = {
            "status_not_explicitly_rejected": (
                status not in {
                    "rejected",
                    "unresolved",
                    "partially_resolved",
                    "observed_unresolved",
                }
            ),
            "resolved_status_or_exact_statusless_v37_contract": (
                explicit_status_accepted or statusless_v37_contract
            ),
            "edge_pair_exact": (
                expected_join is None or join_addr == expected_join
            ),
            "predecessor_in_exact_CFG_set": (
                predecessor_set is None or pred_addr in predecessor_set
            ),
            "source_sid_present": source_sid is not None,
            "target_sid_present": target_sid is not None,
            "input_order_not_authority": (
                record.get("input_order_used") is False
            ),
            "successor_order_not_authority": (
                record.get("successor_order_used") is False
            ),
        }
        accepted = all(gates.values())
        receipt = {
            "kind": (
                "v37_binding_contract_accepted_v80g"
                if accepted else
                "v37_binding_contract_rejected_v80g"
            ),
            "version": getattr(
                self,
                "mars_v37_binding_contract_recognition_version_v80g",
                "v80g_mars_v37_binding_contract_recognition_v1",
            ),
            "status": "accepted" if accepted else "rejected",
            "record_status": status,
            "recognition_mode": (
                "explicit_resolved_status"
                if explicit_status_accepted
                else (
                    "statusless_exact_v37_binding_contract"
                    if statusless_v37_contract
                    else "none"
                )
            ),
            "edge_id": [pred_addr, join_addr],
            "target_sid": target_sid,
            "source_sid": source_sid,
            "transition_id": list(transition_id or []),
            "gates": gates,
            "input_order_used": False,
            "successor_order_used": False,
        }
        return accepted, receipt

    def _state_flow_record_is_fixed_binding_v80i(self, record):
        """Admit only resolved records into the fixed predecessor index.

        A populated source_sid is evidence, not resolution.  Explicit
        unresolved records must remain available for residual recovery instead
        of occupying the edge slot and suppressing their own accepted receipt.
        """
        if not isinstance(record, dict):
            return False, {
                "kind": "source_record_fixed_binding_rejected_v80i",
                "reason": "record_not_dictionary",
            }

        pair = self._state_flow_edge_pair_v1(record)
        target_sid = self._state_flow_sid_v1(record.get("target_sid"))
        source_sid = self._state_flow_sid_v1(record.get("source_sid"))
        status = record.get("status")

        v80g_accepted = False
        v80g_receipt = None
        if pair is not None:
            try:
                v80g_accepted, v80g_receipt = (
                    self._state_flow_v37_binding_is_exact_resolved_v80g(
                        record,
                        expected_join=pair[1],
                        predecessor_set=None,
                    )
                )
            except Exception as exc:
                v80g_receipt = {
                    "kind": "v37_binding_contract_exception_v80i",
                    "reason": type(exc).__name__,
                }

        explicit_resolved = bool(
            status == "resolved"
            and pair is not None
            and target_sid is not None
            and source_sid is not None
            and record.get("input_order_used") is not True
            and record.get("successor_order_used") is not True
        )
        explicitly_nonterminal = status in {
            "unresolved",
            "rejected",
            "partially_resolved",
            "observed_unresolved",
            "probe",
        }
        accepted = bool(
            not explicitly_nonterminal
            and (explicit_resolved or v80g_accepted)
        )
        return accepted, {
            "kind": (
                "source_record_fixed_binding_accepted_v80i"
                if accepted else
                "source_record_fixed_binding_rejected_v80i"
            ),
            "version": getattr(
                self,
                "mars_resolved_fixed_binding_index_version_v80i",
                "v80i_mars_resolved_fixed_binding_index_v1",
            ),
            "status": "accepted" if accepted else "rejected",
            "record_kind": record.get("kind"),
            "record_status": status,
            "edge_id": list(pair) if pair is not None else None,
            "target_sid": target_sid,
            "source_sid": source_sid,
            "recognition_mode": (
                "explicit_resolved_record"
                if explicit_resolved
                else (
                    "statusless_exact_v37_binding"
                    if v80g_accepted else "nonfixed_observation"
                )
            ),
            "explicitly_nonterminal": explicitly_nonterminal,
            "v80g_binding_receipt": v80g_receipt,
            "input_order_used": bool(
                record.get("input_order_used") is True
            ),
            "successor_order_used": bool(
                record.get("successor_order_used") is True
            ),
        }

    def _compile_late_phi_obligation_closure_v78(self, source_records):
        """v79 residual-only closure over the v78 compatibility entrypoint.

        Producer-owned PHIs and resolved v37 transitions are immutable.  Raw
        MULTIEQUAL operations are consulted only for residual predecessor slots
        that remain explicitly unresolved or whose target is absent from the
        original semantic PHI inventory.  Ambiguous raw observations are
        published but never promoted into state-flow failures.
        """
        source_records = [
            dict(item) if isinstance(item, dict) else item
            for item in list(source_records or [])
        ]
        existing_quads = set()
        fixed_by_target = {}
        fixed_records_by_target_v80f = {}
        fixed_binding_index_receipts_v80i = []
        nonfixed_source_observations_v80i = []
        blocked_fixed_index_targets_v80i = {}
        for item in source_records:
            if not isinstance(item, dict):
                continue
            pair = self._state_flow_edge_pair_v1(item)
            if pair is None:
                continue
            target_sid = self._state_flow_sid_v1(item.get("target_sid"))
            source_sid = self._state_flow_sid_v1(item.get("source_sid"))
            accepted_fixed_v80i, fixed_receipt_v80i = (
                self._state_flow_record_is_fixed_binding_v80i(item)
            )
            fixed_binding_index_receipts_v80i.append(
                fixed_receipt_v80i
            )
            if not accepted_fixed_v80i:
                blocks_residual_recovery_v80i = bool(
                    item.get("status") == "resolved"
                    or fixed_receipt_v80i.get("input_order_used")
                    or fixed_receipt_v80i.get("successor_order_used")
                )
                observation_v80i = {
                    "kind": "nonfixed_source_observation_v80i",
                    "version": getattr(
                        self,
                        "mars_resolved_fixed_binding_index_version_v80i",
                        "v80i_mars_resolved_fixed_binding_index_v1",
                    ),
                    "edge_id": list(pair),
                    "target_sid": target_sid,
                    "source_sid": source_sid,
                    "record_kind": item.get("kind"),
                    "record_status": item.get("status"),
                    "classification": fixed_receipt_v80i,
                    "retained_for_residual_recovery": not (
                        blocks_residual_recovery_v80i
                    ),
                    "blocks_residual_recovery_v80i": (
                        blocks_residual_recovery_v80i
                    ),
                }
                nonfixed_source_observations_v80i.append(
                    observation_v80i
                )
                if blocks_residual_recovery_v80i:
                    blocked_fixed_index_targets_v80i.setdefault(
                        (pair[1], target_sid), []
                    ).append(observation_v80i)
                continue
            existing_quads.add(
                (pair[0], pair[1], target_sid, source_sid)
            )
            fixed_by_target.setdefault(
                (pair[1], target_sid), {}
            )[pair[0]] = source_sid
            fixed_records_by_target_v80f.setdefault(
                (pair[1], target_sid), []
            ).append(dict(item))

        original_phi_nodes = self._state_flow_original_phi_nodes_v79()
        original_phi_targets = {
            self._state_flow_sid_v1(
                getattr(phi, "output", None)
                if getattr(phi, "output", None) is not None
                else getattr(phi, "output_sid", None)
            )
            for phi in original_phi_nodes
        }
        original_phi_targets.discard(None)
        explicit_unresolved = {}
        for phi in original_phi_nodes:
            contract = getattr(phi, "predecessor_linkage_contract_v37", None)
            if not isinstance(contract, dict):
                continue
            target_sid = self._state_flow_sid_v1(
                contract.get("target_sid")
                or getattr(phi, "output_sid", None)
                or getattr(phi, "output", None)
            )
            for unresolved in list(contract.get("unresolved_edges", []) or []):
                pair = self._state_flow_edge_pair_v1(unresolved)
                if pair is not None:
                    explicit_unresolved.setdefault((pair[1], target_sid), set()).add(pair[0])

        formula_nodes = dict(self._formula_nodes() or {})
        raw_definition_blocks = {}
        raw_phis = []
        for block in list(getattr(self.func, "blocks", []) or []):
            block_addr = self._state_flow_addr_v1(block)
            for op in list(getattr(block, "ops", []) or []):
                output = getattr(op, "output", None)
                output_sid = self._state_flow_sid_v1(output)
                if output_sid is not None and block_addr is not None:
                    raw_definition_blocks.setdefault(output_sid, set()).add(block_addr)
                if str(getattr(op, "opcode", "") or "").upper() == "MULTIEQUAL":
                    raw_phis.append((block, op))

        selector_sids = self._occurrence_value_selector_target_sids_v77()
        accepted_receipts = []
        observations = []
        added = 0
        residual_targets = 0
        skipped_semantic_owned = 0
        partial_semantic_phi_targets_recovered_v80f = 0
        skipped_complete = 0
        skipped_identity = 0

        for block, phi in raw_phis:
            join_addr = self._state_flow_addr_v1(block)
            target = getattr(phi, "output", None)
            target_sid = self._state_flow_sid_v1(target)
            inputs = list(getattr(phi, "inputs", []) or [])
            join_node = self._state_flow_cfg_node_v1(join_addr)
            pred_addrs = sorted({
                self._state_flow_addr_v1(pred)
                for pred in (list(self._predecessors(join_node) or []) if join_node is not None else [])
                if self._state_flow_addr_v1(pred) is not None
            }, key=str)
            pred_set = set(pred_addrs)
            key = (join_addr, target_sid)
            fixed = dict(fixed_by_target.get(key) or {})
            fixed_records_v80f = list(
                fixed_records_by_target_v80f.get(key) or []
            )
            residual_preds = pred_set - set(fixed)
            unresolved_preds = set(explicit_unresolved.get(key) or set())
            fixed_binding_contract_receipts_v80g = []
            fixed_edges_exact_v80f = bool(fixed)
            if fixed_edges_exact_v80f:
                for item in fixed_records_v80f:
                    accepted_v80g, receipt_v80g = (
                        self._state_flow_v37_binding_is_exact_resolved_v80g(
                            item,
                            expected_join=join_addr,
                            predecessor_set=pred_set,
                        )
                    )
                    fixed_binding_contract_receipts_v80g.append(
                        receipt_v80g
                    )
                    if not accepted_v80g:
                        fixed_edges_exact_v80f = False
            partial_semantic_phi_completion_v80f = bool(
                target_sid in original_phi_targets
                and not (residual_preds & unresolved_preds)
                and fixed_edges_exact_v80f
                and 0 < len(fixed) < len(pred_set)
                and set(fixed).issubset(pred_set)
                and residual_preds
            )

            base = {
                "kind": "residual_phi_obligation_receipt_v79",
                "schema": "residual_phi_obligation_receipt_v1",
                "join_addr": join_addr,
                "target_sid": target_sid,
                "input_count": len(inputs),
                "predecessor_count": len(pred_addrs),
                "fixed_predecessors": sorted(fixed, key=str),
                "residual_predecessors": sorted(residual_preds, key=str),
                "authority": "PALSGL_v79_residual_MULTIEQUAL_definition_reachability_capacity_matching",
                "input_order_used": False,
                "successor_order_used": False,
                "producer_semantic_phi_present": target_sid in original_phi_targets,
                "partial_semantic_phi_completion_candidate_v80f": (
                    partial_semantic_phi_completion_v80f
                ),
                "fixed_edge_record_count_v80f": len(fixed_records_v80f),
                "fixed_edges_exact_v80f": fixed_edges_exact_v80f,
                "fixed_binding_contract_receipts_v80g": list(
                    fixed_binding_contract_receipts_v80g
                ),
                "v37_binding_contract_recognition_version_v80g": (
                    getattr(
                        self,
                        "mars_v37_binding_contract_recognition_version_v80g",
                        "v80g_mars_v37_binding_contract_recognition_v1",
                    )
                ),
                "partial_semantic_phi_completion_version_v80f": (
                    getattr(
                        self,
                        "mars_partial_semantic_phi_completion_version_v80f",
                        "v80f_mars_partial_semantic_phi_completion_v1",
                    )
                ),
                "resolved_fixed_binding_index_version_v80i": (
                    getattr(
                        self,
                        "mars_resolved_fixed_binding_index_version_v80i",
                        "v80i_mars_resolved_fixed_binding_index_v1",
                    )
                ),
                "fixed_binding_index_receipts_v80i": [
                    receipt
                    for receipt in fixed_binding_index_receipts_v80i
                    if receipt.get("target_sid") == target_sid
                ],
                "nonfixed_source_observations_v80i": [
                    observation
                    for observation in nonfixed_source_observations_v80i
                    if observation.get("target_sid") == target_sid
                ],
                "blocked_fixed_index_records_v80i": list(
                    blocked_fixed_index_targets_v80i.get(key) or []
                ),
            }
            if blocked_fixed_index_targets_v80i.get(key):
                skipped_semantic_owned += 1
                observations.append({
                    **base,
                    "status": "observed_unresolved",
                    "reason": (
                        "fixed_binding_index_contains_invalid_resolved_or_"
                        "order_derived_authority_v80i"
                    ),
                    "blocked_records_v80i": list(
                        blocked_fixed_index_targets_v80i.get(key) or []
                    ),
                    "authoritative": False,
                })
                continue
            if join_addr is None or target_sid is None or not pred_set:
                observations.append({
                    **base,
                    "status": "observed_unresolved",
                    "reason": "residual_phi_cfg_or_target_incomplete",
                    "authoritative": False,
                })
                continue
            if not residual_preds:
                skipped_complete += 1
                continue
            if target_sid in original_phi_targets and not (
                residual_preds & unresolved_preds
            ):
                if not partial_semantic_phi_completion_v80f:
                    skipped_semantic_owned += 1
                    observations.append({
                        **base,
                        "status": "semantic_owner_retained",
                        "reason": (
                            "producer_owned_phi_has_no_explicit_residual_"
                            "obligation_or_exact_partial_coverage_v80f"
                        ),
                        "authoritative": False,
                    })
                    continue
                partial_semantic_phi_targets_recovered_v80f += 1
                observations.append({
                    **base,
                    "status": "partial_semantic_phi_completion_admitted_v80f",
                    "reason": (
                        "exact_resolved_predecessor_subset_plus_"
                        "remaining_CFG_predecessors"
                    ),
                    "fixed_source_map": dict(fixed),
                    "authoritative": True,
                    "input_order_used": False,
                    "successor_order_used": False,
                    "ordinal_fallback_used": False,
                })

            residual_targets += 1
            # Remove one raw input for each fixed source SID.  This is multiset
            # subtraction only; no input position is associated with a CFG edge.
            residual_inputs = list(inputs)
            for fixed_sid in fixed.values():
                for index, incoming in enumerate(residual_inputs):
                    if self._state_flow_sid_v1(incoming) == fixed_sid:
                        residual_inputs.pop(index)
                        break
            capacity_evidence_v80e = None
            capacity_match_v80e = False
            equal_cardinality_capacity_fallback_v80h = False
            if len(residual_inputs) != len(residual_preds):
                source_map, reason, capacity_evidence_v80e = (
                    self._state_flow_path_expanded_source_map_v80e(
                        inputs,
                        residual_preds,
                        fixed,
                        target,
                        join_addr,
                        formula_nodes,
                        raw_definition_blocks,
                    )
                )
                explored = int(
                    (capacity_evidence_v80e or {}).get(
                        "solutions_explored", 0
                    )
                    or 0
                )
                candidate_evidence = list(
                    (capacity_evidence_v80e or {}).get(
                        "source_inventory", []
                    )
                    or []
                )
                capacity_match_v80e = source_map is not None
                if source_map is None:
                    observations.append({
                        **base,
                        "status": "observed_unresolved",
                        "reason": reason,
                        "residual_input_count": len(residual_inputs),
                        "candidate_evidence": candidate_evidence,
                        "path_expanded_capacity_evidence_v80e": (
                            capacity_evidence_v80e
                        ),
                        "matching_solutions_explored": explored,
                        "ordinal_fallback_permitted": False,
                        "authoritative": False,
                    })
                    continue
            else:
                candidate_items = []
                candidate_evidence = []
                for incoming in residual_inputs:
                    source_sid = self._state_flow_sid_v1(incoming)
                    definitions = (
                        self._state_flow_defining_block_candidates_v78(
                            incoming, formula_nodes, raw_definition_blocks
                        )
                    )
                    candidates = set()
                    exact = {
                        addr for addr in definitions
                        if addr in residual_preds
                    }
                    candidates |= exact
                    if not candidates:
                        for pred_addr in residual_preds:
                            for definition in definitions:
                                if definition == join_addr and (
                                    source_sid == target_sid
                                    or self._state_flow_same_storage_v78(
                                        target, incoming
                                    )
                                ):
                                    candidates.add(pred_addr)
                                    continue
                                if self._state_flow_reaches_addr_v79(
                                    definition,
                                    pred_addr,
                                    stop_addr=join_addr,
                                ):
                                    candidates.add(pred_addr)
                    if not candidates and (
                        source_sid == target_sid
                        or self._state_flow_same_storage_v78(
                            target, incoming
                        )
                    ):
                        candidates = set(residual_preds)
                    candidate_items.append({
                        "source_sid": source_sid,
                        "candidates": sorted(candidates, key=str),
                    })
                    candidate_evidence.append({
                        "source_sid": source_sid,
                        "defining_block_candidates": definitions,
                        "admissible_predecessors": sorted(
                            candidates, key=str
                        ),
                    })

                source_map, reason, explored = (
                    self._state_flow_unique_source_map_v79(
                        candidate_items, residual_preds
                    )
                )
                strict_failure_reason_v79 = (
                    reason if source_map is None else None
                )
                strict_candidate_evidence_v79 = (
                    list(candidate_evidence)
                    if source_map is None else []
                )
                strict_solutions_explored_v79 = (
                    explored if source_map is None else 0
                )
                if (
                    source_map is None
                    and target_sid in original_phi_targets
                    and bool(residual_preds)
                    and set(residual_preds).issubset(
                        set(unresolved_preds)
                    )
                ):
                    (
                        fallback_map_v80h,
                        fallback_reason_v80h,
                        fallback_evidence_v80h,
                    ) = self._state_flow_path_expanded_source_map_v80e(
                        inputs,
                        residual_preds,
                        fixed,
                        target,
                        join_addr,
                        formula_nodes,
                        raw_definition_blocks,
                    )
                    if fallback_map_v80h is not None:
                        source_map = fallback_map_v80h
                        reason = fallback_reason_v80h
                        capacity_evidence_v80e = dict(
                            fallback_evidence_v80h or {}
                        )
                        capacity_evidence_v80e[
                            "equal_cardinality_fallback_v80h"
                        ] = True
                        capacity_evidence_v80e[
                            "strict_failure_reason_v79"
                        ] = strict_failure_reason_v79
                        capacity_evidence_v80e[
                            "strict_candidate_evidence_v79"
                        ] = strict_candidate_evidence_v79
                        capacity_evidence_v80e[
                            "strict_solutions_explored_v79"
                        ] = strict_solutions_explored_v79
                        capacity_evidence_v80e[
                            "explicit_unresolved_predecessors_v80h"
                        ] = sorted(
                            set(unresolved_preds), key=str
                        )
                        capacity_evidence_v80e[
                            "residual_predecessors_v80h"
                        ] = sorted(
                            set(residual_preds), key=str
                        )
                        capacity_evidence_v80e[
                            "fallback_authority_v80h"
                        ] = (
                            "exact_GraphBuilder_v37_unresolved_edge_set_"
                            "plus_v80e_grouped_capacity_unique_map"
                        )
                        explored = int(
                            capacity_evidence_v80e.get(
                                "solutions_explored", 0
                            )
                            or 0
                        )
                        candidate_evidence = list(
                            capacity_evidence_v80e.get(
                                "source_inventory", []
                            )
                            or []
                        )
                        capacity_match_v80e = True
                        equal_cardinality_capacity_fallback_v80h = True
                    else:
                        capacity_evidence_v80e = dict(
                            fallback_evidence_v80h or {}
                        )
                        capacity_evidence_v80e[
                            "equal_cardinality_fallback_v80h"
                        ] = True
                        capacity_evidence_v80e[
                            "strict_failure_reason_v79"
                        ] = strict_failure_reason_v79
                        capacity_evidence_v80e[
                            "fallback_failure_reason_v80h"
                        ] = fallback_reason_v80h

                if source_map is None:
                    observations.append({
                        **base,
                        "status": "observed_unresolved",
                        "reason": strict_failure_reason_v79 or reason,
                        "candidate_evidence": (
                            strict_candidate_evidence_v79
                            or candidate_evidence
                        ),
                        "strict_matching_solutions_explored_v79": (
                            strict_solutions_explored_v79
                        ),
                        "equal_cardinality_capacity_fallback_v80h": (
                            bool(capacity_evidence_v80e)
                        ),
                        "path_expanded_capacity_evidence_v80e": (
                            capacity_evidence_v80e
                        ),
                        "matching_solutions_explored": explored,
                        "ordinal_fallback_permitted": False,
                        "authoritative": False,
                    })
                    continue

            transition_class = (
                "value_selector_phi" if target_sid in selector_sids
                else "phi_transition"
            )
            for pred_addr, source_sid in sorted(source_map.items(), key=lambda item: str(item[0])):
                incoming = next(
                    (value for value in residual_inputs
                     if self._state_flow_sid_v1(value) == source_sid),
                    None,
                )
                identity_candidate_v80d = bool(
                    transition_class != "value_selector_phi"
                    and incoming is not None
                    and self._state_flow_same_storage_v78(target, incoming)
                )
                if identity_candidate_v80d:
                    # v80d: same-storage is evidence, not an executable
                    # disposition.  SGL must transport the exact transition
                    # and occurrence placement; PALPHIfolder owns the final
                    # assignment-versus-no-op decision after epoch, temporal,
                    # cyclic, source-proof, and concrete-storage analysis.
                    skipped_identity += 1
                quad = (pred_addr, join_addr, target_sid, source_sid)
                if quad in existing_quads:
                    continue
                producer_reason = "residual_phi_definition_reachability_capacity_matching_v79"
                producer_transition_id = (
                    join_addr, pred_addr, target_sid, source_sid, producer_reason
                )
                record = {
                    "kind": "phi_predecessor_binding_v79_residual_closure",
                    "schema": "phi_predecessor_binding_v37_compatible",
                    "status": "resolved",
                    "pred_addr": pred_addr,
                    "join_addr": join_addr,
                    "edge_identity": (pred_addr, join_addr),
                    "target_sid": target_sid,
                    "source_sid": source_sid,
                    "transition_id": producer_transition_id,
                    "id": producer_transition_id,
                    "id_schema": "semantic_phi_predecessor_transition_v1",
                    "reason": producer_reason,
                    "consumer_transition_class": transition_class,
                    "target_is_value_selector_phi": transition_class == "value_selector_phi",
                    "identity_candidate_v80d": identity_candidate_v80d,
                    "identity_candidate_reason_v80d": (
                        "source_target_same_storage_candidate"
                        if identity_candidate_v80d else None
                    ),
                    "identity_decision_authority": "PALPHIfolder",
                    "identity_candidate_is_terminal_disposition": False,
                    "partial_semantic_phi_completion_v80f": (
                        partial_semantic_phi_completion_v80f
                    ),
                    "partial_semantic_phi_fixed_source_map_v80f": (
                        dict(fixed)
                        if partial_semantic_phi_completion_v80f else None
                    ),
                    "path_expanded_capacity_match_v80e": (
                        capacity_match_v80e
                    ),
                    "equal_cardinality_capacity_fallback_v80h": (
                        equal_cardinality_capacity_fallback_v80h
                    ),
                    "path_expanded_capacity_evidence_v80e": (
                        capacity_evidence_v80e
                        if capacity_match_v80e else None
                    ),
                    "defining_block": pred_addr,
                    "edge_identity_frozen": True,
                    "authority": base["authority"],
                    "late_phi_obligation_v78": True,
                    "residual_phi_obligation_v79": True,
                    "input_order_used": False,
                    "successor_order_used": False,
                }
                source_records.append(record)
                existing_quads.add(quad)
                fixed_by_target.setdefault(key, {})[pred_addr] = source_sid
                receipt = {
                    **base,
                    "status": "accepted",
                    "pred_addr": pred_addr,
                    "source_sid": source_sid,
                    "transition_id": list(producer_transition_id),
                    "consumer_transition_class": transition_class,
                    "identity_candidate_v80d": identity_candidate_v80d,
                    "identity_candidate_reason_v80d": (
                        "source_target_same_storage_candidate"
                        if identity_candidate_v80d else None
                    ),
                    "identity_decision_authority": "PALPHIfolder",
                    "identity_candidate_is_terminal_disposition": False,
                    "partial_semantic_phi_completion_v80f": (
                        partial_semantic_phi_completion_v80f
                    ),
                    "partial_semantic_phi_fixed_source_map_v80f": (
                        dict(fixed)
                        if partial_semantic_phi_completion_v80f else None
                    ),
                    "path_expanded_capacity_match_v80e": (
                        capacity_match_v80e
                    ),
                    "equal_cardinality_capacity_fallback_v80h": (
                        equal_cardinality_capacity_fallback_v80h
                    ),
                    "path_expanded_capacity_evidence_v80e": (
                        capacity_evidence_v80e
                        if capacity_match_v80e else None
                    ),
                    "matching_authority": reason,
                    "matching_solutions_explored": explored,
                    "ordinal_fallback_permitted": False,
                    "authoritative": True,
                }
                accepted_receipts.append(receipt)
                added += 1

        audit = {
            "kind": "residual_phi_obligation_closure_verified_v79",
            "schema": "residual_phi_obligation_closure_audit_v1",
            "version": getattr(self, "mars_residual_phi_typed_edge_bridge_version_v79", "v79_mars_residual_phi_and_typed_edge_bridge_v1"),
            "raw_multiequal_ops": len(raw_phis),
            "producer_semantic_phi_targets": len(original_phi_targets),
            "residual_targets_considered": residual_targets,
            "added_transition_obligations": added,
            "already_complete_phi_targets": skipped_complete,
            "producer_owned_phi_targets_skipped": skipped_semantic_owned,
            "partial_semantic_phi_targets_recovered_v80f": (
                partial_semantic_phi_targets_recovered_v80f
            ),
            "statusless_exact_v37_bindings_recognized_v80g": sum(
                1
                for receipt in observations + accepted_receipts
                for fixed_receipt in list(
                    receipt.get(
                        "fixed_binding_contract_receipts_v80g", []
                    ) or []
                )
                if fixed_receipt.get("status") == "accepted"
                and fixed_receipt.get("recognition_mode")
                == "statusless_exact_v37_binding_contract"
            ),
            "v37_binding_contract_recognition_version_v80g": (
                getattr(
                    self,
                    "mars_v37_binding_contract_recognition_version_v80g",
                    "v80g_mars_v37_binding_contract_recognition_v1",
                )
            ),
            "partial_semantic_phi_completion_version_v80f": (
                getattr(
                    self,
                    "mars_partial_semantic_phi_completion_version_v80f",
                    "v80f_mars_partial_semantic_phi_completion_v1",
                )
            ),
            "identity_edges_not_executable": 0,
            "identity_candidates_transported_v80d": skipped_identity,
            "path_expanded_capacity_transitions_v80e": sum(
                1 for receipt in accepted_receipts
                if receipt.get("path_expanded_capacity_match_v80e")
            ),
            "equal_cardinality_capacity_transitions_v80h": sum(
                1 for receipt in accepted_receipts
                if receipt.get(
                    "equal_cardinality_capacity_fallback_v80h"
                )
            ),
            "fixed_bindings_accepted_v80i": sum(
                1 for receipt in fixed_binding_index_receipts_v80i
                if receipt.get("status") == "accepted"
            ),
            "nonfixed_source_observations_retained_v80i": len(
                nonfixed_source_observations_v80i
            ),
            "fixed_index_targets_blocked_v80i": len(
                blocked_fixed_index_targets_v80i
            ),
            "unresolved_source_sid_records_excluded_from_fixed_index_v80i": sum(
                1
                for observation in nonfixed_source_observations_v80i
                if observation.get("source_sid") is not None
                and observation.get("record_status") in {
                    "unresolved",
                    "partially_resolved",
                    "observed_unresolved",
                    "rejected",
                }
            ),
            "resolved_fixed_binding_index_version_v80i": (
                getattr(
                    self,
                    "mars_resolved_fixed_binding_index_version_v80i",
                    "v80i_mars_resolved_fixed_binding_index_v1",
                )
            ),
            "equal_cardinality_capacity_fallback_version_v80h": (
                getattr(
                    self,
                    "mars_equal_cardinality_capacity_fallback_version_v80h",
                    "v80h_mars_equal_cardinality_capacity_fallback_v1",
                )
            ),
            "path_expanded_phi_capacity_version_v80e": (
                getattr(
                    self,
                    "mars_path_expanded_phi_capacity_version_v80e",
                    "v80e_mars_path_expanded_phi_capacity_v1",
                )
            ),
            "identity_candidate_transport_version_v80d": (
                getattr(
                    self,
                    "mars_identity_candidate_transport_version_v80d",
                    "v80d_mars_identity_candidate_transport_v1",
                )
            ),
            "identity_decision_authority": "PALPHIfolder",
            "same_storage_alone_suppresses_transition": False,
            "non_authoritative_observations": len(observations),
            "ordinal_fallback_used": False,
            "observations": list(observations),
        }
        # Preserve v78 attribute names as compatibility aliases while publishing
        # the narrower v79 authority separately.
        self.late_phi_obligation_receipts_v78 = list(accepted_receipts)
        self.late_phi_obligation_failures_v78 = []
        self.late_phi_obligation_audit_v78 = dict(audit)
        self.residual_phi_obligation_receipts_v79 = list(accepted_receipts)
        self.residual_phi_obligation_observations_v79 = list(observations)
        self.residual_phi_obligation_audit_v79 = dict(audit)
        self.func.sgl_late_phi_obligation_receipts_v78 = list(accepted_receipts)
        self.func.sgl_late_phi_obligation_failures_v78 = []
        self.func.sgl_late_phi_obligation_audit_v78 = dict(audit)
        self.func.sgl_residual_phi_obligation_receipts_v79 = list(accepted_receipts)
        self.func.sgl_residual_phi_obligation_observations_v79 = list(observations)
        self.func.sgl_residual_phi_obligation_audit_v79 = dict(audit)
        self.func.sgl_fixed_binding_index_receipts_v80i = list(
            fixed_binding_index_receipts_v80i
        )
        self.func.sgl_nonfixed_source_observations_v80i = list(
            nonfixed_source_observations_v80i
        )
        self.func.sgl_mars_resolved_fixed_binding_index_version_v80i = (
            getattr(
                self,
                "mars_resolved_fixed_binding_index_version_v80i",
                "v80i_mars_resolved_fixed_binding_index_v1",
            )
        )
        return source_records

    def _state_flow_variable_index_v1(self, formula_nodes, phi_nodes):
        by_sid = {}

        def retain(value):
            if value is None:
                return
            if hasattr(value, "var"):
                value = getattr(value, "var", None)
            sid = self._state_flow_sid_v1(value)
            if sid is not None and sid not in by_sid:
                by_sid[sid] = value

        for node in formula_nodes.values():
            retain(getattr(node, "var", None))
            for inp in list(
                getattr(node, "inputs", None)
                or getattr(getattr(node, "op", None), "inputs", None)
                or []
            ):
                retain(inp)
        for phi in phi_nodes:
            retain(getattr(phi, "output", None))
            for inp in list(getattr(phi, "inputs", []) or []):
                retain(inp)

        raw_vars = getattr(self.func, "vars", {}) or {}
        values = raw_vars.values() if isinstance(raw_vars, dict) else raw_vars
        for value in list(values or []):
            retain(value)
        for value in list(getattr(self.func, "parameters", []) or []):
            retain(value)
        return by_sid

    def _state_flow_snapshot_sids_v1(self):
        out = set()
        fields = (
            "sid",
            "snapshot_sid",
            "copy_output_sid",
            "output_sid",
            "source_sid",
            "target_sid",
            "derived_result_sid",
        )
        for record in list(self.snapshot_copy_contracts_v35.values()):
            if not isinstance(record, dict):
                continue
            for field in fields:
                sid = self._state_flow_sid_v1(record.get(field))
                if sid is not None:
                    out.add(sid)
        out.update(
            str(sid)
            for sid in set(self.null_emperor_derived_result_sids_v67 or set())
            if sid is not None
        )
        return out

    def _state_flow_loop_memberships_v1(self, addr):
        memberships = []
        for header, members in dict(self.loop_nodes or {}).items():
            member_addrs = {
                self._state_flow_addr_v1(node)
                for node in set(members or set())
            }
            if addr in member_addrs:
                header_addr = self._state_flow_addr_v1(header)
                if header_addr is not None:
                    memberships.append(header_addr)
        return sorted(set(memberships))

    def _state_flow_definition_role_v1(self, node, var, block_addr):
        if bool(getattr(var, "is_constant", False)):
            return "constant_native_seed"
        if bool(
            getattr(var, "is_parameter", False)
            or getattr(var, "is_param", False)
            or getattr(var, "is_input_varnode", False)
        ):
            return "parameter_or_ABI_entry_value"
        if bool(
            getattr(node, "is_phi", False)
            or getattr(node, "opcode", None) == "MULTIEQUAL"
        ):
            # The PHI output is a merge definition, not itself proof of an
            # entry seed.  Exact incoming edge receipts add PHI_entry_seed or
            # backedge roles later without promoting either to family owner.
            return "phi_merge_definition"

        latch_addrs = {
            self._state_flow_addr_v1(latch)
            for values in dict(self.loop_latches or {}).values()
            for latch in list(values or [])
        }
        if block_addr in latch_addrs:
            return "backedge_update"

        cfg_node = self._state_flow_cfg_node_v1(block_addr)
        entry = getattr(self.cfg, "entry", None)
        if (
            cfg_node is not None
            and entry is not None
            and entry in set(getattr(cfg_node, "dominators", set()) or set())
        ):
            return "dominating_local_definition"
        return "ordinary_predecessor_transition"

    def _state_flow_definition_receipt_v1(
        self, sid, node, var, snapshot_sids
    ):
        opcode = getattr(node, "opcode", None) if node is not None else None
        block_addr = (
            self._state_flow_addr_v1(getattr(node, "block", None))
            if node is not None else None
        )
        if block_addr is None and node is not None:
            block_addr = self._state_flow_addr_v1(node)

        is_parameter = bool(
            getattr(var, "is_parameter", False)
            or getattr(var, "is_param", False)
            or getattr(var, "is_input_varnode", False)
        )
        is_constant = bool(getattr(var, "is_constant", False))
        has_formula = node is not None

        if has_formula:
            source_authority = "PALSemanticGraphBuilder.FormulaNode"
            definition_kind = (
                "phi_definition"
                if bool(
                    getattr(node, "is_phi", False)
                    or opcode == "MULTIEQUAL"
                )
                else "pcode_formula_definition"
            )
        elif is_parameter:
            source_authority = "PALlibrary.PALVariable.parameter_or_input_flag"
            definition_kind = "function_entry_value"
        elif is_constant:
            source_authority = "PALlibrary.PALVariable.constant_flag"
            definition_kind = "constant_value"
        else:
            source_authority = "explicit_upstream_definition_absence"
            definition_kind = "unresolved_definition"

        accepted = []
        rejected = []
        if sid is not None:
            accepted.append("canonical_sid_present")
        else:
            rejected.append("canonical_sid_present")
        if has_formula or is_parameter or is_constant:
            accepted.append("definition_authority_present")
        else:
            rejected.append("definition_authority_present")
        if block_addr is not None or is_parameter or is_constant:
            accepted.append("defining_region_or_entry_class_present")
        else:
            rejected.append("defining_region_or_entry_class_present")

        status = "accepted" if not rejected else "unresolved"
        cfg_node = self._state_flow_cfg_node_v1(block_addr)
        dominators = sorted({
            self._state_flow_addr_v1(item)
            for item in set(getattr(cfg_node, "dominators", set()) or set())
            if self._state_flow_addr_v1(item) is not None
        })

        width_bits = (
            getattr(node, "width_bits", None)
            if node is not None else None
        ) or getattr(var, "width_bits", None)
        width_bytes = (
            getattr(node, "width_bytes", None)
            if node is not None else None
        ) or getattr(var, "width_bytes", None) or getattr(var, "size", None)
        type_value = (
            getattr(var, "declared_type_name", None)
            or getattr(var, "declared_type", None)
            or getattr(var, "var_type", None)
        )
        protected_flags = {
            "temporal_snapshot": sid in snapshot_sids,
            "parameter_or_ABI_entry": is_parameter,
            "persistent_storage": bool(
                getattr(var, "is_persistent", False)
                or getattr(var, "is_global", False)
            ),
            "explicit_protected_state": bool(
                getattr(var, "is_protected_state", False)
                or getattr(node, "is_protected_state", False)
            ),
        }

        op = getattr(node, "op", None) if node is not None else None
        defining_address = None
        for candidate in (
            getattr(op, "address", None),
            getattr(op, "addr", None),
            getattr(op, "op_id", None),
            block_addr,
        ):
            if isinstance(candidate, (int, str)):
                defining_address = candidate
                break

        key = "definition-v1:%s" % sid
        return {
            "kind": "state_flow_definition_receipt_v1",
            "schema": "state_flow_definition_receipt_v1",
            "receipt_key": key,
            "sid": sid,
            "status": status,
            "definition_kind": definition_kind,
            "definition_role": self._state_flow_definition_role_v1(
                node, var, block_addr
            ),
            "opcode": opcode,
            "defining_block": block_addr,
            "defining_address": defining_address,
            "source_authority": source_authority,
            "width_bits": width_bits,
            "width_bytes": width_bytes,
            "type_name": self._state_flow_type_text_v1(type_value),
            "dominance_region": {
                "dominator_blocks": dominators,
                "loop_headers": self._state_flow_loop_memberships_v1(
                    block_addr
                ),
            },
            "protected_state_flags": protected_flags,
            "observed_epoch_roles": [],
            "input_order_used": False,
            "successor_order_used": False,
            "audit": {
                "status": status,
                "accepted_gates": accepted,
                "rejected_gates": rejected,
                "producer_authority": source_authority,
            },
        }

    def _state_flow_add_audit_receipt_v1(self, record):
        receipt_key = record.get("receipt_key")
        audit = dict(record.get("audit") or {})
        audit_record = {
            "kind": "state_flow_record_audit_v1",
            "receipt_key": receipt_key,
            "receipt_kind": record.get("kind"),
            "status": audit.get("status", record.get("status")),
            "accepted_gates": list(audit.get("accepted_gates") or []),
            "rejected_gates": list(audit.get("rejected_gates") or []),
            "producer_authority": audit.get(
                "producer_authority",
                record.get("source_authority"),
            ),
        }
        prior = self.state_flow_audit_receipts_by_key_v1.get(receipt_key)
        if prior is not None and prior != audit_record:
            self.state_flow_failures_v1.append({
                "kind": "state_flow_conflicting_audit_receipt_v1",
                "receipt_key": receipt_key,
            })
            return prior
        if prior is None:
            self.state_flow_audit_receipts_v1.append(audit_record)
            self.state_flow_audit_receipts_by_key_v1[
                receipt_key
            ] = audit_record
        return audit_record

    def _compile_state_flow_definitions_v1(self):
        formula_nodes, phi_nodes = self._state_flow_formula_and_phi_nodes_v1()
        variables = self._state_flow_variable_index_v1(
            formula_nodes, phi_nodes
        )
        node_by_sid = {}
        observed_sids = set(variables)
        for key, node in formula_nodes.items():
            sid = self._state_flow_sid_v1(node)
            if sid is None:
                sid = self._state_flow_sid_v1(key)
            if sid is None:
                continue
            observed_sids.add(sid)
            node_by_sid[sid] = node

        for rec in list(
            getattr(self.func, "phi_predecessor_bindings_v37", []) or []
        ):
            if not isinstance(rec, dict):
                continue
            for field in ("target_sid", "source_sid"):
                sid = self._state_flow_sid_v1(rec.get(field))
                if sid is not None:
                    observed_sids.add(sid)

        snapshot_sids = self._state_flow_snapshot_sids_v1()
        for sid in sorted(observed_sids):
            record = self._state_flow_definition_receipt_v1(
                sid,
                node_by_sid.get(sid),
                variables.get(sid),
                snapshot_sids,
            )
            self.state_flow_definition_receipts_v1.append(record)
            self.state_flow_definition_receipts_by_sid_v1[sid] = record
            self._state_flow_add_audit_receipt_v1(record)

    def _state_flow_edge_pair_v1(self, record):
        if not isinstance(record, dict):
            return None
        edge_id = (
            record.get("edge_identity")
            or record.get("edge_id")
            or []
        )
        if isinstance(edge_id, (tuple, list)) and len(edge_id) == 2:
            return (edge_id[0], edge_id[1])
        pred = record.get("pred_addr", record.get("src_addr"))
        succ = record.get("join_addr", record.get("dst_addr"))
        if pred is None or succ is None:
            return None
        return (pred, succ)

    def _state_flow_loop_edge_sets_v1(self):
        entry_edges = set()
        backedges = set()
        exit_edges = set()
        for header, members in dict(self.loop_nodes or {}).items():
            header_addr = self._state_flow_addr_v1(header)
            member_set = set(members or set())
            member_addrs = {
                self._state_flow_addr_v1(node) for node in member_set
            }
            for node in member_set:
                dst_addr = self._state_flow_addr_v1(node)
                for edge in list(getattr(node, "in_edges", []) or []):
                    src_addr = self._state_flow_addr_v1(
                        getattr(edge, "src", None)
                    )
                    if src_addr not in member_addrs:
                        entry_edges.add((src_addr, dst_addr))
                for edge in list(getattr(node, "out_edges", []) or []):
                    succ_addr = self._state_flow_addr_v1(
                        getattr(edge, "dst", None)
                    )
                    if succ_addr not in member_addrs:
                        exit_edges.add((dst_addr, succ_addr))
            for latch in list(
                dict(self.loop_latches or {}).get(header, []) or []
            ):
                backedges.add(
                    (self._state_flow_addr_v1(latch), header_addr)
                )
        return entry_edges, backedges, exit_edges

    def _compile_state_flow_loop_regions_v1(self):
        cfg_has_regions = isinstance(
            getattr(self.cfg, "loop_nodes", None), dict
        )
        producer = (
            "FunctionCFG.loop_nodes_and_loop_latches"
            if cfg_has_regions else
            "PALSGL_natural_loop_derivation_from_CFG_edges"
        )
        for header in sorted(
            set(self.loop_headers or set()),
            key=lambda item: str(self._state_flow_addr_v1(item)),
        ):
            header_addr = self._state_flow_addr_v1(header)
            members = set(dict(self.loop_nodes or {}).get(header, set()) or set())
            member_addrs = sorted({
                self._state_flow_addr_v1(node)
                for node in members
                if self._state_flow_addr_v1(node) is not None
            })
            latches = list(
                dict(self.loop_latches or {}).get(header, []) or []
            )
            latch_addrs = sorted({
                self._state_flow_addr_v1(node)
                for node in latches
                if self._state_flow_addr_v1(node) is not None
            })
            exit_nodes = set(
                dict(self.loop_exits or {}).get(header, set()) or set()
            )
            exit_addrs = sorted({
                self._state_flow_addr_v1(node)
                for node in exit_nodes
                if self._state_flow_addr_v1(node) is not None
            })

            entry_edges = []
            exit_edges = []
            member_set = set(members)
            for node in members:
                node_addr = self._state_flow_addr_v1(node)
                for edge in list(getattr(node, "in_edges", []) or []):
                    source = getattr(edge, "src", None)
                    if source not in member_set:
                        entry_edges.append([
                            self._state_flow_addr_v1(source),
                            node_addr,
                        ])
                for edge in list(getattr(node, "out_edges", []) or []):
                    target = getattr(edge, "dst", None)
                    if target not in member_set:
                        exit_edges.append([
                            node_addr,
                            self._state_flow_addr_v1(target),
                        ])

            backedges = [
                [latch_addr, header_addr]
                for latch_addr in latch_addrs
            ]
            header_dominates = all(
                header in set(getattr(node, "dominators", set()) or set())
                for node in members
            ) if members else False
            entries_target_header = all(
                len(edge) == 2 and edge[1] == header_addr
                for edge in entry_edges
            )
            reducible = bool(
                header_addr is not None
                and header_addr in member_addrs
                and header_dominates
                and entries_target_header
            )

            accepted = []
            rejected = []
            for gate, passed in (
                ("header_address_present", header_addr is not None),
                ("header_is_loop_member", header_addr in member_addrs),
                ("member_inventory_present", bool(member_addrs)),
                ("latch_or_backedge_present", bool(backedges)),
            ):
                (accepted if passed else rejected).append(gate)
            status = "accepted" if not rejected else "unresolved"
            key = "loop-region-v1:%s" % self._state_flow_addr_token_v1(
                header_addr
            )
            record = {
                "kind": "state_flow_loop_region_receipt_v1",
                "schema": "state_flow_loop_region_receipt_v1",
                "receipt_key": key,
                "header": header_addr,
                "status": status,
                "entry_edges": sorted(
                    self._state_flow_stable_unique_v1(entry_edges),
                    key=repr,
                ),
                "latches": latch_addrs,
                "backedges": backedges,
                "exits": exit_addrs,
                "exit_edges": sorted(
                    self._state_flow_stable_unique_v1(exit_edges),
                    key=repr,
                ),
                "members": member_addrs,
                "region_class": (
                    "reducible_natural_loop"
                    if reducible else
                    "irreducible_or_unresolved"
                ),
                "reducible": reducible,
                "source_authority": producer,
                "input_order_used": False,
                "successor_order_used": False,
                "audit": {
                    "status": status,
                    "accepted_gates": accepted,
                    "rejected_gates": rejected,
                    "producer_authority": producer,
                },
            }
            self.state_flow_loop_region_receipts_v1.append(record)
            self.state_flow_loop_region_receipts_by_header_v1[
                str(header_addr)
            ] = record
            self._state_flow_add_audit_receipt_v1(record)

    def _compile_state_flow_direct_joins_v1(self):
        facts = list(self.cook_emperor_cfg_direct_join_facts_v71 or [])
        owners = list(self.cook_emperor_direct_join_owners_v71 or [])
        for fact in facts:
            pair = self._state_flow_edge_pair_v1(fact)
            if pair is None:
                continue
            matched = [
                owner
                for owner in owners
                if self._state_flow_edge_pair_v1(owner) == pair
            ]
            accepted = [
                "FunctionCFG_edge_identity_frozen"
            ] if self._cook_emperor_fact_is_frozen_v71(fact) else []
            rejected = [] if accepted else [
                "FunctionCFG_edge_identity_frozen"
            ]
            if fact.get("direct_to_join") is True:
                accepted.append("FunctionCFG_direct_to_join")
            else:
                rejected.append("FunctionCFG_direct_to_join")
            if len(matched) == 1:
                accepted.append("exactly_one_typed_structural_owner")
            else:
                rejected.append("exactly_one_typed_structural_owner")
                self.state_flow_failures_v1.append({
                    "kind": "state_flow_direct_join_owner_count_failure_v1",
                    "edge_id": [pair[0], pair[1]],
                    "owner_count": len(matched),
                })
            owner = matched[0] if len(matched) == 1 else {}
            if (
                owner.get("owner_schema")
                == "sgl_direct_join_structural_owner_v1"
            ):
                accepted.append("typed_owner_schema_exact")
            else:
                rejected.append("typed_owner_schema_exact")
            if owner.get("sgl_emits_phi_assignments") is False:
                accepted.append("SGL_emits_no_PHI_assignments")
            else:
                rejected.append("SGL_emits_no_PHI_assignments")
            status = "accepted" if not rejected else "rejected"
            key = "direct-join-v1:%s->%s" % (
                self._state_flow_addr_token_v1(pair[0]),
                self._state_flow_addr_token_v1(pair[1]),
            )
            source_authority = (
                "FunctionCFG_v23_edge_identity_plus_"
                "PALSGL_v71_typed_structural_owner"
            )
            record = {
                "kind": "state_flow_direct_join_receipt_v1",
                "schema": "state_flow_direct_join_receipt_v1",
                "receipt_key": key,
                "edge_id": [pair[0], pair[1]],
                "pred_addr": pair[0],
                "join_addr": pair[1],
                "status": status,
                "FunctionCFG_fact": {
                    "edge_identity_frozen": bool(
                        fact.get("edge_identity_frozen")
                    ),
                    "direct_to_join": bool(fact.get("direct_to_join")),
                    "branch_role": fact.get("branch_role"),
                    "direct_join_owner_kind": fact.get(
                        "direct_join_owner_kind"
                    ),
                    "authority": fact.get("authority"),
                },
                "structural_owner": {
                    "owner_schema": owner.get("owner_schema"),
                    "owner_kind": owner.get("owner_kind"),
                    "owner_node_kind": owner.get("owner_node_kind"),
                    "owner_cfg_addr": owner.get("owner_cfg_addr"),
                    "owner_path": list(owner.get("owner_path") or []),
                    "branch_kind": owner.get("branch_kind"),
                    "sgl_emits_phi_assignments": bool(
                        owner.get("sgl_emits_phi_assignments", False)
                    ),
                },
                "execution_occurrence_owner": {
                    "kind": owner.get("owner_kind"),
                    "node_kind": owner.get("owner_node_kind"),
                    "cfg_addr": owner.get("owner_cfg_addr"),
                    "path": list(owner.get("owner_path") or []),
                },
                "source_authority": source_authority,
                "input_order_used": False,
                "successor_order_used": False,
                "audit": {
                    "status": status,
                    "accepted_gates": accepted,
                    "rejected_gates": rejected,
                    "producer_authority": source_authority,
                },
            }
            self.state_flow_direct_join_receipts_v1.append(record)
            self.state_flow_direct_join_receipts_by_edge_v1[
                "%s->%s" % pair
            ] = record
            self.state_flow_direct_join_receipts_by_tuple_v80[tuple(pair)] = record
            self._state_flow_add_audit_receipt_v1(record)

    def _state_flow_structural_edge_role_v1(
        self, pair, direct_join_record, entry_edges, backedges, exit_edges
    ):
        if direct_join_record is not None:
            owner = dict(
                direct_join_record.get("structural_owner") or {}
            )
            return (
                "direct_join_%s" % (owner.get("owner_kind") or "unresolved"),
                dict(
                    direct_join_record.get(
                        "execution_occurrence_owner"
                    ) or {}
                ),
            )
        if pair in backedges:
            return "backedge_update", {
                "kind": "loop_backedge_edge",
                "cfg_edge": [pair[0], pair[1]],
            }
        if pair in entry_edges:
            return "loop_entry_seed", {
                "kind": "loop_entry_edge",
                "cfg_edge": [pair[0], pair[1]],
            }
        if pair in exit_edges:
            return "loop_exit", {
                "kind": "loop_exit_edge",
                "cfg_edge": [pair[0], pair[1]],
            }
        return "ordinary_predecessor_transition", {
            "kind": "predecessor_edge",
            "cfg_edge": [pair[0], pair[1]],
        }

    def _state_flow_add_definition_epoch_role_v1(
        self, sid, role, pair, relation
    ):
        if sid is None:
            return
        record = self.state_flow_definition_receipts_by_sid_v1.get(str(sid))
        if not isinstance(record, dict):
            return
        observation = {
            "role": role,
            "edge_id": [pair[0], pair[1]],
            "relation": relation,
        }
        values = list(record.get("observed_epoch_roles") or [])
        if observation not in values:
            values.append(observation)
        record["observed_epoch_roles"] = values

    def _state_flow_semantic_region_route_v80k(
        self, pred_addr, join_addr
    ):
        """Resolve a PHI semantic predecessor across one exact loop boundary.

        A PHI predecessor token identifies the value epoch that reaches the
        join.  It is not guaranteed to be a literal one-hop CFG edge.  The
        alpha-four survivor is the exact shape:

            semantic value predecessor 0x10126b
            loop header/exit controller 0x10126f
            post-loop PHI join          0x101281

        v80k admits the semantic transition only when one and only one natural
        loop contains the semantic predecessor and owns one physical exit edge
        directly to the PHI join.  The semantic edge remains the immutable PHI
        token; the physical control edge is transported separately.

        No predecessor, successor, MULTIEQUAL, or occurrence ordinal is used.
        """
        pred_addr = self._state_flow_addr_v1(pred_addr)
        join_addr = self._state_flow_addr_v1(join_addr)
        version = getattr(
            self,
            "mars_semantic_region_transition_transport_version_v80k",
            "v80k_mars_semantic_region_transition_transport_v1",
        )
        base = {
            "kind": "state_flow_semantic_region_transition_v80k",
            "schema": "state_flow_semantic_region_transition_v1",
            "version": version,
            "semantic_edge_id": [pred_addr, join_addr],
            "input_order_used": False,
            "successor_order_used": False,
            "authority": (
                "PALSGL_natural_loop_membership_plus_exact_physical_exit_edge"
            ),
        }
        if pred_addr is None or join_addr is None:
            return {
                **base,
                "status": "rejected",
                "reason": "semantic_edge_endpoint_missing",
                "candidates": [],
            }

        pred_node = self._state_flow_cfg_node_v1(pred_addr)
        join_node = self._state_flow_cfg_node_v1(join_addr)
        if pred_node is None or join_node is None:
            return {
                **base,
                "status": "rejected",
                "reason": "semantic_edge_endpoint_not_in_CFG",
                "candidates": [],
            }

        candidates = []
        for header, raw_members in dict(self.loop_nodes or {}).items():
            members = set(raw_members or set())
            if pred_node not in members or join_node in members:
                continue
            header_addr = self._state_flow_addr_v1(header)
            physical_exits = []
            for member in members:
                member_addr = self._state_flow_addr_v1(member)
                for edge in list(getattr(member, "out_edges", []) or []):
                    dst = getattr(edge, "dst", None)
                    dst_addr = self._state_flow_addr_v1(dst)
                    if dst is join_node or dst_addr == join_addr:
                        physical_exits.append(
                            (member_addr, join_addr)
                        )
            physical_exits = sorted(set(physical_exits), key=str)
            if len(physical_exits) != 1:
                continue

            exit_src = physical_exits[0][0]
            exit_node = self._state_flow_cfg_node_v1(exit_src)
            reachable_inside = False
            if exit_node is pred_node:
                reachable_inside = True
            else:
                work = [pred_node]
                seen = {pred_node}
                while work and not reachable_inside:
                    node = work.pop()
                    for edge in list(getattr(node, "out_edges", []) or []):
                        nxt = getattr(edge, "dst", None)
                        if nxt is exit_node:
                            reachable_inside = True
                            break
                        if nxt is None or nxt in seen or nxt not in members:
                            continue
                        seen.add(nxt)
                        work.append(nxt)
            if not reachable_inside:
                continue

            candidates.append({
                "loop_header": header_addr,
                "physical_control_edge_id": [
                    physical_exits[0][0], physical_exits[0][1]
                ],
                "semantic_predecessor": pred_addr,
                "join_addr": join_addr,
                "member_count": len(members),
                "semantic_predecessor_reaches_exit_inside_region": True,
            })

        if len(candidates) == 1:
            return {
                **base,
                "status": "accepted",
                "reason": (
                    "one_natural_loop_contains_semantic_predecessor_and_"
                    "owns_one_exact_exit_to_join"
                ),
                "loop_header": candidates[0]["loop_header"],
                "physical_control_edge_id": candidates[0][
                    "physical_control_edge_id"
                ],
                "candidates": candidates,
                "semantic_transition_is_literal_CFG_edge": False,
                "placement_owner_kind": "loop_exit_edge",
            }
        return {
            **base,
            "status": "rejected",
            "reason": (
                "no_exact_semantic_region_route"
                if not candidates
                else "multiple_semantic_region_routes"
            ),
            "candidates": candidates,
            "candidate_count": len(candidates),
        }

    def _state_flow_phi_transition_transport_route_v80m(
        self, pred_addr, join_addr
    ):
        """Resolve exact transport authority for one semantic PHI edge.

        v80k established that a semantic PHI predecessor is not always a
        literal one-hop CFG predecessor of the join.  v80l accidentally
        required the literal edge again during conservation admission, which
        vetoed the exact semantic-loop-exit transition v80k was designed to
        carry.

        v80m admits exactly one of two transport forms:
          * the semantic pair is a literal CFG edge; or
          * v80k proves one unique natural-loop region and one physical exit
            edge to the join.

        The semantic transition identity is never rewritten to the physical
        control edge.  The latter is transported as occurrence-owner evidence.
        """
        pred_addr = self._state_flow_addr_v1(pred_addr)
        join_addr = self._state_flow_addr_v1(join_addr)
        edge = (pred_addr, join_addr)
        version = getattr(
            self,
            "mars_phi_conservation_route_alignment_version_v80m",
            "v80m_mars_phi_conservation_route_alignment_v1",
        )
        literal = bool(
            pred_addr is not None
            and join_addr is not None
            and self._state_flow_cfg_edge_exists_v1(pred_addr, join_addr)
        )
        semantic_route = None
        if literal:
            record = {
                "kind": "phi_transition_transport_route_v80m",
                "schema": "phi_transition_transport_route_v1",
                "version": version,
                "status": "accepted",
                "transport_mode": "literal_CFG_edge",
                "semantic_edge_id": [pred_addr, join_addr],
                "physical_control_edge_id": [pred_addr, join_addr],
                "literal_CFG_edge": True,
                "semantic_region_route_v80k": None,
                "input_order_used": False,
                "successor_order_used": False,
                "authority": "PALSGL_exact_literal_CFG_edge_v80m",
            }
        else:
            semantic_route = self._state_flow_semantic_region_route_v80k(
                pred_addr, join_addr
            )
            accepted = bool(
                isinstance(semantic_route, dict)
                and semantic_route.get("status") == "accepted"
                and len(
                    list(semantic_route.get("physical_control_edge_id") or [])
                ) == 2
            )
            record = {
                "kind": "phi_transition_transport_route_v80m",
                "schema": "phi_transition_transport_route_v1",
                "version": version,
                "status": "accepted" if accepted else "rejected",
                "transport_mode": (
                    "semantic_region_transition"
                    if accepted else "unresolved"
                ),
                "semantic_edge_id": [pred_addr, join_addr],
                "physical_control_edge_id": (
                    list(semantic_route.get("physical_control_edge_id") or [])
                    if isinstance(semantic_route, dict) else []
                ),
                "loop_header": (
                    semantic_route.get("loop_header")
                    if isinstance(semantic_route, dict) else None
                ),
                "literal_CFG_edge": False,
                "semantic_region_route_v80k": (
                    dict(semantic_route)
                    if isinstance(semantic_route, dict) else None
                ),
                "reason": (
                    semantic_route.get("reason")
                    if isinstance(semantic_route, dict)
                    else "semantic_region_route_missing"
                ),
                "input_order_used": False,
                "successor_order_used": False,
                "authority": (
                    "PALSGL_v80k_unique_semantic_region_route_consumed_by_v80m"
                    if accepted
                    else "PALSGL_v80m_no_exact_transport_route"
                ),
            }

        key = edge
        prior = self.state_flow_phi_transition_transport_routes_by_edge_v80m.get(
            key
        )
        if prior is None:
            self.state_flow_phi_transition_transport_routes_v80m.append(record)
            self.state_flow_phi_transition_transport_routes_by_edge_v80m[key] = record
        elif prior != record:
            failure = {
                "kind": "phi_transition_transport_route_conflict_v80m",
                "edge_id": [pred_addr, join_addr],
                "first": prior,
                "second": record,
            }
            self.state_flow_failures_v1.append(failure)
            return {**record, "status": "rejected", "conflict": failure}
        return record

    def _state_flow_reconcile_phi_transition_conservation_v80l(
        self, source_records
    ):
        """Conserve uniquely proven PHI transitions across all producer ledgers.

        v80e-v80j repaired individual matching, admission, indexing, and
        precedence gates.  The remaining alpha-four failure showed that a
        source can still disappear between those local decisions.

        v80l establishes one final invariant before edge-epoch publication:

          exact semantic PHI predecessor set
          == exact uniquely solved predecessor/source map
          == resolved canonical source-record set

        Only an edge explicitly left unresolved by the v37 producer contract
        may be completed.  Existing resolved bindings must agree with the
        unique whole-PHI map.  No input ordinal, predecessor order, successor
        order, or positional fallback is admitted.
        """
        records = [
            dict(item) if isinstance(item, dict) else item
            for item in list(source_records or [])
        ]
        receipts = []
        observations = []
        failures = []

        original_phis = list(self._state_flow_original_phi_nodes_v79() or [])
        phi_by_target = {}
        for phi in original_phis:
            target_sid = self._state_flow_sid_v1(
                getattr(phi, "output", None)
                if getattr(phi, "output", None) is not None
                else getattr(phi, "output_sid", None)
            )
            if target_sid is not None:
                phi_by_target.setdefault(target_sid, []).append(phi)

        formula_nodes = dict(self._formula_nodes() or {})
        raw_definition_blocks = {}
        raw_phis = []
        for block in list(getattr(self.func, "blocks", []) or []):
            block_addr = self._state_flow_addr_v1(block)
            for op in list(getattr(block, "ops", []) or []):
                output = getattr(op, "output", None)
                output_sid = self._state_flow_sid_v1(output)
                if output_sid is not None and block_addr is not None:
                    raw_definition_blocks.setdefault(
                        output_sid, set()
                    ).add(block_addr)
                if str(
                    getattr(op, "opcode", "") or ""
                ).upper() == "MULTIEQUAL":
                    raw_phis.append((block, op))

        selector_sids = self._occurrence_value_selector_target_sids_v77()
        added = 0
        eligible_targets = 0

        for block, raw_phi in raw_phis:
            join_addr = self._state_flow_addr_v1(block)
            target = getattr(raw_phi, "output", None)
            target_sid = self._state_flow_sid_v1(target)
            inputs = list(getattr(raw_phi, "inputs", []) or [])
            matching_phis = list(phi_by_target.get(target_sid) or [])
            if len(matching_phis) != 1:
                continue
            semantic_phi = matching_phis[0]
            contract = getattr(
                semantic_phi, "predecessor_linkage_contract_v37", None
            )
            if not isinstance(contract, dict):
                continue

            join_node = self._state_flow_cfg_node_v1(join_addr)
            literal_cfg_predecessors = sorted({
                self._state_flow_addr_v1(pred)
                for pred in (
                    list(self._predecessors(join_node) or [])
                    if join_node is not None else []
                )
                if self._state_flow_addr_v1(pred) is not None
            }, key=str)
            literal_cfg_predecessor_set = set(literal_cfg_predecessors)
            unresolved_predecessors = {
                pair[0]
                for item in list(contract.get("unresolved_edges") or [])
                for pair in [self._state_flow_edge_pair_v1(item)]
                if pair is not None
                and pair[1] == join_addr
            }

            existing_by_pred = {}
            existing_records_by_pred = {}
            conflicts = []
            for record in records:
                if not isinstance(record, dict):
                    continue
                pair = self._state_flow_edge_pair_v1(record)
                if pair is None or pair[1] != join_addr:
                    continue
                if self._state_flow_sid_v1(
                    record.get("target_sid")
                ) != target_sid:
                    continue
                accepted, classification = (
                    self._state_flow_record_is_fixed_binding_v80i(record)
                )
                if not accepted:
                    continue
                source_sid = self._state_flow_sid_v1(
                    record.get("source_sid")
                )
                prior = existing_by_pred.get(pair[0])
                if prior is not None and prior != source_sid:
                    conflicts.append({
                        "kind": (
                            "phi_transition_conservation_existing_"
                            "predecessor_conflict_v80l"
                        ),
                        "join_addr": join_addr,
                        "pred_addr": pair[0],
                        "target_sid": target_sid,
                        "first_source_sid": prior,
                        "second_source_sid": source_sid,
                    })
                    continue
                existing_by_pred[pair[0]] = source_sid
                existing_records_by_pred.setdefault(
                    pair[0], []
                ).append({
                    "record": dict(record),
                    "classification": classification,
                })

            # v80n: choose the semantic ticket domain before deciding which
            # tickets are missing.  v80m aligned the later transport gate, but
            # the old code still formed ``missing_predecessors`` from literal
            # one-hop CFG predecessors.  A v80k semantic-region predecessor was
            # therefore discarded before route admission could ever inspect it.
            contract_semantic_predecessor_set = (
                set(existing_by_pred) | set(unresolved_predecessors)
            )
            merged_predecessor_set = (
                literal_cfg_predecessor_set
                | contract_semantic_predecessor_set
            )
            predecessor_authority_source_v80n = None
            if (
                contract_semantic_predecessor_set
                and len(contract_semantic_predecessor_set) == len(inputs)
            ):
                predecessor_set = set(contract_semantic_predecessor_set)
                predecessor_authority_source_v80n = (
                    "v37_resolved_plus_unresolved_semantic_ticket_set"
                )
            elif (
                literal_cfg_predecessor_set
                and len(literal_cfg_predecessor_set) == len(inputs)
            ):
                predecessor_set = set(literal_cfg_predecessor_set)
                predecessor_authority_source_v80n = (
                    "literal_CFG_predecessor_set"
                )
            elif (
                merged_predecessor_set
                and len(merged_predecessor_set) == len(inputs)
            ):
                predecessor_set = set(merged_predecessor_set)
                predecessor_authority_source_v80n = (
                    "exact_cardinality_merged_semantic_and_literal_set"
                )
            else:
                # Preserve all evidence for a fail-closed observation.  This
                # set cannot pass the exact-cardinality gate below.
                predecessor_set = (
                    set(contract_semantic_predecessor_set)
                    if contract_semantic_predecessor_set
                    else set(literal_cfg_predecessor_set)
                )
                predecessor_authority_source_v80n = (
                    "unresolved_predecessor_authority_cardinality"
                )
            predecessors = sorted(predecessor_set, key=str)
            missing_predecessors = predecessor_set - set(existing_by_pred)
            base = {
                "kind": "phi_transition_conservation_receipt_v80l",
                "schema": "phi_transition_conservation_receipt_v1",
                "version": getattr(
                    self,
                    "mars_phi_transition_conservation_version_v80l",
                    "v80l_mars_phi_transition_conservation_v1",
                ),
                "join_addr": join_addr,
                "target_sid": target_sid,
                "predecessors": list(predecessors),
                "literal_CFG_predecessors": list(literal_cfg_predecessors),
                "contract_semantic_predecessors": sorted(
                    contract_semantic_predecessor_set, key=str
                ),
                "merged_predecessors": sorted(
                    merged_predecessor_set, key=str
                ),
                "predecessor_authority_source_v80n": (
                    predecessor_authority_source_v80n
                ),
                "existing_resolved_source_map": dict(existing_by_pred),
                "missing_predecessors": sorted(
                    missing_predecessors, key=str
                ),
                "explicit_unresolved_predecessors": sorted(
                    unresolved_predecessors, key=str
                ),
                "input_count": len(inputs),
                "predecessor_count": len(predecessors),
                "input_order_used": False,
                "successor_order_used": False,
                "ordinal_fallback_used": False,
            }

            if conflicts:
                failures.extend(conflicts)
                observations.append({
                    **base,
                    "status": "rejected",
                    "reason": (
                        "existing_resolved_predecessor_sources_conflict"
                    ),
                    "conflicts": conflicts,
                    "authoritative": False,
                })
                continue
            if not missing_predecessors:
                continue

            missing_transport_routes_v80m = {
                pred_addr: self._state_flow_phi_transition_transport_route_v80m(
                    pred_addr, join_addr
                )
                for pred_addr in sorted(missing_predecessors, key=str)
            }
            gates = {
                "one_semantic_phi_owner": len(matching_phis) == 1,
                "exact_predecessor_ticket_domain_present_v80n": bool(predecessor_set),
                "raw_input_ticket_domain_cardinality_exact_v80n": (
                    len(inputs) == len(predecessor_set)
                ),
                "missing_edges_explicitly_unresolved_by_v37": (
                    bool(missing_predecessors)
                    and missing_predecessors.issubset(
                        unresolved_predecessors
                    )
                ),
                "existing_resolved_edges_in_selected_ticket_domain_v80n": (
                    set(existing_by_pred).issubset(predecessor_set)
                ),
                "all_missing_edges_have_exact_transport_route_v80m": all(
                    isinstance(
                        missing_transport_routes_v80m.get(pred_addr), dict
                    )
                    and missing_transport_routes_v80m[pred_addr].get(
                        "status"
                    ) == "accepted"
                    for pred_addr in missing_predecessors
                ),
            }
            failed_gates = [
                name for name, passed in gates.items() if not passed
            ]
            if failed_gates:
                observations.append({
                    **base,
                    "status": "not_eligible",
                    "reason": (
                        "whole_phi_transition_conservation_gates_not_met"
                    ),
                    "gates": gates,
                    "failed_gates": failed_gates,
                    "transport_routes_v80m": {
                        pred: dict(route)
                        for pred, route in missing_transport_routes_v80m.items()
                    },
                    "authoritative": False,
                })
                continue

            eligible_targets += 1
            full_map, map_reason, map_evidence = (
                self._state_flow_path_expanded_source_map_v80e(
                    inputs,
                    predecessor_set,
                    {},
                    target,
                    join_addr,
                    formula_nodes,
                    raw_definition_blocks,
                )
            )
            map_gates = {
                "one_unique_whole_phi_source_map": full_map is not None,
                "map_covers_exact_selected_ticket_domain_v80n": (
                    isinstance(full_map, dict)
                    and set(full_map) == predecessor_set
                ),
                "existing_resolved_map_agrees": (
                    isinstance(full_map, dict)
                    and all(
                        full_map.get(pred_addr) == source_sid
                        for pred_addr, source_sid
                        in existing_by_pred.items()
                    )
                ),
                "all_selected_source_sids_present": (
                    isinstance(full_map, dict)
                    and all(
                        self._state_flow_sid_v1(source_sid) is not None
                        for source_sid in full_map.values()
                    )
                ),
            }
            failed_map_gates = [
                name for name, passed in map_gates.items() if not passed
            ]
            if failed_map_gates:
                observations.append({
                    **base,
                    "status": "observed_unresolved",
                    "reason": map_reason,
                    "gates": gates,
                    "map_gates": map_gates,
                    "failed_gates": failed_map_gates,
                    "whole_phi_map_evidence_v80l": map_evidence,
                    "authoritative": False,
                })
                continue

            transition_class = (
                "value_selector_phi"
                if target_sid in selector_sids
                else "phi_transition"
            )
            for pred_addr in sorted(missing_predecessors, key=str):
                source_sid = self._state_flow_sid_v1(
                    full_map.get(pred_addr)
                )
                quad = (
                    pred_addr, join_addr, target_sid, source_sid
                )
                competing = [
                    record
                    for record in records
                    if isinstance(record, dict)
                    and self._state_flow_edge_pair_v1(record)
                    == (pred_addr, join_addr)
                    and self._state_flow_sid_v1(
                        record.get("target_sid")
                    ) == target_sid
                    and self._state_flow_sid_v1(
                        record.get("source_sid")
                    ) not in (None, source_sid)
                ]
                if competing:
                    failure = {
                        "kind": (
                            "phi_transition_conservation_competing_"
                            "source_v80l"
                        ),
                        "join_addr": join_addr,
                        "pred_addr": pred_addr,
                        "target_sid": target_sid,
                        "selected_source_sid": source_sid,
                        "competing_source_sids": sorted({
                            self._state_flow_sid_v1(
                                item.get("source_sid")
                            )
                            for item in competing
                        }, key=str),
                    }
                    failures.append(failure)
                    continue

                transport_route_v80m = dict(
                    missing_transport_routes_v80m.get(pred_addr) or {}
                )
                reason = (
                    "whole_phi_predecessor_ticket_conservation_unique_map_v80n"
                )
                producer_transition_id = (
                    join_addr,
                    pred_addr,
                    target_sid,
                    source_sid,
                    reason,
                )
                record = {
                    "kind": (
                        "phi_predecessor_binding_v80n_"
                        "ticket_finalized_before_gate"
                    ),
                    "schema": "phi_predecessor_binding_v37_compatible",
                    "status": "resolved",
                    "pred_addr": pred_addr,
                    "join_addr": join_addr,
                    "edge_id": (pred_addr, join_addr),
                    "edge_identity": (pred_addr, join_addr),
                    "target_sid": target_sid,
                    "source_sid": source_sid,
                    "transition_id": producer_transition_id,
                    "id": producer_transition_id,
                    "id_schema": (
                        "semantic_phi_predecessor_transition_v1"
                    ),
                    "reason": reason,
                    "consumer_transition_class": transition_class,
                    "target_is_value_selector_phi": (
                        transition_class == "value_selector_phi"
                    ),
                    "defining_block": pred_addr,
                    "edge_identity_frozen": True,
                    "direct_to_join": (
                        transport_route_v80m.get("transport_mode")
                        == "literal_CFG_edge"
                    ),
                    "semantic_transition_transport_route_v80m": (
                        transport_route_v80m
                    ),
                    "physical_control_edge_id": list(
                        transport_route_v80m.get(
                            "physical_control_edge_id"
                        ) or []
                    ),
                    "authority": (
                        "PALSGL_v80n_selected_semantic_ticket_domain_plus_"
                        "unique_whole_PHI_source_map_plus_exact_transport_route"
                    ),
                    "phi_transition_conservation_v80l": True,
                    "phi_transition_conservation_route_alignment_v80m": True,
                    "phi_ticket_finalized_before_gate_v80n": True,
                    "predecessor_authority_source_v80n": (
                        predecessor_authority_source_v80n
                    ),
                    "whole_phi_source_map_v80l": dict(full_map),
                    "whole_phi_map_evidence_v80l": map_evidence,
                    "prior_local_closure_versions": [
                        "v80e", "v80f", "v80g",
                        "v80h", "v80i", "v80j", "v80k",
                    ],
                    "input_order_used": False,
                    "successor_order_used": False,
                }
                records.append(record)
                receipt = {
                    **base,
                    "status": "accepted",
                    "pred_addr": pred_addr,
                    "source_sid": source_sid,
                    "transition_id": list(producer_transition_id),
                    "consumer_transition_class": transition_class,
                    "gates": gates,
                    "map_gates": map_gates,
                    "selected_whole_phi_source_map": dict(full_map),
                    "whole_phi_map_reason": map_reason,
                    "whole_phi_map_evidence_v80l": map_evidence,
                    "transport_route_v80m": transport_route_v80m,
                    "ticket_finalization_version_v80n": getattr(
                        self,
                        "mars_phi_ticket_finalization_version_v80n",
                        "v80n_mars_phi_ticket_finalization_v1",
                    ),
                    "repaired_quad": list(quad),
                    "authoritative": True,
                    "authority": record["authority"],
                }
                receipts.append(receipt)
                added += 1

        audit = {
            "kind": (
                "phi_transition_conservation_verified_v80l"
                if not failures
                else "phi_transition_conservation_failed_v80l"
            ),
            "schema": "phi_transition_conservation_audit_v1",
            "route_alignment_version_v80m": getattr(
                self,
                "mars_phi_conservation_route_alignment_version_v80m",
                "v80m_mars_phi_conservation_route_alignment_v1",
            ),
            "ticket_finalization_version_v80n": getattr(
                self,
                "mars_phi_ticket_finalization_version_v80n",
                "v80n_mars_phi_ticket_finalization_v1",
            ),
            "transport_route_receipts_v80m": len(
                self.state_flow_phi_transition_transport_routes_v80m
            ),
            "version": getattr(
                self,
                "mars_phi_transition_conservation_version_v80l",
                "v80l_mars_phi_transition_conservation_v1",
            ),
            "eligible_targets": eligible_targets,
            "reconciled_transitions": added,
            "accepted_receipts": len(receipts),
            "non_authoritative_observations": len(observations),
            "failures": list(failures),
            "input_order_used": False,
            "successor_order_used": False,
            "ordinal_fallback_used": False,
            "rule": (
                "selected_semantic_ticket_domain_equals_unique_whole_PHI_"
                "source_map_equals_resolved_source_record_set"
            ),
        }
        self.state_flow_phi_transition_conservation_receipts_v80l = list(
            receipts
        )
        self.state_flow_phi_transition_conservation_observations_v80l = list(
            observations
        )
        self.state_flow_phi_transition_conservation_failures_v80l = list(
            failures
        )
        self.state_flow_phi_transition_conservation_audit_v80l = dict(
            audit
        )
        self.func.sgl_state_flow_phi_transition_conservation_receipts_v80l = (
            list(receipts)
        )
        self.func.sgl_state_flow_phi_transition_conservation_observations_v80l = (
            list(observations)
        )
        self.func.sgl_state_flow_phi_transition_conservation_failures_v80l = (
            list(failures)
        )
        self.func.sgl_state_flow_phi_transition_conservation_audit_v80l = (
            dict(audit)
        )
        self.func.sgl_mars_phi_transition_conservation_version_v80l = (
            getattr(
                self,
                "mars_phi_transition_conservation_version_v80l",
                "v80l_mars_phi_transition_conservation_v1",
            )
        )
        self.func.sgl_mars_phi_conservation_route_alignment_version_v80m = (
            getattr(
                self,
                "mars_phi_conservation_route_alignment_version_v80m",
                "v80m_mars_phi_conservation_route_alignment_v1",
            )
        )
        self.func.sgl_mars_phi_ticket_finalization_version_v80n = (
            getattr(
                self,
                "mars_phi_ticket_finalization_version_v80n",
                "v80n_mars_phi_ticket_finalization_v1",
            )
        )
        self.func.sgl_state_flow_phi_transition_transport_routes_v80m = list(
            self.state_flow_phi_transition_transport_routes_v80m
        )
        return records

    def _state_flow_canonical_source_records_v80j(
        self, source_records
    ):
        """Prefer exact resolved bindings before material edge-epoch keys exist.

        Residual closure retains upstream observations for provenance.  A weak
        unresolved record can therefore precede a newly generated resolved
        record with the same `(pred, join, target, source)` quad.

        The edge compiler historically inserted the weak record's receipt key
        into `seen` before validating its transition token.  The later resolved
        record was then discarded as a duplicate.  v80j canonicalizes this
        producer ledger first, preserving the losing observation as a sidecar.
        """
        records = [
            dict(item) if isinstance(item, dict) else item
            for item in list(source_records or [])
        ]
        canonical = []
        slot_by_quad = {}
        sidecars = []
        failures = []

        def classification(record):
            pair = self._state_flow_edge_pair_v1(record)
            target_sid = self._state_flow_sid_v1(
                record.get("target_sid")
            )
            source_sid = self._state_flow_sid_v1(
                record.get("source_sid")
            )
            quad = (
                pair[0],
                pair[1],
                target_sid,
                source_sid,
            ) if pair is not None and source_sid is not None else None

            fixed = False
            fixed_receipt = None
            try:
                fixed, fixed_receipt = (
                    self._state_flow_record_is_fixed_binding_v80i(record)
                )
            except Exception as exc:
                fixed_receipt = {
                    "kind": "fixed_binding_classifier_exception_v80j",
                    "reason": type(exc).__name__,
                }

            status = record.get("status")
            exact_resolved = bool(
                fixed
                or (
                    status == "resolved"
                    and pair is not None
                    and target_sid is not None
                    and source_sid is not None
                    and record.get("input_order_used") is not True
                    and record.get("successor_order_used") is not True
                )
            )
            explicitly_nonterminal = status in {
                "unresolved",
                "rejected",
                "partially_resolved",
                "observed_unresolved",
                "probe",
            }
            rank = (
                30 if exact_resolved
                else 10 if not explicitly_nonterminal
                else 0
            )
            return {
                "quad": quad,
                "pair": pair,
                "target_sid": target_sid,
                "source_sid": source_sid,
                "rank": rank,
                "exact_resolved": exact_resolved,
                "explicitly_nonterminal": explicitly_nonterminal,
                "status": status,
                "kind": record.get("kind"),
                "transition_id": (
                    record.get("transition_id")
                    or record.get("phi_transition_id")
                    or record.get("semantic_transition_id")
                    or record.get("id")
                ),
                "authority": record.get("authority"),
                "fixed_binding_receipt_v80i": fixed_receipt,
            }

        def semantic_signature(record, info):
            transition_id = info.get("transition_id")
            try:
                transition_id = tuple(transition_id)
            except Exception:
                transition_id = None
            return (
                info.get("quad"),
                transition_id,
                record.get("reason"),
                record.get("authority"),
                record.get("consumer_transition_class"),
                record.get("target_is_value_selector_phi"),
            )

        for index, record in enumerate(records):
            if not isinstance(record, dict):
                canonical.append(record)
                continue
            info = classification(record)
            quad = info["quad"]
            if quad is None:
                canonical.append(record)
                continue

            prior_slot = slot_by_quad.get(quad)
            if prior_slot is None:
                slot_by_quad[quad] = len(canonical)
                canonical.append(record)
                continue

            prior = canonical[prior_slot]
            prior_info = classification(prior)
            replace = info["rank"] > prior_info["rank"]
            same_rank = info["rank"] == prior_info["rank"]
            same_semantics = (
                semantic_signature(record, info)
                == semantic_signature(prior, prior_info)
            )

            if same_rank and not same_semantics:
                # The source/target/edge semantics agree by quad, but two
                # equally authoritative producer records disagree about their
                # transition provenance.  Do not silently pick one.
                failure = {
                    "kind": (
                        "state_flow_same_quad_equal_authority_"
                        "producer_conflict_v80j"
                    ),
                    "version": getattr(
                        self,
                        "mars_resolved_record_precedence_version_v80j",
                        "v80j_mars_resolved_record_precedence_v1",
                    ),
                    "quad": list(quad),
                    "prior": prior_info,
                    "candidate": info,
                }
                failures.append(failure)
                # Retain the earlier record deterministically and publish the
                # conflict; downstream state-flow closure remains fail-closed.
                replace = False

            winner = record if replace else prior
            loser = prior if replace else record
            winner_info = info if replace else prior_info
            loser_info = prior_info if replace else info

            if replace:
                canonical[prior_slot] = record

            sidecars.append({
                "kind": "state_flow_source_record_precedence_v80j",
                "schema": "state_flow_source_record_precedence_v1",
                "version": getattr(
                    self,
                    "mars_resolved_record_precedence_version_v80j",
                    "v80j_mars_resolved_record_precedence_v1",
                ),
                "quad": list(quad),
                "winner_kind": winner.get("kind"),
                "winner_status": winner.get("status"),
                "winner_rank": winner_info["rank"],
                "winner_transition_id": winner_info.get("transition_id"),
                "loser_kind": loser.get("kind"),
                "loser_status": loser.get("status"),
                "loser_rank": loser_info["rank"],
                "loser_transition_id": loser_info.get("transition_id"),
                "resolution": (
                    "resolved_record_replaces_nonterminal_observation"
                    if replace and winner_info["exact_resolved"]
                    and loser_info["explicitly_nonterminal"]
                    else (
                        "existing_resolved_record_retained_over_"
                        "nonterminal_observation"
                        if not replace and winner_info["exact_resolved"]
                        and loser_info["explicitly_nonterminal"]
                        else (
                            "semantically_identical_duplicate_collapsed"
                            if same_semantics else
                            "equal_authority_conflict_retained_first"
                        )
                    )
                ),
                "material_receipt_created": False,
                "losing_observation_terminal": False,
                "input_order_used": False,
                "successor_order_used": False,
            })

        self.state_flow_source_record_precedence_receipts_v80j = list(
            sidecars
        )
        self.state_flow_source_record_precedence_failures_v80j = list(
            failures
        )
        self.func.sgl_state_flow_source_record_precedence_receipts_v80j = (
            list(sidecars)
        )
        self.func.sgl_state_flow_source_record_precedence_failures_v80j = (
            list(failures)
        )
        self.func.sgl_mars_resolved_record_precedence_version_v80j = (
            getattr(
                self,
                "mars_resolved_record_precedence_version_v80j",
                "v80j_mars_resolved_record_precedence_v1",
            )
        )
        return canonical


    def _state_flow_phi_root_predecessor_evidence_v80p(
        self, join_addr, target_sid, raw_phi=None, semantic_phis=None
    ):
        """Collect predecessor tickets at the PHI root, before v79/v80 gates.

        This deliberately ignores the accepted/rejected queue state.  It walks
        only bounded PHI authority surfaces and extracts explicit edge identity
        for the requested join/target.  No list position or PHI input ordinal is
        treated as predecessor authority.
        """
        join_addr = self._state_flow_addr_v1(join_addr)
        target_sid = self._state_flow_sid_v1(target_sid)
        evidence = {}
        seen = set()

        def coerce_addr(value):
            if isinstance(value, int):
                return value
            if isinstance(value, str):
                try:
                    return int(value.strip(), 0)
                except Exception:
                    return None
            return self._state_flow_addr_v1(value)

        def retain(pred, source, detail=None):
            pred = coerce_addr(pred)
            if pred is None or pred == join_addr:
                return
            evidence.setdefault(pred, []).append({
                "source": source,
                "detail": detail,
            })

        def token_fields(value):
            if not isinstance(value, (tuple, list)) or len(value) != 5:
                return None
            token_join = coerce_addr(value[0])
            token_pred = coerce_addr(value[1])
            token_target = self._state_flow_sid_v1(value[2])
            if token_join is None or token_pred is None or token_target is None:
                return None
            return token_join, token_pred, token_target

        def edge_from_key(key):
            if isinstance(key, (tuple, list)) and len(key) == 2:
                left, right = coerce_addr(key[0]), coerce_addr(key[1])
                return (left, right) if None not in (left, right) else None
            if isinstance(key, str) and "->" in key:
                left, right = key.split("->", 1)
                left, right = coerce_addr(left), coerce_addr(right)
                return (left, right) if None not in (left, right) else None
            return None

        def walk(value, source, depth=0, inherited_edge=None):
            if value is None or depth > 8:
                return
            if isinstance(value, (dict, list, tuple, set)) or hasattr(value, "__dict__"):
                marker_id = id(value)
                if marker_id in seen:
                    return
                seen.add(marker_id)

            fields = token_fields(value)
            if fields is not None:
                token_join, token_pred, token_target = fields
                if token_join == join_addr and token_target == target_sid:
                    retain(token_pred, source, "five_field_transition")
                return

            if isinstance(value, dict):
                pair = self._state_flow_edge_pair_v1(value) or inherited_edge
                item_target = self._state_flow_sid_v1(
                    value.get("target_sid")
                    or value.get("output_sid")
                    or value.get("phi_target_sid")
                    or value.get("phi_output_sid")
                )
                raw_token = (
                    value.get("transition_id")
                    or value.get("phi_transition_id")
                    or value.get("semantic_transition_id")
                    or value.get("id")
                )
                token = token_fields(raw_token)
                if token is not None:
                    token_join, token_pred, token_target = token
                    if token_join == join_addr and token_target == target_sid:
                        retain(token_pred, source, "dict_transition_token")
                if pair is not None:
                    pred = coerce_addr(pair[0])
                    successor = coerce_addr(pair[1])
                    if successor == join_addr and item_target in (None, target_sid):
                        retain(pred, source, value.get("status") or value.get("kind"))
                else:
                    pred = coerce_addr(
                        value.get("pred_addr")
                        or value.get("predecessor_addr")
                        or value.get("predecessor")
                        or value.get("pred")
                    )
                    successor = coerce_addr(
                        value.get("join_addr")
                        or value.get("successor_addr")
                        or value.get("successor")
                        or value.get("join")
                    )
                    if successor == join_addr and item_target in (None, target_sid):
                        retain(pred, source, value.get("status") or value.get("kind"))
                for key, child in list(value.items()):
                    walk(child, source, depth + 1, edge_from_key(key) or pair or inherited_edge)
                return

            if isinstance(value, (list, tuple, set)):
                for child in list(value):
                    walk(child, source, depth + 1, inherited_edge)
                return

            # Bounded object traversal: only PHI/linkage authority attributes.
            attrs = (
                "predecessor_linkage_contract_v37",
                "phi_predecessor_bindings_v37",
                "predecessor_bindings_v37",
                "resolved_edges",
                "unresolved_edges",
                "bindings",
                "edge_bindings",
                "transition_id",
                "phi_transition_id",
                "semantic_transition_id",
                "edge_id",
                "edge_identity",
            )
            for attr in attrs:
                try:
                    child = getattr(value, attr, None)
                except Exception:
                    child = None
                if child is not None:
                    walk(child, "%s.%s" % (source, attr), depth + 1, inherited_edge)

        surfaces = [
            ("func.phi_predecessor_bindings_v37", getattr(
                self.func, "phi_predecessor_bindings_v37", None
            )),
            ("func.phi_transition_descriptions_v37", getattr(
                self.func, "phi_transition_descriptions_v37", None
            )),
            ("func.phi_transition_by_edge_v37", getattr(
                self.func, "phi_transition_by_edge_v37", None
            )),
            ("raw_phi", raw_phi),
        ]
        for index, phi in enumerate(list(semantic_phis or [])):
            surfaces.append(("semantic_phi[%d]" % index, phi))
        for source, payload in surfaces:
            walk(payload, source)
        return evidence

    def _state_flow_specialized_phi_root_pathway_v80p(self, source_records):
        """Bypass the locked v79/v80 admission queue for one proven PHI class.

        The pathway starts at each raw MULTIEQUAL root, builds candidate
        predecessor domains from literal CFG edges plus explicit root linkage
        evidence, and accepts only one globally unique predecessor/source map.
        The resulting resolved source ticket is inserted before the state-flow
        edge ledger is frozen.  Existing exact bindings always win.
        """
        from itertools import combinations

        records = [
            dict(item) if isinstance(item, dict) else item
            for item in list(source_records or [])
        ]
        version = getattr(
            self,
            "mars_specialized_phi_root_pathway_version_v80p",
            "v80p_mars_specialized_phi_root_pathway_rewrite_v1",
        )
        receipts = []
        observations = []
        failures = []
        formula_nodes = dict(self._formula_nodes() or {})
        raw_definition_blocks = {}
        raw_phis = []
        for block in list(getattr(self.func, "blocks", []) or []):
            block_addr = self._state_flow_addr_v1(block)
            for op in list(getattr(block, "ops", []) or []):
                output_sid = self._state_flow_sid_v1(getattr(op, "output", None))
                if output_sid is not None and block_addr is not None:
                    raw_definition_blocks.setdefault(output_sid, set()).add(block_addr)
                if str(getattr(op, "opcode", "") or "").upper() == "MULTIEQUAL":
                    raw_phis.append((block, op))

        semantic_by_target = {}
        for phi in list(self._state_flow_original_phi_nodes_v79() or []):
            target_sid = self._state_flow_sid_v1(
                getattr(phi, "output", None)
                if getattr(phi, "output", None) is not None
                else getattr(phi, "output_sid", None)
            )
            if target_sid is not None:
                semantic_by_target.setdefault(target_sid, []).append(phi)
        selector_sids = self._occurrence_value_selector_target_sids_v77()

        for block, raw_phi in raw_phis:
            join_addr = self._state_flow_addr_v1(block)
            target = getattr(raw_phi, "output", None)
            target_sid = self._state_flow_sid_v1(target)
            inputs = list(getattr(raw_phi, "inputs", []) or [])
            input_count = len(inputs)
            if join_addr is None or target_sid is None or input_count < 2:
                continue

            existing_by_pred = {}
            competing = []
            for record in records:
                if not isinstance(record, dict):
                    continue
                pair = self._state_flow_edge_pair_v1(record)
                if pair is None or pair[1] != join_addr:
                    continue
                if self._state_flow_sid_v1(record.get("target_sid")) != target_sid:
                    continue
                source_sid = self._state_flow_sid_v1(record.get("source_sid"))
                if source_sid is None:
                    continue
                fixed, _classification = self._state_flow_record_is_fixed_binding_v80i(record)
                if not fixed:
                    continue
                prior = existing_by_pred.get(pair[0])
                if prior is not None and prior != source_sid:
                    competing.append((pair[0], prior, source_sid))
                existing_by_pred[pair[0]] = source_sid
            if competing or len(existing_by_pred) >= input_count:
                continue

            join_node = self._state_flow_cfg_node_v1(join_addr)
            literal = {
                self._state_flow_addr_v1(pred)
                for pred in (list(self._predecessors(join_node) or []) if join_node is not None else [])
            }
            literal.discard(None)
            root_evidence = self._state_flow_phi_root_predecessor_evidence_v80p(
                join_addr,
                target_sid,
                raw_phi=raw_phi,
                semantic_phis=semantic_by_target.get(target_sid, []),
            )
            explicit = set(root_evidence)
            mandatory = set(existing_by_pred)
            candidates = set(literal) | explicit | mandatory

            # The specialized path is only for a root-evidenced omission.  It
            # does not invent predecessor addresses from generic reachability.
            if not explicit or len(candidates) < input_count:
                observations.append({
                    "kind": "specialized_phi_root_pathway_observation_v80p",
                    "version": version,
                    "status": "not_applicable",
                    "join_addr": join_addr,
                    "target_sid": target_sid,
                    "input_count": input_count,
                    "existing_predecessors": sorted(mandatory, key=str),
                    "literal_predecessors": sorted(literal, key=str),
                    "explicit_root_predecessors": sorted(explicit, key=str),
                    "reason": "root_evidence_or_cardinality_insufficient",
                })
                continue

            ranked = sorted(
                candidates,
                key=lambda pred: (
                    0 if pred in mandatory else 1 if pred in explicit else 2,
                    str(pred),
                ),
            )
            # Bound combinatorics while retaining every mandatory/root ticket.
            if len(ranked) > 14:
                required = [pred for pred in ranked if pred in mandatory or pred in explicit]
                optional = [pred for pred in ranked if pred not in set(required)]
                ranked = (required + optional)[:14]
            if len(mandatory) > input_count or not mandatory.issubset(set(ranked)):
                failures.append({
                    "kind": "specialized_phi_root_domain_failure_v80p",
                    "join_addr": join_addr,
                    "target_sid": target_sid,
                    "reason": "mandatory_domain_exceeds_or_escapes_bound",
                })
                continue

            domain_candidates = []
            seen_domains = set()
            root_domain = set(explicit) | mandatory
            if len(root_domain) == input_count and mandatory.issubset(root_domain):
                # The specialized branch exists specifically to consume the
                # explicit root ticket domain before literal-controller edges
                # can compete with it.  Once root evidence supplies exact
                # cardinality, do not reopen the old queue's candidate space.
                domain_candidates.append(set(root_domain))
                seen_domains.add(tuple(sorted(root_domain, key=str)))
            else:
                preferred = [
                    set(literal) | explicit | mandatory,
                    set(literal) | mandatory,
                ]
                for domain in preferred:
                    if len(domain) == input_count and mandatory.issubset(domain):
                        key = tuple(sorted(domain, key=str))
                        if key not in seen_domains:
                            seen_domains.add(key)
                            domain_candidates.append(set(domain))
                remaining = [pred for pred in ranked if pred not in mandatory]
                choose = input_count - len(mandatory)
                if choose >= 0:
                    for combo in combinations(remaining, choose):
                        domain = mandatory | set(combo)
                        key = tuple(sorted(domain, key=str))
                        if key in seen_domains:
                            continue
                        seen_domains.add(key)
                        domain_candidates.append(domain)
                        if len(domain_candidates) >= 512:
                            break

            solutions = {}
            rejected_domains = []
            for domain in domain_candidates:
                routes = {
                    pred: self._state_flow_phi_transition_transport_route_v80m(
                        pred, join_addr
                    )
                    for pred in sorted(domain, key=str)
                }
                if not all(
                    isinstance(route, dict) and route.get("status") == "accepted"
                    for route in routes.values()
                ):
                    rejected_domains.append({
                        "domain": sorted(domain, key=str),
                        "reason": "transport_route_not_exact",
                    })
                    continue
                full_map, map_reason, map_evidence = (
                    self._state_flow_path_expanded_source_map_v80e(
                        inputs,
                        domain,
                        {},
                        target,
                        join_addr,
                        formula_nodes,
                        raw_definition_blocks,
                    )
                )
                if not isinstance(full_map, dict) or set(full_map) != set(domain):
                    rejected_domains.append({
                        "domain": sorted(domain, key=str),
                        "reason": map_reason,
                    })
                    continue
                if any(full_map.get(pred) != sid for pred, sid in existing_by_pred.items()):
                    rejected_domains.append({
                        "domain": sorted(domain, key=str),
                        "reason": "existing_resolved_map_disagrees",
                    })
                    continue
                signature = tuple(sorted(
                    ((pred, self._state_flow_sid_v1(source)) for pred, source in full_map.items()),
                    key=lambda item: str(item[0]),
                ))
                solutions[signature] = {
                    "domain": set(domain),
                    "source_map": {pred: self._state_flow_sid_v1(source) for pred, source in full_map.items()},
                    "routes": routes,
                    "map_reason": map_reason,
                    "map_evidence": map_evidence,
                }

            if len(solutions) != 1:
                observations.append({
                    "kind": "specialized_phi_root_pathway_observation_v80p",
                    "version": version,
                    "status": "not_eligible",
                    "join_addr": join_addr,
                    "target_sid": target_sid,
                    "input_count": input_count,
                    "candidate_domains": len(domain_candidates),
                    "unique_source_maps": len(solutions),
                    "explicit_root_predecessors": sorted(explicit, key=str),
                    "rejected_domains": rejected_domains[:32],
                    "reason": "specialized_root_path_not_globally_unique",
                })
                continue

            solution = next(iter(solutions.values()))
            domain = solution["domain"]
            full_map = solution["source_map"]
            missing = sorted(domain - set(existing_by_pred), key=str)
            if not missing:
                continue
            transition_class = (
                "value_selector_phi" if target_sid in selector_sids else "phi_transition"
            )
            for pred_addr in missing:
                source_sid = self._state_flow_sid_v1(full_map.get(pred_addr))
                if source_sid is None:
                    failures.append({
                        "kind": "specialized_phi_root_source_missing_v80p",
                        "join_addr": join_addr,
                        "pred_addr": pred_addr,
                        "target_sid": target_sid,
                    })
                    continue
                slot_competitors = [
                    record for record in records
                    if isinstance(record, dict)
                    and self._state_flow_edge_pair_v1(record) == (pred_addr, join_addr)
                    and self._state_flow_sid_v1(record.get("target_sid")) == target_sid
                    and self._state_flow_sid_v1(record.get("source_sid")) not in (None, source_sid)
                ]
                if slot_competitors:
                    failures.append({
                        "kind": "specialized_phi_root_competing_source_v80p",
                        "join_addr": join_addr,
                        "pred_addr": pred_addr,
                        "target_sid": target_sid,
                        "source_sid": source_sid,
                    })
                    continue
                reason = "specialized_phi_root_pathway_unique_domain_v80p"
                producer_transition_id = (
                    join_addr, pred_addr, target_sid, source_sid, reason
                )
                route = dict(solution["routes"].get(pred_addr) or {})
                source_record = {
                    "kind": "phi_predecessor_binding_v80p_specialized_root_pathway",
                    "schema": "phi_predecessor_binding_v37_compatible",
                    "version": version,
                    "status": "resolved",
                    "pred_addr": pred_addr,
                    "join_addr": join_addr,
                    "edge_id": [pred_addr, join_addr],
                    "edge_identity": [pred_addr, join_addr],
                    "target_sid": target_sid,
                    "source_sid": source_sid,
                    "transition_id": producer_transition_id,
                    "id": producer_transition_id,
                    "id_schema": "semantic_phi_predecessor_transition_v1",
                    "reason": reason,
                    "consumer_transition_class": transition_class,
                    "target_is_value_selector_phi": transition_class == "value_selector_phi",
                    "defining_block": pred_addr,
                    "edge_identity_frozen": True,
                    "direct_to_join": route.get("transport_mode") == "literal_CFG_edge",
                    "semantic_transition_transport_route_v80m": route,
                    "physical_control_edge_id": list(route.get("physical_control_edge_id") or []),
                    "authority": "PALSGL_v80p_root_PHI_unique_domain_direct_ticket",
                    "specialized_phi_root_pathway_v80p": True,
                    "whole_phi_source_map_v80p": dict(full_map),
                    "root_predecessor_evidence_v80p": {
                        str(pred): list(root_evidence.get(pred, []))
                        for pred in sorted(explicit, key=str)
                    },
                    "input_order_used": False,
                    "successor_order_used": False,
                }
                consumer_transition_id, consumer_class = (
                    self._state_flow_consumer_transition_id_v77(
                        source_record,
                        producer_transition_id,
                        pred_addr=pred_addr,
                        join_addr=join_addr,
                        target_sid=target_sid,
                        source_sid=source_sid,
                        authority=source_record["authority"],
                        context="v80p_specialized_phi_root_pathway",
                        required=True,
                    )
                )
                source_record["consumer_transition_id"] = consumer_transition_id
                source_record["consumer_transition_class"] = consumer_class
                records.append(source_record)
                receipts.append({
                    "kind": "specialized_phi_root_pathway_receipt_v80p",
                    "schema": "specialized_phi_root_pathway_receipt_v1",
                    "version": version,
                    "status": "accepted",
                    "producer_transition_id": producer_transition_id,
                    "consumer_transition_id": consumer_transition_id,
                    "consumer_transition_class": consumer_class,
                    "repaired_quad": [pred_addr, join_addr, target_sid, source_sid],
                    "selected_predecessor_domain": sorted(domain, key=str),
                    "selected_source_map": dict(full_map),
                    "transport_route_v80m": route,
                    "authority": source_record["authority"],
                    "input_order_used": False,
                    "successor_order_used": False,
                })

        audit = {
            "kind": (
                "specialized_phi_root_pathway_verified_v80p"
                if not failures else "specialized_phi_root_pathway_failed_v80p"
            ),
            "schema": "specialized_phi_root_pathway_audit_v1",
            "version": version,
            "accepted_tickets": len(receipts),
            "observations": len(observations),
            "failures": list(failures),
            "queue_admission_bypassed": True,
            "state_flow_freeze_precedes_ticket": False,
            "input_order_used": False,
            "successor_order_used": False,
            "rule": "root_PHI_unique_domain_materializes_exact_ticket_before_state_flow_freeze",
        }
        self.specialized_phi_root_pathway_receipts_v80p = list(receipts)
        self.specialized_phi_root_pathway_observations_v80p = list(observations)
        self.specialized_phi_root_pathway_failures_v80p = list(failures)
        self.specialized_phi_root_pathway_audit_v80p = dict(audit)
        self.func.sgl_mars_specialized_phi_root_pathway_version_v80p = version
        self.func.sgl_specialized_phi_root_pathway_receipts_v80p = list(receipts)
        self.func.sgl_specialized_phi_root_pathway_observations_v80p = list(observations)
        self.func.sgl_specialized_phi_root_pathway_failures_v80p = list(failures)
        self.func.sgl_specialized_phi_root_pathway_audit_v80p = dict(audit)
        return records

    def _audit_specialized_phi_terminal_closure_v80p(self):
        """Require each v80p root ticket to reach the terminal handoff chain."""
        failures = []
        receipts = []
        expected = sorted({
            tuple(item.get("consumer_transition_id"))
            for item in list(self.specialized_phi_root_pathway_receipts_v80p or [])
            if isinstance(item, dict)
            and item.get("status") == "accepted"
            and isinstance(item.get("consumer_transition_id"), (tuple, list))
            and len(item.get("consumer_transition_id")) == 5
        }, key=str)
        for transition_id in expected:
            edges = [
                item for item in list(self.state_flow_edge_epoch_receipts_v1 or [])
                if isinstance(item, dict)
                and item.get("status") == "accepted"
                and tuple(item.get("transition_id") or ()) == transition_id
            ]
            placements = [
                item for item in list(self.transition_placement_receipts_v75 or [])
                if isinstance(item, dict)
                and item.get("status") == "accepted"
                and tuple(item.get("transition_id") or ()) == transition_id
                and list(item.get("authorized_placements") or [])
            ]
            obligation = self.consumer_plan_obligations_by_transition_v80.get(transition_id)
            gates = {
                "one_exact_accepted_edge_epoch": len(edges) == 1,
                "one_exact_accepted_placement_receipt": len(placements) == 1,
                "authorized_placement_present": (
                    len(placements) == 1
                    and bool(list(placements[0].get("authorized_placements") or []))
                ),
                "consumer_plan_obligation_present": isinstance(obligation, dict),
            }
            receipt = {
                "kind": "specialized_phi_terminal_closure_receipt_v80p",
                "schema": "specialized_phi_terminal_closure_receipt_v1",
                "transition_id": transition_id,
                "status": "accepted" if all(gates.values()) else "rejected",
                "gates": gates,
                "accepted_edge_epochs": len(edges),
                "accepted_placement_receipts": len(placements),
                "authority": "PALSGL_v80p_direct_root_to_terminal_chain",
            }
            receipts.append(receipt)
            if not all(gates.values()):
                failures.append({
                    "kind": "specialized_phi_terminal_closure_failure_v80p",
                    "transition_id": transition_id,
                    "failed_gates": [name for name, passed in gates.items() if not passed],
                })
        audit = {
            "kind": (
                "specialized_phi_terminal_closure_verified_v80p"
                if not failures else "specialized_phi_terminal_closure_failed_v80p"
            ),
            "schema": "specialized_phi_terminal_closure_audit_v1",
            "version": getattr(
                self,
                "mars_specialized_phi_root_pathway_version_v80p",
                "v80p_mars_specialized_phi_root_pathway_rewrite_v1",
            ),
            "expected_tickets": len(expected),
            "receipts": receipts,
            "failures": failures,
        }
        self.specialized_phi_terminal_closure_audit_v80p = dict(audit)
        self.func.sgl_specialized_phi_terminal_closure_audit_v80p = dict(audit)
        if failures:
            self.occurrence_authority_failures_v75.extend(failures)
        return audit

    def _state_flow_phi_transition_demands_v80o(self):
        """Collect exact canonical PHI demands from the v37 authority surfaces.

        PHIfolder later composes live v34/v41 tickets from
        ``phi_transition_descriptions_v37`` and ``phi_transition_by_edge_v37``.
        Earlier SGL v80x passes read only ``phi_predecessor_bindings_v37`` and
        therefore could report a clean zero-repair audit while a canonical
        downstream demand remained outside the source ledger.

        This collector is bounded and metadata-only.  It accepts no input,
        predecessor, successor, or occurrence ordinal as authority.
        """
        def coerce_addr(value):
            if isinstance(value, int):
                return value
            if isinstance(value, str):
                text = value.strip()
                try:
                    return int(text, 0)
                except Exception:
                    return None
            return self._state_flow_addr_v1(value)

        def edge_from_key(value):
            if isinstance(value, (tuple, list)) and len(value) == 2:
                pair = (coerce_addr(value[0]), coerce_addr(value[1]))
                return pair if None not in pair else None
            if isinstance(value, str) and "->" in value:
                left, right = value.split("->", 1)
                pair = (coerce_addr(left), coerce_addr(right))
                return pair if None not in pair else None
            return None

        records = []
        observations = []
        seen_objects = set()
        seen_records = set()

        def retain(record, source_attribute, inherited_edge=None):
            if not isinstance(record, dict):
                return
            item = dict(record)
            if inherited_edge is not None and self._state_flow_edge_pair_v1(item) is None:
                item["edge_id"] = [inherited_edge[0], inherited_edge[1]]
            item["v80o_demand_source_attribute"] = source_attribute
            raw = (
                item.get("transition_id")
                or item.get("phi_transition_id")
                or item.get("semantic_transition_id")
                or item.get("id")
            )
            pair = self._state_flow_edge_pair_v1(item)
            direct = bool(
                isinstance(raw, (tuple, list)) and len(raw) == 5
            ) or bool(
                pair is not None
                and (
                    item.get("target_sid") is not None
                    or item.get("output_sid") is not None
                )
                and (
                    item.get("source_sid") is not None
                    or item.get("input_sid") is not None
                )
            )
            if not direct:
                return
            marker = repr((source_attribute, inherited_edge, item))
            if marker in seen_records:
                return
            seen_records.add(marker)
            records.append(item)

        def walk(value, source_attribute, depth=0, inherited_edge=None):
            if depth > 6 or value is None:
                return
            if isinstance(value, dict):
                marker = id(value)
                if marker in seen_objects:
                    return
                seen_objects.add(marker)
                retain(value, source_attribute, inherited_edge=inherited_edge)
                for key, child in list(value.items()):
                    child_edge = edge_from_key(key) or inherited_edge
                    walk(child, source_attribute, depth + 1, child_edge)
                return
            if isinstance(value, (tuple, list)):
                if len(value) == 5:
                    token_join = coerce_addr(value[0])
                    token_pred = coerce_addr(value[1])
                    token_target = self._state_flow_sid_v1(value[2])
                    token_source = self._state_flow_sid_v1(value[3])
                    if (
                        token_join is not None
                        and token_pred is not None
                        and token_target is not None
                        and token_source is not None
                        and value[4] is not None
                    ):
                        retain(
                            {"transition_id": tuple(value)},
                            source_attribute,
                            inherited_edge=(token_pred, token_join),
                        )
                        return
                for child in list(value):
                    walk(child, source_attribute, depth + 1, inherited_edge)
                return
            if isinstance(value, set):
                for child in sorted(value, key=repr):
                    walk(child, source_attribute, depth + 1, inherited_edge)

        surfaces = (
            ("phi_transition_descriptions_v37", getattr(
                self.func, "phi_transition_descriptions_v37", None
            )),
            ("phi_transition_by_edge_v37", getattr(
                self.func, "phi_transition_by_edge_v37", None
            )),
        )
        nonempty = []
        for name, payload in surfaces:
            if payload:
                nonempty.append(name)
                walk(payload, name)
            observations.append({
                "kind": "phi_transition_demand_surface_observation_v80o",
                "version": getattr(
                    self,
                    "mars_phi_demand_unlock_generation_version_v80o",
                    "v80o_mars_phi_demand_unlock_generation_commit_v1",
                ),
                "source_attribute": name,
                "present": payload is not None,
                "nonempty": bool(payload),
                "input_order_used": False,
                "successor_order_used": False,
            })
        return records, nonempty, observations

    def _state_flow_phi_input_sid_index_v80o(self):
        index = {}
        for phi in list(self._state_flow_original_phi_nodes_v79() or []):
            output = getattr(phi, "output", None)
            target_sid = self._state_flow_sid_v1(
                output if output is not None else getattr(phi, "output_sid", None)
            )
            if target_sid is None:
                continue
            values = []
            for attr in ("raw_inputs", "inputs", "input_sids"):
                candidate = getattr(phi, attr, None)
                if candidate:
                    values.extend(list(candidate or []))
            source_sids = {
                self._state_flow_sid_v1(value) for value in values
            }
            source_sids.discard(None)
            index.setdefault(target_sid, set()).update(source_sids)
        return index

    def _state_flow_unlock_phi_transition_demands_v80o(self, source_records):
        """Insert exact lower-layer PHI demand before v79/v80 source gating.

        The demand is admitted only when its canonical five-field producer token
        agrees with one live PHI target/input pair and one exact literal or v80k
        semantic-region transport route.  Existing source records retain
        precedence.  A competing source on the same semantic predecessor slot
        fails closed.
        """
        records = [
            dict(item) if isinstance(item, dict) else item
            for item in list(source_records or [])
        ]
        demands, nonempty_surfaces, observations = (
            self._state_flow_phi_transition_demands_v80o()
        )
        input_index = self._state_flow_phi_input_sid_index_v80o()
        existing_quads = set()
        existing_by_slot = {}
        for item in records:
            if not isinstance(item, dict):
                continue
            pair = self._state_flow_edge_pair_v1(item)
            if pair is None:
                continue
            pred_addr = self._state_flow_addr_v1(pair[0])
            join_addr = self._state_flow_addr_v1(pair[1])
            target_sid = self._state_flow_sid_v1(item.get("target_sid"))
            source_sid = self._state_flow_sid_v1(item.get("source_sid"))
            if None in (pred_addr, join_addr, target_sid, source_sid):
                continue
            existing_quads.add((pred_addr, join_addr, target_sid, source_sid))
            existing_by_slot.setdefault(
                (pred_addr, join_addr, target_sid), set()
            ).add(source_sid)

        receipts = []
        failures = []
        accepted_ids = set()
        version = getattr(
            self,
            "mars_phi_demand_unlock_generation_version_v80o",
            "v80o_mars_phi_demand_unlock_generation_commit_v1",
        )

        def coerce_addr(value):
            if isinstance(value, int):
                return value
            if isinstance(value, str):
                try:
                    return int(value.strip(), 0)
                except Exception:
                    return None
            return self._state_flow_addr_v1(value)

        for demand in demands:
            raw_transition_id = (
                demand.get("transition_id")
                or demand.get("phi_transition_id")
                or demand.get("semantic_transition_id")
                or demand.get("id")
            )
            pair = self._state_flow_edge_pair_v1(demand)
            if pair is None:
                pred_candidate = (
                    demand.get("predecessor_addr")
                    or demand.get("predecessor")
                    or demand.get("pred")
                )
                join_candidate = (
                    demand.get("successor_addr")
                    or demand.get("successor")
                    or demand.get("join")
                )
                if pred_candidate is not None and join_candidate is not None:
                    pair = (pred_candidate, join_candidate)
            if isinstance(raw_transition_id, (tuple, list)) and len(raw_transition_id) == 5:
                join_addr = coerce_addr(raw_transition_id[0])
                pred_addr = coerce_addr(raw_transition_id[1])
                target_sid = self._state_flow_sid_v1(raw_transition_id[2])
                source_sid = self._state_flow_sid_v1(raw_transition_id[3])
            else:
                join_addr = coerce_addr(pair[1]) if pair is not None else None
                pred_addr = coerce_addr(pair[0]) if pair is not None else None
                target_sid = self._state_flow_sid_v1(
                    demand.get("target_sid")
                    or demand.get("output_sid")
                    or demand.get("phi_target_sid")
                    or demand.get("phi_output_sid")
                )
                source_sid = self._state_flow_sid_v1(
                    demand.get("source_sid")
                    or demand.get("input_sid")
                    or demand.get("phi_source_sid")
                    or demand.get("phi_input_sid")
                )

            # v80o may serialize an exact canonical description whose v37
            # producer exposed the five fields separately instead of as a
            # tuple.  This is not ordinal reconstruction: all four identities
            # and the reason/class are explicit and are validated below.
            serialized_from_explicit_fields_v80o = False
            if not (
                isinstance(raw_transition_id, (tuple, list))
                and len(raw_transition_id) == 5
            ):
                reason = (
                    demand.get("reason")
                    or demand.get("transition_reason")
                    or demand.get("consumer_transition_class")
                    or demand.get("phi_transition_class")
                    or demand.get("transition_class")
                )
                if (
                    None not in (join_addr, pred_addr, target_sid, source_sid)
                    and reason is not None
                    and str(reason).strip()
                ):
                    raw_transition_id = (
                        join_addr, pred_addr, target_sid, source_sid, str(reason)
                    )
                    serialized_from_explicit_fields_v80o = True

            producer = (
                demand.get("authority")
                or demand.get("source_authority")
                or "PALSemanticGraphBuilder_v37_phi_transition_description"
            )
            producer_transition_id = self._state_flow_exact_transition_id_v75(
                raw_transition_id,
                pred_addr=pred_addr,
                join_addr=join_addr,
                target_sid=target_sid,
                source_sid=source_sid,
                authority=producer,
                context="v80o_phi_transition_demand_unlock",
                required=False,
            )
            consumer_transition_id, transition_class = (
                self._state_flow_consumer_transition_id_v77(
                    demand,
                    producer_transition_id,
                    pred_addr=pred_addr,
                    join_addr=join_addr,
                    target_sid=target_sid,
                    source_sid=source_sid,
                    authority=producer,
                    context="v80o_phi_transition_demand_unlock",
                    required=False,
                )
            ) if producer_transition_id is not None else (None, None)
            route = self._state_flow_phi_transition_transport_route_v80m(
                pred_addr, join_addr
            ) if pred_addr is not None and join_addr is not None else None
            slot_sources = set(
                existing_by_slot.get((pred_addr, join_addr, target_sid), set())
            )
            status_text = str(demand.get("status") or "").lower()
            gates = {
                "exact_five_field_producer_ticket": (
                    producer_transition_id is not None
                ),
                "exact_five_field_consumer_ticket": (
                    consumer_transition_id is not None
                ),
                "target_is_live_phi": target_sid in input_index,
                "source_is_live_phi_input": (
                    target_sid in input_index
                    and source_sid in input_index.get(target_sid, set())
                ),
                "transport_route_exact": (
                    isinstance(route, dict) and route.get("status") == "accepted"
                ),
                "demand_not_explicitly_nonterminal": status_text not in {
                    "rejected", "unresolved", "ambiguous", "failed", "probe"
                },
                "no_competing_source_record": (
                    not slot_sources or slot_sources == {source_sid}
                ),
                "input_order_not_authority": demand.get("input_order_used") is not True,
                "successor_order_not_authority": demand.get("successor_order_used") is not True,
            }
            quad = (pred_addr, join_addr, target_sid, source_sid)
            accepted = all(gates.values())
            receipt = {
                "kind": "phi_transition_demand_unlock_receipt_v80o",
                "schema": "phi_transition_demand_unlock_receipt_v1",
                "version": version,
                "status": "accepted" if accepted else "rejected",
                "source_attribute": demand.get("v80o_demand_source_attribute"),
                "producer_transition_id": producer_transition_id,
                "consumer_transition_id": consumer_transition_id,
                "consumer_transition_class": transition_class,
                "quad": list(quad),
                "already_materialized": quad in existing_quads,
                "producer_ticket_serialized_from_explicit_fields_v80o": (
                    serialized_from_explicit_fields_v80o
                ),
                "transport_route_v80m": dict(route) if isinstance(route, dict) else None,
                "gates": gates,
                "input_order_used": False,
                "successor_order_used": False,
                "authority": "PALSGL_v80o_exact_v37_transition_demand_unlock",
            }
            receipts.append(receipt)
            if not accepted:
                if producer_transition_id is not None and target_sid in input_index:
                    failures.append({
                        "kind": "phi_transition_demand_unlock_gate_failure_v80o",
                        "transition_id": consumer_transition_id,
                        "producer_transition_id": producer_transition_id,
                        "failed_gates": [
                            name for name, passed in gates.items() if not passed
                        ],
                        "receipt": dict(receipt),
                    })
                continue

            accepted_ids.add(consumer_transition_id)
            if quad in existing_quads:
                continue
            source_record = {
                "kind": "phi_predecessor_binding_v80o_demand_unlock",
                "schema": "phi_predecessor_binding_v37_compatible",
                "version": version,
                "status": "resolved",
                "pred_addr": pred_addr,
                "join_addr": join_addr,
                "edge_id": [pred_addr, join_addr],
                "edge_identity": [pred_addr, join_addr],
                "target_sid": target_sid,
                "source_sid": source_sid,
                "transition_id": tuple(producer_transition_id),
                "consumer_transition_id": tuple(consumer_transition_id),
                "consumer_transition_class": transition_class,
                "reason": producer_transition_id[4],
                "authority": "PALSGL_v80o_exact_v37_transition_demand_unlock",
                "source_authority": producer,
                "edge_identity_frozen": True,
                "input_order_used": False,
                "successor_order_used": False,
                "target_is_value_selector_phi": (
                    transition_class == "value_selector_phi"
                ),
                "semantic_transition_transport_route_v80m": dict(route),
                "phi_transition_demand_unlocked_v80o": True,
                "producer_ticket_serialized_from_explicit_fields_v80o": (
                    serialized_from_explicit_fields_v80o
                ),
                "demand_source_attribute_v80o": demand.get(
                    "v80o_demand_source_attribute"
                ),
            }
            records.append(source_record)
            existing_quads.add(quad)
            existing_by_slot.setdefault(
                (pred_addr, join_addr, target_sid), set()
            ).add(source_sid)

        if nonempty_surfaces and not demands:
            failures.append({
                "kind": "phi_transition_demand_surface_unreadable_v80o",
                "source_attributes": list(nonempty_surfaces),
                "reason": "nonempty_v37_transition_surface_yielded_no_exact_demand",
            })
        audit = {
            "kind": (
                "phi_transition_demand_unlock_verified_v80o"
                if not failures else "phi_transition_demand_unlock_failed_v80o"
            ),
            "schema": "phi_transition_demand_unlock_audit_v1",
            "version": version,
            "nonempty_source_attributes": list(nonempty_surfaces),
            "candidate_demands": len(demands),
            "accepted_demands": len(accepted_ids),
            "new_source_records": sum(
                1 for item in receipts
                if item.get("status") == "accepted"
                and not item.get("already_materialized")
            ),
            "receipts": len(receipts),
            "failures": list(failures),
            "vacuous_success_forbidden": True,
            "input_order_used": False,
            "successor_order_used": False,
            "rule": (
                "canonical_v37_transition_demand_enters_source_ledger_before_"
                "v79_v80_gating_or_fails_closed"
            ),
        }
        self.phi_transition_demand_unlock_receipts_v80o = list(receipts)
        self.phi_transition_demand_unlock_observations_v80o = list(observations)
        self.phi_transition_demand_unlock_failures_v80o = list(failures)
        self.phi_transition_demand_unlock_audit_v80o = dict(audit)
        self.func.sgl_mars_phi_demand_unlock_generation_version_v80o = version
        self.func.sgl_phi_transition_demand_unlock_receipts_v80o = list(receipts)
        self.func.sgl_phi_transition_demand_unlock_observations_v80o = list(observations)
        self.func.sgl_phi_transition_demand_unlock_failures_v80o = list(failures)
        self.func.sgl_phi_transition_demand_unlock_audit_v80o = dict(audit)
        return records

    def _compile_state_flow_edge_epochs_v1(self):
        entry_edges, backedges, exit_edges = (
            self._state_flow_loop_edge_sets_v1()
        )
        direct_by_pair = {
            self._state_flow_edge_pair_v1(record): record
            for record in self.state_flow_direct_join_receipts_v1
        }
        source_records = self._compile_late_phi_obligation_closure_v78(
            list(getattr(self.func, "phi_predecessor_bindings_v37", []) or [])
        )
        source_records = self._state_flow_unlock_phi_transition_demands_v80o(
            source_records
        )
        if self.phi_transition_demand_unlock_failures_v80o:
            self.state_flow_failures_v1.extend(
                self.phi_transition_demand_unlock_failures_v80o
            )
        source_records = self._state_flow_canonical_source_records_v80j(
            source_records
        )
        source_records = (
            self._state_flow_reconcile_phi_transition_conservation_v80l(
                source_records
            )
        )
        source_records = self._state_flow_canonical_source_records_v80j(
            source_records
        )
        # v80p: root-pathway rewrite bypasses the v79/v80 admission queue and
        # materializes an exact source ticket before edge-epoch freezing.
        source_records = self._state_flow_specialized_phi_root_pathway_v80p(
            source_records
        )
        source_records = self._state_flow_canonical_source_records_v80j(
            source_records
        )
        if self.specialized_phi_root_pathway_failures_v80p:
            self.state_flow_failures_v1.extend(
                self.specialized_phi_root_pathway_failures_v80p
            )
        if self.state_flow_phi_transition_conservation_failures_v80l:
            self.state_flow_failures_v1.extend(
                self.state_flow_phi_transition_conservation_failures_v80l
            )
        if self.state_flow_source_record_precedence_failures_v80j:
            self.state_flow_failures_v1.extend(
                self.state_flow_source_record_precedence_failures_v80j
            )
        seen = set()
        resolved_edge_targets = set()

        for upstream in source_records:
            if not isinstance(upstream, dict):
                continue
            pair = self._state_flow_edge_pair_v1(upstream)
            if pair is None:
                continue
            target_sid = self._state_flow_sid_v1(
                upstream.get("target_sid")
            )
            source_sid = self._state_flow_sid_v1(
                upstream.get("source_sid")
            )
            key = "edge-epoch-v1:%s->%s:%s<-%s" % (
                self._state_flow_addr_token_v1(pair[0]),
                self._state_flow_addr_token_v1(pair[1]),
                target_sid,
                source_sid,
            )
            if key in seen:
                self.state_flow_failures_v1.append({
                    "kind": "state_flow_duplicate_edge_epoch_receipt_v1",
                    "receipt_key": key,
                })
                continue
            seen.add(key)

            structural_role, occurrence_owner = (
                self._state_flow_structural_edge_role_v1(
                    pair,
                    direct_by_pair.get(pair),
                    entry_edges,
                    backedges,
                    exit_edges,
                )
            )
            literal_cfg_edge_v80k = self._state_flow_cfg_edge_exists_v1(
                pair[0], pair[1]
            )
            semantic_region_route_v80k = None
            exact_upstream_resolution_v80k = bool(
                upstream.get("status") == "resolved"
                and source_sid is not None
                and target_sid is not None
                and upstream.get("edge_identity_frozen") is True
                and upstream.get("input_order_used") is False
                and upstream.get("successor_order_used") is False
            )
            if (
                not literal_cfg_edge_v80k
                and exact_upstream_resolution_v80k
            ):
                semantic_region_route_v80k = (
                    self._state_flow_semantic_region_route_v80k(
                        pair[0], pair[1]
                    )
                )
                self.state_flow_semantic_region_transition_receipts_v80k.append(
                    semantic_region_route_v80k
                )
                if semantic_region_route_v80k.get("status") == "accepted":
                    structural_role = "semantic_loop_exit_transition"
                    occurrence_owner = {
                        "kind": "loop_exit_edge",
                        "loop_header": semantic_region_route_v80k.get(
                            "loop_header"
                        ),
                        "cfg_edge": list(
                            semantic_region_route_v80k.get(
                                "physical_control_edge_id"
                            ) or []
                        ),
                        "semantic_edge": [pair[0], pair[1]],
                        "authority": (
                            "PALSGL_v80k_exact_semantic_region_route"
                        ),
                    }
                else:
                    self.state_flow_semantic_region_transition_failures_v80k.append(
                        semantic_region_route_v80k
                    )
            semantic_region_accepted_v80k = bool(
                isinstance(semantic_region_route_v80k, dict)
                and semantic_region_route_v80k.get("status") == "accepted"
            )
            accepted = []
            rejected = []
            gates = (
                ("edge_identity_has_two_endpoints", len(pair) == 2),
                (
                    "resolved_control_transport_authority",
                    literal_cfg_edge_v80k
                    or semantic_region_accepted_v80k,
                ),
                ("target_sid_present", target_sid is not None),
                ("source_sid_present", source_sid is not None),
                (
                    "upstream_resolution_exact",
                    upstream.get("status") == "resolved",
                ),
                (
                    "input_order_not_authority",
                    upstream.get("input_order_used") is False,
                ),
                (
                    "successor_order_not_authority",
                    upstream.get("successor_order_used") is False,
                ),
            )
            for gate, passed in gates:
                (accepted if passed else rejected).append(gate)
            status = "accepted" if not rejected else "rejected"
            if rejected:
                self.state_flow_failures_v1.append({
                    "kind": "state_flow_resolved_edge_epoch_gate_failure_v1",
                    "receipt_key": key,
                    "failed_gates": rejected,
                })

            producer = (
                upstream.get("authority")
                or "PALSemanticGraphBuilder_v37_PHI_predecessor_linkage"
            )
            raw_transition_id = (
                upstream.get("transition_id")
                or upstream.get("phi_transition_id")
                or upstream.get("semantic_transition_id")
                or upstream.get("id")
            )
            producer_transition_id = self._state_flow_exact_transition_id_v75(
                raw_transition_id,
                pred_addr=pair[0],
                join_addr=pair[1],
                target_sid=target_sid,
                source_sid=source_sid,
                authority=producer,
                context="resolved_phi_predecessor_binding_v37",
                required=(status == "accepted"),
            )
            transition_id, consumer_transition_class = (
                self._state_flow_consumer_transition_id_v77(
                    upstream,
                    producer_transition_id,
                    pred_addr=pair[0],
                    join_addr=pair[1],
                    target_sid=target_sid,
                    source_sid=source_sid,
                    authority=producer,
                    context="resolved_phi_predecessor_binding_v37",
                    required=(status == "accepted"),
                )
            )
            if producer_transition_id is None:
                rejected.append("producer_transition_id_transported")
                status = "rejected"
            else:
                accepted.append("producer_transition_id_transported")
            if transition_id is None:
                rejected.append("consumer_transition_id_projected_v77")
                status = "rejected"
            else:
                accepted.append("consumer_transition_id_projected_v77")
            record = {
                "kind": "state_flow_edge_epoch_receipt_v1",
                "schema": "state_flow_edge_epoch_receipt_v1",
                "receipt_key": key,
                "status": status,
                "predecessor": pair[0],
                "successor": pair[1],
                "join": upstream.get("join_addr", pair[1]),
                "edge_id": [pair[0], pair[1]],
                "semantic_edge_id": [pair[0], pair[1]],
                "physical_control_edge_id": (
                    list(
                        semantic_region_route_v80k.get(
                            "physical_control_edge_id"
                        ) or []
                    )
                    if semantic_region_accepted_v80k
                    else [pair[0], pair[1]]
                ),
                "edge_transport_mode_v80k": (
                    "semantic_region_transition"
                    if semantic_region_accepted_v80k
                    else "literal_CFG_edge"
                ),
                "semantic_region_transition_v80k": (
                    dict(semantic_region_route_v80k)
                    if isinstance(semantic_region_route_v80k, dict)
                    else None
                ),
                "phi_transition_conservation_route_v80m": (
                    dict(
                        upstream.get(
                            "semantic_transition_transport_route_v80m"
                        ) or {}
                    )
                    if upstream.get(
                        "phi_transition_conservation_route_alignment_v80m"
                    ) is True
                    else None
                ),
                "source_sid": source_sid,
                "target_sid": target_sid,
                "transition_id": transition_id,
                "consumer_transition_id": transition_id,
                "consumer_transition_class": consumer_transition_class,
                "transition_id_schema": "phi_transition_id_v1",
                "transition_id_authority": (
                    "PALPHIfolder_phi_transition_id_v1_schema"
                ),
                "transition_id_projection_authority": (
                    "PALSGL_v77_adjacent_consumer_key_projection"
                ),
                "transition_id_reconstructed_by_SGL": False,
                "transition_id_projected_by_SGL": True,
                "producer_transition_id": producer_transition_id,
                "producer_transition_id_schema": (
                    upstream.get("id_schema")
                    or upstream.get("transition_id_schema")
                    or "semantic_phi_predecessor_transition_v1"
                ),
                "producer_transition_id_authority": producer,
                "structural_role": structural_role,
                "execution_occurrence_owner": occurrence_owner,
                "binding_reason": upstream.get("reason"),
                "defining_block": upstream.get("defining_block"),
                "source_authority": producer,
                "upstream_status": upstream.get("status"),
                "edge_identity_frozen": bool(
                    upstream.get("edge_identity_frozen", False)
                ),
                "input_order_used": False,
                "successor_order_used": False,
                "audit": {
                    "status": status,
                    "accepted_gates": accepted,
                    "rejected_gates": rejected,
                    "producer_authority": producer,
                },
            }
            self.state_flow_edge_epoch_receipts_v1.append(record)
            self.state_flow_edge_epoch_receipts_by_key_v1[key] = record
            self._state_flow_add_audit_receipt_v1(record)
            if (
                status == "accepted"
                and transition_id is not None
                and source_sid is not None
            ):
                resolved_edge_targets.add((pair, target_sid))
                self._state_flow_add_definition_epoch_role_v1(
                    source_sid,
                    structural_role,
                    pair,
                    "transition_source",
                )
                self._state_flow_add_definition_epoch_role_v1(
                    target_sid,
                    (
                        "PHI_entry_seed"
                        if structural_role == "loop_entry_seed"
                        else structural_role
                    ),
                    pair,
                    "transition_target",
                )

        conservation_edge_failures_v80l = []
        for conservation in list(
            self.state_flow_phi_transition_conservation_receipts_v80l or []
        ):
            expected = (
                conservation.get("pred_addr"),
                conservation.get("join_addr"),
                self._state_flow_sid_v1(
                    conservation.get("target_sid")
                ),
                self._state_flow_sid_v1(
                    conservation.get("source_sid")
                ),
            )
            matches = [
                record
                for record in self.state_flow_edge_epoch_receipts_v1
                if (
                    record.get("predecessor"),
                    record.get("successor"),
                    self._state_flow_sid_v1(
                        record.get("target_sid")
                    ),
                    self._state_flow_sid_v1(
                        record.get("source_sid")
                    ),
                ) == expected
                and record.get("status") == "accepted"
                and isinstance(
                    record.get("transition_id"), tuple
                )
                and len(record.get("transition_id")) == 5
            ]
            if len(matches) != 1:
                conservation_edge_failures_v80l.append({
                    "kind": (
                        "phi_transition_conservation_transport_route_"
                        "cardinality_failure_v80m"
                    ),
                    "expected_quad": list(expected),
                    "accepted_edge_epoch_receipts": len(matches),
                })
        if conservation_edge_failures_v80l:
            self.state_flow_failures_v1.extend(
                conservation_edge_failures_v80l
            )
            self.state_flow_phi_transition_conservation_failures_v80l.extend(
                conservation_edge_failures_v80l
            )
        self.state_flow_phi_transition_conservation_audit_v80l[
            "edge_epoch_conservation_failures"
        ] = list(conservation_edge_failures_v80l)
        self.state_flow_phi_transition_conservation_audit_v80l[
            "edge_epoch_conservation_exact"
        ] = not bool(conservation_edge_failures_v80l)
        self.state_flow_phi_transition_conservation_audit_v80l[
            "route_alignment_version_v80m"
        ] = self.mars_phi_conservation_route_alignment_version_v80m
        self.state_flow_phi_transition_conservation_audit_v80l[
            "transport_route_receipts_v80m"
        ] = list(self.state_flow_phi_transition_transport_routes_v80m)
        self.func.sgl_state_flow_phi_transition_conservation_audit_v80l = dict(
            self.state_flow_phi_transition_conservation_audit_v80l
        )

        _, phi_nodes = self._state_flow_formula_and_phi_nodes_v1()
        for phi in phi_nodes:
            contract = getattr(
                phi, "predecessor_linkage_contract_v37", None
            )
            if not isinstance(contract, dict):
                continue
            target_sid = self._state_flow_sid_v1(
                contract.get("target_sid")
                or getattr(phi, "output_sid", None)
            )
            for unresolved in list(
                contract.get("unresolved_edges", []) or []
            ):
                pair = self._state_flow_edge_pair_v1(unresolved)
                if pair is None:
                    continue
                key = "edge-epoch-v1:%s->%s:%s<-unresolved" % (
                    self._state_flow_addr_token_v1(pair[0]),
                    self._state_flow_addr_token_v1(pair[1]),
                    target_sid,
                )
                if key in seen:
                    continue
                seen.add(key)
                if (pair, target_sid) in resolved_edge_targets:
                    precedence = {
                        "kind": "state_flow_resolved_record_precedence_v79",
                        "schema": "state_flow_resolved_record_precedence_v1",
                        "edge_id": [pair[0], pair[1]],
                        "target_sid": target_sid,
                        "resolution": "resolved_v37_record_retained",
                        "unresolved_observation_terminal": False,
                        "authority": "PALSGL_v79_resolved_before_unresolved_merge",
                    }
                    # v80c: precedence is an evidence-only observation sidecar.
                    # It is not one of the four material state-flow record classes
                    # and therefore must never consume a record-audit receipt key.
                    self.resolved_record_precedence_receipts_v79.append(precedence)
                    continue
                structural_role, occurrence_owner = (
                    self._state_flow_structural_edge_role_v1(
                        pair,
                        direct_by_pair.get(pair),
                        entry_edges,
                        backedges,
                        exit_edges,
                    )
                )
                producer = (
                    contract.get("authority")
                    or "PALSemanticGraphBuilder_v37_explicit_unresolved"
                )
                cfg_edge_exists = self._state_flow_cfg_edge_exists_v1(
                    pair[0], pair[1]
                )
                accepted_gates = [
                    "edge_identity_has_two_endpoints",
                    "absence_is_explicit",
                    "input_order_not_authority",
                    "successor_order_not_authority",
                ]
                rejected_gates = [
                    "unique_source_definition_authority"
                ]
                if cfg_edge_exists:
                    accepted_gates.append("unresolved_CFG_edge_exists")
                else:
                    rejected_gates.append("unresolved_CFG_edge_exists")
                    self.state_flow_failures_v1.append({
                        "kind": (
                            "state_flow_unresolved_edge_endpoint_missing_v1"
                        ),
                        "edge_id": [pair[0], pair[1]],
                        "target_sid": target_sid,
                    })
                raw_transition_id = (
                    unresolved.get("transition_id")
                    or unresolved.get("phi_transition_id")
                    or unresolved.get("semantic_transition_id")
                    or unresolved.get("id")
                    or contract.get("transition_id")
                )
                producer_transition_id = self._state_flow_exact_transition_id_v75(
                    raw_transition_id,
                    pred_addr=pair[0],
                    join_addr=pair[1],
                    target_sid=target_sid,
                    source_sid=None,
                    authority=producer,
                    context="explicit_unresolved_phi_predecessor_binding_v37",
                    required=False,
                )
                record = {
                    "kind": "state_flow_edge_epoch_receipt_v1",
                    "schema": "state_flow_edge_epoch_receipt_v1",
                    "receipt_key": key,
                    "status": "unresolved",
                    "predecessor": pair[0],
                    "successor": pair[1],
                    "join": pair[1],
                    "edge_id": [pair[0], pair[1]],
                    "source_sid": None,
                    "transition_id": None,
                    "consumer_transition_id": None,
                    "consumer_transition_class": None,
                    "transition_id_schema": "phi_transition_id_v1",
                    "transition_id_authority": (
                        "PALPHIfolder_phi_transition_id_v1_schema"
                    ),
                    "transition_id_projection_authority": (
                        "PALSGL_v77_adjacent_consumer_key_projection"
                    ),
                    "transition_id_reconstructed_by_SGL": False,
                    "transition_id_projected_by_SGL": False,
                    "producer_transition_id": producer_transition_id,
                    "producer_transition_id_authority": producer,
                    "possible_source_sids": [
                        self._state_flow_sid_v1(value)
                        for value in list(
                            unresolved.get(
                                "possible_source_sids", []
                            ) or []
                        )
                    ],
                    "target_sid": target_sid,
                    "structural_role": structural_role,
                    "execution_occurrence_owner": occurrence_owner,
                    "binding_reason": unresolved.get("reason"),
                    "source_authority": producer,
                    "input_order_used": False,
                    "successor_order_used": False,
                    "audit": {
                        "status": "unresolved",
                        "accepted_gates": accepted_gates,
                        "rejected_gates": rejected_gates,
                        "producer_authority": producer,
                    },
                }
                self.state_flow_edge_epoch_receipts_v1.append(record)
                self.state_flow_edge_epoch_receipts_by_key_v1[key] = record
                self._state_flow_add_audit_receipt_v1(record)

    def _compile_contract_capability_receipt_v80(self, stage):
        """Publish and self-audit the semantic behavior actually provided.

        A version label is not accepted as evidence.  The receipt is derived
        from the live residual, merge, typed-owner, and occurrence products.
        """
        policies = dict(self.sgl_state_flow_capabilities_v80 or {})
        failures = []
        observations = list(
            getattr(self, "residual_phi_obligation_observations_v79", []) or []
        )
        bad_observations = [
            item for item in observations
            if isinstance(item, dict)
            and (
                item.get("authoritative") is not False
                or item.get("status") not in {
                    "observed_unresolved", "semantic_owner_retained"
                }
            )
        ]
        if bad_observations:
            failures.append({
                "gate": "residual_ambiguity_is_observation_only",
                "records": bad_observations,
            })
        late_failures = list(
            getattr(self, "late_phi_obligation_failures_v78", []) or []
        )
        if late_failures:
            failures.append({
                "gate": "legacy_late_phi_failure_channel_empty",
                "failures": late_failures,
            })
        merge_conflicts = [
            item for item in list(getattr(self, "state_flow_failures_v1", []) or [])
            if isinstance(item, dict)
            and item.get("kind") == "state_flow_resolved_unresolved_edge_conflict_v1"
        ]
        if merge_conflicts:
            failures.append({
                "gate": "resolved_record_dominates_unresolved_observation",
                "conflicts": merge_conflicts,
            })
        if stage == "occurrence_authority_compiled":
            typed_failures = list(
                dict(getattr(self, "typed_owner_resolution_audit_v80", {}) or {}).get(
                    "failures", []
                ) or []
            )
            if typed_failures:
                failures.append({
                    "gate": "typed_loop_exit_owner_projection_complete",
                    "failures": typed_failures,
                })
            obligation_failures = list(
                dict(getattr(self, "consumer_plan_obligation_audit_v80", {}) or {}).get(
                    "failures", []
                ) or []
            )
            if obligation_failures:
                failures.append({
                    "gate": "accepted_transition_plan_obligations_complete",
                    "failures": obligation_failures,
                })
        for key, expected in {
            "residual_ambiguity_policy": "observation_only",
            "resolved_unresolved_policy": "resolved_precedence",
            "typed_loop_exit_owner_projection": True,
            "input_order_matching": False,
            "successor_order_matching": False,
            "consumer_plan_obligation_publication": True,
            "semantic_region_transition_transport": True,
            "phi_transition_conservation": True,
            "phi_conservation_transport_route_alignment": True,
            "phi_ticket_finalization": True,
            "phi_demand_unlock_generation_commit": True,
        }.items():
            if policies.get(key) != expected:
                failures.append({
                    "gate": "capability_policy_exact",
                    "field": key,
                    "expected": expected,
                    "observed": policies.get(key),
                })

        receipt = {
            "kind": (
                "sgl_contract_capability_verified_v80"
                if not failures else "sgl_contract_capability_failed_v80"
            ),
            "schema": "sgl_contract_capability_receipt_v1",
            "version": self.mars_contract_capability_owner_projection_version_v80,
            "stage": stage,
            **policies,
            "residual_observations": len(observations),
            "resolved_precedence_receipts": len(
                getattr(self, "resolved_record_precedence_receipts_v79", []) or []
            ),
            "typed_owner_resolution_receipts": len(
                getattr(self, "typed_owner_resolution_receipts_v80", []) or []
            ),
            "consumer_plan_obligations": len(
                getattr(self, "consumer_plan_obligations_v80", []) or []
            ),
            "failures": failures,
            "status": "verified" if not failures else "failed",
            "ExecTree_rewritten": False,
            "branch_polarity_rewritten": False,
            "loop_discovery_rewritten": False,
            "direct_join_classification_rewritten": False,
            "input_order_used": False,
            "successor_order_used": False,
        }
        encoded = json.dumps(
            receipt, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")
        receipt["sha256"] = hashlib.sha256(encoded).hexdigest()
        self.sgl_contract_capability_receipt_v80 = receipt
        self.func.sgl_state_flow_capabilities_v80 = dict(policies)
        self.func.sgl_contract_capability_receipt_v80 = dict(receipt)
        return receipt

    def _direct_join_receipt_for_edge_v80(self, pair):
        """Resolve one direct-join receipt without key-shape dependence."""
        pair = tuple(pair or ())
        if len(pair) != 2:
            return None
        record = getattr(
            self, "state_flow_direct_join_receipts_by_tuple_v80", {}
        ).get(pair)
        if isinstance(record, dict):
            return record
        return self.state_flow_direct_join_receipts_by_edge_v1.get(
            "%s->%s" % pair
        )

    def _typed_owner_resolution_receipt_v80(
        self, pair, direct_record, owner_kind, resolution, candidates, gates,
    ):
        receipt = {
            "kind": "typed_direct_join_owner_resolution_v80",
            "schema": "typed_direct_join_owner_resolution_v1",
            "version": getattr(
                self,
                "mars_contract_capability_owner_projection_version_v80",
                "v80_mars_contract_capability_and_owner_projection_v1",
            ),
            "edge_id": [pair[0], pair[1]],
            "owner_kind": owner_kind,
            "resolution": resolution,
            "occurrence_ids": [
                item.get("occurrence_id") for item in list(candidates or [])
            ],
            "direct_join_receipt_key": (direct_record or {}).get("receipt_key"),
            "gates": dict(gates or {}),
            "input_order_used": False,
            "successor_order_used": False,
            "authority": "PALSGL_v80_exact_typed_owner_projection",
        }
        if not hasattr(self, "typed_owner_resolution_receipts_v80"):
            self.typed_owner_resolution_receipts_v80 = []
        self.typed_owner_resolution_receipts_v80.append(receipt)
        return receipt

    def _consumer_plan_obligation_v80(self, record, edge_record):
        """Publish PHIfolder's plan-coverage obligation for one accepted record."""
        if not isinstance(record, dict) or record.get("status") != "accepted":
            return None
        edge = tuple(record.get("edge_id") or ())
        transition_id = self._state_flow_exact_transition_id_v75(
            record.get("transition_id"),
            pred_addr=(edge[0] if len(edge) == 2 else None),
            join_addr=(edge[1] if len(edge) == 2 else None),
            target_sid=record.get("target_sid"),
            source_sid=record.get("source_sid"),
            authority=record.get("transition_id_authority"),
            required=True,
            context="v80_consumer_plan_obligation",
        )
        if transition_id is None:
            return None
        pair = tuple(record.get("edge_id") or ())
        source_sid = self._state_flow_sid_v1(record.get("source_sid"))
        target_sid = self._state_flow_sid_v1(record.get("target_sid"))
        residual_matches = []
        for residual in list(
            getattr(self, "residual_phi_obligation_receipts_v79", []) or []
        ):
            if not isinstance(residual, dict) or residual.get("status") != "accepted":
                continue
            residual_pair = (
                self._state_flow_addr_v1(residual.get("pred_addr")),
                self._state_flow_addr_v1(residual.get("join_addr")),
            )
            if residual_pair != pair:
                continue
            if self._state_flow_sid_v1(residual.get("source_sid")) != source_sid:
                continue
            if self._state_flow_sid_v1(residual.get("target_sid")) != target_sid:
                continue
            residual_matches.append(residual)
        placements = list(record.get("authorized_placements") or [])
        obligation = {
            "kind": "consumer_plan_obligation_v80",
            "schema": "consumer_plan_obligation_v1",
            "version": getattr(
                self,
                "mars_contract_capability_owner_projection_version_v80",
                "v80_mars_contract_capability_and_owner_projection_v1",
            ),
            "transition_id": transition_id,
            "transition_class": (
                record.get("consumer_transition_class") or "phi_transition"
            ),
            "terminal_transition": True,
            "accepted_transition_authority": True,
            "identity_decision_authority": "PALPHIfolder",
            "residual_evidence_present": bool(residual_matches),
            "residual_evidence_count": len(residual_matches),
            "authorized_placement_ids": [
                item.get("placement_id") for item in placements
            ],
            "authorized_placement_count": len(placements),
            "plan_coverage_required": True,
            "case_reference_is_terminal": False,
            "observation_is_terminal": False,
            "authority": "PALSGL_v80_accepted_occurrence_authority",
        }
        record["consumer_plan_obligation"] = obligation
        if not hasattr(self, "consumer_plan_obligations_v80"):
            self.consumer_plan_obligations_v80 = []
        if not hasattr(self, "consumer_plan_obligations_by_transition_v80"):
            self.consumer_plan_obligations_by_transition_v80 = {}
        self.consumer_plan_obligations_v80.append(obligation)
        self.consumer_plan_obligations_by_transition_v80[transition_id] = obligation
        return obligation

    def _publish_state_flow_handoff_v1(self):
        payload = dict(self.state_flow_handoff_v1 or {})
        self.func.sgl_mars_state_flow_version_v74 = (
            self.mars_state_flow_version_v74
        )
