    def _state_flow_validate_audit_coverage_v80c(self):
        """Prove one exact audit receipt for every material state-flow record.

        Precedence observations and other evidence-only sidecars are intentionally
        outside this ledger.  Counts alone are insufficient because equal totals
        can still hide missing, extra, null, or conflicting receipt identities.
        """
        data_records = (
            list(self.state_flow_definition_receipts_v1)
            + list(self.state_flow_edge_epoch_receipts_v1)
            + list(self.state_flow_loop_region_receipts_v1)
            + list(self.state_flow_direct_join_receipts_v1)
        )
        audit_records = list(self.state_flow_audit_receipts_v1)

        data_by_key = {}
        audit_by_key = {}
        null_data_key_records = []
        null_audit_key_records = []
        duplicate_data_keys = []
        duplicate_audit_keys = []

        for index, record in enumerate(data_records):
            key = record.get("receipt_key")
            if key in (None, ""):
                null_data_key_records.append({
                    "index": index,
                    "kind": record.get("kind"),
                })
                continue
            if key in data_by_key:
                duplicate_data_keys.append(key)
            else:
                data_by_key[key] = record

        for index, record in enumerate(audit_records):
            key = record.get("receipt_key")
            if key in (None, ""):
                null_audit_key_records.append({
                    "index": index,
                    "kind": record.get("kind"),
                    "receipt_kind": record.get("receipt_kind"),
                })
                continue
            if key in audit_by_key:
                duplicate_audit_keys.append(key)
            else:
                audit_by_key[key] = record

        data_keys = set(data_by_key)
        audit_keys = set(audit_by_key)
        missing_audit_keys = sorted(data_keys - audit_keys, key=str)
        extra_audit_keys = sorted(audit_keys - data_keys, key=str)

        kind_mismatches = []
        status_mismatches = []
        for key in sorted(data_keys & audit_keys, key=str):
            data_record = data_by_key[key]
            audit_record = audit_by_key[key]
            expected_kind = data_record.get("kind")
            actual_kind = audit_record.get("receipt_kind")
            if expected_kind != actual_kind:
                kind_mismatches.append({
                    "receipt_key": key,
                    "data_kind": expected_kind,
                    "audit_receipt_kind": actual_kind,
                })

            data_audit = dict(data_record.get("audit") or {})
            expected_status = data_audit.get(
                "status", data_record.get("status")
            )
            actual_status = audit_record.get("status")
            if expected_status != actual_status:
                status_mismatches.append({
                    "receipt_key": key,
                    "data_status": expected_status,
                    "audit_status": actual_status,
                })

        failure = {
            "kind": "state_flow_audit_receipt_key_set_mismatch_v80c",
            "schema": "state_flow_audit_receipt_key_set_audit_v1",
            "version": getattr(
                self,
                "mars_state_flow_audit_ledger_partition_version_v80c",
                "v80c_mars_state_flow_audit_ledger_partition_v1",
            ),
            "data_record_count": len(data_records),
            "audit_receipt_count": len(audit_records),
            "missing_audit_keys": missing_audit_keys,
            "extra_audit_keys": extra_audit_keys,
            "null_data_key_records": null_data_key_records,
            "null_audit_key_records": null_audit_key_records,
            "duplicate_data_keys": sorted(set(duplicate_data_keys), key=str),
            "duplicate_audit_keys": sorted(set(duplicate_audit_keys), key=str),
            "kind_mismatches": kind_mismatches,
            "status_mismatches": status_mismatches,
            "precedence_observation_count": len(
                getattr(
                    self,
                    "resolved_record_precedence_receipts_v79",
                    [],
                ) or []
            ),
        }
        failed = any((
            missing_audit_keys,
            extra_audit_keys,
            null_data_key_records,
            null_audit_key_records,
            duplicate_data_keys,
            duplicate_audit_keys,
            kind_mismatches,
            status_mismatches,
        ))
        audit = {
            "kind": (
                "state_flow_audit_receipt_key_set_verified_v80c"
                if not failed else
                "state_flow_audit_receipt_key_set_failed_v80c"
            ),
            "schema": "state_flow_audit_receipt_key_set_audit_v1",
            "version": failure["version"],
            "status": "accepted" if not failed else "rejected",
            "data_record_count": len(data_records),
            "audit_receipt_count": len(audit_records),
            "data_receipt_key_count": len(data_keys),
            "audit_receipt_key_count": len(audit_keys),
            "precedence_observation_count": failure[
                "precedence_observation_count"
            ],
            "input_order_used": False,
            "successor_order_used": False,
            "ordinal_fallback_used": False,
        }
        self.state_flow_audit_receipt_key_set_audit_v80c = audit
        self.func.sgl_state_flow_audit_receipt_key_set_audit_v80c = dict(
            audit
        )
        self.func.sgl_mars_state_flow_audit_ledger_partition_version_v80c = (
            failure["version"]
        )
        if failed:
            self.state_flow_failures_v1.append(failure)
        return audit

